import type { Family } from "./types";

export const families = [{"id":"001","titleEn":"Milne’s rationality conjecture and algebraic specialization","titleFr":"Conjecture de rationalité de Milne et spécialisation algébrique","claim":"Proves Milne's rationality conjecture for abelian varieties over Q with good reduction: specialized Hodge classes pair rationally with complementary divisor products, independently of cohomology theory. Together with result 032, every specialized Hodge class is represented by a single rational algebraic cycle simultaneously in all prime-to-p and crystalline realizations, for every residue characteristic p.","nature":"geometrie-algebrique","domain":"nombres","complexity":"avance","problemYear":1988,"yearKnown":false,"manuscriptDate":"2026-10-07","lean":false,"pdfs":[{"title":"Milne's rationality conjecture for abelian varieties","href":"preprints/Milnes-rationality-conjecture-for-abelian-varieties-October-7-2026/paper.pdf"}],"plainFr":"Une variété abélienne généralise une courbe elliptique en plus grande dimension. Le manuscrit affirme qu'après bonne réduction, une classe de Hodge rationnelle donne le même rationnel face aux produits de diviseurs, et provient d'un seul cycle algébrique rationnel.","plainEn":"An abelian variety generalizes an elliptic curve to higher dimension. The manuscript asserts that after good reduction a rational Hodge class gives the same rational against divisor products, and comes from a single rational algebraic cycle.","expertFr":"Le manuscrit affirme la conjecture de rationalité de Milne, même en caractéristique 2 : après bonne réduction, une classe de Hodge rationnelle s'apparie au même rationnel avec les produits de diviseurs complémentaires, en réalisations premières à p et cristallines. Avec le théorème de Hodge à multiplication complexe, chaque telle classe vient d'un seul cycle algébrique rationnel.","expertEn":"The manuscript asserts Milne's rationality conjecture, including residue characteristic 2: after good reduction, a rational Hodge class pairs to the same rational with any complementary divisor product, in every prime-to-p realization and in crystalline cohomology. With the Hodge theorem for complex multiplication, each such specialized class comes from one rational algebraic cycle.","sparkFr":"L'intérêt est structurel en géométrie algébrique : quelles classes de cohomologie viennent de cycles.","sparkEn":"The interest is structural inside algebraic geometry: which cohomology classes come from cycles."},{"id":"002","titleEn":"The full BSD formula from low Selmer corank","titleFr":"Formule complète de Birch–Swinnerton-Dyer à petit corang de Selmer","claim":"Proves the full Birch–Swinnerton-Dyer leading-term formula for every elliptic curve over ℚ whose full q-power Selmer group has corank zero or one for some prime q, including finiteness of the Tate–Shafarevich group. With result 006, this gives full BSD for a density-one set of quadratic twists of every elliptic curve over ℚ.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1965,"yearKnown":true,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"Exact Birch–Swinnerton-Dyer Formula from Low Selmer Corank","href":"preprints/Exact-Birch-Swinnerton-Dyer-Formula-from-Low-Selmer-Corank-October-7-2026/exact-bsd-low-selmer-corank.pdf"},{"title":"The Selmer converse for elliptic curves at every prime","href":"preprints/The-Selmer-converse-for-elliptic-curves-at-every-prime-October-7-2026/main.pdf"},{"title":"The two-primary Birch–Swinnerton-Dyer formula in Selmer corank at most one","href":"preprints/The-two-primary-Birch-Swinnerton-Dyer-formula-in-Selmer-corank-at-most-one-October-6-2026/paper.pdf"}],"plainFr":"Une courbe elliptique est une courbe cubique dont les points rationnels forment un groupe de type fini. Le manuscrit affirme la formule complète de Birch–Swinnerton-Dyer, groupe de Tate–Shafarevich fini inclus, dès que le Selmer des puissances d'un premier a corang nul ou un.","plainEn":"An elliptic curve is a cubic curve whose rational points form a finitely generated group. The manuscript asserts the full Birch–Swinnerton-Dyer formula, including a finite Tate–Shafarevich group, whenever a prime-power Selmer group has corank zero or one.","expertFr":"Le manuscrit affirme la formule complète du terme dominant de Birch–Swinnerton-Dyer si le Selmer des puissances d'un premier a corang nul ou un : les rangs analytique et de Mordell–Weil égalent ce corang, et Tate–Shafarevich est fini. Tous les facteurs premiers entrent, sans hypothèse de réduction, torsion, isogénie ou image résiduelle ; avec la densité, cela couvre une densité un de tordues quadratiques.","expertEn":"The manuscript asserts the full Birch–Swinnerton-Dyer leading term when a prime-power Selmer group has corank zero or one: analytic and Mordell–Weil ranks equal that corank, and Tate–Shafarevich is finite. Every prime factor enters, with no hypothesis on reduction, torsion, isogenies, or residual image; with the density result this covers a density-one set of quadratic twists.","sparkFr":"Piste en arithmétique effective : le rang des points rationnels est l'invariant que l'on cherche à calculer sur une courbe elliptique.","sparkEn":"A reason to look in computational arithmetic: the rank of rational points is the invariant one tries to compute for an elliptic curve."},{"id":"003","titleEn":"The quasi-Riemann hypothesis","titleFr":"La quasi-hypothèse de Riemann","claim":"Proves that every Dirichlet L-function, including ζ(s), is zero-free in s 7/8, resolving the quasi-Riemann hypothesis. The same half-plane is zero-free for every finite-order Hecke L-function over Q(√(-3)). A companion gives a different proof of the zero-free half-plane s 11/12.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1859,"yearKnown":true,"manuscriptDate":"2026-09-30","lean":true,"pdfs":[{"title":"The Quasi-Riemann Hypothesis: A Zero-Free Half-Plane s 7/8","href":"preprints/The-Quasi-Riemann-Hypothesis-September-30-2026/paper.pdf"},{"title":"The Quasi-Riemann Hypothesis (alternate 11/12 proof)","href":"preprints/The-Quasi-Riemann-Hypothesis-October-5-2026/paper2.pdf"},{"title":"Uniform exclusion of Landau–Siegel zeros","href":"preprints/Uniform-exclusion-of-Landau-Siegel-zeros-October-1-2026/paper.pdf"}],"plainFr":"Zêta de Riemann et les fonctions L de Dirichlet codent les nombres premiers. Le manuscrit affirme qu'elles, ainsi que certaines fonctions L de Hecke, n'ont pas de zéro de partie réelle supérieure à 7/8, hors le pôle en 1.","plainEn":"The Riemann zeta function and Dirichlet L-functions encode the primes. The manuscript asserts that they, and certain Hecke L-functions, have no zero of real part greater than 7/8, except the pole at 1.","expertFr":"Le manuscrit affirme que toute fonction L de Dirichlet, zêta comprise, et toute fonction L de Hecke d'ordre fini sur le corps de racine carrée de moins trois, est sans zéro dans le demi-plan de partie réelle supérieure à 7/8, pôle en 1 permis. Un texte compagnon redonne le demi-plan de partie réelle supérieure à 11/12.","expertEn":"The manuscript asserts that every Dirichlet L-function, zeta included, and every finite-order Hecke L-function over the field of square root of minus three, is zero-free for real part greater than 7/8, allowing the pole at 1. A companion gives again the half-plane of real part greater than 11/12.","sparkFr":"Piste spectrale : les zéros de zêta sont l'objet que la physique mathématique compare parfois à des niveaux d'énergie, sans lien affirmé ici.","sparkEn":"A spectral reason to look: zeta zeros are what mathematical physics sometimes compares with energy levels, with no link asserted here."},{"id":"004","titleEn":"Hilbert’s tenth problem over ℚ","titleFr":"Le dixième problème de Hilbert sur les rationnels","claim":"Proves that no algorithm decides whether an integer-coefficient polynomial in an arbitrary number of variables has a rational zero, resolving Hilbert's tenth problem over ℚ negatively.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"Hilbert’s tenth problem over the rational numbers","href":"preprints/Hilberts-tenth-problem-over-the-rational-numbers-October-6-2026/main.pdf"},{"title":"A pointwise 2-converse for elliptic curves with rational two-torsion","href":"preprints/A-pointwise-2-converse-for-elliptic-curves-with-rational-two-torsion-October-7-2026/paper.pdf"}],"plainFr":"Le dixième problème de Hilbert demande un procédé qui décide si une équation polynomiale a une solution. Le manuscrit affirme qu'aucun algorithme ne décide si un polynôme à coefficients entiers, en un nombre quelconque de variables, a un zéro rationnel.","plainEn":"Hilbert's tenth problem asks for a procedure deciding whether a polynomial equation has a solution. The manuscript asserts that no algorithm decides whether an integer polynomial, in any number of variables, has a rational zero.","expertFr":"Le manuscrit affirme une réponse négative au dixième problème de Hilbert sur les rationnels : aucun algorithme ne décide si un polynôme à coefficients entiers a un zéro rationnel. Le nombre de variables fait partie de l'entrée.","expertEn":"The manuscript asserts a negative answer to Hilbert's tenth problem over the rationals: no algorithm decides whether an integer polynomial has a rational zero. The number of variables is part of the input.","sparkFr":"Piste en calcul : c'est un résultat d'indécidabilité pour les équations polynomiales à inconnues rationnelles.","sparkEn":"A reason to look in computing: this is an undecidability result for polynomial equations in rational unknowns."},{"id":"005","titleEn":"Irrationality of Catalan’s constant","titleFr":"Irrationalité de la constante de Catalan","claim":"Proves that Catalan's constant G= _j≥0(-1)^j/(2j+1)^2 is irrational.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Catalan's constant is irrational","href":"preprints/Catalans-constant-is-irrational-September-24-2026/paper.pdf"}],"plainFr":"La constante de Catalan est la somme alternée des inverses des carrés impairs. Le manuscrit affirme que cette constante est irrationnelle : elle n'est pas un rapport de deux entiers.","plainEn":"Catalan's constant is the alternating sum of the reciprocals of the odd squares. The manuscript asserts that this constant is irrational: it is not a ratio of two integers.","expertFr":"Le manuscrit affirme que la constante de Catalan est irrationnelle. Cette constante est la somme, pour les entiers j à partir de zéro, de moins un puissance j sur le carré de deux j plus un.","expertEn":"The manuscript asserts that Catalan's constant is irrational. The constant is the sum, for integers j from zero, of minus one to the j over the square of two j plus one.","sparkFr":"Piste discrète : cette série alternée réapparaît dans des modèles de dimères, mais le manuscrit n'affirme qu'une irrationalité.","sparkEn":"A combinatorial reason to look: this alternating series reappears in dimer models, but the manuscript asserts only irrationality."},{"id":"006","titleEn":"Goldfeld’s conjecture: densities and mean analytic rank","titleFr":"Conjecture de Goldfeld : densités et rang analytique moyen","claim":"Proves Goldfeld's conjecture for quadratic twists of every elliptic curve over ℚ: analytic ranks zero and one each have density 1/2, and the mean analytic rank tends to 1/2. Both statements order signed squarefree twist parameters by absolute value.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1965,"yearKnown":false,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"Goldfeld's analytic density conjecture and the 2-converse for elliptic curves","href":"preprints/Goldfelds-analytic-density-conjecture-and-the-2-converse-for-elliptic-curves-October-7-2026/paper.pdf"},{"title":"The mean analytic rank of quadratic twists of elliptic curves","href":"preprints/The-mean-analytic-rank-of-quadratic-twists-of-elliptic-curves-October-6-2026/paper.pdf"}],"plainFr":"Tordre une courbe elliptique par des entiers sans facteur carré produit une famille de courbes voisines. Le manuscrit affirme que les rangs analytiques zéro et un y ont chacun densité un demi, et que le rang analytique moyen tend vers un demi.","plainEn":"Twisting an elliptic curve by squarefree integers produces a family of related curves. The manuscript asserts that analytic ranks zero and one each have density one half, and that the mean analytic rank tends to one half.","expertFr":"Le manuscrit affirme la conjecture de Goldfeld : pour toute courbe elliptique sur les rationnels, les tordues quadratiques de rangs analytiques zéro et un ont chacune densité un demi, et le rang moyen tend vers un demi. Si le corang de Selmer des puissances de 2 vaut zéro ou un, il égale les rangs analytique et de Mordell–Weil, et Tate–Shafarevich est fini.","expertEn":"The manuscript asserts Goldfeld's conjecture: for every elliptic curve over the rationals, quadratic twists of analytic ranks zero and one each have density one half, and the mean rank tends to one half. If the 2-power Selmer corank is zero or one, it equals the analytic and Mordell–Weil ranks, and Tate–Shafarevich is finite.","sparkFr":"Piste en statistiques arithmétiques : le manuscrit affirme une densité un demi pour les rangs des tordues, sans usage appliqué.","sparkEn":"A reason to look in arithmetic statistics: the manuscript asserts density one half for ranks of twists, with no applied use."},{"id":"007","titleEn":"Ordinary two-point correlations and the corrected Elliott conjecture","titleFr":"Corrélations de Chowla à deux points et conjecture d'Elliott corrigée","claim":"Proves the ordinary two-point Chowla conjecture, with a bound O(X/( X)^c) for Liouville correlation sums along fixed nonproportional affine forms, where c > 0 is absolute. More generally, proves the binary corrected Elliott conjecture for complex multiplicative functions bounded by one when one factor is uniformly nonpretentious against each fixed Dirichlet character times n^it for |t|≤ X.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Ordinary two-point correlations of multiplicative functions","href":"preprints/Ordinary-two-point-correlations-of-multiplicative-functions-September-24-2026/final.pdf"}],"plainFr":"La fonction de Liouville signe chaque entier selon la parité de ses facteurs premiers. Le manuscrit affirme que ces signes sont décorrélés le long de deux formes affines non proportionnelles, avec un gain logarithmique, et énonce une forme binaire de la conjecture d'Elliott corrigée.","plainEn":"The Liouville function signs each integer by the parity of its prime factors. The manuscript asserts that these signs are uncorrelated along two nonproportional affine forms, with a logarithmic saving, and states a binary form of the corrected Elliott conjecture.","expertFr":"Le manuscrit affirme la conjecture de Chowla ordinaire à deux points : les corrélations de Liouville le long de formes affines fixes non proportionnelles gagnent une puissance de logarithme, d'exposant absolu. Il affirme aussi la forme binaire corrigée d'Elliott pour les fonctions multiplicatives de module au plus un, si un facteur est uniformément non prétentieux, y compris en classes fixes.","expertEn":"The manuscript asserts the ordinary two-point Chowla conjecture: Liouville correlations along fixed nonproportional affine forms save a power of the logarithm, with an absolute exponent. It also asserts the binary corrected Elliott conjecture for multiplicative functions of modulus at most one, if one factor is uniformly nonpretentious, including fixed classes.","sparkFr":"Piste statistique : ces corrélations de signes multiplicatifs ont la forme de lois de paires, sans modèle physique affirmé.","sparkEn":"A statistical reason to look: these correlations of multiplicative signs have the shape of pair laws, with no physical model asserted."},{"id":"008","titleEn":"The Deligne–Drinfeld conjecture","titleFr":"La conjecture de Deligne–Drinfeld","claim":"Proves that the rational Grothendieck–Teichmüller Lie algebra, with the Ihara bracket, is freely generated by one element in each odd weight 3, 5, 7, …, resolving the Deligne–Drinfeld conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1968,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The Deligne-Drinfeld conjecture","href":"preprints/The-Deligne-Drinfeld-conjecture-September-23-2026/paper.pdf"}],"plainFr":"L'algèbre de Lie de Grothendieck–Teichmüller encode des symétries du groupe fondamental des configurations de points sur la droite. Le manuscrit affirme qu'elle est, sur les rationnels et pour le crochet d'Ihara, librement engendrée par un élément dans chaque poids impair à partir de trois.","plainEn":"The Grothendieck–Teichmüller Lie algebra encodes symmetries of the fundamental group of point configurations on the line. The manuscript asserts that over the rationals, for the Ihara bracket, it is freely generated by one element in each odd weight from three on.","expertFr":"Le manuscrit affirme la conjecture de Deligne–Drinfeld : l'algèbre de Lie rationnelle de Grothendieck–Teichmüller, pour le crochet d'Ihara, est librement engendrée par un élément dans chaque poids impair à partir de trois. L'isomorphisme correspondant subsiste après complétion en poids.","expertEn":"The manuscript asserts the Deligne–Drinfeld conjecture: the rational Grothendieck–Teichmüller Lie algebra, for the Ihara bracket, is freely generated by one element in each odd weight from three on. The corresponding isomorphism remains after weight completion.","sparkFr":"Piste en déformation : cette algèbre organise des symétries de tresses, un cadre aussi regardé en physique mathématique, sans application affirmée.","sparkEn":"A deformation reason to look: this algebra organizes braid symmetries, a setting also seen in mathematical physics, with no application asserted."},{"id":"009","titleEn":"Function-field reconstruction from Milnor K-theory and Galois data","titleFr":"Reconstruction des corps de fonctions par la K-théorie de Milnor","claim":"Reconstructs function fields of transcendence degree at least two over algebraically closed constants from K^ M_1/ℓ, K^ M_2/ℓ, and their product. These data recover the perfect closure and constants when ℓ differs from the characteristic, and the original field and its named base in equal characteristic. Also proves Bogomolov–Pop reconstruction from abelian-by-central pro-ℓ Galois data away from the characteristic.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1962,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Reconstruction of Function Fields from Mod-ℓ Milnor K-Theory","href":"preprints/Reconstruction-of-Function-Fields-from-Mod-ell-Milnor-K-Theory-October-5-2026/mod-ell-bogomolov-pop.pdf"},{"title":"Reconstruction from Milnor K-theory modulo the characteristic","href":"preprints/Reconstruction-from-Milnor-K-theory-modulo-the-characteristic-October-5-2026/paper.pdf"},{"title":"The Bogomolov-Pop reconstruction theorem","href":"preprints/The-Bogomolov-Pop-reconstruction-theorem-September-23-2026/paper.pdf"}],"plainFr":"Un corps de fonctions est le corps des fonctions rationnelles sur une variété de dimension au moins deux. Le manuscrit affirme que des morceaux de K-théorie de Milnor, ou des données galoisiennes, reconstruisent ce corps aux ambiguïtés indiquées.","plainEn":"A function field is the field of rational functions on a variety of dimension at least two. The manuscript asserts that pieces of Milnor K-theory, or Galois data, reconstruct that field up to the stated ambiguities.","expertFr":"Le manuscrit affirme que, en transcendance au moins deux, la K-théorie de Milnor modulo ℓ en degrés un et deux, avec leur produit, reconstruit la clôture parfaite et les constantes si ℓ diffère de la caractéristique, et le corps sinon. Il affirme aussi la reconstruction de Bogomolov–Pop par les données pro-ℓ abéliennes-par-centrales, à un scalaire près et, en caractéristique positive, à Frobenius près.","expertEn":"The manuscript asserts that in transcendence degree at least two, Milnor K-theory modulo ℓ in degrees one and two, with their product, recovers the perfect closure and constants when ℓ differs from the characteristic, and the field otherwise. It also asserts Bogomolov–Pop reconstruction from abelian-by-central pro-ℓ data, up to one scalar and, in positive characteristic, up to Frobenius.","sparkFr":"L'intérêt est structurel en géométrie anabélienne : reconstruire un corps depuis son groupe de Galois ou sa K-théorie.","sparkEn":"The interest is structural inside anabelian geometry: reconstructing a field from its Galois group or its K-theory."},{"id":"010","titleEn":"Unrestricted pro-modularity at the prime two","titleFr":"Pro-modularité sans restriction résiduelle au premier deux","claim":"Every continuous odd absolutely irreducible two-dimensional 2-adic representation of G_ Q unramified outside finitely many primes occurs in a completed Hecke algebra at some odd tame level. Also proves classical modularity up to Tate twist for irreducible odd representations with these finiteness conditions that are de Rham at 2 with distinct Hodge–Tate weights, resolving the dyadic Fontaine–Mazur case without residual restrictions.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1977,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"Unrestricted pro-modularity at the prime two","href":"preprints/Unrestricted-pro-modularity-at-the-prime-two-October-6-2026/two-adic-promodularity.pdf"},{"title":"The Dimension of the Two-Adic Hecke Algebra at Odd Level","href":"preprints/The-Dimension-of-the-Two-Adic-Hecke-Algebra-at-Odd-Level-October-5-2026/two-adic-hecke.pdf"},{"title":"Fontaine–Mazur modularity at the prime 2","href":"preprints/Fontaine-Mazur-modularity-at-the-prime-2-October-6-2026/paper.pdf"}],"plainFr":"Une représentation galoisienne de dimension deux fait agir les symétries des nombres sur un plan 2-adique. Le manuscrit affirme que toute telle représentation impaire et irréductible, peu ramifiée, apparaît dans une algèbre de Hecke complétée, et qu'un cas de Rham est modulaire à une torsion près.","plainEn":"A two-dimensional Galois representation lets number symmetries act on a 2-adic plane. The manuscript asserts that every odd irreducible example, ramified at finitely many primes, occurs in a completed Hecke algebra, and that a de Rham case is modular up to a twist.","expertFr":"Le manuscrit affirme que toute représentation 2-adique continue, impaire et absolument irréductible, non ramifiée hors d'un ensemble fini, apparaît dans une algèbre de Hecke complétée de niveau modéré impair, sans hypothèse de Rham. Si elle est de Rham en 2 à poids de Hodge–Tate distincts, il affirme la modularité classique à torsion de Tate près, sans restriction résiduelle.","expertEn":"The manuscript asserts that every continuous odd absolutely irreducible 2-adic representation, unramified outside a finite set, occurs in a completed Hecke algebra of odd tame level, with no de Rham hypothesis. If it is de Rham at 2 with distinct Hodge–Tate weights, it asserts classical modularity up to Tate twist, with no residual restriction.","sparkFr":"Piste vers Langlands : la modularité relie représentations galoisiennes et formes automorphes, sans déploiement affirmé hors des mathématiques.","sparkEn":"A reason to look toward Langlands: modularity links Galois representations and automorphic forms, with no deployment asserted outside mathematics."},{"id":"011","titleEn":"Prime-factor statistics of p-1","titleFr":"Statistique des facteurs premiers de p moins un","claim":"Proves that the normalized ordered logarithms of the prime factors of p-1, counted with multiplicity, converge jointly to the Poisson–Dirichlet law PD(1) as p ranges uniformly over primes up to x and x→∞. This resolves the Ford–Konyagin–Luca conjecture. It also proves that infinitely many integers n have more than n^1-ε totient preimages, for every ε > 0.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1760,"yearKnown":false,"manuscriptDate":"2026-09-17","lean":false,"pdfs":[{"title":"Weighted dilation graphs, smooth shifted primes and totient fibers","href":"preprints/Weighted-Dilation-Graphs-Smooth-Shifted-Primes-and-Totient-Fibers-September-24-2026/paper.pdf"},{"title":"The Poisson-Dirichlet law for prime predecessors","href":"preprints/The-Poisson-Dirichlet-Law-for-Prime-Predecessors-September-24-2026/paper.pdf"},{"title":"Prime Predecessors with an Even Number of Prime Factors","href":"preprints/Prime-Predecessors-with-an-Even-Number-of-Prime-Factors-September-17-2026/paper.pdf"}],"plainFr":"Pour un nombre premier p, l'entier p moins un a ses propres facteurs premiers. Le manuscrit affirme que leurs tailles ordonnées suivent la loi de Poisson–Dirichlet, et que le totient d'Euler prend certaines valeurs avec énormément d'antécédents.","plainEn":"For a prime p, the integer p minus one has its own prime factors. The manuscript asserts that their ordered sizes follow the Poisson–Dirichlet law, and that Euler's totient takes some values with enormously many preimages.","expertFr":"Le manuscrit affirme la conjecture de Ford–Konyagin–Luca : les logarithmes ordonnés des facteurs premiers de p moins un, avec multiplicité, convergent vers la loi de Poisson–Dirichlet. Il affirme aussi qu'une infinité d'entiers ont plus de n puissance 1 moins epsilon antécédents par le totient, et beaucoup de premiers dont le prédécesseur n'a pas de grand facteur.","expertEn":"The manuscript asserts the Ford–Konyagin–Luca conjecture: ordered logarithms of the prime factors of p minus one, with multiplicity, converge to the Poisson–Dirichlet law. It also asserts infinitely many integers with more than n to the power 1 minus epsilon totient preimages, and many primes whose predecessor has no large prime factor.","sparkFr":"Piste probabiliste : la loi limite affirmée est une loi de Poisson–Dirichlet, du type des permutations aléatoires.","sparkEn":"A probabilistic reason to look: the asserted limit is a Poisson–Dirichlet law, of the type met in random permutations."},{"id":"012","titleEn":"Independent largest prime factors of consecutive integers","titleFr":"Plus grands facteurs premiers d'entiers consécutifs","claim":"Resolves the Erdős–Pomerance joint Dickman conjecture: the logarithmic sizes of the largest prime factors of n and n+1 are asymptotically independent in ordinary natural density. In particular, the integers satisfying P^+(n) P^+(n+1) have density 1/2.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The joint Dickman law for consecutive integers","href":"preprints/The-joint-Dickman-law-for-consecutive-integers-September-24-2026/paper.pdf"}],"plainFr":"Le plus grand facteur premier d'un entier mesure à quel point il est divisible par un grand premier. Le manuscrit affirme que ces tailles, pour n et pour n plus un, se comportent comme deux lois de Dickman indépendantes, donc qu'une comparaison des deux a densité un demi.","plainEn":"The largest prime factor of an integer measures how divisible it is by a large prime. The manuscript asserts that these sizes, for n and for n plus one, behave as two independent Dickman laws, so that one comparison of the two has density one half.","expertFr":"Le manuscrit affirme la conjecture jointe de Dickman d'Erdős–Pomerance : les tailles logarithmiques des plus grands facteurs premiers de n et de n plus un sont asymptotiquement indépendantes en densité naturelle, avec marges de Dickman. En particulier, leur comparaison a densité naturelle un demi.","expertEn":"The manuscript asserts the Erdős–Pomerance joint Dickman conjecture: the logarithmic sizes of the largest prime factors of n and of n plus one are asymptotically independent in natural density, with Dickman marginals. In particular, their comparison has natural density one half.","sparkFr":"Piste probabiliste : l'indépendance affirmée est celle de deux lois de Dickman, modèle classique des entiers friables.","sparkEn":"A probabilistic reason to look: the asserted independence is that of two Dickman laws, a classical model of smooth integers."},{"id":"013","titleEn":"Ostmann’s inverse Goldbach conjecture","titleFr":"Conjecture de Goldbach inverse d'Ostmann","claim":"Proves that no finite modification of the primes can be written as A+B with A,B Z_≥0 each containing at least two elements. This resolves Ostmann's inverse Goldbach conjecture on additive indecomposability.","nature":"nombres","domain":"nombres","complexity":"lecture","problemYear":1742,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The additive indecomposability of the primes","href":"preprints/the-additive-indecomposability-of-the-primes-September-24-2026/paper.pdf"}],"plainFr":"Une somme de deux ensembles d'entiers réunit toutes les sommes d'un élément de chacun. Le manuscrit affirme qu'aucune modification finie des nombres premiers ne s'écrit ainsi avec deux ensembles ayant chacun au moins deux éléments.","plainEn":"A sum of two sets of integers collects all sums of one element from each. The manuscript asserts that no finite modification of the primes can be written this way with two sets each having at least two elements.","expertFr":"Le manuscrit affirme la conjecture de Goldbach inverse d'Ostmann : aucun ensemble qui ne diffère des premiers que par un nombre fini d'éléments n'est une somme A plus B d'ensembles d'entiers positifs ou nuls à au moins deux éléments. C'est une indécomposabilité additive de l'ensemble des premiers.","expertEn":"The manuscript asserts Ostmann's inverse Goldbach conjecture: no set differing from the primes by finitely many elements is a sum A plus B of sets of nonnegative integers with at least two elements each. This is an additive indecomposability of the set of primes.","sparkFr":"L'intérêt est structurel en théorie additive des nombres : une indécomposabilité de l'ensemble des premiers.","sparkEn":"The interest is structural inside additive number theory: an indecomposability of the set of primes."},{"id":"014","titleEn":"Restricted geometric Langlands, global Arthur enhancements, and generic Ramanujan","titleFr":"Langlands géométrique restreint et raffinements d'Arthur","claim":"Proves the restricted geometric Langlands equivalence for connected reductive groups on smooth projective connected curves over F_q under the four stated Lie-theoretic characteristic hypotheses. Over arbitrary algebraically closed fields of characteristic p > 0, the same conclusion holds assuming additionally that p is very good for the group and p |W_G|. Over global function fields, proves Ramanujan at every place for globally generic cuspidal representations of split adjoint absolutely simple exceptional groups, ","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1967,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Global Arthur Enhancements of Cuspidal Excursion Parameters","href":"preprints/Global-Arthur-Enhancements-of-Cuspidal-Excursion-Parameters-October-5-2026/manuscript.pdf"},{"title":"Rationality of the Canonical Unramified Arthur Filtration","href":"preprints/Rationality-of-the-Canonical-Unramified-Arthur-Filtration-September-24-2026/paper.pdf"},{"title":"Ramanujan-Arthur Decompositions of Cuspidal Functions at Full Finite Level","href":"preprints/Ramanujan-Arthur-Decompositions-of-Cuspidal-Functions-at-Full-Finite-Level-September-24-2026/paper.pdf"},{"title":"Temperedness at ramified places for globally generic exceptional groups","href":"preprints/Temperedness-at-ramified-places-for-globally-generic-exceptional-groups-October-5-2026/ramified-ramanujan.pdf"},{"title":"The Restricted Geometric Langlands Equivalence in Positive Characteristic","href":"preprints/The-Restricted-Geometric-Langlands-Equivalence-in-Positive-Characteristic-September-24-2026/paper.pdf"},{"title":"Constructible tame Hecke eigensheaves in positive characteristic","href":"preprints/Constructible-tame-Hecke-eigensheaves-in-positive-characteristic-October-5-2026/constructible-tame-hecke-eigensheaves-positive-characteristic.pdf"}],"plainFr":"La correspondance de Langlands géométrique relie des faisceaux sur une courbe à des données spectrales. Le manuscrit affirme une équivalence restreinte pour les groupes réductifs, sous des hypothèses de caractéristique, et un raffinement d'Arthur pour certains paramètres cuspidaux.","plainEn":"Geometric Langlands relates sheaves on a curve to spectral data. The manuscript asserts a restricted equivalence for reductive groups, under characteristic hypotheses, and an Arthur enhancement for certain cuspidal parameters.","expertFr":"Le manuscrit affirme le Langlands géométrique restreint pour les groupes réductifs sur une courbe sur un corps fini, sous quatre hypothèses de caractéristique, et si celle-ci est très bonne et ne divise pas le groupe de Weyl. Sur un corps de fonctions, il affirme un raffinement d'Arthur sans paquets ni multiplicité, et Ramanujan en toute place pour les cuspidales génériques des groupes exceptionnels adjoints.","expertEn":"The manuscript asserts restricted geometric Langlands for connected reductive groups on a curve over a finite field, under four characteristic hypotheses, and when the characteristic is very good and does not divide the Weyl group. Over a function field it asserts a global Arthur enhancement without packets or multiplicity, and Ramanujan at every place for generic cuspidals of adjoint exceptional groups.","sparkFr":"Piste en physique mathématique : cette correspondance est l'analogue de certaines dualités de jauge, sans usage affirmé ici.","sparkEn":"A reason to look in mathematical physics: this correspondence is the analogue of certain gauge dualities, with no use asserted here."},{"id":"015","titleEn":"Torus-packet equidistribution in prime, quartic, and sextic degrees","titleFr":"Équidistribution des paquets de tores en degrés premier, quartique et sextique","claim":"Proves Haar equidistribution without escape of mass for complete volume-weighted torus packets from totally real fields: arbitrary lattices and prescribed local types in fixed prime degree at least five, arbitrary-order Picard packets in primitive quartic fields, and maximal-order ideal-class packets in primitive sextic fields. Here primitive means having no proper intermediate field; the relevant order or field discriminant tends to infinity.","nature":"nombres","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Equidistribution of Prime-Degree Torus Packets with Arbitrary Local Type","href":"preprints/Equidistribution-of-Prime-Degree-Torus-Packets-with-Arbitrary-Local-Type-September-24-2026/paper.pdf"},{"title":"Equidistribution of primitive quartic torus packets for arbitrary orders","href":"preprints/Equidistribution-of-Primitive-Quartic-Torus-Packets-for-Arbitrary-Orders-October-5-2026/quartic-torus-packets.pdf"},{"title":"Equidistribution of Primitive Sextic Torus Packets","href":"preprints/Equidistribution-of-Primitive-Sextic-Torus-Packets-October-5-2026/primitive-sextic-torus-packets.pdf"}],"plainFr":"Un paquet de tores est un nuage d'unités et d'idéaux dans un espace de réseaux. Le manuscrit affirme que, dans les degrés premier, quartique et sextique qu'il nomme, ces nuages s'équirépartissent selon la mesure de Haar, sans masse qui s'échappe.","plainEn":"A torus packet is a cloud of units and ideals in a space of lattices. The manuscript asserts that in the prime, quartic, and sextic degrees it names, these clouds equidistribute for Haar measure, with no mass escaping.","expertFr":"Le manuscrit affirme l'équidistribution de Haar sans fuite de masse pour des paquets de tores de corps totalement réels : degré premier au moins cinq à types locaux prescrits, paquets de Picard quartiques primitifs, et classes d'idéaux sextiques primitives d'ordre maximal. Le discriminant tend vers l'infini, et primitif veut dire sans corps intermédiaire.","expertEn":"The manuscript asserts Haar equidistribution without escape of mass for torus packets from totally real fields: prime degree at least five with prescribed local types, primitive quartic Picard packets, and primitive sextic maximal-order class packets. The discriminant tends to infinity, and primitive means there is no intermediate field.","sparkFr":"Piste en dynamique homogène : la mesure limite affirmée est la mesure de Haar sur un espace de réseaux.","sparkEn":"A reason to look in homogeneous dynamics: the asserted limit is Haar measure on a space of lattices."},{"id":"016","titleEn":"Zilber–Pink in abelian varieties and the Siegel threefold","titleFr":"Zilber–Pink pour les variétés abéliennes et la variété de Siegel","claim":"Proves the abelian Zilber–Pink conjecture over Q: every irreducible subvariety has finitely many maximal atypical subvarieties relative to its smallest containing torsion coset. It also proves the full curve case in the Siegel threefold A_2 for Hodge-generic curves defined over Q, without boundary or reduction assumptions.","nature":"geometrie-algebrique","domain":"physique","complexity":"avance","problemYear":1950,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The abelian Zilber–Pink conjecture","href":"preprints/The-Abelian-Zilber-Pink-Conjecture-September-24-2026/paper.pdf"},{"title":"The E×CM component of Zilber–Pink for curves in A2","href":"preprints/The-E-times-CM-Component-of-Zilber-Pink-for-Curves-in-A2-September-24-2026/paper.pdf"},{"title":"Quaternionic division points on curves in the Siegel threefold","href":"preprints/Quaternionic-Division-Points-on-Curves-in-the-Siegel-Threefold-September-24-2026/paper.pdf"},{"title":"Elliptic squares and Zilber–Pink for curves in A2","href":"preprints/Elliptic-Squares-and-Zilber-Pink-for-Curves-in-A2-September-24-2026/paper.pdf"}],"plainFr":"Dans une variété abélienne, les sous-variétés spéciales sont les lieux découpés par la torsion. Le manuscrit affirme qu'une sous-variété irréductible n'a qu'un nombre fini de pièces atypiques maximales, et de même pour les courbes de Hodge génériques dans la variété de Siegel.","plainEn":"Inside an abelian variety, special subvarieties are the loci cut out by torsion. The manuscript asserts that an irreducible subvariety has only finitely many maximal atypical pieces, and likewise for Hodge-generic curves in the Siegel variety.","expertFr":"Le manuscrit affirme la conjecture de Zilber–Pink abélienne sur les rationnels : toute sous-variété irréductible n'a qu'un nombre fini de sous-variétés atypiques maximales dans son plus petit coset de torsion. Il affirme aussi le cas des courbes de Hodge génériques sur les rationnels dans la variété de Siegel, sans hypothèse de bord ni de réduction.","expertEn":"The manuscript asserts the abelian Zilber–Pink conjecture over the rationals: every irreducible subvariety has finitely many maximal atypical subvarieties in its smallest torsion coset. It also asserts the case of Hodge-generic curves over the rationals in the Siegel threefold, with no boundary or reduction hypothesis.","sparkFr":"L'intérêt est structurel en géométrie arithmétique : la finitude des intersections atypiques de lieux spéciaux.","sparkEn":"The interest is structural inside arithmetic geometry: finiteness of atypical intersections of special loci."},{"id":"017","titleEn":"The irrationality exponent of π is 2","titleFr":"L'exposant d'irrationalité de pi est égal à 2","claim":"Proves that the irrationality exponent of π is exactly 2: for every ε > 0 and all sufficiently large denominators q, every rational p/q satisfies |π-p/q|≥ q^-2-ε. This also proves convergence of the Flint–Hills series _n≥11/(n^3 ^2 n), with angles in radians.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1761,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The irrationality exponent of pi is 2","href":"preprints/The-irrationality-exponent-of-pi-is-2-September-24-2026/paper.pdf"}],"plainFr":"L'exposant d'irrationalité mesure la qualité des approximations de pi par des fractions. Le manuscrit affirme que cet exposant vaut exactement 2, et que la série de Flint–Hills, en sinus carré de n, converge.","plainEn":"The irrationality exponent measures how well pi can be approximated by fractions. The manuscript asserts that this exponent is exactly 2, and that the Flint–Hills series, built from the squared sine of n, converges.","expertFr":"Le manuscrit affirme que l'exposant d'irrationalité de pi vaut exactement 2 : pour tout epsilon positif et tout dénominateur assez grand, p sur q reste à distance au moins q puissance moins 2 moins epsilon. Il en déduit la convergence de la série de Flint–Hills, inverse de n au cube fois le sinus au carré de n, en radians.","expertEn":"The manuscript asserts that the irrationality exponent of pi is exactly 2: for every positive epsilon and all large denominators, p over q stays at least q to the power minus 2 minus epsilon away. It deduces convergence of the Flint–Hills series, the reciprocal of n cubed times sine squared of n, in radians.","sparkFr":"Piste en analyse : la convergence affirmée concerne une série classique bâtie sur le sinus de l'entier n.","sparkEn":"A reason to look in analysis: the asserted convergence concerns a classical series built from the sine of the integer n."},{"id":"018","titleEn":"The Margulis–Platonov conjecture over global fields","titleFr":"Conjecture de Margulis–Platonov sur les corps globaux","claim":"Proves the Margulis–Platonov conjecture over every global field, including function fields of characteristic two. For an absolutely almost simple simply connected algebraic group G over k, every noncentral abstract normal subgroup of G(k) is the inverse image of an open normal subgroup in the finite product of its anisotropic nonarchimedean local groups.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1975,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Margulis–Platonov conjecture over global function fields","href":"preprints/The-Margulis-Platonov-conjecture-over-global-function-fields-October-5-2026/margulis-platonov-global-function-fields.pdf"},{"title":"The Margulis–Platonov conjecture over number fields","href":"preprints/The-Margulis-Platonov-conjecture-over-number-fields-September-23-2026/paper.pdf"}],"plainFr":"Les points rationnels d'un groupe algébrique simple forment un grand groupe discret. Le manuscrit affirme que tout sous-groupe normal non central de ces points provient d'un sous-groupe ouvert d'un produit de groupes locaux, sur tout corps global, y compris en caractéristique deux.","plainEn":"The rational points of a simple algebraic group form a large discrete group. The manuscript asserts that every noncentral normal subgroup of those points comes from an open subgroup of a product of local groups, over every global field, including characteristic two.","expertFr":"Le manuscrit affirme la conjecture de Margulis–Platonov sur tout corps global, corps de fonctions de caractéristique deux inclus. Pour un groupe absolument presque simple et simplement connexe, tout sous-groupe normal non central des points rationnels est l'image inverse d'un sous-groupe normal ouvert du produit fini de ses groupes locaux anisotropes.","expertEn":"The manuscript asserts the Margulis–Platonov conjecture over every global field, including function fields of characteristic two. For an absolutely almost simple simply connected group, every noncentral normal subgroup of the rational points is the inverse image of an open normal subgroup of the product of its anisotropic local groups.","sparkFr":"L'intérêt est structurel dans la théorie des groupes arithmétiques : une description des sous-groupes normaux.","sparkEn":"The interest is structural inside the theory of arithmetic groups: a description of normal subgroups."},{"id":"019","titleEn":"The local p-adic section conjecture and global consequences","titleFr":"Conjecture de section p-adique locale et conséquences globales","claim":"Proves that rational points on every smooth proper geometrically connected curve of genus at least two over a finite extension of ℚp correspond bijectively to conjugacy classes of sections of its full arithmetic étale fundamental group. It also proves Grothendieck's section conjecture over ℚ for the modular curves X_0(N) and X_1(N) of genus at least two.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1968,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Étale covers with a prescribed exterior sheet","href":"preprints/Etale-covers-with-a-prescribed-exterior-sheet-September-24-2026/main.pdf"},{"title":"The p-adic section conjecture","href":"preprints/The-p-adic-section-conjecture-October-6-2026/main.pdf"}],"plainFr":"Sur une courbe de genre au moins deux sur un corps p-adique, les points devraient correspondre à des sections du groupe fondamental. Le manuscrit affirme cette bijection locale, et la conjecture de section de Grothendieck pour les courbes modulaires de genre au moins deux.","plainEn":"On a curve of genus at least two over a p-adic field, points should match sections of the fundamental group. The manuscript asserts this local bijection, and Grothendieck's section conjecture for modular curves of genus at least two.","expertFr":"Le manuscrit affirme que les points rationnels d'une courbe propre lisse de genre au moins deux sur un corps p-adique correspondent aux classes de sections de son groupe fondamental étale. Il affirme la conjecture de section de Grothendieck pour les courbes modulaires X0(N) et X1(N) de genre au moins deux, et le résumé construit un revêtement étale qui isole de petits disques avec degré divisible par p.","expertEn":"The manuscript asserts that rational points of a smooth proper curve of genus at least two over a p-adic field match section classes of its étale fundamental group. It asserts Grothendieck's section conjecture for the modular curves X0(N) and X1(N) of genus at least two, and the abstract builds an étale cover isolating small disks with degree divisible by p.","sparkFr":"L'intérêt est structurel en géométrie anabélienne : lire les points d'une courbe dans son groupe fondamental.","sparkEn":"The interest is structural inside anabelian geometry: reading the points of a curve in its fundamental group."},{"id":"020","titleEn":"Squarefree quartics and power-free polynomial values","titleFr":"Valeurs sans facteur carré des polynômes de degré quatre","claim":"Proves the squarefree-values conjecture for irreducible integer quartics with no fixed prime-square divisor: squarefree values on positive integers have the predicted positive Euler-product density. More generally, establishes the (d-2)-power-free density for irreducible integer polynomials of degrees four through eight under the necessary local condition; together with Browning's higher-degree theorem, this covers every d ≥ 4.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Squarefree values of quartics and power-free values of polynomials","href":"preprints/Squarefree-values-of-quartics-and-power-free-values-of-polynomials-September-24-2026/manuscript.pdf"}],"plainFr":"Un polynôme entier prend des valeurs entières, et l'on demande si elles sont souvent sans facteur carré. Le manuscrit affirme la densité positive prédite pour les quartiques irréductibles sans diviseur carré fixe, et la densité analogue en degrés quatre à huit.","plainEn":"An integer polynomial takes integer values, and one asks how often they are squarefree. The manuscript asserts the predicted positive density for irreducible quartics with no fixed square divisor, and the analogous density in degrees four through eight.","expertFr":"Le manuscrit affirme que toute quartique entière irréductible sans diviseur carré fixe prend des valeurs sans facteur carré selon la densité de produit eulérien prédite. Il affirme la densité sans puissance d moins 2 en degrés 4 à 8 et, avec le théorème de Browning, pour tout degré au moins 4.","expertEn":"The manuscript asserts that every irreducible integer quartic with no fixed square divisor takes squarefree values at the predicted Euler-product density. It asserts the power-free density of order d minus 2 in degrees 4 through 8 and, with Browning's theorem, for every degree at least 4.","sparkFr":"L'intérêt est structurel en théorie analytique des nombres : des densités de valeurs polynomiales sans puissance.","sparkEn":"The interest is structural inside analytic number theory: densities of power-free polynomial values."},{"id":"021","titleEn":"A quadratic bound for Jacobsthal’s function","titleFr":"Une borne quadratique pour la fonction de Jacobsthal","claim":"Answers Jacobsthal's quadratic-bound question: every interval of Ck^2 consecutive integers contains an integer coprime to any prescribed positive integer with at most k distinct prime divisors, for an absolute constant C. The bound is uniform over prime sets and interval positions and removes the classical logarithmic loss.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1960,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A quadratic bound for Jacobsthal's function","href":"preprints/A-quadratic-bound-for-Jacobsthals-function-September-25-2026/paper.pdf"}],"plainFr":"La fonction de Jacobsthal demande un intervalle qui contient toujours un entier premier à un module n'ayant que k facteurs premiers distincts. Le manuscrit affirme qu'une longueur de l'ordre du carré de k suffit, sans la perte logarithmique classique.","plainEn":"Jacobsthal's function asks for an interval that always contains an integer coprime to a modulus with only k distinct prime factors. The manuscript asserts that a length of order k squared suffices, without the classical logarithmic loss.","expertFr":"Le manuscrit affirme qu'une constante absolue C borne la fonction de Jacobsthal par C fois k au carré : tout tel intervalle rencontre un entier premier à tout module d'au plus k facteurs premiers distincts. La borne est uniforme en les premiers et en la position de l'intervalle.","expertEn":"The manuscript asserts that an absolute constant C bounds Jacobsthal's function by C times k squared: every such interval meets an integer coprime to any modulus with at most k distinct prime factors. The bound is uniform in the primes and in the position of the interval.","sparkFr":"Piste algorithmique : cette fonction borne des suites d'entiers qui partagent tous un facteur avec un module donné.","sparkEn":"A computational reason to look: this function bounds runs of integers that all share a factor with a given modulus."},{"id":"022","titleEn":"The weak inhomogeneous Duffin–Schaeffer conjecture","titleFr":"Conjecture de Duffin–Schaeffer inhomogène faible","claim":"Proves that for every real shift γ and finite-valued ψ: N→[0,∞), divergence of _qφ(q)ψ(q)/q implies \\|qx-γ\\| ψ(q) for infinitely many q, for almost every x. Here ϕ is Euler's totient and the norm is distance to the nearest integer. Numerators are unrestricted; no monotonicity or Diophantine condition on γ is needed.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1760,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"The Weak Inhomogeneous Duffin–Schaeffer Conjecture","href":"preprints/The-weak-inhomogeneous-Duffin-Schaeffer-conjecture-September-25-2026/paper.pdf"}],"plainFr":"L'approximation des réels par des fractions dépend d'une série bâtie sur le totient d'Euler. Le manuscrit affirme que si elle diverge, presque tout réel satisfait l'inégalité décalée pour une infinité de dénominateurs, sans monotonie ni condition sur le décalage.","plainEn":"Approximation of reals by fractions depends on a series built from Euler's totient. The manuscript asserts that if it diverges, almost every real satisfies the shifted inequality for infinitely many denominators, with no monotonicity or condition on the shift.","expertFr":"Le manuscrit affirme la conjecture de Duffin–Schaeffer inhomogène faible : si la série du totient fois psi(q) sur q diverge, alors pour presque tout x la distance de qx moins gamma à l'entier le plus proche est inférieure à psi(q) infiniment souvent. Le décalage est quelconque, les numérateurs ne sont pas réduits, et aucune monotonie n'est demandée.","expertEn":"The manuscript asserts the weak inhomogeneous Duffin–Schaeffer conjecture: if the series of the totient times psi(q) over q diverges, then for almost every x the distance from qx minus gamma to the nearest integer is less than psi(q) infinitely often. The shift is arbitrary, numerators need not be reduced, and no monotonicity is required.","sparkFr":"Piste métrique : l'énoncé est une propriété affirmée pour presque tout nombre réel, au sens de la mesure.","sparkEn":"A metric reason to look: the statement is a property asserted for almost every real number, in the sense of measure."},{"id":"023","titleEn":"Patterson's first moment for cubic Gauss sums","titleFr":"Premier moment de Patterson pour les sommes de Gauss cubiques","claim":"Proves unconditionally the all-primary-prime form of Patterson’s first-moment asymptotic: normalized cubic Gauss sums over primary Eisenstein primes of norm at most X, including both conjugates, have an explicit positive main term of order X^5/6/ X. Every fixed nonzero prime-angle Fourier mode has smaller order.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"An unconditional first moment for cubic Gauss sums","href":"preprints/An-unconditional-first-moment-for-cubic-Gauss-sums-September-25-2026/paper.pdf"}],"plainFr":"Les sommes de Gauss cubiques sont des sommes oscillantes liées aux premiers d'Eisenstein. Le manuscrit affirme un terme principal positif d'ordre X puissance 5/6 sur un logarithme, et un ordre plus petit pour chaque mode angulaire non nul.","plainEn":"Cubic Gauss sums are oscillating sums attached to Eisenstein primes. The manuscript asserts a positive main term of order X to the 5/6 over a logarithm, and a smaller order for every nonzero angular mode.","expertFr":"Le manuscrit affirme inconditionnellement le premier moment de Patterson pour les sommes de Gauss cubiques normalisées sur tous les premiers d'Eisenstein primaires, conjugués inclus. Le terme principal est d'ordre X puissance 5/6 sur un logarithme, de coefficient six cinquièmes fois la constante du résumé, et chaque mode angulaire non nul fixé est plus petit.","expertEn":"The manuscript asserts unconditionally Patterson's first moment for normalized cubic Gauss sums over all primary Eisenstein primes, conjugates included. The main term has order X to the 5/6 over a logarithm, with coefficient six fifths times the constant in the abstract, and every fixed nonzero angular mode is smaller.","sparkFr":"L'intérêt est structurel en théorie analytique des nombres : un moment de sommes de Gauss cubiques.","sparkEn":"The interest is structural inside analytic number theory: a moment of cubic Gauss sums."},{"id":"024","titleEn":"An asymptotic formula for the number of totients","titleFr":"Formule asymptotique pour le nombre de totients","claim":"Gives an asymptotic equivalent for the number V(x) of distinct totient values up to x, with a positive bounded phase-dependent factor determined by convergent arithmetic approximations. In particular, V(cx)/V(x)→ c for every fixed c > 0, answering Erdős and Hall’s scaling question.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"An asymptotic formula for the number of totients","href":"preprints/An-asymptotic-formula-for-the-number-of-totients-September-25-2026/An-asymptotic-formula-for-the-number-of-totients-September-25-2026.pdf"}],"plainFr":"Le totient d'Euler compte les résidus premiers à un entier, et beaucoup d'entiers ne sont jamais atteints. Le manuscrit affirme un équivalent du nombre de valeurs distinctes jusqu'à x, et que ce nombre se dilate linéairement si x est multiplié par une constante positive.","plainEn":"Euler's totient counts residues coprime to an integer, and many integers are never hit. The manuscript asserts an equivalent for the number of distinct values up to x, and that this count scales linearly if x is multiplied by a positive constant.","expertFr":"Le manuscrit affirme un équivalent de V(x), nombre de totients distincts jusqu'à x, avec un facteur positif borné, limite uniforme de fonctions issues de données arithmétiques finies. Pour toute constante c positive, V de c x sur V de x tend vers c, réponse à la question d'échelle d'Erdős et Hall.","expertEn":"The manuscript asserts an equivalent for V(x), the number of distinct totients up to x, with a positive bounded factor, a uniform limit of functions from finite arithmetic data. For every positive constant c, V of c x over V of x tends to c, answering the scaling question of Erdős and Hall.","sparkFr":"Piste en calcul arithmétique : V(x) compte les valeurs distinctes d'une fonction élémentaire, sans algorithme nouveau affirmé.","sparkEn":"A reason to look in arithmetic computation: V(x) counts distinct values of an elementary function, with no new algorithm asserted."},{"id":"025","titleEn":"Short Egyptian fractions","titleFr":"Fractions égyptiennes courtes","claim":"Every rational a/b with 1≤ a b is a sum of O( b) distinct positive unit fractions. The worst-case minimum number of terms has the same order, resolving Erdős’s conjecture on short Egyptian fractions.","nature":"combinatoire","domain":"structures","complexity":"frontiere","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Short Egyptian fractions","href":"preprints/Short-Egyptian-fractions-September-25-2026/Short-Egyptian-fractions-September-25-2026.pdf"}],"plainFr":"Une fraction égyptienne écrit un rationnel comme somme d'inverses distincts. Le manuscrit affirme que tout rationnel a sur b de la plage considérée est une telle somme d'un nombre de termes de l'ordre de la racine de b, et que cet ordre est optimal.","plainEn":"An Egyptian fraction writes a rational as a sum of distinct reciprocals. The manuscript asserts that every rational a over b in the range considered is such a sum with order the square root of b terms, and that this order is sharp.","expertFr":"Le manuscrit affirme une conjecture d'Erdős : tout rationnel a sur b de la plage indiquée est somme d'un nombre d'ordre racine de b de fractions unitaires distinctes, et cet ordre est optimal. Le nombre de sommes de k termes égales à 1, et le plus petit entier au moins 2 absent comme dénominateur, croissent doublement exponentiellement en k.","expertEn":"The manuscript asserts a conjecture of Erdős: every rational a over b in the stated range is a sum of order square root of b distinct unit fractions, and this order is sharp. The number of k-term sums equal to 1, and the least integer at least 2 missing as a denominator, grow doubly exponentially in k.","sparkFr":"Piste combinatoire : décomposer un rationnel en inverses distincts est un problème d'écriture additive, sans usage industriel affirmé.","sparkEn":"A combinatorial reason to look: splitting a rational into distinct reciprocals is an additive writing problem, with no industrial use asserted."},{"id":"026","titleEn":"Positive lower density of large prime gaps","titleFr":"Densité inférieure positive des grands écarts entre nombres premiers","claim":"For every fixed C > 0, a positive proportion of consecutive prime gaps exceed C p_n, throughout every sufficiently large initial segment of the primes. The proportion may depend on C. Consequently, the indices where p_n/n increases have positive lower density, answering Erdős and Prachar.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Positive lower density of large prime gaps","href":"preprints/Positive-lower-density-of-large-prime-gaps-September-25-2026/main.pdf"}],"plainFr":"L'écart entre deux premiers consécutifs est parfois grand devant une échelle liée au plus petit. Le manuscrit affirme que, pour toute constante C, une proportion positive d'écarts dépasse le seuil en C, et que les places où le n-ième premier sur n augmente ont une densité inférieure positive.","plainEn":"The gap between consecutive primes is sometimes large on a scale tied to the smaller one. The manuscript asserts that for every constant C a positive proportion of gaps exceed the C-threshold, and that places where the n-th prime over n increases have positive lower density.","expertFr":"Le manuscrit affirme que pour tout C positif, une proportion positive des écarts de premiers consécutifs dépasse le seuil en C lié au plus petit premier, dans tout segment initial assez grand. Les indices où le n-ième premier divisé par n augmente ont donc une densité inférieure positive, réponse à Erdős et Prachar.","expertEn":"The manuscript asserts that for every positive C, a positive proportion of consecutive prime gaps exceed the C-threshold tied to the smaller prime, in every large enough initial segment. The indices where the n-th prime divided by n increases therefore have positive lower density, answering Erdős and Prachar.","sparkFr":"L'intérêt est structurel en théorie des nombres premiers : une densité d'écarts grands, sans modèle appliqué affirmé.","sparkEn":"The interest is structural inside prime number theory: a density of large gaps, with no applied model asserted."},{"id":"027","titleEn":"Potential integral density on curve character varieties","titleFr":"Densité intégrale potentielle des variétés de caractères","claim":"Resolves the determinant-one curve case of Litt's integral-density question. For every smooth connected complex algebraic curve and every rank, integral points become Zariski dense in every component of its SLr character variety over the full ring of integers of one number field. Prescribed quasi-unipotent boundary conjugacy classes are allowed, including nonsemisimple classes.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Integral points on character varieties of curves","href":"preprints/Integral-points-on-character-varieties-of-curves-September-25-2026/paper.pdf"}],"plainFr":"Une variété de caractères rassemble, à conjugaison près, les actions linéaires du groupe fondamental d'une courbe. Le manuscrit affirme que, pour tout rang, les points entiers deviennent denses au sens de Zariski dans chaque composante, sur les entiers d'un corps de nombres.","plainEn":"A character variety collects, up to conjugation, linear actions of the fundamental group of a curve. The manuscript asserts that in every rank, integral points become Zariski dense in every component, over the integers of one number field.","expertFr":"Le manuscrit affirme le cas de déterminant un de la question de Litt : pour toute courbe complexe lisse connexe et tout rang, les points entiers sont Zariski denses dans chaque composante de la variété de caractères, sur l'anneau des entiers d'un corps de nombres. Les classes de bord quasi-unipotentes, même non semi-simples, sont permises.","expertEn":"The manuscript asserts the determinant-one case of Litt's question: for every smooth connected complex curve and every rank, integral points are Zariski dense in every component of the character variety over the integers of one number field. Quasi-unipotent boundary classes, including nonsemisimple ones, are allowed.","sparkFr":"Piste topologique : ces variétés classent des représentations linéaires du groupe fondamental d'une courbe, sans application physique affirmée.","sparkEn":"A topological reason to look: these varieties classify linear representations of a curve's fundamental group, with no physical application asserted."},{"id":"028","titleEn":"Uniformly bounded components of Gaussian-prime graphs","titleFr":"La conjecture du fossé gaussien","claim":"Proves the Gaussian moat conjecture: no infinite walk through distinct Gaussian primes can have uniformly bounded steps. More strongly, for every distance bound D, the graph joining Gaussian primes at distance at most D has uniformly bounded finite component sizes, depending only on D, including primes on the coordinate axes.","nature":"nombres","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"Bounded-Step Walks on Gaussian Primes","href":"preprints/Bounded-Step-Walks-on-Gaussian-Primes-September-26-2026/paper.pdf"}],"plainFr":"Les premiers de Gauss sont les éléments premiers du quadrillage des entiers complexes. Le manuscrit affirme qu'aucun chemin infini à pas bornés ne joint des premiers distincts, et que chaque borne de distance limite la taille des composantes.","plainEn":"Gaussian primes are the prime elements in the grid of complex integers. The manuscript asserts that no infinite path of bounded steps joins distinct primes, and that each distance bound limits the size of the components.","expertFr":"Le manuscrit affirme la conjecture du fossé gaussien, axes compris : pour chaque borne de distance, les composantes du graphe des premiers de Gauss ont une taille bornée ne dépendant que de cette borne. La borne n'est pas explicite ; le résumé invoque un crible périodique fini, par échantillonnage et estimations d'information.","expertEn":"The manuscript asserts the Gaussian moat conjecture, axes included: for each distance bound, components of the Gaussian-prime graph have size bounded in terms of that bound alone. The bound is not explicit; the abstract invokes a finite periodic sieve, by sampling and information estimates.","sparkFr":"Piste indiquée par le résumé : un crible géométrique et des estimations d'information pour bloquer les longues marches.","sparkEn":"A reason to look, as the abstract indicates: a geometric sieve and information estimates used to block long walks."},{"id":"029","titleEn":"Primitive roots for every admissible integer base","titleFr":"Racines primitives pour toute base entière admissible","claim":"Proves the infinitude assertion in Artin's primitive root conjecture for every integer a that is neither −1 nor a square. For each such base, at least c_a x/( x)^2 primes in every sufficiently large interval (x,2x) have primitive root a, with c_a 0.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1927,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Primitive roots for every admissible integer base","href":"preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/primitive-roots-all-integer-bases.pdf"},{"title":"Simultaneous primitive roots: a conditional lower bound for prime bases","href":"preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf"}],"plainFr":"Une racine primitive modulo un premier engendre tous les résidus non nuls par ses puissances. Le manuscrit affirme l'infinitude d'Artin : si la base n'est ni moins un ni un carré, beaucoup de premiers de chaque grand intervalle du simple au double ont cette base pour racine primitive.","plainEn":"A primitive root modulo a prime generates every nonzero residue by its powers. The manuscript asserts Artin's infinitude: if the base is neither minus one nor a square, many primes in each large interval from x to 2x have that base as primitive root.","expertFr":"Le manuscrit affirme l'infinitude dans la conjecture d'Artin pour tout entier qui n'est ni moins un ni un carré. Pour chaque telle base, tout intervalle assez grand de x à 2x contient au moins une constante positive fois x sur le carré d'un logarithme de premiers ayant cette racine primitive.","expertEn":"The manuscript asserts the infinitude in Artin's conjecture for every integer that is neither minus one nor a square. For each such base, every large enough interval from x to 2x contains at least a positive constant times x over a squared logarithm of primes with that primitive root.","sparkFr":"L'intérêt est structurel en théorie algorithmique des nombres : l'existence de générateurs multiplicatifs modulo des premiers.","sparkEn":"The interest is structural inside algorithmic number theory: the existence of multiplicative generators modulo primes."},{"id":"030","titleEn":"Modularity of elliptic curves over imaginary quadratic fields","titleFr":"Modularité des courbes elliptiques sur les corps quadratiques imaginaires","claim":"Proves the modularity conjecture for elliptic curves over imaginary quadratic fields: every elliptic curve over every imaginary quadratic field is modular, with matching local parameters at every place.","nature":"nombres","domain":"calcul","complexity":"avance","problemYear":1965,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Modularity of elliptic curves over imaginary quadratic fields","href":"preprints/Modularity-of-elliptic-curves-over-imaginary-quadratic-fields-October-4-2026/paper.pdf"}],"plainFr":"Une courbe elliptique sur un corps quadratique imaginaire est une cubique à coefficients dans un corps de nombres non réel. Le manuscrit affirme que chacune est modulaire, avec des paramètres locaux qui coïncident en toute place.","plainEn":"An elliptic curve over an imaginary quadratic field is a cubic with coefficients in a number field that is not real. The manuscript asserts that each one is modular, with local parameters that match at every place.","expertFr":"Le manuscrit affirme la conjecture de modularité des courbes elliptiques sur les corps quadratiques imaginaires : toute telle courbe, sur tout tel corps, est modulaire. Les paramètres locaux coïncident en toute place.","expertEn":"The manuscript asserts the modularity conjecture for elliptic curves over imaginary quadratic fields: every such curve, over every such field, is modular. The local parameters match at every place.","sparkFr":"Piste vers Langlands : la modularité identifie la courbe à des données automorphes, sans procédure de calcul affirmée.","sparkEn":"A reason to look toward Langlands: modularity identifies the curve with automorphic data, with no computational procedure asserted."},{"id":"031","titleEn":"Uchida’s conjecture for open homomorphisms of Galois groups","titleFr":"Conjecture d'Uchida pour les homomorphismes ouverts de Galois","claim":"Proves Uchida's conjecture: every continuous open homomorphism between Galois groups of possibly infinite solvably closed Galois extensions of number fields comes from a unique equivariant field embedding in the opposite direction. No restriction on the kernel or separate cyclotomic-compatibility assumption is needed.","nature":"nombres","domain":"formes","complexity":"avance","problemYear":1832,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"Open Homomorphisms of Global Solvably Closed Galois Groups","href":"preprints/Open-Homomorphisms-of-Global-Solvably-Closed-Galois-Groups-October-5-2026/open-homomorphisms-solvably-closed-galois-groups.pdf"}],"plainFr":"Le groupe de Galois d'un corps de nombres enregistre les symétries de ses extensions. Le manuscrit affirme que tout homomorphisme continu ouvert entre groupes de Galois d'extensions solvablement closes provient d'un unique plongement de corps en sens inverse.","plainEn":"The Galois group of a number field records the symmetries of its extensions. The manuscript asserts that every continuous open homomorphism between Galois groups of solvably closed extensions comes from a unique field embedding in the opposite direction.","expertFr":"Le manuscrit affirme la conjecture d'Uchida : tout homomorphisme continu ouvert entre groupes de Galois d'extensions galoisiennes solvablement closes de corps de nombres est induit par un unique plongement de corps équivariant en sens opposé. Ni restriction sur le noyau ni compatibilité cyclotomique séparée n'est requise.","expertEn":"The manuscript asserts Uchida's conjecture: every continuous open homomorphism between Galois groups of solvably closed Galois extensions of number fields is induced by a unique equivariant field embedding in the opposite direction. Neither a kernel restriction nor a separate cyclotomic compatibility is required.","sparkFr":"L'intérêt est structurel en géométrie anabélienne : reconstruire un plongement de corps depuis un homomorphisme galoisien.","sparkEn":"The interest is structural inside anabelian geometry: reconstructing a field embedding from a Galois homomorphism."},{"id":"032","titleEn":"The rational Hodge conjecture for CM abelian varieties","titleFr":"Conjecture de Hodge rationnelle pour les variétés abéliennes à multiplication complexe","claim":"Proves the rational Hodge conjecture for every complex CM abelian variety, in every dimension and codimension. Through Milne's theorems, this also gives the Tate conjecture for all abelian varieties over finite fields and the Hodge standard conjecture for abelian varieties in every characteristic.","nature":"geometrie-algebrique","domain":"calcul","complexity":"frontiere","problemYear":1950,"yearKnown":true,"manuscriptDate":"2026-09-10","lean":false,"pdfs":[{"title":"The rational Hodge conjecture for CM abelian varieties","href":"preprints/The-rational-Hodge-conjecture-for-CM-abelian-varieties-October-6-2026/paper.pdf"},{"title":"Algebraic Kuga–Satake correspondences and Hodge conjectures on a K3 quadratic locus","href":"preprints/Algebraic-Kuga-Satake-correspondences-and-Hodge-conjectures-on-a-K3-quadratic-locus-September-30-2026/paper.pdf"},{"title":"Weil classes and Hodge classes on abelian powers","href":"preprints/Weil-classes-and-Hodge-classes-on-abelian-powers-October-6-2026/paper.pdf"},{"title":"Abelian covers, Gale correspondences, and the Hodge conjecture for powers","href":"preprints/Abelian-covers-Gale-correspondences-and-the-Hodge-conjecture-for-powers-October-6-2026/paper.pdf"},{"title":"A Conditional Reduction for Algebraic Kuga–Satake Correspondences","href":"preprints/A-Conditional-Reduction-for-Algebraic-Kuga-Satake-Correspondences-September-10-2026/paper.pdf"}],"plainFr":"Une classe de Hodge se comporte comme la classe d'une sous-variété algébrique. Le manuscrit affirme que, sur toute variété abélienne complexe à multiplication complexe, elle est combinaison rationnelle de cycles, avec la conjecture de Tate sur les corps finis pour conséquence.","plainEn":"A Hodge class behaves like the class of an algebraic subvariety. The manuscript asserts that on every complex abelian variety with complex multiplication it is a rational combination of cycles, with the Tate conjecture over finite fields as a consequence.","expertFr":"Le manuscrit affirme la conjecture de Hodge rationnelle pour toute variété abélienne complexe à multiplication complexe, en toute dimension et codimension. Par les théorèmes de Milne, il en tire la conjecture de Tate sur les corps finis, la forme généralisée dans le cas à multiplication complexe, et la conjecture standard de Hodge en toute caractéristique.","expertEn":"The manuscript asserts the rational Hodge conjecture for every complex abelian variety with complex multiplication, in every dimension and codimension. Through Milne's theorems it obtains the Tate conjecture over finite fields, the generalized form in the complex-multiplication case, and the Hodge standard conjecture in every characteristic.","sparkFr":"L'intérêt est structurel en géométrie algébrique : quelles classes de cohomologie proviennent de cycles algébriques.","sparkEn":"The interest is structural inside algebraic geometry: which cohomology classes come from algebraic cycles."},{"id":"033","titleEn":"Iitaka subadditivity, variation, and logarithmic additivity","titleFr":"Sous-additivité d'Iitaka orbifolde, variation et additivité logarithmique","claim":"Proves Campana's orbifold Iitaka subadditivity conjecture for smooth Fujiki-class-C manifolds with rational simple-normal-crossing boundaries. For projective fibrations f:U→ V of smooth complex quasi-projective varieties with connected fibers, general fiber F, and (V)≥0, proves Popa's inequality (U)≥ (F)+ \\ (V), Var (f)\\, where variation measures the whole geometric generic fiber.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1990,"yearKnown":false,"manuscriptDate":"2026-09-10","lean":true,"pdfs":[{"title":"Orbifold and logarithmic Iitaka subadditivity","href":"preprints/Orbifold-and-logarithmic-Iitaka-subadditivity-September-26-2026/paper.pdf"},{"title":"Logarithmic Kodaira dimension and whole-fiber variation","href":"preprints/Logarithmic-Kodaira-dimension-and-whole-fiber-variation-September-26-2026/paper.pdf"},{"title":"The reverse logarithmic Kodaira inequality and additivity","href":"preprints/The-reverse-logarithmic-Kodaira-inequality-and-additivity-September-26-2026/paper.pdf"},{"title":"Projective Hodge lines and ordinary Iitaka subadditivity","href":"preprints/Projective-Hodge-lines-and-ordinary-Iitaka-subadditivity-September-27-2026/paper.pdf"},{"title":"B-semiampleness for compact log-smooth Kähler fibrations","href":"preprints/B-semiampleness-for-compact-log-smooth-Kahler-fibrations-September-10-2026/paper.pdf"}],"plainFr":"La dimension de Kodaira mesure l'abondance du fibré canonique d'une variété. Le manuscrit affirme la sous-additivité d'Iitaka orbifolde de Campana pour certaines variétés à bord, et une inégalité de Popa pour une fibration, sa fibre et sa base.","plainEn":"The Kodaira dimension measures how ample the canonical bundle of a variety is. The manuscript asserts Campana's orbifold Iitaka subadditivity for certain manifolds with boundary, and a Popa inequality for a fibration, its fiber, and its base.","expertFr":"Le manuscrit affirme la sous-additivité d'Iitaka orbifolde de Campana pour les variétés de classe de Fujiki C à bord rationnel à croisements normaux, coefficient un inclus ; les cas ordinaire et logarithmique suivent. Pour les fibrations projectives à fibres connexes et base de dimension de Kodaira positive ou nulle, il affirme l'inégalité de Popa entre total, fibre et variation.","expertEn":"The manuscript asserts Campana's orbifold Iitaka subadditivity for Fujiki class C manifolds with rational normal-crossings boundary, coefficient one included; ordinary and logarithmic cases follow. For projective fibrations with connected fibers and base of nonnegative Kodaira dimension, it asserts Popa's inequality among total space, fiber, and variation.","sparkFr":"L'intérêt est structurel dans le programme des modèles minimaux : comment la dimension de Kodaira se comporte en famille.","sparkEn":"The interest is structural inside the minimal model program: how Kodaira dimension behaves in families."},{"id":"034","titleEn":"Log abundance for compact Kähler spaces under logarithmic Iitaka subadditivity","titleFr":"Abondance logarithmique des espaces de Kähler compacts","claim":"Using logarithmic Iitaka subadditivity, proves log abundance in every dimension for normal compact Kähler log canonical pairs with effective rational boundary: an analytically nef ℚ-Cartier adjoint is semiample. It also proves projective log abundance over every algebraically closed field of characteristic zero and the effective Iitaka fibration conjecture for smooth projective varieties of nonnegative Kodaira dimension in that setting. A further result resolves the finite-rational-coefficient index conjecture for ","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1985,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Log abundance for compact Kähler spaces under logarithmic Iitaka subadditivity","href":"preprints/Log-abundance-for-compact-Kahler-spaces-under-logarithmic-Iitaka-subadditivity-October-6-2026/main.pdf"},{"title":"Uniform indices for semi-log-canonical log Calabi–Yau pairs","href":"preprints/Uniform-indices-for-semi-log-canonical-log-Calabi-Yau-pairs-October-5-2026/uniform-slc-index.pdf"},{"title":"Conditional good minimal models for compact Kähler fourfolds","href":"preprints/Conditional-good-minimal-models-for-compact-Kahler-fourfolds-October-6-2026/paper.pdf"},{"title":"Log abundance in characteristic zero","href":"preprints/Log-abundance-in-characteristic-zero-September-24-2026/paper.pdf"},{"title":"Minimal metrics and interior injectivity for nef adjoints","href":"preprints/Minimal-metrics-and-interior-injectivity-for-nef-adjoints-September-27-2026/paper.pdf"},{"title":"Fourfold nonvanishing by minimal metrics and moving jets","href":"preprints/Fourfold-nonvanishing-by-minimal-metrics-and-moving-jets-September-27-2026/paper.pdf"}],"plainFr":"L'abondance demande si un diviseur canonique numériquement positif définit une application. Le manuscrit affirme, via la sous-additivité logarithmique d'Iitaka, qu'un adjoint nef sur un espace de Kähler log canonique à bord rationnel est semi-ample en toute dimension.","plainEn":"Abundance asks whether a numerically positive canonical divisor defines a map. The manuscript asserts, via logarithmic Iitaka subadditivity, that a nef adjoint on a log canonical Kähler space with rational boundary is semiample in every dimension.","expertFr":"Via la sous-additivité d'Iitaka logarithmique, le manuscrit affirme l'abondance en toute dimension : sur une paire de Kähler compacte log canonique à bord rationnel, un adjoint nef et rationnellement de Cartier est semi-ample. Il affirme aussi l'abondance projective en caractéristique nulle et la fibration d'Iitaka effective si la dimension de Kodaira est positive ou nulle.","expertEn":"Via logarithmic Iitaka subadditivity, the manuscript asserts abundance in every dimension: on a compact Kähler log canonical pair with rational boundary, a nef and rationally Cartier adjoint is semiample. It also asserts projective abundance in characteristic zero and the effective Iitaka fibration when the Kodaira dimension is nonnegative.","sparkFr":"L'intérêt est structurel dans le programme des modèles minimaux : passer d'une positivité numérique à une application.","sparkEn":"The interest is structural inside the minimal model program: passing from numerical positivity to a map."},{"id":"035","titleEn":"Log-canonical threefold abundance in numerical dimension one","titleFr":"Abondance log canonique des solides en dimension numérique un","claim":"Proves log abundance for projective log canonical threefold pairs over algebraically closed fields of characteristic p > 3 when the effective boundary is rational and the ℚ-Cartier adjoint is nef of numerical dimension one. The adjoint is semiample, without requiring the original variety to be terminal or ℚ-factorial.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1985,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Log abundance in numerical dimension one for threefolds in positive characteristic","href":"preprints/Log-abundance-in-numerical-dimension-one-for-threefolds-in-positive-characteristic-October-5-2026/paper.pdf"},{"title":"Abundance in numerical dimension one for terminal threefolds in positive characteristic","href":"preprints/Abundance-in-numerical-dimension-one-for-terminal-threefolds-in-positive-characteristic-September-24-2026/paper.pdf"}],"plainFr":"En dimension trois, l'abondance prédit qu'un diviseur adjoint numériquement positif est semi-ample. Le manuscrit affirme cet énoncé si la dimension numérique vaut un, le bord rationnel est effectif, la paire est log canonique et la caractéristique dépasse trois.","plainEn":"In dimension three, abundance predicts that a numerically positive adjoint divisor is semiample. The manuscript asserts this when the numerical dimension is one, the rational boundary is effective, the pair is log canonical, and the characteristic exceeds three.","expertFr":"Le manuscrit affirme l'abondance logarithmique des solides projectifs log canoniques en caractéristique supérieure à trois, si le bord effectif est rationnel et l'adjoint, rationnellement de Cartier, est nef de dimension numérique un. Il est alors semi-ample, sans hypothèse terminale ni de factorialité rationnelle.","expertEn":"The manuscript asserts logarithmic abundance for projective log canonical threefolds in characteristic greater than three, when the effective boundary is rational and the rationally Cartier adjoint is nef of numerical dimension one. It is then semiample, with no terminal or rational-factoriality hypothesis.","sparkFr":"L'intérêt est structurel en géométrie birationnelle de dimension trois : un cas d'abondance en caractéristique positive.","sparkEn":"The interest is structural inside threefold birational geometry: a case of abundance in positive characteristic."},{"id":"036","titleEn":"Numerical semiampleness and generalized minimal models","titleFr":"Semi-amplitude numérique et modèles minimaux généralisés","claim":"Proves numerical semiampleness for nef adjoints K_X+B+M with K_X+B pseudo-effective and M nef rational, for projective klt rational pairs over algebraically closed characteristic-zero fields and smooth compact Kähler rational klt simple-normal-crossing pairs, using Bott–Chern cohomology in the latter case. Separately, projective generalized log canonical rational pairs over such fields admit minimal models for pseudo-effective adjoints and Mori fiber spaces otherwise, with nef b-data fixed.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Numerical semiampleness of nef adjoint classes on compact Kähler manifolds","href":"preprints/Numerical-semiampleness-of-nef-adjoint-classes-on-compact-Kahler-manifolds-October-6-2026/numerical-generalized-abundance.pdf"},{"title":"Numerical Semiampleness of Nef Adjoint Divisors","href":"preprints/Numerical-Semiampleness-of-Nef-Adjoint-Divisors-October-3-2026/paper.pdf"},{"title":"Minimal models and Mori fibre spaces for generalized log canonical Q-pairs","href":"preprints/Minimal-models-and-Mori-fibre-spaces-for-generalized-log-canonical-Q-pairs-September-24-2026/paper.pdf"},{"title":"Minimal models in numerical dimension one","href":"preprints/Minimal-models-in-numerical-dimension-one-September-24-2026/paper.pdf"}],"plainFr":"Un programme de modèles minimaux simplifie une variété en contractant des courbes de courbure négative. Le manuscrit affirme une semi-amplitude numérique pour certains adjoints en caractéristique nulle, et des modèles minimaux ou des fibrations de Mori pour des paires généralisées.","plainEn":"A minimal model program simplifies a variety by contracting curves of negative curvature. The manuscript asserts numerical semiampleness for certain adjoints in characteristic zero, and minimal models or Mori fibrations for generalized pairs.","expertFr":"Le manuscrit affirme la semi-amplitude numérique de l'adjoint nef si le canonique plus le bord est pseudo-effectif, pour les paires klt projectives en caractéristique nulle et les paires klt kählériennes lisses, via Bott–Chern. Le cas kählérien ne porte pas sur le fibré original ; les paires généralisées projectives ont un modèle minimal ou un espace de Mori, données nef fixes.","expertEn":"The manuscript asserts numerical semiampleness of the nef adjoint when the canonical plus boundary is pseudo-effective, for projective klt pairs in characteristic zero and smooth Kähler klt pairs, via Bott–Chern. The Kähler case is not about the original bundle; projective generalized pairs have a minimal model or a Mori space, with fixed nef data.","sparkFr":"L'intérêt est structurel dans le programme des modèles minimaux, y compris dans le cadre kählérien.","sparkEn":"The interest is structural inside the minimal model program, including in the Kähler setting."},{"id":"037","titleEn":"The ordinary-double-point volume gap","titleFr":"Écart de volume des points doubles ordinaires","claim":"Proves the ordinary-double-point volume-gap conjecture: every singular complex algebraic klt germ of dimension n ≥ 2, with zero boundary, has normalized volume at most 2(n-1)^n. Equality holds precisely for an analytic ordinary double point.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The ordinary-double-point gap in every dimension","href":"preprints/The-ordinary-double-point-gap-in-every-dimension-September-24-2026/paper.pdf"},{"title":"The normalized-volume gap in dimension four","href":"preprints/The-normalized-volume-gap-in-dimension-four-September-24-2026/paper.pdf"}],"plainFr":"Le volume normalisé mesure la sévérité d'une singularité isolée. Le manuscrit affirme qu'un germe complexe singulier de dimension n au moins 2, sans bord, a un volume au plus 2 fois (n moins 1) puissance n, avec égalité pour un point double ordinaire.","plainEn":"Normalized volume measures how severe an isolated singularity is. The manuscript asserts that a singular complex germ of dimension n at least 2, with no boundary, has volume at most 2 times (n minus 1) to the n, with equality for an ordinary double point.","expertFr":"Le manuscrit affirme la conjecture d'écart du point double ordinaire : tout germe algébrique complexe klt singulier de dimension n au moins 2, à bord nul, a un volume normalisé au plus 2 fois (n moins 1) puissance n. L'égalité a lieu précisément pour un point double ordinaire analytique.","expertEn":"The manuscript asserts the ordinary-double-point gap conjecture: every singular complex algebraic klt germ of dimension n at least 2, with zero boundary, has normalized volume at most 2 times (n minus 1) to the n. Equality holds precisely for an analytic ordinary double point.","sparkFr":"Piste en stabilité locale : le volume normalisé compare les singularités en K-stabilité, sans application affirmée ici.","sparkEn":"A reason to look in local stability: normalized volume compares singularities in K-stability, with no application asserted here."},{"id":"038","titleEn":"Fujita’s freeness conjecture","titleFr":"Conjecture de liberté de Fujita","claim":"Proves Fujita's freeness conjecture at its sharp bound in every dimension: for a smooth projective complex variety X of dimension n and an ample line bundle L, the adjoint K_X+mL is globally generated for every integer m≥ n+1.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Fujita's freeness conjecture","href":"preprints/Fujitas-freeness-conjecture-September-23-2026/Fujitas-freeness-conjecture-September-23-2026.pdf"}],"plainFr":"Un fibré adjoint tord le fibré canonique par un fibré ample. Le manuscrit affirme la conjecture de Fujita à la borne optimale : en dimension n, au moins n plus un copies du fibré ample rendent l'adjoint engendré par ses sections.","plainEn":"An adjoint bundle twists the canonical bundle by an ample bundle. The manuscript asserts Fujita's conjecture at the sharp bound: in dimension n, at least n plus one copies of the ample bundle make the adjoint generated by its sections.","expertFr":"Le manuscrit affirme la conjecture de liberté de Fujita en toute dimension : sur une variété projective complexe lisse de dimension n, l'adjoint du canonique par m fois un fibré ample est globalement engendré dès que m vaut au moins n plus un. La borne est présentée comme optimale.","expertEn":"The manuscript asserts Fujita's freeness conjecture in every dimension: on a smooth complex projective variety of dimension n, the adjoint of the canonical bundle by m times an ample line bundle is globally generated once m is at least n plus one. The bound is presented as sharp.","sparkFr":"L'intérêt est structurel en géométrie algébrique : engendrer le fibré canonique tordu par un fibré ample.","sparkEn":"The interest is structural inside algebraic geometry: generating the canonical bundle twisted by an ample bundle."},{"id":"039","titleEn":"Nagata’s conjecture and maximal Seshadri constants","titleFr":"Conjecture de Nagata et constantes de Seshadri maximales","claim":"Proves Nagata's strict inequality _i m_i d r for every nonzero effective plane curve of degree d through r ≥ 10 very general complex points, with arbitrary multiplicities mi. It also proves maximal multipoint Seshadri constants (L^n/r)^1/n for every smooth polarized projective variety of dimension n ≥ 2 and all sufficiently large r: at very general points over ℂ, and at the geometric generic tuple over any algebraically closed field of positive characteristic.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Nagata's conjecture for plane curves","href":"preprints/Nagatas-Conjecture-for-Plane-Curves-September-23-2026/main.pdf"},{"title":"Maximal Seshadri constants on arbitrary polarized surfaces","href":"preprints/Maximal-Seshadri-Constants-on-Arbitrary-Polarized-Surfaces-September-23-2026/main.pdf"},{"title":"Maximal Multipoint Seshadri Constants in Higher Dimensions","href":"preprints/Maximal-Multipoint-Seshadri-Constants-in-Higher-Dimensions-October-5-2026/main.pdf"},{"title":"Maximal multipoint Seshadri constants in positive characteristic","href":"preprints/Maximal-multipoint-Seshadri-constants-in-positive-characteristic-October-5-2026/seshadri-positive-characteristic.pdf"}],"plainFr":"La conjecture de Nagata borne la multiplicité d'une courbe plane en des points très généraux. Le manuscrit affirme l'inégalité stricte dès dix points, et des constantes de Seshadri multipoints maximales en dimension au moins deux, pour tout grand nombre de points.","plainEn":"Nagata's conjecture bounds the multiplicity of a plane curve at very general points. The manuscript asserts the strict inequality from ten points on, and maximal multipoint Seshadri constants in dimension at least two, for every large number of points.","expertFr":"Le manuscrit affirme l'inégalité stricte de Nagata : la multiplicité totale d'une courbe plane de degré d en au moins dix points très généraux est strictement inférieure à d fois la racine de r. Il affirme aussi les constantes de Seshadri multipoints maximales, racine n-ième du volume sur r, pour tout r assez grand en dimension au moins deux.","expertEn":"The manuscript asserts Nagata's strict inequality: the total multiplicity of a degree-d plane curve at ten or more very general points is strictly less than d times the square root of r. It also asserts maximal multipoint Seshadri constants, the n-th root of the volume over r, in dimension at least two for all large r.","sparkFr":"L'intérêt est structurel en géométrie des points imposés : combien de fois une courbe peut passer par des points généraux.","sparkEn":"The interest is structural inside the geometry of imposed points: how often a curve can pass through general points."},{"id":"040","titleEn":"Bloch’s conjecture for complex surfaces","titleFr":"Conjecture de Bloch pour les surfaces complexes","claim":"Proves Bloch's conjecture: for every smooth connected projective complex surface S with p_g(S)=0, the Albanese map CH_0(S)^0 (S)( C) on integral degree-zero zero-cycles is an isomorphism. This combines the new p_g=q=0 theorem with the classical theorem of Bloch, Kas, and Lieberman.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1980,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Bloch’s conjecture for surfaces with p_g=0","href":"preprints/Blochs-Conjecture-for-Surfaces-with-pg-equals-q-equals-0-September-24-2026/paper.pdf"}],"plainFr":"Les zéro-cycles sont des combinaisons formelles de points d'une surface, à équivalence rationnelle près. Le manuscrit affirme la conjecture de Bloch : si le genre géométrique est nul, les cycles de degré zéro sont exactement lus par l'application d'Albanese.","plainEn":"Zero-cycles are formal combinations of points on a surface, up to rational equivalence. The manuscript asserts Bloch's conjecture: if the geometric genus is zero, degree-zero cycles are read exactly by the Albanese map.","expertFr":"Le manuscrit affirme la conjecture de Bloch : sur toute surface projective complexe lisse connexe de genre géométrique nul, l'application d'Albanese des zéro-cycles de degré zéro est un isomorphisme. Le texte réunit un théorème nouveau à irrégularité nulle et le théorème classique de Bloch, Kas et Lieberman.","expertEn":"The manuscript asserts Bloch's conjecture: on every smooth connected projective complex surface of geometric genus zero, the Albanese map on degree-zero zero-cycles is an isomorphism. The text joins a new theorem at irregularity zero with the classical theorem of Bloch, Kas, and Lieberman.","sparkFr":"L'intérêt est structurel en géométrie algébrique : relier les combinaisons de points à une variété abélienne associée.","sparkEn":"The interest is structural inside algebraic geometry: relating combinations of points to an associated abelian variety."},{"id":"041","titleEn":"Hyperkähler SYZ and projective-space bases","titleFr":"Conjecture SYZ hyperkählérienne et bases projectives","claim":"Proves the strong hyperkähler SYZ conjecture: every holomorphic line bundle with nonzero nef isotropic first Chern class on a compact irreducible holomorphic symplectic Kähler manifold is semiample. It also proves that every projective Lagrangian fibration with normal projective base has projective space as its base, in every dimension and deformation type.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1996,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Projective-space bases of Lagrangian fibrations","href":"preprints/Projective-Space-Bases-of-Lagrangian-Fibrations-September-23-2026/main.pdf"},{"title":"The strong hyperkähler SYZ conjecture","href":"preprints/The-Strong-Hyperkahler-SYZ-Conjecture-September-23-2026/main.pdf"}],"plainFr":"Une variété holomorphiquement symplectique généralise une surface K3 en plus grande dimension. Le manuscrit affirme qu'un fibré nef isotrope sur une telle variété compacte est semi-ample, et que la base d'une fibration lagrangienne projective est un espace projectif.","plainEn":"A holomorphic symplectic manifold generalizes a K3 surface to higher dimension. The manuscript asserts that a nef isotropic line bundle on such a compact manifold is semiample, and that the base of a projective Lagrangian fibration is projective space.","expertFr":"Le manuscrit affirme la conjecture SYZ hyperkählérienne forte : un fibré holomorphe de classe de Chern nef, isotrope et non nulle, sur une variété kählérienne compacte irréductible holomorphiquement symplectique, est semi-ample. Toute fibration lagrangienne projective à base projective normale a pour base un espace projectif, en toute dimension et tout type de déformation.","expertEn":"The manuscript asserts the strong hyperkähler SYZ conjecture: a holomorphic bundle with nonzero nef isotropic Chern class, on a compact irreducible holomorphic symplectic Kähler manifold, is semiample. Every projective Lagrangian fibration with normal projective base has projective space as base, in every dimension and deformation type.","sparkFr":"Piste en symétrie miroir : SYZ propose des miroirs par des fibrations lagrangiennes, et le manuscrit affirme une semi-amplitude de cette conjecture.","sparkEn":"A reason to look in mirror symmetry: SYZ proposes mirrors by Lagrangian fibrations, and the manuscript asserts a semiampleness form of that conjecture."},{"id":"042","titleEn":"Oka classification for minimal compact complex surfaces: Kodaira dimension zero and class VII","titleFr":"Classification d'Oka : dimension de Kodaira nulle et classe VII","claim":"Proves that every complex K3 surface is Oka, including nonprojective surfaces. More generally, every connected minimal compact complex surface of Kodaira dimension zero is Oka; a connected minimal compact complex surface of class VII is Oka exactly when it is a Hopf or Enoki surface.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":1954,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Every complex K3 surface is Oka","href":"preprints/Every-complex-K3-surface-is-Oka-September-23-2026/paper.pdf"}],"plainFr":"Une variété d'Oka approche les applications holomorphes locales par des applications entières. Le manuscrit affirme que toute surface K3 est d'Oka, ainsi que les surfaces minimales de dimension de Kodaira nulle, et celles de classe VII seulement si elles sont de Hopf ou d'Enoki.","plainEn":"An Oka manifold approximates local holomorphic maps by entire maps. The manuscript asserts that every K3 surface is Oka, as are minimal surfaces of Kodaira dimension zero, and class VII surfaces only when they are Hopf or Enoki surfaces.","expertFr":"Le manuscrit affirme que toute surface K3 complexe, même non projective, est d'Oka : les applications holomorphes locales s'approchent par des applications entières. Toute surface minimale de dimension de Kodaira nulle l'est aussi, et une surface minimale de classe VII l'est exactement si elle est de Hopf ou d'Enoki.","expertEn":"The manuscript asserts that every complex K3 surface, even nonprojective, is Oka: local holomorphic maps are approximated by entire maps. Every minimal surface of Kodaira dimension zero is Oka too, and a minimal class VII surface is Oka exactly when it is Hopf or Enoki.","sparkFr":"Piste en analyse complexe : le principe d'Oka est une flexibilité holomorphe, du type du h-principe, sans usage affirmé hors des mathématiques.","sparkEn":"A reason to look in complex analysis: the Oka principle is a holomorphic flexibility, of h-principle type, with no use asserted outside mathematics."},{"id":"043","titleEn":"P = W for fixed-determinant SLn moduli spaces","titleFr":"Égalité P égale W pour les modules de Higgs à déterminant fixé","claim":"Proves P_k=W_2k=W_2k+1 on the full rational cohomology of smooth coprime fixed-determinant, trace-free Higgs moduli spaces and their character varieties for composite ranks over smooth projective complex curves of genus at least two. This includes variant cohomology and, together with the known prime-rank theorems, establishes the fixed-determinant P = W conjecture in every coprime rank.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"P=W in composite rank for fixed determinant","href":"preprints/P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026/P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026.pdf"}],"plainFr":"Les modules de Higgs et les variétés de caractères sont deux habitats des systèmes locaux sur une courbe. Le manuscrit affirme que deux filtrations de leur cohomologie rationnelle, dites P et W, coïncident à déterminant fixé lorsque le degré est premier au rang.","plainEn":"Higgs moduli and character varieties are two homes for local systems on a curve. The manuscript asserts that two filtrations of their rational cohomology, called P and W, coincide at fixed determinant when the degree is coprime to the rank.","expertFr":"Le manuscrit affirme que la filtration P en degré k égale les crans pairs et impairs voisins de la filtration W, sur la cohomologie des modules de Higgs lisses à déterminant fixé, de rang composé et de degré premier au rang. Avec les rangs premiers connus, cela donne P égale W à déterminant fixé en tout rang premier au degré.","expertEn":"The manuscript asserts that the P filtration in degree k equals the neighboring even and odd steps of the W filtration, on the cohomology of smooth fixed-determinant Higgs moduli of composite rank and coprime degree. With the known prime ranks, this gives fixed-determinant P equals W in every coprime rank.","sparkFr":"Piste en théorie de Hodge non abélienne : l'égalité rapproche une filtration perverse et la filtration par le poids.","sparkEn":"A reason to look in nonabelian Hodge theory: the equality matches a perverse filtration with the weight filtration."},{"id":"044","titleEn":"The equivariant cohomological Hikita conjecture","titleFr":"Conjecture cohomologique équivariante de Hikita","claim":"Proves the equivariant cohomological Hikita correspondence for every finite quiver, including loops and multiple arrows, with arbitrary dimension and framing vectors and commuting flavor torus. When every semistable point is stable and the gauge action is free, the equivariant cohomology of the Nakajima variety is canonically the coordinate ring of the scheme-theoretic cocharacter-fixed locus of its flavor-deformed Coulomb branch.","nature":"algebre","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The equivariant cohomological Hikita conjecture for arbitrary quivers","href":"preprints/The-equivariant-cohomological-Hikita-conjecture-for-arbitrary-quivers-September-24-2026/main.pdf"}],"plainFr":"Les variétés de Nakajima et les branches de Coulomb sont deux constructions attachées à un diagramme de flèches. Le manuscrit affirme que, sous une hypothèse de liberté, la cohomologie équivariante de la première est l'anneau du lieu fixe de la seconde.","plainEn":"Nakajima varieties and Coulomb branches are two constructions attached to a diagram of arrows. The manuscript asserts that, under a freeness hypothesis, the equivariant cohomology of the first is the coordinate ring of a fixed locus of the second.","expertFr":"Le manuscrit affirme la conjecture de Hikita cohomologique équivariante pour tout carquois fini, boucles comprises, avec dimensions, cadrages et tore de saveur arbitraires. Si le lieu semi-stable est stable et l'action de jauge libre, la cohomologie de Nakajima est l'anneau du lieu fixe schématique de la branche de Coulomb déformée, nilpotents inclus.","expertEn":"The manuscript asserts the equivariant cohomological Hikita conjecture for every finite quiver, loops included, with arbitrary dimensions, framings, and flavor torus. If the semistable locus is stable and the gauge action is free, Nakajima cohomology is the ring of the scheme-theoretic fixed locus of the deformed Coulomb branch, nilpotents included.","sparkFr":"Piste en physique mathématique : les branches de Coulomb viennent de théories de jauge tridimensionnelles, et le manuscrit affirme une identification cohomologique.","sparkEn":"A reason to look in mathematical physics: Coulomb branches come from three-dimensional gauge theories, and the manuscript asserts a cohomological identification."},{"id":"046","titleEn":"Shafarevich counterexamples in dimension two and with large fundamental group","titleFr":"Contre-exemples à la convexité holomorphe de Shafarevich","claim":"Constructs a smooth projective complex fourfold with large fundamental group whose universal cover contains no positive-dimensional compact analytic subvariety but is neither Stein nor holomorphically convex. A separate smooth projective complex surface already disproves unrestricted Shafarevich holomorphic convexity in dimension two.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A projective fourfold with large fundamental group and non-Stein universal cover","href":"preprints/A-projective-fourfold-with-large-fundamental-group-and-non-Stein-universal-cover-October-5-2026/large-fundamental-group-non-stein.pdf"},{"title":"A surface counterexample to Shafarevich holomorphic convexity","href":"preprints/A-surface-counterexample-to-Shafarevich-holomorphic-convexity-September-23-2026/paper.pdf"}],"plainFr":"On attendait qu'un revêtement universel de variété projective à grand groupe fondamental soit holomorphiquement convexe. Le manuscrit affirme des contre-exemples : une surface, et une variété de dimension quatre dont le revêtement n'est ni de Stein ni convexe.","plainEn":"One expected the universal cover of a projective variety with large fundamental group to be holomorphically convex. The manuscript asserts counterexamples: a surface, and a fourfold whose cover is neither Stein nor convex.","expertFr":"Le manuscrit construit une variété projective complexe lisse de dimension quatre, à grand groupe fondamental, dont le revêtement universel n'a pas de sous-variété analytique compacte positive mais n'est ni de Stein ni holomorphiquement convexe. Une surface projective lisse séparée réfute la convexité holomorphe de Shafarevich déjà en dimension deux.","expertEn":"The manuscript constructs a smooth projective complex fourfold with large fundamental group whose universal cover has no positive compact analytic subvariety but is neither Stein nor holomorphically convex. A separate smooth projective surface disproves Shafarevich holomorphic convexity already in dimension two.","sparkFr":"L'intérêt est structurel en géométrie complexe : une limite sur la forme des revêtements universels projectifs.","sparkEn":"The interest is structural inside complex geometry: a limit on the shape of projective universal covers."},{"id":"047","titleEn":"Zariski cancellation and affine fibrations over the complex numbers","titleFr":"Annulation de Zariski et fibrations affines complexes","claim":"Constructs an integral complex affine fourfold X A^4 with X× A^1 A^5, disproving affine-space cancellation over ℂ in dimension four. It also disproves the Dolgachev–Weisfeiler affine-fibration conjecture: smooth surjections X→ A^1 and A^5→ A^2 have every residue-field fiber isomorphic to affine three-space but are not Zariski-locally trivial.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An explicit failure of complex affine-space cancellation","href":"preprints/An-explicit-failure-of-complex-affine-space-cancellation-September-23-2026/paper.pdf"}],"plainFr":"L'annulation demande si une variété qui devient un espace affine après produit par une droite l'était déjà. Le manuscrit affirme un contre-exemple complexe en dimension quatre, et des fibrations lisses à fibres affines qui ne sont pas localement triviales.","plainEn":"Cancellation asks whether a variety that becomes affine space after product with a line already was one. The manuscript asserts a complex counterexample in dimension four, and smooth fibrations with affine fibers that are not locally trivial.","expertFr":"Le manuscrit construit une variété affine complexe de dimension quatre, distincte de l'espace affine, qui le devient après produit par une droite. Il réfute aussi Dolgachev–Weisfeiler : des fibrations lisses vers la droite ou le plan ont toutes leurs fibres égales à l'espace de dimension trois, sans être localement triviales au sens de Zariski.","expertEn":"The manuscript constructs a complex affine fourfold, not affine space, which becomes affine space after product with a line. It also disproves Dolgachev–Weisfeiler: smooth fibrations onto the line or the plane have every fiber equal to affine three-space, yet are not Zariski-locally trivial.","sparkFr":"L'intérêt est structurel en géométrie affine : des produits et des fibrations qui ne se trivialisent pas comme attendu.","sparkEn":"The interest is structural inside affine geometry: products and fibrations that do not trivialize as expected."},{"id":"048","titleEn":"A characteristic-zero counterexample to Lipman–Zariski","titleFr":"Un contre-exemple en caractéristique nulle à Lipman–Zariski","claim":"Constructs a singular normal affine complex surface with free rank-two tangent sheaf, disproving the characteristic-zero Lipman–Zariski conjecture.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A singular normal affine surface with free tangent sheaf","href":"preprints/A-singular-normal-affine-surface-with-free-tangent-sheaf-September-23-2026/paper.pdf"}],"plainFr":"Le faisceau tangent enregistre les directions infinitésimales sur une variété. Le manuscrit affirme une surface affine complexe normale et singulière dont le faisceau tangent est libre de rang deux, contre-exemple à Lipman–Zariski en caractéristique nulle.","plainEn":"The tangent sheaf records infinitesimal directions on a variety. The manuscript asserts a singular normal affine complex surface whose tangent sheaf is free of rank two, a counterexample to Lipman–Zariski in characteristic zero.","expertFr":"Le manuscrit construit une surface affine complexe normale et singulière dont le faisceau tangent est libre de rang deux. Il affirme que cet exemple réfute la conjecture de Lipman–Zariski en caractéristique nulle.","expertEn":"The manuscript constructs a singular normal affine complex surface whose tangent sheaf is free of rank two. It asserts that this example disproves the Lipman–Zariski conjecture in characteristic zero.","sparkFr":"L'intérêt est structurel en géométrie des singularités : un faisceau tangent libre n'implique pas ici la lissité.","sparkEn":"The interest is structural inside singularity geometry: a free tangent sheaf does not imply smoothness here."},{"id":"049","titleEn":"A stable-coordinate counterexample in four variables","titleFr":"Un contre-exemple à la coordonnée stable en quatre variables","claim":"Constructs a polynomial in four complex variables that is not a coordinate but becomes one after adjoining a single variable, disproving the Stable Coordinate conjecture in four variables. Every fiber is affine three-space, yet none of its embeddings is rectifiable, also disproving the Abhyankar–Sathaye conjecture even when all fibers are affine spaces.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A stable coordinate that is not a coordinate in four variables","href":"preprints/A-stable-coordinate-that-is-not-a-coordinate-in-four-variables-October-5-2026/stable-coordinate-four-variables.pdf"},{"title":"An explicit noncoordinate polynomial with affine three-space zero fibre","href":"preprints/An-explicit-noncoordinate-polynomial-with-affine-three-space-zero-fibre-September-24-2026/paper.pdf"}],"plainFr":"Un polynôme coordonnée se complète en un changement de variables. Le manuscrit affirme un polynôme de degré cinq en quatre variables complexes qui n'en est pas un, le devient après une variable de plus, et dont les fibres affines ne se redressent pas.","plainEn":"A coordinate polynomial completes to a change of variables. The manuscript asserts a degree-five polynomial in four complex variables that is not one, becomes one after one more variable, and whose affine fibers do not straighten.","expertFr":"Le manuscrit construit un polynôme de degré cinq en quatre variables complexes, qui n'est pas une coordonnée mais le devient après une variable de plus. Toutes ses fibres sont des espaces de dimension trois, sans plongement rectifiable, ce qui réfute aussi Abhyankar–Sathaye en dimension quatre.","expertEn":"The manuscript constructs a degree-five polynomial in four complex variables that is not a coordinate but becomes one after one more variable. Every fiber is three-space, with no rectifiable embedding, which also disproves Abhyankar–Sathaye in dimension four.","sparkFr":"L'intérêt est structurel en géométrie affine : reconnaître si un polynôme fait partie d'un changement de coordonnées.","sparkEn":"The interest is structural inside affine geometry: recognizing whether a polynomial is part of a coordinate change."},{"id":"050","titleEn":"A counterexample to Griffiths’ positivity conjecture","titleFr":"Un contre-exemple à la positivité de Griffiths","claim":"Constructs ample rank-two bundles on P^1× P^1 with no smooth Hermitian metric of strictly Griffiths-positive curvature, disproving Griffiths' positivity conjecture already on the quadric surface.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Ample rank-two bundles on the quadric surface without Griffiths-positive metrics","href":"preprints/ample-rank-two-bundles-on-the-quadric-surface-without-griffiths-positive-metrics-September-24-2026/paper.pdf"}],"plainFr":"La positivité de Griffiths est une courbure positive forte pour une métrique sur un fibré. Le manuscrit affirme des fibrés amples de rang deux sur le produit de deux droites projectives, sans métrique lisse de courbure strictement positive en ce sens.","plainEn":"Griffiths positivity is a strong positive curvature for a metric on a bundle. The manuscript asserts ample rank-two bundles on the product of two projective lines, with no smooth metric of strictly positive curvature in that sense.","expertFr":"Le manuscrit construit des fibrés amples de rang deux sur le produit de deux droites projectives, sans métrique hermitienne lisse de courbure de Griffiths strictement positive. Le résumé donne un fibré dont des tirés en arrière, tensorisés par O de bidegré un, restent amples mais sans une telle métrique aux grandes puissances.","expertEn":"The manuscript constructs ample rank-two bundles on the product of two projective lines, with no smooth Hermitian metric of strictly positive Griffiths curvature. The abstract gives a bundle whose pullbacks, tensored by O of bidegree one, stay ample but have no such metric at large powers.","sparkFr":"L'intérêt est structurel en géométrie différentielle complexe : l'amplitude algébrique n'implique pas ici la positivité de Griffiths.","sparkEn":"The interest is structural inside complex differential geometry: algebraic ampleness does not imply Griffiths positivity here."},{"id":"051","titleEn":"Kobayashi’s canonical-ampleness conjecture","titleFr":"Conjecture d'amplitude canonique de Kobayashi","claim":"Every compact connected Kähler manifold of positive complex dimension with no nonconstant entire curve has ample canonical bundle and is therefore projective. This proves Kobayashi's canonical-ampleness conjecture in the smooth compact Kähler setting.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":1933,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Canonical ampleness of compact hyperbolic Kähler manifolds","href":"preprints/Canonical-ampleness-of-compact-hyperbolic-Kahler-manifolds-September-23-2026/canonical-ampleness.pdf"}],"plainFr":"Une courbe entière est une application holomorphe non constante depuis la droite complexe. Le manuscrit affirme que toute variété de Kähler compacte connexe, de dimension positive et sans une telle courbe, a un fibré canonique ample, donc est projective.","plainEn":"An entire curve is a nonconstant holomorphic map from the complex line. The manuscript asserts that every compact connected Kähler manifold of positive dimension with no such curve has ample canonical bundle, hence is projective.","expertFr":"Le manuscrit affirme la conjecture d'amplitude canonique de Kobayashi pour les variétés de Kähler compactes lisses : sans courbe entière non constante, et en dimension positive, le fibré canonique est ample. La variété est donc projective.","expertEn":"The manuscript asserts Kobayashi's canonical-ampleness conjecture for smooth compact Kähler manifolds: with no nonconstant entire curve, and in positive dimension, the canonical bundle is ample. The manifold is therefore projective.","sparkFr":"Piste en hyperbolicité complexe : l'absence de courbes entières est ici reliée à la positivité du fibré canonique.","sparkEn":"A reason to look in complex hyperbolicity: the absence of entire curves is tied here to positivity of the canonical bundle."},{"id":"052","titleEn":"Tangent splittings and product decompositions","titleFr":"Scindements du fibré tangent et décompositions en produit","claim":"A splitting of the tangent bundle of a compact Kähler manifold into two integrable holomorphic subbundles induces a compatible product decomposition of its universal cover, proving the two-summand form of Beauville's splitting conjecture. On smooth rationally connected projective manifolds, both summands are automatically integrable, establishing Höring's conjecture and the corresponding product decomposition.","nature":"algebre","domain":"formes","complexity":"avance","problemYear":1933,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Universal-cover splitting for compact Kähler manifolds","href":"preprints/Universal-cover-splitting-for-compact-Kahler-manifolds-September-23-2026/paper.pdf"},{"title":"Integrability of split tangent bundles on rationally connected manifolds","href":"preprints/Integrability-of-split-tangent-bundles-on-rationally-connected-manifolds-September-23-2026/main.pdf"}],"plainFr":"Un scindement du fibré tangent partage les directions en deux sous-fibrés holomorphes. Le manuscrit affirme que, s'ils sont intégrables, le revêtement universel d'une variété de Kähler compacte est un produit, et que l'intégrabilité est automatique si la variété est rationnellement connexe.","plainEn":"A splitting of the tangent bundle shares directions into two holomorphic subbundles. The manuscript asserts that if they are integrable, the universal cover of a compact Kähler manifold is a product, and that integrability is automatic if the manifold is rationally connected.","expertFr":"Le manuscrit affirme la forme à deux sommants de la conjecture de Beauville : un scindement du tangent d'une variété de Kähler compacte en sous-fibrés holomorphes intégrables donne un produit du revêtement universel. Sur une variété projective rationnellement connexe, les deux sommants sont intégrables d'eux-mêmes, cas présenté comme la conjecture de Höring.","expertEn":"The manuscript asserts the two-summand form of Beauville's conjecture: a splitting of the tangent bundle of a compact Kähler manifold into integrable holomorphic subbundles yields a product of the universal cover. On a rationally connected projective manifold both summands are integrable on their own, presented as Höring's conjecture.","sparkFr":"L'intérêt est structurel en géométrie différentielle complexe : quand un scindement infinitésimal donne un produit.","sparkEn":"The interest is structural inside complex differential geometry: when an infinitesimal splitting yields a product."},{"id":"053","titleEn":"A counterexample to Pixton completeness in Chow","titleFr":"Un contre-exemple à la complétude de Pixton en Chow","claim":"Constructs a tautological relation on a moduli space of stable pointed curves that vanishes in rational Chow, hence in rational cohomology, but lies outside Pixton's original relation span. This disproves the Chow and rational-cohomological forms of his original completeness conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A high-arity counterexample to Pixton completeness in Chow","href":"preprints/A-high-arity-counterexample-to-Pixton-completeness-in-Chow-September-24-2026/paper.pdf"}],"plainFr":"Les classes tautologiques sont celles que produit naturellement l'espace des courbes pointées stables. Le manuscrit affirme une relation nulle en Chow rationnel, donc en cohomologie rationnelle, mais hors de l'espace des relations originales de Pixton.","plainEn":"Tautological classes are those naturally produced by the space of stable pointed curves. The manuscript asserts a relation that vanishes in rational Chow, hence in rational cohomology, but outside Pixton's original span of relations.","expertFr":"Le manuscrit construit une classe tautologique hors des relations originales de Pixton, mais nulle en Chow rationnel et donc en cohomologie rationnelle. Cela réfute les formes en Chow et en cohomologie de sa conjecture de complétude ; l'exemple a le genre et le nombre de marquages très grands écrits dans le résumé.","expertEn":"The manuscript constructs a tautological class outside Pixton's original relations, but zero in rational Chow and hence in rational cohomology. This disproves the Chow and cohomological forms of his completeness conjecture; the example has the very large genus and number of markings written in the abstract.","sparkFr":"L'intérêt est structurel en géométrie des espaces de modules : le système de Pixton n'épuise pas le noyau tautologique.","sparkEn":"The interest is structural inside moduli geometry: Pixton's system does not exhaust the tautological kernel."},{"id":"054","titleEn":"Irrational cubic fourfolds with Hodge-theoretic and categorical K3 associations","titleFr":"Cubiques de dimension quatre irrationnelles malgré une association K3","claim":"For every sufficiently large admissible Hassett discriminant, a very general smooth complex cubic fourfold is irrational despite having both an untwisted geometric K3 category and an integral Hodge-theoretic K3 association. This disproves Kuznetsov's rationality conjecture and the sufficiency of the associated-K3 criterion for rationality; the discriminant threshold is ineffective.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1924,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Irrational cubic fourfolds with geometric K3 categories","href":"preprints/Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026/Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026.pdf"}],"plainFr":"Une cubique de dimension quatre est une hypersurface de degré trois dans un espace projectif de dimension cinq. Le manuscrit affirme que, pour un grand discriminant de Hassett, une cubique très générale est irrationnelle malgré une association de type K3.","plainEn":"A cubic fourfold is a degree-three hypersurface in five-dimensional projective space. The manuscript asserts that for a large Hassett discriminant, a very general cubic is irrational despite a K3-type association.","expertFr":"Le manuscrit affirme que, pour tout discriminant de Hassett admissible assez grand, une cubique lisse très générale est irrationnelle bien que sa composante de Kuznetsov soit la catégorie dérivée d'une surface K3, avec aussi une K3 de Hodge. Cela réfute la conjecture de rationalité de Kuznetsov et la suffisance du critère de la K3 associée ; le seuil est ineffectif.","expertEn":"The manuscript asserts that for every large enough admissible Hassett discriminant, a very general smooth cubic is irrational although its Kuznetsov component is the derived category of a K3 surface, with a Hodge-theoretic K3 as well. This disproves Kuznetsov's rationality conjecture and the sufficiency of the associated-K3 test; the threshold is ineffective.","sparkFr":"L'intérêt est structurel en géométrie birationnelle : séparer des données de type K3 et la rationalité.","sparkEn":"The interest is structural inside birational geometry: separating K3-type data from rationality."},{"id":"055","titleEn":"Gepner symmetry and large-volume stability on threefolds","titleFr":"Symétrie de Gepner et stabilité en grand volume","claim":"Proves Toda's Gepner conjecture for every smooth complex quintic threefold, constructing a numerical Bridgeland stability condition with the prescribed phase shift 2/5. Also constructs numerical Bridgeland stability conditions at every sufficiently large volume on all smooth projective complex threefolds with trivial canonical bundle, with the exact ordinary and square-root-Todd central charges.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":2002,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A Gepner stability condition on every smooth quintic threefold","href":"preprints/A-Gepner-stability-condition-on-every-smooth-quintic-threefold-September-24-2026/paper.pdf"},{"title":"Prescribed large-volume charges on threefolds with trivial canonical bundle","href":"preprints/Prescribed-large-volume-charges-on-threefolds-with-trivial-canonical-bundle-September-24-2026/paper.pdf"}],"plainFr":"Une stabilité de Bridgeland ordonne des complexes de faisceaux par une phase. Le manuscrit affirme la conjecture de Gepner de Toda pour toute quintique lisse de dimension trois, avec un déphasage de deux cinquièmes, et des stabilités en grand volume si le canonique est trivial.","plainEn":"A Bridgeland stability orders complexes of sheaves by a phase. The manuscript asserts Toda's Gepner conjecture for every smooth quintic threefold, with a phase shift of two fifths, and large-volume stabilities when the canonical bundle is trivial.","expertFr":"Le manuscrit affirme la conjecture de Gepner de Toda : sur toute quintique complexe lisse, le fibré hyperplan puis la torsion sphérique par le faisceau structural augmentent la phase de deux cinquièmes. Il construit aussi des stabilités de Bridgeland numériques en tout grand volume sur les variétés de dimension trois à canonique trivial, avec les charges centrales indiquées.","expertEn":"The manuscript asserts Toda's Gepner conjecture: on every smooth complex quintic, the hyperplane bundle and then the spherical twist by the structure sheaf raise the phase by two fifths. It also constructs numerical Bridgeland stabilities at every large volume on threefolds with trivial canonical bundle, with the stated central charges.","sparkFr":"Piste en symétrie miroir : le point de Gepner est un avatar, venu des cordes, du grand volume, et le manuscrit affirme le déphasage prévu.","sparkEn":"A reason to look in mirror symmetry: the Gepner point is a string-theoretic avatar of large volume, and the manuscript asserts the predicted phase shift."},{"id":"056","titleEn":"Termination of projective and Kähler fourfold minimal model programs","titleFr":"Terminaison des programmes de modèles minimaux en dimension quatre","claim":"Proves termination of every existing generalized log canonical flip sequence on globally Weil ℚ-factorial compact Kähler fourfolds, with rational boundary, fixed rational analytically nef b-data, and projective small flip diagrams with the prescribed ample signs. Also proves termination of arbitrary permitted minimal model programs for projective log canonical fourfolds with rational boundary in characteristic zero.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1949,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Termination of generalized log canonical flips on compact Kähler fourfolds","href":"preprints/Termination-of-generalized-log-canonical-flips-on-compact-Kahler-fourfolds-October-7-2026/termination-generalized-lc-kahler-fourfolds.pdf"},{"title":"Termination of generalized-canonical flips on compact Kähler fourfolds","href":"preprints/Termination-of-generalized-canonical-flips-on-compact-Kahler-fourfolds-October-6-2026/termination-generalized-terminal-flips-compact-kahler-fourfolds.pdf"},{"title":"Termination for projective log canonical fourfolds with rational boundary","href":"preprints/Termination-for-projective-log-canonical-fourfolds-with-rational-boundary-September-24-2026/paper.pdf"},{"title":"Finite ordinary minimal model programs on compact Kähler fourfolds","href":"preprints/Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-October-6-2026/paper.pdf"},{"title":"Finite ordinary minimal model programs on compact Kähler fourfolds","href":"preprints/Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-September-24-2026/paper.pdf"}],"plainFr":"La terminaison dit qu'une suite de flips, opérations du programme des modèles minimaux, ne continue pas toujours. Le manuscrit affirme cette terminaison pour les suites de dimension quatre qu'il considère, en cadre kählérien et en cadre projectif de caractéristique nulle.","plainEn":"Termination says that a sequence of flips, operations of the minimal model program, does not go on forever. The manuscript asserts this termination for the fourfold sequences it considers, in a Kähler setting and in a projective setting of characteristic zero.","expertFr":"Le manuscrit affirme que toute suite existante de flips log canoniques généralisés termine sur une variété de Kähler compacte de dimension quatre, globalement factorielle au sens de Weil, à bord rationnel et données nef fixes. Il affirme aussi la terminaison des programmes permis pour les paires projectives log canoniques de dimension quatre en caractéristique nulle, sans existence de tous les flips.","expertEn":"The manuscript asserts that every existing generalized log canonical flip sequence terminates on a compact Kähler fourfold, globally factorial in the Weil sense, with rational boundary and fixed nef data. It also asserts termination of permitted programs for projective log canonical fourfold pairs in characteristic zero, without existence of every flip.","sparkFr":"L'intérêt est structurel dans le programme des modèles minimaux : une suite de flips en dimension quatre s'arrête.","sparkEn":"The interest is structural inside the minimal model program: a sequence of fourfold flips stops."},{"id":"057","titleEn":"Fundamental groups of special complex varieties and root orbifolds","titleFr":"Abélianité des groupes fondamentaux des variétés spéciales","claim":"Proves Campana's abelianity conjecture: special compact Kähler manifolds have virtually abelian fundamental groups. Using this theorem, establishes the same conclusion for order-two root orbifolds of smooth projective complex fourfolds along one nonempty smooth connected divisor, when special in the stated differential-line sense. For smooth special complex quasi-projective varieties, proves that every finite-dimensional complex linear representation of the fundamental group has virtually nilpotent image of class a","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":1990,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The abelianity conjecture for special compact Kähler manifolds","href":"preprints/The-abelianity-conjecture-for-special-compact-Kahler-manifolds-September-23-2026/paper.pdf"},{"title":"Two-step monodromy of special quasi-projective varieties","href":"preprints/Two-step-monodromy-of-special-quasi-projective-varieties-September-24-2026/paper.pdf"},{"title":"A conditional abelianity theorem for special fourfold pairs with a half-weight divisor","href":"preprints/A-conditional-abelianity-theorem-for-special-fourfold-pairs-with-a-half-weight-divisor-October-5-2026/main.pdf"}],"plainFr":"Le groupe fondamental enregistre les lacets à déformation près. Le manuscrit affirme la conjecture de Campana : il est virtuellement abélien pour une variété de Kähler compacte spéciale, avec des conclusions voisines pour certains orbi-espaces et représentations.","plainEn":"The fundamental group records loops up to deformation. The manuscript asserts Campana's conjecture: it is virtually abelian for a special compact Kähler manifold, with related conclusions for certain orbifolds and representations.","expertFr":"Le manuscrit affirme la conjecture d'abélianité de Campana : le groupe fondamental d'une variété de Kähler compacte spéciale est virtuellement abélien, donc aussi en dimension de Kodaira nulle. Il l'étend à certains orbi-espaces de racine d'ordre deux en dimension quatre, et affirme une image virtuellement nilpotente pour les représentations linéaires des variétés spéciales quasi-projectives.","expertEn":"The manuscript asserts Campana's abelianity conjecture: the fundamental group of a special compact Kähler manifold is virtually abelian, hence also in Kodaira dimension zero. It extends this to certain order-two root orbifolds in dimension four, and asserts a virtually nilpotent image for linear representations of special quasi-projective varieties.","sparkFr":"Piste topologique : l'énoncé borne la complexité des lacets sur les variétés dites spéciales, sans application hors des mathématiques.","sparkEn":"A topological reason to look: the statement bounds the complexity of loops on so-called special manifolds, with no application outside mathematics."},{"id":"058","titleEn":"Semialgebraic universal covers and bounded domains","titleFr":"Revêtements universels semi-algébriques de Kollár–Pardon","claim":"Proves the Kollár–Pardon conjecture: the semialgebraic universal covers of connected normal projective complex varieties are exactly products D× C^m× F, with D bounded symmetric and F simply connected, normal, and projective. A universal cover is quasi-projective exactly when the bounded symmetric factor is absent. In particular, a smooth projective variety covered by ℂn has a finite étale cover by an abelian variety.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1962,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Semialgebraic universal covers of normal projective varieties","href":"preprints/Semialgebraic-universal-covers-of-normal-projective-varieties-September-24-2026/paper.pdf"},{"title":"Symmetry of semialgebraic bounded domains with compact quotient","href":"preprints/Symmetry-of-semialgebraic-bounded-domains-with-compact-quotient-September-24-2026/paper.pdf"}],"plainFr":"Le revêtement universel déroule les lacets d'une variété projective. Le manuscrit affirme que, s'il est un ouvert semi-algébrique, il est un produit d'un domaine borné symétrique, d'un espace affine complexe et d'une variété projective simplement connexe.","plainEn":"The universal cover unwraps the loops of a projective variety. The manuscript asserts that if it is a semialgebraic open set, it is a product of a bounded symmetric domain, a complex affine space, and a simply connected projective variety.","expertFr":"Le manuscrit affirme la conjecture de Kollár–Pardon : un revêtement universel semi-algébrique est un produit d'un domaine borné symétrique, d'un espace affine et d'une variété projective simplement connexe. Il est quasi-projectif exactement sans le facteur borné, et un revêtement par un espace affine donne une variété abélienne après un revêtement étale fini.","expertEn":"The manuscript asserts the Kollár–Pardon conjecture: a semialgebraic universal cover is a product of a bounded symmetric domain, an affine space, and a simply connected projective variety. It is quasi-projective exactly without the bounded factor, and a cover by affine space yields an abelian variety after a finite étale cover.","sparkFr":"L'intérêt est structurel en géométrie complexe : quels revêtements universels peuvent être semi-algébriques.","sparkEn":"The interest is structural inside complex geometry: which universal covers can be semialgebraic."},{"id":"059","titleEn":"Counterexamples to Zariski’s multiplicity conjecture","titleFr":"Contre-exemples à la conjecture de multiplicité de Zariski","claim":"Disproves Zariski's multiplicity conjecture by constructing reduced holomorphic hypersurface germs that are ambiently homeomorphic but have different multiplicities. The examples include hypersurfaces in ℂ4 with isolated critical points and multiplicities four and five.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Ambiently homeomorphic isolated hypersurfaces of multiplicities two and three","href":"preprints/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/paper.pdf"},{"title":"Ambiently homeomorphic isolated hypersurface germs in ℂ⁴ with multiplicities four and five","href":"preprints/Ambiently-homeomorphic-isolated-hypersurface-germs-in-C4-with-multiplicities-four-and-five-September-27-2026/paper.pdf"}],"plainFr":"La multiplicité compte les feuillets d'une hypersurface singulière à l'origine. Le manuscrit affirme des germes réduits, homéomorphes dans l'espace ambiant, mais de multiplicités différentes, réponse négative à la conjecture de Zariski.","plainEn":"Multiplicity counts the sheets of a singular hypersurface at the origin. The manuscript asserts reduced germs that are homeomorphic in the ambient space but have different multiplicities, a negative answer to Zariski's conjecture.","expertFr":"Le manuscrit réfute la conjecture de multiplicité de Zariski par des germes d'hypersurfaces réduites, homéomorphes dans l'espace, de multiplicités différentes. L'énoncé cite quatre et cinq en dimension quatre à point critique isolé ; le résumé cite deux et trois en dimension multiple de huit, et une réponse négative au corang d'Arnold.","expertEn":"The manuscript disproves Zariski's multiplicity conjecture by reduced hypersurface germs, ambiently homeomorphic, of different multiplicities. The claim cites four and five in dimension four with an isolated critical point; the abstract cites two and three in dimension a multiple of eight, and a negative answer to Arnold's corank problem.","sparkFr":"L'intérêt est structurel en topologie des singularités : l'homéomorphisme ambiant ne conserve pas ici la multiplicité.","sparkEn":"The interest is structural inside the topology of singularities: ambient homeomorphism does not preserve multiplicity here."},{"id":"060","titleEn":"The Global Spherical Shell conjecture","titleFr":"Conjecture de la coquille sphérique globale","claim":"Every connected minimal compact complex surface of class VII with b_2 0 contains a global spherical shell, proving the positive-b2 Global Spherical Shell conjecture. Such a shell is a holomorphically embedded neighborhood of the standard three-sphere in C^2 \\0\\ whose complement is connected.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Global Spherical Shells on Minimal Surfaces of Class VII","href":"preprints/Global-Spherical-Shells-on-Minimal-Surfaces-of-Class-VII-September-24-2026/paper.pdf"}],"plainFr":"Une coquille sphérique globale est un voisinage holomorphe de la sphère de dimension trois, à complémentaire connexe. Le manuscrit affirme que toute surface minimale de classe VII, de second nombre de Betti positif, en contient une.","plainEn":"A global spherical shell is a holomorphic neighborhood of the three-sphere, with connected complement. The manuscript asserts that every minimal class VII surface with positive second Betti number contains one.","expertFr":"Le manuscrit affirme la conjecture de la coquille sphérique globale : toute surface complexe compacte minimale connexe de classe VII, de second nombre de Betti positif, contient une telle coquille. C'est un voisinage de la sphère standard dans le plan complexe privé de l'origine, à complémentaire connexe.","expertEn":"The manuscript asserts the Global Spherical Shell conjecture: every connected minimal compact complex surface of class VII, with positive second Betti number, contains such a shell. It is a neighborhood of the standard sphere in the complex plane minus the origin, with connected complement.","sparkFr":"L'intérêt est structurel en géométrie des surfaces complexes : une forme pour les surfaces minimales de classe VII.","sparkEn":"The interest is structural inside the geometry of complex surfaces: a form for minimal class VII surfaces."},{"id":"062","titleEn":"Projective contact classification and the LeBrun–Salamon conjecture","titleFr":"Classification de contact et conjecture de LeBrun–Salamon","claim":"Proves the LeBrun–Salamon conjecture: every closed connected positive quaternionic-Kähler manifold of real dimension at least eight is homothetic to a compact symmetric Wolf space. It also proves contact-Fano homogeneity and classifies smooth connected complex projective contact manifolds of complex dimension at least three: those with b_2=1 are adjoint varieties with their canonical contact structures, while those with b_2≥2 have underlying manifold P(T^*Z) for a smooth projective variety Z.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":1933,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Contact Fano manifolds and the LeBrun–Salamon conjecture","href":"preprints/Contact-Fano-manifolds-and-the-LeBrun-Salamon-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Une variété quaternionique-kählérienne positive a une métrique d'holonomie quaternionique. Le manuscrit affirme que tout exemple fermé de dimension au moins huit est homothétique à un espace de Wolf, et classe les variétés projectives de contact de dimension au moins trois.","plainEn":"A positive quaternionic-Kähler manifold has a metric of quaternionic holonomy. The manuscript asserts that every closed example of dimension at least eight is homothetic to a Wolf space, and classifies projective contact manifolds of dimension at least three.","expertFr":"Le manuscrit affirme la conjecture de LeBrun–Salamon : toute variété quaternionique-kählérienne positive fermée, de dimension réelle au moins huit, est homothétique à un espace de Wolf symétrique. Il classe les variétés projectives de contact de dimension complexe au moins trois selon que le second nombre de Betti vaut un, cas adjoint, ou au moins deux, cas d'un cotangent projectivisé.","expertEn":"The manuscript asserts the LeBrun–Salamon conjecture: every closed positive quaternionic-Kähler manifold of real dimension at least eight is homothetic to a symmetric Wolf space. It classifies projective contact manifolds of complex dimension at least three by whether the second Betti number is one, the adjoint case, or at least two, a projectivized cotangent bundle.","sparkFr":"Piste en holonomie spéciale : ces métriques sont un cadre aussi regardé en physique théorique, sans application affirmée par le manuscrit.","sparkEn":"A reason to look in special holonomy: these metrics are a setting also seen in theoretical physics, with no application asserted by the manuscript."},{"id":"063","titleEn":"The generalized Mukai conjecture","titleFr":"Conjecture de Mukai généralisée","claim":"Proves the generalized Mukai conjecture: every positive-dimensional smooth complex projective Fano manifold of dimension n, Picard number ρ and pseudoindex ι satisfies ρ( -1)≤ n, with equality exactly for ( P^ -1)^ρ. Here the pseudoindex is the least anticanonical degree of a rational curve.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The generalized Mukai conjecture","href":"preprints/The-Generalized-Mukai-Conjecture-September-24-2026/article.pdf"}],"plainFr":"Une variété de Fano est une variété projective dont le fibré anticanonique est ample. Le manuscrit affirme que le nombre de Picard fois un de moins que le pseudo-indice est au plus la dimension, avec égalité seulement pour un produit d'espaces projectifs.","plainEn":"A Fano manifold is a projective manifold whose anticanonical bundle is ample. The manuscript asserts that the Picard number times one less than the pseudoindex is at most the dimension, with equality only for a product of projective spaces.","expertFr":"Le manuscrit affirme la conjecture de Mukai généralisée : pour une variété de Fano lisse de dimension n, de nombre de Picard rho et de pseudo-indice iota, rho fois (iota moins un) est au plus n. L'égalité vaut exactement pour rho copies de l'espace projectif de dimension iota moins un, iota étant le plus petit degré anticanonique d'une courbe rationnelle.","expertEn":"The manuscript asserts the generalized Mukai conjecture: for a smooth Fano manifold of dimension n, Picard number rho and pseudoindex iota, rho times (iota minus one) is at most n. Equality holds exactly for rho copies of projective space of dimension iota minus one, iota being the least anticanonical degree of a rational curve.","sparkFr":"L'intérêt est structurel en géométrie birationnelle : une inégalité entre nombre de Picard, pseudo-indice et dimension.","sparkEn":"The interest is structural inside birational geometry: an inequality among Picard number, pseudoindex, and dimension."},{"id":"064","titleEn":"Topological triviality of μ-constant surface singularities","titleFr":"Trivialité topologique des singularités de surface à nombre de Milnor constant","claim":"Proves topological right-triviality for every holomorphic one-parameter family of isolated hypersurface singularities in ℂ3 with constant Milnor number, resolving the surface case of the μ-constant problem. After shrinking the parameter disk and representatives, ambient homeomorphisms vary jointly continuously, fix the origin section and preserve the defining functions.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1962,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Topological triviality of mu-constant families of surface singularities","href":"preprints/Topological-triviality-of-mu-constant-families-of-surface-singularities-September-24-2026/main.pdf"}],"plainFr":"Le nombre de Milnor mesure la complexité d'une singularité isolée d'hypersurface. Le manuscrit affirme qu'une famille holomorphe de telles singularités dans l'espace de dimension trois, à nombre de Milnor constant, est topologiquement triviale.","plainEn":"The Milnor number measures the complexity of an isolated hypersurface singularity. The manuscript asserts that a holomorphic family of such singularities in three-dimensional space, with constant Milnor number, is topologically trivial.","expertFr":"Le manuscrit affirme la trivialité topologique à droite de toute famille holomorphe à un paramètre de singularités isolées d'hypersurface dans l'espace de dimension trois, à nombre de Milnor constant. Après rétrécissement, les homéomorphismes varient continûment, fixent l'origine et préservent les équations.","expertEn":"The manuscript asserts topological right-triviality of every holomorphic one-parameter family of isolated hypersurface singularities in three-space, with constant Milnor number. After shrinking, the homeomorphisms vary continuously, fix the origin, and preserve the equations.","sparkFr":"L'intérêt est structurel en théorie des singularités : la constance du nombre de Milnor rigidifie ici la topologie plongée.","sparkEn":"The interest is structural inside singularity theory: constancy of the Milnor number rigidifies the embedded topology here."},{"id":"065","titleEn":"Virasoro constraints for complete intersections and projective-bundle towers","titleFr":"Contraintes de Virasoro pour les intersections complètes et les tours de fibrés projectifs","claim":"Proves the full ordinary unreduced descendant Virasoro conjecture for smooth complete intersections in complex projective space, in every genus and curve class with arbitrary cohomology insertions. The constraints also pass from any smooth projective complex base satisfying them to the projectivization of every algebraic vector bundle of rank at least two, and hence to projective-bundle towers.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1997,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Virasoro Constraints under Projectivization","href":"preprints/Virasoro-Constraints-under-Projectivization-October-5-2026/virasoro-constraints-under-projectivization.pdf"},{"title":"Virasoro Constraints for Projective Complete Intersections","href":"preprints/Virasoro-Constraints-for-Projective-Complete-Intersections-September-24-2026/article.pdf"}],"plainFr":"Ces contraintes organisent les nombres qui comptent les courbes, degré par degré. Le manuscrit affirme qu'elles valent pour toute intersection complète lisse de l'espace projectif complexe, en tout genre et toute classe, et qu'elles passent aux projectivisations de fibrés de rang au moins deux, puis aux tours.","plainEn":"These constraints organize the numbers that count curves on a variety, degree by degree. The manuscript asserts that they hold for every smooth complete intersection in complex projective space, in every genus and curve class, and that they pass to projectivizations of bundles of rank at least two, and then to towers.","expertFr":"Le manuscrit affirme la conjecture de Virasoro descendante, ordinaire et non réduite, pour les intersections complètes lisses de l'espace projectif complexe, avec des insertions cohomologiques arbitraires. Si une base projective lisse complexe les satisfait, elles passent à la projectivisation de tout fibré vectoriel algébrique de rang au moins deux, sans scindage ni positivité, donc aux tours de fibrés projectifs.","expertEn":"The manuscript asserts the full ordinary unreduced descendant Virasoro conjecture for smooth complete intersections in complex projective space, with arbitrary cohomology insertions. If a smooth projective complex base satisfies them, they pass to the projectivization of every algebraic vector bundle of rank at least two, with no splitting or positivity assumption, and hence to projective-bundle towers.","sparkFr":"Piste pour la physique des théories topologiques : ces contraintes structurent le comptage des courbes, sans usage appliqué affirmé.","sparkEn":"A reason to look in topological field theory: these constraints structure curve counts, with no applied use asserted."},{"id":"066","titleEn":"Bounded klt complements for Fano contractions","titleFr":"Compléments klt bornés pour les contractions de Fano","claim":"Proves the finite-rational-coefficient form of Shokurov’s bounded-klt-complement conjecture for ϵ-lc complex Fano-type pairs with nef anti-log-canonical divisor. For ϵ-lc Fano contractions over any algebraically closed characteristic-zero field, it gives klt complements near every base point, with index bounded only by dimension and positive rational ϵ.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Bounded klt complements for Fano contractions","href":"preprints/Bounded-klt-complements-for-Fano-contractions-September-25-2026/Bounded-klt-complements-for-Fano-contractions-September-25-2026.pdf"},{"title":"Uniform Cartier sections for Fano type contractions","href":"preprints/Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026/Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026.pdf"}],"plainFr":"Un complément est une petite correction qui rend plus régulière une variété de type Fano, gouvernée par son diviseur anticanonique. Le manuscrit affirme que, près de chaque point de la base, cette correction existe avec un indice borné seulement par la dimension et par un seuil de régularité rationnel positif.","plainEn":"A complement is a small correction that makes a Fano-type variety, governed by its anticanonical divisor, more regular. The manuscript asserts that near each base point such a correction exists, with an index bounded only by the dimension and by a positive rational regularity threshold.","expertFr":"Le manuscrit affirme la forme à coefficients rationnels finis de la conjecture de Shokurov sur les compléments klt bornés, pour les paires de Fano epsilon-log-canoniques à anti-log-canonique nef. Sur un corps algébriquement clos de caractéristique nulle, toute contraction de Fano epsilon-lc admet, près de chaque point fermé, un complément klt d'indice borné par la dimension et par epsilon.","expertEn":"The manuscript asserts the finite-rational-coefficient form of Shokurov's bounded klt-complement conjecture for complex epsilon-log-canonical Fano-type pairs with nef anti-log-canonical divisor. For every epsilon-lc Fano contraction over an algebraically closed field of characteristic zero, there is near each closed base point a klt complement whose index is bounded only by the dimension and by epsilon.","sparkFr":"L'intérêt est structural, à l'intérieur de la géométrie birationnelle des variétés de Fano.","sparkEn":"The interest is structural, inside the birational geometry of Fano varieties."},{"id":"067","titleEn":"The Campana–Peternell conjecture in dimension six","titleFr":"La conjecture de Campana–Peternell en dimension six","claim":"Proves the Campana–Peternell conjecture in complex dimension six: every smooth connected complex projective Fano sixfold with nef tangent bundle is rational homogeneous.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1990,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"The Campana–Peternell conjecture in dimension six","href":"preprints/The-Campana-Peternell-conjecture-in-dimension-six-September-25-2026/main.pdf"}],"plainFr":"Une variété de Fano projective lisse peut avoir un fibré tangent non négatif, au sens nef. Le manuscrit affirme qu'en dimension complexe six, toute telle variété connexe est un espace rationnellement homogène.","plainEn":"A smooth projective Fano variety may have a tangent bundle that is nonnegative in the nef sense. The manuscript asserts that in complex dimension six, every connected example is a rational homogeneous space.","expertFr":"Le manuscrit affirme qu'en dimension complexe six, toute variété de Fano projective lisse et connexe, à fibré tangent nef, est rationnellement homogène. Si la dimension complexe moins l'irrégularité maximale q(X) vaut au plus six, le revêtement universel ordinaire d'une variété kählérienne compacte connexe à fibré tangent holomorphe nef est le produit d'un homogène rationnel et d'un espace affine de dimension q(X).","expertEn":"The manuscript asserts that every smooth connected complex projective Fano sixfold with nef tangent bundle is rational homogeneous. If complex dimension minus the maximal irregularity q(X) is at most six, the ordinary universal cover of a connected compact Kähler manifold with nef holomorphic tangent bundle is a rational homogeneous space times an affine space of dimension q(X).","sparkFr":"L'intérêt est structural : le manuscrit relie la positivité du fibré tangent à l'homogénéité rationnelle.","sparkEn":"The interest is structural: the manuscript links positivity of the tangent bundle to rational homogeneity."},{"id":"068","titleEn":"Anticanonical nonvanishing in every dimension","titleFr":"Non-annulation anticanonique en toute dimension","claim":"If X is a smooth connected complex projective variety and -K_X admits a smooth Hermitian metric with nonnegative curvature, then H^0(X,-mK_X) 0 for some m > 0. Thus smooth semipositivity forces a nonzero section of a positive tensor power of the anticanonical bundle in every dimension.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":false,"pdfs":[{"title":"Anticanonical nonvanishing from smooth semipositivity","href":"preprints/Anticanonical-nonvanishing-from-smooth-semipositivity-September-26-2026/main.pdf"},{"title":"Invariant anticanonical indices and conversion of twisted differentials","href":"preprints/Invariant-anticanonical-indices-and-conversion-of-twisted-differentials-September-26-2026/main.pdf"},{"title":"Bounded anticanonical metrics on klt pairs and torus quotients","href":"preprints/Bounded-anticanonical-metrics-on-klt-pairs-and-torus-quotients-September-26-2026/main.pdf"},{"title":"Cohomological transfer and equivariant anticanonical sections","href":"preprints/Cohomological-transfer-and-equivariant-anticanonical-sections-September-26-2026/main.pdf"},{"title":"Metric descent and rank-preserving contractions","href":"preprints/Metric-descent-and-rank-preserving-contractions-September-26-2026/main.pdf"},{"title":"Integrable metrics and effectivity with controlled boundary","href":"preprints/Integrable-metrics-and-effectivity-with-controlled-boundary-September-26-2026/main.pdf"}],"plainFr":"Le fibré anticanonique marque une direction de positivité sur une variété projective lisse. Le manuscrit affirme que, s'il porte une métrique hermitienne lisse de courbure positive ou nulle, une de ses puissances positives admet une section non nulle, en toute dimension.","plainEn":"The anticanonical bundle marks a direction of positivity on a smooth projective variety. The manuscript asserts that if it carries a smooth Hermitian metric of nonnegative curvature, some positive power has a nonzero section, in every dimension.","expertFr":"Si une variété projective complexe lisse et connexe a un fibré anticanonique muni d'une métrique hermitienne lisse de courbure non négative, le manuscrit affirme qu'une puissance positive possède une section globale non nulle. La semipositivité lisse force ainsi cette non-annulation en toute dimension.","expertEn":"If a smooth connected complex projective variety has an anticanonical bundle carrying a smooth Hermitian metric of nonnegative curvature, the manuscript asserts that some positive power has a nonzero global section. Smooth semipositivity therefore forces this nonvanishing in every dimension.","sparkFr":"L'intérêt est structural, entre géométrie complexe et positivité des métriques hermitiennes.","sparkEn":"The interest is structural, between complex geometry and positivity of Hermitian metrics."},{"id":"069","titleEn":"Global quantum geometric Langlands at irrational level","titleFr":"Langlands géométrique quantique global à niveau non rationnel","claim":"Proves the unramified de Rham quantum geometric Langlands equivalence for every connected simple complex algebraic group on every smooth projective connected complex curve, at every shifted level c∈ C Q. It identifies the full derived categories of twisted D-modules for the group and its Langlands dual, retaining all global forms and connected components.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1967,"yearKnown":true,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Global quantum geometric Langlands at irrational level","href":"preprints/Global-quantum-geometric-Langlands-at-irrational-level-October-4-2026/quantum-langlands.pdf"}],"plainFr":"Cette correspondance relie, sur une courbe, les objets attachés à un groupe et ceux de son groupe dual. Le manuscrit affirme une équivalence non ramifiée, au sens de de Rham, pour tout niveau complexe non rationnel, entre les catégories de modules différentiels tordus des deux côtés.","plainEn":"This correspondence relates, on a curve, the objects attached to a group and those of its dual group. The manuscript asserts an unramified de Rham equivalence, at every nonrational complex level, between the categories of twisted differential modules on the two sides.","expertFr":"Le manuscrit affirme l'équivalence de Langlands géométrique quantique non ramifiée, en de Rham, pour tout groupe complexe simple connexe, toute courbe projective lisse connexe et tout niveau décalé non rationnel. Elle identifie les catégories dérivées de D-modules tordus des champs de fibrés du groupe et de son dual, aux niveaux c et l'opposé de 1 sur r c, en gardant les formes globales et les composantes connexes.","expertEn":"The manuscript asserts the unramified de Rham quantum geometric Langlands equivalence for every connected simple complex group, every smooth projective connected curve and every nonrational shifted level. It identifies the derived categories of twisted D-modules on the bundle stacks of the group and its dual, at levels c and the negative reciprocal of r c, keeping global forms and connected components.","sparkFr":"Piste pour la physique mathématique des théories de jauge : cette dualité compare des catégories de champs, sans application affirmée.","sparkEn":"A reason for mathematical physics to look: this duality compares categories of fields, with no application asserted."},{"id":"071","titleEn":"Koebe’s circle-domain conjecture","titleFr":"La conjecture des domaines cerclés de Koebe","claim":"Resolves the existence part of Koebe's circle-domain conjecture: every domain in the Riemann sphere is conformally equivalent to a domain whose complementary components are round disks or points. It also proves that circle domains with conformally removable boundary are rigid, meaning every conformal equivalence to another circle domain is Möbius, establishing this direction of the He–Schramm conjecture.","nature":"physique-math","domain":"formes","complexity":"frontiere","problemYear":1908,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Removable Boundaries and Rigidity of Circle Domains","href":"preprints/Removable-Boundaries-and-Rigidity-of-Circle-Domains-September-23-2026/paper.pdf"},{"title":"Koebe's Circle-Domain Conjecture","href":"preprints/Koebes-Circle-Domain-Conjecture-September-23-2026/paper.pdf"}],"plainFr":"Un domaine de la sphère peut être redessiné par une carte qui préserve les angles. Le manuscrit affirme que tout domaine de la sphère de Riemann équivaut ainsi à un domaine dont les trous sont des disques ronds ou des points, et que certains domaines cerclés sont rigides.","plainEn":"A domain on the sphere can be redrawn by a map that preserves angles. The manuscript asserts that every domain on the Riemann sphere is equivalent in this way to one whose holes are round disks or points, and that certain circle domains are rigid.","expertFr":"Le manuscrit affirme que tout domaine de la sphère de Riemann est conformément équivalent à un domaine dont les complémentaires sont des disques ou des points. Tout domaine cerclé à bord conformément effaçable est rigide : une équivalence conforme vers un autre domaine cerclé est de Möbius, ce sens de He–Schramm valant sans borne sur le nombre de composantes.","expertEn":"The manuscript asserts that every domain on the Riemann sphere is conformally equivalent to a domain whose complementary components are disks or points. Every circle domain with conformally removable boundary is rigid: a conformal map onto another circle domain is Möbius, this direction of He–Schramm holding with no bound on the number of components.","sparkFr":"Piste vers les cartes conformes de la théorie du potentiel plane : les domaines cerclés y sont un modèle naturel, sans usage affirmé.","sparkEn":"A reason to look at conformal maps in planar potential theory: circle domains are a natural model, with no use asserted."},{"id":"072","titleEn":"Brennan's conjecture and the integral-means spectrum","titleFr":"La conjecture de Brennan et le spectre des moyennes intégrales","claim":"Proves Brennan's conjecture: for every conformal bijection ϕ from a simply connected plane domain onto the disk, |φ'|^s is area-integrable for 4/3 s 4. The sharp universal integral-means identity is B_ S(t)=|t|-1 for t ≤ −2. A strict bound B_b(-1) 1/4 for bounded univalent functions disproves Kraetzer's prediction at that parameter.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1978,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Brennan's conjecture and sharp inverse-square integral means","href":"preprints/Brennans-conjecture-and-sharp-inverse-square-integral-means-September-24-2026/paper.pdf"},{"title":"A strict inverse-first-power bound for univalent functions","href":"preprints/A-strict-inverse-first-power-bound-for-univalent-functions-September-24-2026/paper.pdf"}],"plainFr":"On déforme un domaine simplement connexe du plan vers le disque par une carte qui préserve les angles. Le manuscrit affirme qu'une puissance de sa dérivée, pour tout exposant strictement entre quatre tiers et quatre, reste intégrable en aire, et il identifie un exposant optimal de moyennes intégrales.","plainEn":"One deforms a simply connected plane domain onto the disk by an angle-preserving map. The manuscript asserts that a power of its derivative, for every exponent strictly between four thirds and four, is area-integrable, and it identifies a sharp integral-means exponent.","expertFr":"Le manuscrit affirme la conjecture de Brennan : la puissance s du module de la dérivée, pour une bijection conforme d'un domaine simplement connexe vers le disque, est intégrable en aire pour tout s entre 4/3 et 4, bornes exclues. Il affirme l'identité des moyennes, valeur absolue de t moins 1 pour t au plus −2, et une borne stricte en −1 pour les fonctions univalentes bornées, contre Kraetzer.","expertEn":"The manuscript asserts Brennan's conjecture: the power s of the modulus of the derivative of a conformal bijection from a simply connected domain onto the disk is area-integrable for every s strictly between 4/3 and 4. It also asserts the means identity, absolute value of t minus 1 for t at most −2, and a strict bound at −1 for bounded univalent functions, against Kraetzer.","sparkFr":"L'intérêt est structural, au cœur de la théorie des fonctions univalentes et des moyennes conformes.","sparkEn":"The interest is structural, inside the theory of univalent functions and conformal means."},{"id":"073","titleEn":"The Falconer distance conjecture","titleFr":"La conjecture des distances de Falconer","claim":"Resolves the Falconer distance conjecture in every dimension d ≥ 2: every compact set E⊂ R^d with Hausdorff dimension greater than d/2 determines a set of Euclidean distances of positive Lebesgue measure.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1985,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The Falconer distance conjecture in all dimensions","href":"preprints/The-Falconer-distance-conjecture-in-all-dimensions-September-23-2026/paper.pdf"}],"plainFr":"Il s'agit des distances usuelles entre les points d'un ensemble compact. Le manuscrit affirme qu'en toute dimension au moins deux, si la dimension de Hausdorff, une taille fine de l'ensemble, dépasse la moitié de la dimension ambiante, ces distances occupent un ensemble de mesure positive.","plainEn":"This concerns the ordinary distances between points of a compact set. The manuscript asserts that in every dimension at least two, if the Hausdorff dimension, a fine measure of size, exceeds half the ambient dimension, those distances occupy a set of positive measure.","expertFr":"Le manuscrit affirme la conjecture des distances de Falconer en toute dimension d au moins 2. Tout compact de l'espace euclidien dont la dimension de Hausdorff dépasse d/2 détermine un ensemble de distances euclidiennes de mesure de Lebesgue positive.","expertEn":"The manuscript asserts the Falconer distance conjecture in every dimension d at least 2. Every compact set in Euclidean space whose Hausdorff dimension exceeds d/2 determines a set of Euclidean distances of positive Lebesgue measure.","sparkFr":"Piste pour la géométrie des nuages de points : une taille minimale forcerait une vraie plage de distances, sans application affirmée.","sparkEn":"A reason to look in the geometry of point clouds: a minimal size would force a genuine range of distances, with no application asserted."},{"id":"074","titleEn":"Kakeya in three and four dimensions","titleFr":"Le problème de Kakeya en dimensions trois et quatre","claim":"Resolves the Kakeya maximal conjecture in three dimensions and the Hausdorff-dimension conjecture in four. In three dimensions, the radius-δ tube maximal operator maps L^3( R^3) to L^3(S^2) with norm O_ε(δ^-ε) for every ε > 0. In four dimensions, every set containing a unit segment in every direction has Hausdorff dimension four.","nature":"analyse","domain":"formes","complexity":"lecture","problemYear":1917,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Kakeya maximal conjecture in three dimensions","href":"preprints/The-Kakeya-maximal-conjecture-in-three-dimensions-September-23-2026/paper.pdf"},{"title":"Every four-dimensional Kakeya set has full Hausdorff dimension","href":"preprints/Every-four-dimensional-Kakeya-set-has-full-Hausdorff-dimension-September-24-2026/paper.pdf"}],"plainFr":"Un ensemble de Kakeya contient un segment de longueur un dans chaque direction. Le manuscrit affirme qu'en dimension trois les moyennes sur des tubes très fins sont presque bornées à l'exposant trois, et qu'en dimension quatre un tel ensemble a la dimension de Hausdorff maximale.","plainEn":"A Kakeya set contains a unit-length segment in every direction. The manuscript asserts that in three dimensions averages over very thin tubes are almost bounded at exponent three, and that in four dimensions such a set has full Hausdorff dimension.","expertFr":"Le manuscrit affirme la conjecture maximale de Kakeya en dimension trois : l'opérateur des moyennes sur les tubes unité de rayon delta envoie L3 de l'espace vers L3 des directions avec une norme au plus C epsilon fois delta puissance moins epsilon, pour tout epsilon positif. En dimension quatre, tout ensemble contenant un segment unité dans chaque direction a dimension de Hausdorff égale à quatre.","expertEn":"The manuscript asserts the Kakeya maximal conjecture in three dimensions: the averaging operator over unit tubes of radius delta maps L3 of space to L3 of directions with norm at most C epsilon times delta to the power minus epsilon, for every positive epsilon. In four dimensions, every set containing a unit segment in every direction has Hausdorff dimension four.","sparkFr":"Piste pour l'analyse de Fourier : contrôler des tubes dans toutes les directions borne des sommes de fréquences, sans usage affirmé.","sparkEn":"A reason to look in Fourier analysis: controlling tubes in every direction bounds frequency sums, with no use asserted."},{"id":"075","titleEn":"The L L Fourier-convergence conjecture","titleFr":"Convergence de Fourier dans l'espace L log L","claim":"Proves that the ordinary symmetric Fourier partial sums of every complex-valued function in L L( T) converge almost everywhere along the full sequence. This resolves the classical sufficiency conjecture at the L L scale.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Almost-everywhere Fourier convergence in L log L","href":"preprints/Almost-everywhere-Fourier-convergence-in-L-log-L-September-23-2026/paper.pdf"}],"plainFr":"Les sommes de Fourier reconstruisent un signal périodique à partir de ses fréquences. Le manuscrit affirme que, pour toute fonction complexe dont l'intégrale du module fois un logarithme reste finie, ces sommes symétriques convergent presque partout vers la fonction.","plainEn":"Fourier sums rebuild a periodic signal from its frequencies. The manuscript asserts that for every complex function whose integral of absolute value times a logarithm stays finite, the symmetric sums converge almost everywhere to the function.","expertFr":"Le manuscrit affirme que les sommes partielles symétriques ordinaires de Fourier de toute fonction à valeurs complexes dans L log L du cercle convergent presque partout le long de toute la suite. Cela établit, selon le texte, la conjecture classique de suffisance à l'échelle L log L.","expertEn":"The manuscript asserts that the ordinary symmetric Fourier partial sums of every complex-valued function in L log L on the circle converge almost everywhere along the full sequence. According to the text, this establishes the classical sufficiency conjecture at the L log L scale.","sparkFr":"Piste pour la reconstruction des signaux périodiques : la convergence presque partout dit où les sommes de Fourier retrouvent la fonction.","sparkEn":"A reason to look at periodic signal reconstruction: almost-everywhere convergence says where Fourier sums recover the function."},{"id":"076","titleEn":"Real ultraflat Littlewood polynomials and unbounded binary merit factors","titleFr":"Polynômes de Littlewood réels ultra-plats et facteurs de mérite non bornés","claim":"Constructs polynomials with N consecutive coefficients in \\-1,1\\ whose modulus is (1+o(1)) N uniformly on the entire unit circle, for every sufficiently large integer length N. Thus real Littlewood polynomials are ultraflat, including at the real endpoints. Their binary merit factors tend to infinity, disproving Turyn's bounded-merit-factor conjecture.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1948,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Ultraflat real Littlewood polynomials","href":"preprints/Ultraflat-real-Littlewood-polynomials-October-5-2026/ultraflat-real-littlewood-polynomials.pdf"},{"title":"Nearly minimal maxima and positive minima of Littlewood polynomials","href":"preprints/Nearly-minimal-maxima-and-positive-minima-of-Littlewood-polynomials-October-5-2026/littlewood-lower-envelope.pdf"},{"title":"Asymptotically minimal maxima of real Littlewood polynomials","href":"preprints/Asymptotically-minimal-maxima-of-real-Littlewood-polynomials-September-23-2026/paper.pdf"}],"plainFr":"Ces polynômes ont tous leurs coefficients égaux à plus un ou moins un. Le manuscrit affirme qu'il en existe, de longueur arbitrairement grande, dont le module reste presque proportionnel à cette longueur sur tout le cercle unité, et que leur facteur de mérite binaire peut devenir arbitrairement grand.","plainEn":"These polynomials have every coefficient equal to plus one or minus one. The manuscript asserts that some, of arbitrarily large length, have modulus nearly proportional to that length everywhere on the unit circle, and that their binary merit factor can become arbitrarily large.","expertFr":"Pour tout entier N assez grand, le manuscrit construit un polynôme de longueur N à coefficients dans moins un et un, de module (1+o(1)) N uniformément sur le cercle unité, y compris aux extrémités réelles, les signes pouvant dépendre de N. Les facteurs de mérite binaires tendent vers l'infini, ce qui réfute selon le texte la conjecture de Turyn d'un facteur de mérite borné.","expertEn":"For every sufficiently large integer N, the manuscript constructs a length-N polynomial with coefficients in minus one and one, of modulus (1+o(1)) N uniformly on the unit circle, including the real endpoints, with signs allowed to depend on N. The binary merit factors tend to infinity, which according to the text refutes Turyn's bounded-merit-factor conjecture.","sparkFr":"Piste vers les suites à faible autocorrélation : le facteur de mérite mesure une platitude sur le cercle, sans procédé technique affirmé.","sparkEn":"A reason to look at low-autocorrelation sequences: the merit factor measures flatness on the circle, with no engineering method asserted."},{"id":"077","titleEn":"Fourier restriction for positively curved surfaces","titleFr":"Restriction de Fourier pour les surfaces à courbure positive","claim":"Proves the diagonal Fourier extension conjecture for positively curved surfaces in three dimensions. For every compact smooth positively curved surface ⊂ R^3, including surfaces with boundary, the extension operator is bounded from L^p to L^p( R^3) for every p > 3.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Elliptic capacity propagation and Fourier restriction to the sphere","href":"preprints/Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026/Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026.pdf"},{"title":"Diagonal Fourier extension for positively curved surfaces in three dimensions","href":"preprints/Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026/Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026.pdf"}],"plainFr":"L'extension de Fourier reconstruit une onde dans l'espace à partir de données posées sur une surface. Le manuscrit affirme que, pour une surface compacte lisse de courbure positive en dimension trois, bord compris, cet opérateur reste borné pour les exposants d'intégrabilité strictement supérieurs à trois.","plainEn":"Fourier extension rebuilds a wave in space from data placed on a surface. The manuscript asserts that for a compact smooth positively curved surface in three dimensions, boundary included, this operator stays bounded for integrability exponents strictly above three.","expertFr":"Le manuscrit affirme la conjecture diagonale d'extension de Fourier : pour toute surface compacte lisse à courbure positive dans R^3, bord compris, l'opérateur est borné de L^p vers L^p de l'espace pour tout p strictement supérieur à 3. Pour la sphère, il affirme aussi la forme à données bornées, de L infini vers L^p pour tout p > 3, et déclare le seuil p = 3 optimal.","expertEn":"The manuscript asserts the diagonal Fourier extension conjecture: for every compact smooth positively curved surface in R^3, boundary included, the operator is bounded from L^p to L^p of space for every p strictly above 3. For the sphere, it also asserts the bounded-data form, from L infinity into L^p for every p > 3, and declares the threshold p = 3 sharp.","sparkFr":"Piste pour la propagation des ondes : la restriction de Fourier borne ce qu'une surface courbée rayonne, sans modèle physique précis affirmé.","sparkEn":"A reason to look in wave propagation: Fourier restriction bounds what a curved surface radiates, with no specific physical model asserted."},{"id":"078","titleEn":"The three-dimensional Bochner–Riesz conjecture","titleFr":"La conjecture de Bochner–Riesz en dimension trois","claim":"Resolves the three-dimensional Bochner–Riesz conjecture in its strict range: the Bochner–Riesz multipliers of order δ are bounded on L^p( R^3) for every 1≤ p≤∞ whenever δ \\3|1/p-1/2|-1/2,0\\.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1958,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Bochner–Riesz multipliers in three dimensions","href":"preprints/Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026/Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026.pdf"}],"plainFr":"Ces opérateurs adoucissent la façon dont on somme les fréquences d'une fonction de l'espace. Le manuscrit affirme qu'en dimension trois ils restent bornés sur les espaces de fonctions intégrables dans toute la plage stricte prévue par la conjecture.","plainEn":"These operators soften the way one sums the frequencies of a function on space. The manuscript asserts that in three dimensions they stay bounded on integrable-function spaces throughout the strict range predicted by the conjecture.","expertFr":"Le manuscrit affirme que les multiplicateurs de Bochner–Riesz d'ordre delta sont bornés sur L^p de R^3, pour tout p entre 1 et l'infini, dès que delta dépasse strictement le maximum de 3 fois la valeur absolue de 1/p moins 1/2, moins 1/2, et de 0. La bornitude sur L^3 pour tout ordre positif, puis l'interpolation et la dualité, donnent cette plage stricte.","expertEn":"The manuscript asserts that Bochner–Riesz multipliers of order delta are bounded on L^p of R^3, for every p from 1 to infinity, whenever delta strictly exceeds the maximum of 3 times the absolute value of 1/p minus 1/2, minus 1/2, and of 0. Boundedness on L^3 for every positive order, then interpolation and duality, yield this strict range.","sparkFr":"Piste pour la sommation des séries de Fourier en dimension trois : ces multiplicateurs gouvernent la convergence, sans application affirmée.","sparkEn":"A reason to look at summing Fourier series in three dimensions: these multipliers govern convergence, with no application asserted."},{"id":"079","titleEn":"Local smoothing in three dimensions","titleFr":"Régularisation locale de l'équation des ondes en dimension trois","claim":"Resolves Sogge's local smoothing conjecture for the Euclidean wave equation in three spatial dimensions. The estimate holds throughout the full strict range 2 p ∞, with Sobolev regularity above \\0,1-3/p\\. In particular, the critical L3 estimate holds with every positive Sobolev loss.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1991,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Critical local smoothing for the three-dimensional wave equation","href":"preprints/Critical-local-smoothing-for-the-three-dimensional-wave-equation-September-24-2026/paper.pdf"}],"plainFr":"L'équation des ondes décrit comment une perturbation se propage dans l'espace. Le manuscrit affirme qu'en trois dimensions d'espace la solution gagne un peu de régularité en moyenne locale, dans toute la plage stricte de Sogge, y compris au cas critique avec une perte positive arbitrairement petite.","plainEn":"The wave equation describes how a disturbance propagates through space. The manuscript asserts that in three spatial dimensions the solution gains a little local regularity on average, throughout Sogge's strict range, including the critical case with every arbitrarily small positive loss.","expertFr":"Le manuscrit affirme la conjecture de régularisation locale de Sogge pour l'équation des ondes euclidienne en trois dimensions d'espace, pour tout p strictement entre 2 et l'infini, avec une régularité de Sobolev au-dessus du maximum de 0 et de 1 moins 3/p. En particulier, l'estimation critique dans L3 vaut avec toute perte de Sobolev strictement positive.","expertEn":"The manuscript asserts Sogge's local smoothing conjecture for the Euclidean wave equation in three spatial dimensions, for every p strictly between 2 and infinity, with Sobolev regularity above the maximum of 0 and of 1 minus 3/p. In particular, the critical L3 estimate holds with every strictly positive Sobolev loss.","sparkFr":"Piste pour la physique des ondes : ce gain local décrit un lissage dû à la propagation, sans milieu matériel précisé.","sparkEn":"A reason to look in wave physics: this local gain describes smoothing due to propagation, with no material medium specified."},{"id":"080","titleEn":"The exact Sobolev endpoint for Schrödinger convergence","titleFr":"L'exposant de Sobolev optimal pour la convergence de Schrödinger","claim":"Proves almost-everywhere convergence e^it → f as t 0 for every f∈ H^n/(2(n+1))( R^n) and every dimension n ≥ 2. This attains the sharp Sobolev equality case of Carleson's Schrödinger convergence problem, including the planar endpoint H1/3.","nature":"analyse","domain":"hasard","complexity":"frontiere","problemYear":1926,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Endpoint convergence for the planar Schrodinger equation","href":"preprints/Endpoint-convergence-for-the-planar-Schrodinger-equation-September-24-2026/paper.pdf"},{"title":"Endpoint pointwise convergence for the Schrodinger equation in higher dimensions","href":"preprints/Endpoint-pointwise-convergence-for-the-Schrodinger-equation-in-higher-dimensions-September-24-2026/paper.pdf"}],"plainFr":"L'équation de Schrödinger fait évoluer une fonction d'onde à partir d'une donnée initiale. Le manuscrit affirme qu'en dimension au moins deux, au seuil de régularité de Sobolev indiqué, cette évolution revient vers la donnée presque partout lorsque le temps tend vers zéro.","plainEn":"The Schrödinger equation evolves a wave function from initial data. The manuscript asserts that in dimension at least two, at the stated Sobolev regularity threshold, this evolution returns to the data almost everywhere as time tends to zero.","expertFr":"Le manuscrit affirme la convergence presque partout de l'évolution de Schrödinger vers la donnée au temps 0, dans l'espace de Sobolev d'exposant n sur 2(n+1), pour toute dimension n au moins 2, donc le cas d'égalité de Carleson, extrémité plane 1/3 comprise. Dans le plan, la régularisation gaussienne existe d'abord pour les temps jusqu'à 1, sur un ensemble de mesure pleine, et l'évolution est continue en 0.","expertEn":"The manuscript asserts almost-everywhere convergence of the Schrödinger evolution to the data at time 0, in the Sobolev space of exponent n over 2(n+1), in every dimension n at least 2, hence Carleson's equality case, including the planar endpoint 1/3. In the plane the Gaussian regularization exists first for times up to 1, on a full-measure set, and the evolution is continuous at 0.","sparkFr":"Piste pour la mécanique quantique linéaire : il s'agit du retour de la fonction d'onde vers sa donnée, sans potentiel affirmé.","sparkEn":"A reason to look in linear quantum mechanics: this is the return of the wave function to its data, with no potential asserted."},{"id":"081","titleEn":"Riesz transforms and rectifiability in higher codimension","titleFr":"Transformées de Riesz et rectifiabilité en codimension supérieure","claim":"Resolves the remaining higher-codimension Riesz-transform rectifiability problem: for d ≥ 4 and 2≤ n≤ d-2, an n-Ahlfors–David regular Radon measure on ℝd is uniformly n-rectifiable whenever its n-dimensional Riesz transform is uniformly L2-bounded over all positive hard truncations. The rectifiability bounds depend only on dimension, regularity and operator bounds.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Riesz transforms and uniform rectifiability in higher codimension","href":"preprints/Riesz-transforms-and-uniform-rectifiability-in-higher-codimension-September-24-2026/paper.pdf"}],"plainFr":"Un ensemble rectifiable ressemble, de près, à des morceaux de surfaces régulières. Le manuscrit affirme que, dans les codimensions encore ouvertes, une mesure assez régulière l'est uniformément dès que sa transformée de Riesz tronquée reste bornée sur les fonctions de carré intégrable.","plainEn":"A rectifiable set looks, at small scales, like pieces of well-drawn surfaces. The manuscript asserts that in the still open codimensions, a sufficiently regular measure is uniformly rectifiable whenever its Riesz transform stays bounded on square-integrable functions, for every truncation.","expertFr":"Pour d au moins 4 et n entre 2 et d moins 2, le manuscrit affirme qu'une mesure de Radon n-régulière d'Ahlfors–David est uniformément n-rectifiable si sa transformée de Riesz est uniformément bornée de L2 scalaire vers L2 vectoriel, pour toute troncature dure positive. Les bornes ne dépendent que de la dimension, de la régularité et de l'opérateur, et donnent de grands morceaux lipschitziens.","expertEn":"For d at least 4 and n between 2 and d minus 2, the manuscript asserts that an n-Ahlfors–David regular Radon measure on d-dimensional space is uniformly n-rectifiable if its n-dimensional Riesz transform is uniformly bounded from scalar L2 to vector L2, for every positive hard truncation. The bounds depend only on dimension, regularity and the operator norm, and yield big pieces of Lipschitz images of balls.","sparkFr":"L'intérêt est structural en théorie géométrique de la mesure : une borne d'opérateur singulier force une régularité de surface.","sparkEn":"The interest is structural in geometric measure theory: a singular-operator bound forces surface-like regularity."},{"id":"082","titleEn":"Annular variation and dyadic absolute bounds for the triangular Hilbert transform","titleFr":"Variation annulaire de la transformée de Hilbert triangulaire","claim":"Proves maximal and annular r-variation bounds, for every r > 2, from complex L^3( R^2)× L^3( R^2) to L^3/2( R^2). The maximal estimate controls both hard truncation endpoints and gives almost-everywhere and norm convergence. Pairing with a third input settles the triangular Hilbert transform estimate at the symmetric L^3× L^3× L^3 point.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Annular variation of the triangular Hilbert transform at the symmetric point","href":"preprints/Annular-variation-of-the-triangular-Hilbert-transform-at-the-symmetric-point-October-5-2026/annular-variation.pdf"},{"title":"An L³ bound for the dyadic triangular Hilbert form","href":"preprints/An-L3-bound-for-the-dyadic-triangular-Hilbert-form-October-5-2026/dyadic-triangular-hilbert.pdf"},{"title":"The maximal triangular Hilbert transform at the symmetric point","href":"preprints/The-maximal-triangular-Hilbert-transform-at-the-symmetric-point-September-24-2026/paper.pdf"}],"plainFr":"La transformée de Hilbert triangulaire est une intégrale singulière qui couple des fonctions du plan. Le manuscrit affirme, au point symétrique des exposants trois, des bornes de variation annulaire et maximale, d'où la convergence presque partout et en norme de la valeur principale.","plainEn":"The triangular Hilbert transform is a singular integral that couples functions on the plane. The manuscript asserts, at the symmetric point of exponent three, annular and maximal variation bounds, and hence almost-everywhere and norm convergence of the principal value.","expertFr":"Le manuscrit affirme, pour tout r strictement supérieur à 2, des bornes de r-variation maximale et annulaire depuis le produit L3 complexe du plan vers L de puissance 3/2, les partitions d'échelles pouvant dépendre du point. Couplée à une troisième fonction, l'estimation maximale règle la transformée de Hilbert triangulaire scalaire au point L3 fois L3 fois L3, avec valeurs principales presque partout et en norme.","expertEn":"The manuscript asserts, for every r strictly above 2, maximal and annular r-variation bounds from the complex L3 product on the plane to L of power 3/2, with scale partitions allowed to depend on the point. Paired with a third function, the maximal estimate settles the scalar triangular Hilbert transform at the point L3 times L3 times L3, with almost-everywhere and norm principal values.","sparkFr":"L'intérêt est structural en analyse harmonique : ces variations contrôlent une intégrale singulière multilinéaire du plan.","sparkEn":"The interest is structural in harmonic analysis: these variations control a multilinear singular integral in the plane."},{"id":"083","titleEn":"Hilbert transforms along Lipschitz directions","titleFr":"Transformée de Hilbert le long de champs lipschitziens","claim":"Proves a uniform strong L2 bound for the planar Hilbert transform along any Lipschitz unit vector field, at integration lengths bounded by an absolute multiple of its reciprocal Lipschitz constant. The estimate is uniform over inner truncations and yields an L2-bounded principal-value operator, establishing Stein's weak-type conjecture at this short scale.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A uniform Hilbert transform estimate for Lipschitz directions","href":"preprints/A-uniform-Hilbert-transform-estimate-for-Lipschitz-directions-September-25-2026/main.pdf"}],"plainFr":"On intègre une fonction du plan le long d'un champ de directions qui ne varie pas trop vite. Le manuscrit affirme une borne uniforme sur les fonctions de carré intégrable lorsque l'intégration reste courte devant l'inverse de cette variation, ainsi qu'une valeur principale bornée.","plainEn":"One integrates a function on the plane along a direction field that does not vary too fast. The manuscript asserts a uniform bound on square-integrable functions when the integration stays short relative to the reciprocal of that variation, and a bounded principal value.","expertFr":"Le manuscrit affirme une borne L2 forte et uniforme pour la transformée de Hilbert plane le long de tout champ unitaire lipschitzien, sur une longueur au plus un multiple absolu de l'inverse de la constante de Lipschitz. Elle est uniforme en la troncature intérieure, donne une valeur principale bornée sur L2 et répond, à cette courte échelle, à la conjecture faible (2,2) de Stein.","expertEn":"The manuscript asserts a uniform strong L2 bound for the planar Hilbert transform along any Lipschitz unit field, at length at most an absolute multiple of the reciprocal Lipschitz constant. It is uniform in the inner truncation, yields an L2-bounded principal value, and thus answers Stein's weak (2,2) conjecture at this short scale.","sparkFr":"Piste pour l'intégration le long de directions variables, comme dans l'étude des champs, sans méthode appliquée affirmée.","sparkEn":"A reason to look at integration along variable directions, as in the study of fields, with no applied method asserted."},{"id":"084","titleEn":"The geometric case of the Erdős similarity conjecture","titleFr":"Le cas géométrique de la conjecture de similitude d'Erdős","claim":"For every fixed q∈(0,1), constructs compact subsets of [0,1] with measure arbitrarily close to one containing no translated and nontrivially dilated copy of \\q^n:n≥1\\, with dilations of either sign. This resolves the geometric-progression case of the Erdős similarity conjecture for every ratio.","nature":"operateurs","domain":"structures","complexity":"frontiere","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The geometric case of the Erdős similarity conjecture","href":"preprints/The-geometric-case-of-the-Erdos-similarity-conjecture-October-5-2026/geometric-erdos-similarity.pdf"},{"title":"The dyadic case of the Erdős similarity conjecture","href":"preprints/The-dyadic-case-of-the-Erdos-similarity-conjecture-September-25-2026/paper.pdf"}],"plainFr":"Une suite géométrique est une suite de points qui se resserrent selon un rapport fixe. Le manuscrit affirme que, pour chaque rapport entre zéro et un, un compact du segment unité de mesure arbitrairement proche de un peut éviter toute copie décalée et dilatée de cette suite, dilatation positive ou négative.","plainEn":"A geometric sequence is a sequence of points that shrink by a fixed ratio. The manuscript asserts that, for each ratio between zero and one, a compact subset of the unit interval with measure arbitrarily close to one can avoid every shifted and dilated copy of that sequence, with either sign of dilation.","expertFr":"Pour tout rapport q entre 0 et 1, le manuscrit construit des compacts de l'intervalle unité, de mesure arbitrairement proche de un, sans copie translatée et dilatée de façon non triviale de la suite des puissances de q, les dilatations non nulles pouvant avoir les deux signes. L'ensemble peut dépendre du rapport, et le texte n'affirme rien de simultané pour des rapports distincts.","expertEn":"For every ratio q between 0 and 1, the manuscript constructs compact subsets of the unit interval, of measure arbitrarily close to one, containing no translated and nontrivially dilated copy of the sequence of powers of q, with either sign of nonzero dilation. The set may depend on the ratio, and the text asserts nothing simultaneous for distinct ratios.","sparkFr":"L'intérêt est structural en théorie de la mesure : un ensemble de mesure presque pleine peut éviter une forme géométrique prescrite.","sparkEn":"The interest is structural in measure theory: a set of almost full measure can avoid a prescribed geometric pattern."},{"id":"085","titleEn":"Endpoint Sobolev regularity of centered disk averages","titleFr":"Régularité de Sobolev extrémale des moyennes de disques centrés","claim":"Resolves the planar centered-disk case of the Hajłasz–Onninen maximal-function regularity problem. For every real f∈ W^1,1( R^2), the centered disk maximal function satisfies \\| Mf\\|_1≤ C\\| f\\|_1 with an absolute constant. It belongs locally to W^1,1 and has a globally integrable weak gradient.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"An Endpoint Gradient Bound for the Centered Disk Maximal Operator","href":"preprints/An-Endpoint-Gradient-Bound-for-the-Centered-Disk-Maximal-Operator-September-26-2026/article.pdf"}],"plainFr":"En chaque point du plan, on prend la plus grande moyenne de la valeur absolue sur les disques centrés là. Le manuscrit affirme que, si la fonction et son gradient sont intégrables, cette maximale reste localement dans le même espace de Sobolev et a un gradient faible globalement intégrable.","plainEn":"At each point of the plane, one replaces a function by the largest average of its absolute value over disks centered there. The manuscript asserts that if the function is integrable together with its gradient, this maximal function stays in the same Sobolev space locally and has a globally integrable weak gradient.","expertFr":"Le manuscrit résout le cas planaire des disques centrés dans la question de Hajłasz et Onninen : pour toute fonction réelle de l'espace de Sobolev d'exposant 1 et d'intégrabilité 1 sur le plan, la norme L1 de la maximale centrée est au plus une constante absolue fois la norme L1 de la fonction. Cette maximale appartient localement à ce même espace et possède un gradient faible globalement intégrable.","expertEn":"The manuscript resolves the planar centered-disk case of the question of Hajłasz and Onninen: for every real function in the Sobolev space of order 1 and integrability 1 on the plane, the L1 norm of the centered maximal function is at most an absolute constant times the L1 norm of the function. This maximal function belongs locally to the same space and has a globally integrable weak gradient.","sparkFr":"L'intérêt est structural en analyse réelle : la moyenne maximale centrée hériterait de la régularité de Sobolev extrémale.","sparkEn":"The interest is structural in real analysis: the centered maximal average would inherit the endpoint Sobolev regularity."},{"id":"086","titleEn":"An L3 bound for the trilinear Hilbert transform","titleFr":"Une borne L3 pour la transformée de Hilbert trilinéaire","claim":"Proves that the principal-value trilinear Hilbert transform with shifts x-t, x-2t, x-3t is bounded from L^3( R)^3 to L^1( R). This resolves the L3 exponent case of the standard conjecture for slopes 1, 2, 3.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1968,"yearKnown":true,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"An L3 bound for the trilinear Hilbert transform","href":"preprints/An-L3-bound-for-the-trilinear-Hilbert-transform-October-5-2026/paper.pdf"}],"plainFr":"Cette transformée combine trois fonctions de la droite par une intégrale singulière à trois décalages fixes. Le manuscrit affirme que, pour les pentes un, deux et trois, elle envoie le produit des espaces d'exposant trois dans l'espace des fonctions intégrables.","plainEn":"This transform combines three functions on the line by a singular integral with three fixed shifts. The manuscript asserts that for the slopes one, two and three, it maps the product of the spaces of exponent three into the space of integrable functions.","expertFr":"Le manuscrit affirme que la transformée de Hilbert trilinéaire en valeur principale, avec les décalages t, 2t et 3t, est bornée du produit de trois espaces L3 de la droite vers L1. Cela résout le cas d'exposant 3 de la conjecture standard pour les pentes 1, 2 et 3.","expertEn":"The manuscript asserts that the principal-value trilinear Hilbert transform, with shifts t, 2t and 3t, is bounded from the product of three L3 spaces on the line to L1. This resolves the exponent-3 case of the standard conjecture for the slopes 1, 2 and 3.","sparkFr":"L'intérêt est structural en analyse harmonique : le texte règle un cas symétrique d'une forme trilinéaire singulière.","sparkEn":"The interest is structural in harmonic analysis: the text settles a symmetric case of a singular trilinear form."},{"id":"087","titleEn":"The Mahler conjectures, functional inequalities and polar-product symplectic width","titleFr":"Conjectures de Mahler, inégalités fonctionnelles et largeur symplectique","claim":"Resolves the symmetric and nonsymmetric geometric Mahler conjectures in every dimension, with Hanner polytopes and simplices as the respective volume-product minimizers and all equality cases classified. The corresponding sharp functional Mahler inequalities also hold. For n ≥ 2, every symmetric polar product K× K^ in dimension 2n has Gromov width 4.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1939,"yearKnown":true,"manuscriptDate":"2026-09-22","lean":true,"pdfs":[{"title":"The symmetric Mahler conjecture and its equality cases","href":"preprints/The-symmetric-Mahler-conjecture-and-its-equality-cases-September-22-2026/paper.pdf"},{"title":"The Mahler Conjecture for General Convex Bodies","href":"preprints/The-Mahler-Conjecture-for-General-Convex-Bodies-September-22-2026/paper.pdf"},{"title":"Symplectic Balls in Symmetric Polar Products","href":"preprints/Symplectic-Balls-in-Symmetric-Polar-Products-September-22-2026/paper.pdf"}],"plainFr":"On compare le volume d'un corps convexe à celui de son polaire. Le manuscrit affirme qu'en toute dimension le minimum vient des polytopes de Hanner dans le cas symétrique et des simplexes sinon, et que le produit polaire symétrique a largeur de Gromov égale à quatre.","plainEn":"One compares the volume of a convex body with the volume of its polar. The manuscript asserts that in every dimension the minimum comes from Hanner polytopes in the symmetric case and from simplices otherwise, and that a symmetric polar product has Gromov width four.","expertFr":"Le manuscrit affirme les conjectures de Mahler en toute dimension : polytopes de Hanner et simplexes minimisent le produit de volume, égalités classées, le minimum symétrique étant 4^n sur la factorielle de n, atteint sur les images linéaires inversibles de Hanner. Les inégalités fonctionnelles optimales suivent, et pour n au moins 2 le produit polaire symétrique en dimension 2n a largeur de Gromov 4.","expertEn":"The manuscript asserts the Mahler conjectures in every dimension: Hanner polytopes and simplices minimize the volume product, with equality classified, the symmetric minimum being 4^n over n factorial on invertible linear images of Hanner polytopes. Sharp functional inequalities follow, and for n at least 2 a symmetric polar product in dimension 2n has Gromov width 4.","sparkFr":"Piste vers la géométrie symplectique : la largeur de Gromov est une capacité, ici évaluée sur un produit polaire, sans usage affirmé.","sparkEn":"A reason to look in symplectic geometry: Gromov width is a capacity, here evaluated on a polar product, with no use asserted."},{"id":"088","titleEn":"Sharp projection-body inequalities and a counterexample to simplex maximization","titleFr":"Corps de projection : minimum ellipsoïdal et contre-exemple aux simplexes","claim":"Proves Petty's projection-volume conjecture in the remaining dimensions n ≥ 4: ellipsoids uniquely minimize projection-body volume at fixed body volume. Also establishes the full Lutwak–Petty projection inequalities. In contrast, products of simplices exceed Brannen's proposed simplex maximum for normalized projection-body volume by an exponential factor in every sufficiently large dimension.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1971,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Petty’s projection-volume conjecture in dimensions at least four","href":"preprints/Pettys-projection-volume-conjecture-in-dimensions-at-least-four-September-24-2026/paper.pdf"},{"title":"A product counterexample to the simplex maximum for projection-body volume","href":"preprints/A-product-counterexample-to-the-simplex-maximum-for-projection-body-volume-September-24-2026/paper.pdf"}],"plainFr":"Le corps de projection d'un convexe rassemble les volumes de ses ombres dans toutes les directions. Le manuscrit affirme qu'en dimension au moins quatre les ellipsoïdes minimisent seuls ce volume à volume fixé, tandis que des produits de simplexes dépassent, en grande dimension, le maximum proposé pour les simplexes.","plainEn":"The projection body of a convex set gathers the volumes of its shadows in every direction. The manuscript asserts that in dimension at least four ellipsoids alone minimize this volume at fixed body volume, while products of simplices exceed, in high dimension, the maximum proposed for simplices.","expertFr":"Le manuscrit affirme la conjecture de Petty en dimension au moins 4 : les ellipsoïdes minimisent seuls le volume du corps de projection à volume fixé, et les inégalités de Lutwak–Petty sont obtenues en entier. Des produits de simplexes dépassent d'un facteur exponentiel, en grande dimension, le maximum de Brannen pour le volume de projection normalisé.","expertEn":"The manuscript asserts Petty's projection-volume conjecture in every dimension at least 4: ellipsoids uniquely minimize projection-body volume at fixed body volume, and the Lutwak–Petty projection inequalities are established in full. Products of simplices exceed, by an exponential factor in every sufficiently large dimension, Brannen's proposed maximum for normalized projection-body volume.","sparkFr":"L'intérêt est structural en géométrie convexe : le texte fixe le minimum des ombres et écarte un maximum proposé pour les simplexes.","sparkEn":"The interest is structural in convex geometry: the text fixes the minimum for shadows and rules out a proposed maximum for simplices."},{"id":"089","titleEn":"Bounded-distortion L1 embeddings of planar and bounded-treewidth graphs","titleFr":"Plongements L1 des graphes planaires et de largeur arborescente bornée","claim":"Resolves the planar and bounded-treewidth cases of the Gupta–Newman–Rabinovich–Sinclair conjecture. Shortest-path metrics of finite connected graphs with arbitrary positive edge lengths embed into real L1 with universal distortion for planar graphs, and distortion depending only on treewidth for bounded-treewidth graphs. The corresponding multicommodity flow–cut gaps are uniformly bounded.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Planar Graph Metrics Embed into L1 with Constant Distortion","href":"preprints/Planar-Graph-Metrics-Embed-into-L1-with-Constant-Distortion-September-23-2026/paper.pdf"},{"title":"L1 Embeddings of Graphs of Bounded Treewidth","href":"preprints/L1-Embeddings-of-Graphs-of-Bounded-Treewidth-September-23-2026/paper.pdf"}],"plainFr":"On réalise les distances d'un graphe dans un espace où la distance est une somme d'écarts absolus. Le manuscrit affirme qu'un graphe planaire fini à longueurs positives s'y plonge avec une distorsion universelle, et que seule la largeur arborescente compte si elle est bornée.","plainEn":"One wants to realize the distances of a graph by points in a space whose distance is a sum of absolute deviations. The manuscript asserts that a finite planar graph, with arbitrary positive edge lengths, embeds there with universally bounded distortion, and that only the treewidth matters when it is bounded.","expertFr":"Le manuscrit résout les cas planaire et de largeur arborescente bornée de la conjecture de Gupta–Newman–Rabinovich–Sinclair. Les plus courts chemins se plongent dans L1 réel avec distorsion universelle si le graphe est planaire, sinon avec une distorsion ne dépendant que de la largeur arborescente, et les écarts flot-coupe sont uniformément bornés.","expertEn":"The manuscript resolves the planar and bounded-treewidth cases of the Gupta–Newman–Rabinovich–Sinclair conjecture. Shortest-path metrics of finite connected graphs with positive lengths embed into real L1 with universal distortion in the planar case, with distortion depending only on treewidth otherwise, and the corresponding multicommodity flow-cut gaps are uniformly bounded.","sparkFr":"Piste pour l'algorithmique des coupes : une distorsion L1 bornée contrôle l'écart entre flots et coupes, sans algorithme détaillé ici.","sparkEn":"A reason to look in cut algorithms: a bounded L1 distortion controls the gap between flows and cuts, with no algorithm detailed here."},{"id":"090","titleEn":"Triangular-lattice optimality, long-range Riesz and Coulomb energies, and spherical logarithmic energy","titleFr":"Optimalité du réseau triangulaire pour des énergies de Riesz, de Coulomb et logarithmiques","claim":"Proves that the triangular lattice minimizes the lower limit of energy per particle for every nonnegative completely monotone potential of squared distance among locally finite planar configurations of centered-disk density one. It also minimizes unit-background renormalized Riesz energies for 0 s 2 and Coulomb energy, resolving Sandier–Serfaty and the two-dimensional Brauchart–Hardin–Saff conjecture on the linear term of optimal spherical logarithmic energy.","nature":"analyse","domain":"physique","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An atomic certificate for triangular-lattice universal optimality","href":"preprints/An-atomic-certificate-for-triangular-lattice-universal-optimality-September-26-2026/paper.pdf"},{"title":"Universal optimality of the triangular lattice","href":"preprints/Universal-optimality-of-the-triangular-lattice-September-23-2026/paper.pdf"},{"title":"A sharp Fourier certificate for planar circle packing","href":"preprints/A-sharp-Fourier-certificate-for-planar-circle-packing-September-23-2026/paper.pdf"},{"title":"Triangular minimality for planar Coulomb renormalized energy","href":"preprints/Triangular-minimality-for-planar-Coulomb-renormalized-energy-September-23-2026/paper.pdf"}],"plainFr":"On compare l'énergie de nuages de points du plan pour des potentiels très régulièrement décroissants. Le manuscrit affirme que le réseau triangulaire de densité un minimise l'énergie par particule, y compris pour certaines énergies de Coulomb, de Riesz et logarithmiques sur la sphère.","plainEn":"One compares the energy of planar point clouds for potentials that decay in a very regular way. The manuscript asserts that the density-one triangular lattice minimizes the energy per particle, including for certain Coulomb and Riesz energies and for a term of logarithmic energy on the sphere.","expertFr":"Le manuscrit affirme que le réseau triangulaire de densité un minimise l'énergie par particule pour tout potentiel positif complètement monotone du carré de la distance, parmi les configurations planes localement finies de cette densité. Il minimise aussi les énergies de Riesz entre 0 et 2, l'énergie de Coulomb, et résout Sandier–Serfaty ainsi que le terme linéaire de Brauchart–Hardin–Saff.","expertEn":"The manuscript asserts that the density-one triangular lattice minimizes energy per particle for every nonnegative completely monotone potential of squared distance, among locally finite planar configurations of that density. It also minimizes Riesz energies for exponents between 0 and 2 and Coulomb energy, and resolves Sandier–Serfaty and the linear term of Brauchart–Hardin–Saff.","sparkFr":"Piste pour la physique des cristaux et des gaz de Coulomb plans : le réseau triangulaire est le candidat naturel d'énergie minimale.","sparkEn":"A reason to look in the physics of crystals and planar Coulomb gases: the triangular lattice is the natural minimal-energy candidate."},{"id":"091","titleEn":"Logarithmic and Lp Brunn–Minkowski inequalities and the B-conjecture","titleFr":"Inégalités de Brunn–Minkowski logarithmiques et la conjecture B","claim":"Proves the logarithmic Brunn–Minkowski inequality for origin-symmetric convex bodies in every dimension, and the scalar-dilation B-conjecture for all even log-concave Radon measures. For Lebesgue volume it also proves the additive Lp Brunn–Minkowski inequality for full-dimensional origin-symmetric convex bodies throughout 0 p 1.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1902,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The logarithmic Brunn–Minkowski conjecture","href":"preprints/The-logarithmic-Brunn-Minkowski-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Ces inégalités comparent le volume d'un mélange de corps convexes aux volumes des corps eux-mêmes. Le manuscrit affirme la forme logarithmique pour les convexes symétriques par rapport à l'origine, en toute dimension, ainsi que la conjecture B pour les mesures paires log-concaves.","plainEn":"These inequalities compare the volume of a mixture of convex bodies with the volumes of the bodies themselves. The manuscript asserts the logarithmic form for convex bodies symmetric about the origin, in every dimension, and the B-conjecture for even log-concave measures.","expertFr":"Le manuscrit affirme l'inégalité de Brunn–Minkowski logarithmique pour tous les corps convexes symétriques, en toute dimension, et l'inégalité Lp additive du volume de Lebesgue pour les exposants strictement entre 0 et 1. Avec le transfert de Saroglou, elle donne l'inégalité logarithmique pour toute mesure de Radon log-concave paire et la conjecture B de dilatation scalaire.","expertEn":"The manuscript asserts the logarithmic Brunn–Minkowski inequality for all origin-symmetric convex bodies, in every dimension, and the additive Lp volume inequality for exponents strictly between 0 and 1. With Saroglou's transfer, it yields the logarithmic inequality for every even log-concave Radon measure and the scalar-dilation B-conjecture.","sparkFr":"Piste vers les mesures log-concaves en grande dimension : ces inégalités comparent des volumes mélangés, sans calcul numérique affirmé.","sparkEn":"A reason to look at high-dimensional log-concave measures: these inequalities compare mixed volumes, with no numerical computation asserted."},{"id":"092","titleEn":"The optimal order of convex-body covering density","titleFr":"L'ordre optimal de la densité de recouvrement des corps convexes","claim":"Determines the optimal worst-case covering density as (n n), for both lattice and unrestricted translative coverings. Every convex body in ℝn, n ≥ 2, admits a lattice covering of density at most Cn n; centrally symmetric examples in every sufficiently large dimension require at least cn n even without the lattice restriction, for absolute c,C 0.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1887,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A single-lattice covering bound of order n log n","href":"preprints/A-single-lattice-covering-bound-of-order-n-log-n-September-23-2026/paper.pdf"},{"title":"Translative covering densities of order n log n","href":"preprints/Translative-covering-densities-of-order-n-log-n-September-23-2026/paper.pdf"}],"plainFr":"Recouvrir l'espace par des copies translatées d'un corps convexe a un coût, la densité. Le manuscrit affirme que le pire cas, avec ou sans réseau, est de l'ordre de la dimension fois son logarithme.","plainEn":"Covering space by translated copies of a convex body has a cost, the density. The manuscript asserts that the worst case, with or without a lattice, is of the order of the dimension times its logarithm.","expertFr":"Le manuscrit affirme que tout corps convexe de l'espace de dimension n au moins 2 admet un recouvrement par les translatés d'un réseau de rang plein, de densité au plus une constante absolue fois n log n, sans symétrie ni régularité du bord. Des exemples centrés symétriques exigent, en toute dimension assez grande, au moins une constante absolue fois n log n même sans contrainte de réseau.","expertEn":"The manuscript asserts that every convex body in dimension n at least 2 admits a covering by translates of one full-rank lattice, of density at most an absolute constant times n log n, with no symmetry or boundary regularity. Centrally symmetric examples require, in every sufficiently large dimension, at least an absolute constant times n log n even without a lattice constraint.","sparkFr":"Piste pour le recouvrement géométrique : l'ordre décrit le surcoût inévitable dans le pire des corps convexes.","sparkEn":"A reason to look in geometric covering: the order describes the unavoidable overhead for the worst convex body."},{"id":"093","titleEn":"Dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","titleFr":"Sobolev logarithmique sans dimension pour des mesures log-concaves sous-gaussiennes","claim":"Proves a dimension-free logarithmic Sobolev inequality for centered log-concave densities with uniformly subgaussian linear marginals, with constant bounded by a universal multiple of the squared linear subgaussian parameter.","nature":"probabilites","domain":"hasard","complexity":"frontiere","problemYear":1974,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","href":"preprints/A-dimension-free-logarithmic-Sobolev-inequality-for-subgaussian-log-concave-measures-September-23-2026/paper.pdf"}],"plainFr":"Cette inégalité borne l'entropie d'une fonction par l'énergie de son gradient. Le manuscrit affirme une constante indépendante de la dimension pour les densités log-concaves centrées dont toutes les directions linéaires sont uniformément sous-gaussiennes.","plainEn":"This inequality bounds the entropy of a function by the energy of its gradient. The manuscript asserts a dimension-free constant for centered log-concave densities whose linear directions are uniformly subgaussian.","expertFr":"Le manuscrit affirme qu'une probabilité log-concave centrée, à densité sur l'espace de dimension n et de paramètre sous-gaussien linéaire a, satisfait une inégalité de Sobolev logarithmique de constante universelle fois a au carré. L'entropie du carré d'une fonction lisse à support compact est alors majorée par cette constante fois l'intégrale du carré de son gradient.","expertEn":"The manuscript asserts that a centered log-concave probability, with a density on n-dimensional space and linear subgaussian parameter a, satisfies a logarithmic Sobolev inequality with constant a universal multiple of a squared. The entropy of the square of a compactly supported smooth function is then at most this constant times the integral of the square of its gradient.","sparkFr":"Piste pour l'échantillonnage en grande dimension : une constante sans dimension contrôlerait la concentration de ces mesures.","sparkEn":"A reason to look at high-dimensional sampling: a dimension-free constant would control the concentration of these measures."},{"id":"094","titleEn":"Subpolynomial dimension reduction in Lp","titleFr":"Réduction de dimension sous-polynomiale dans les espaces Lp","claim":"For every fixed 1 p ∞ and distortion D > 1, every n-point subset of real Lp embeds into ℓ_p^d with distortion at most D and dimension d=n^o(1), answering Naor's sublinear-dimension question for p ≠ 2. In contrast, exact embeddings require worst-case dimension (n^2) when p ≠ 2.","nature":"algebre","domain":"formes","complexity":"frontiere","problemYear":1984,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Subpolynomial dimension reduction in Lp","href":"preprints/Subpolynomial-dimension-reduction-in-Lp-September-23-2026/paper.pdf"}],"plainFr":"On replace un nuage fini de points d'un espace Lp dans un espace du même type, bien plus petit, sans trop tordre les distances. Le manuscrit affirme qu'une distorsion fixée au-dessus de un suffit en dimension sous-polynomiale, tandis qu'un plongement exact exige, si p n'est pas deux, un ordre n au carré.","plainEn":"One places a finite point cloud from an Lp space into a much smaller space of the same type, without twisting distances too much. The manuscript asserts that a fixed distortion above one suffices in subpolynomial dimension, while an exact embedding needs order n squared if p is not two.","expertFr":"Pour tout p fixé strictement entre 1 et l'infini et toute distorsion D supérieure à 1, le manuscrit affirme que tout ensemble de n points d'un Lp réel se plonge dans un espace lp de dimension n puissance o(1), avec distorsion au plus D et sans imposer la linéarité. Les plongements exacts exigent au contraire, lorsque p diffère de 2, une dimension de pire cas de l'ordre de n au carré.","expertEn":"For every fixed p strictly between 1 and infinity and every distortion D above 1, the manuscript asserts that every n-point subset of a real Lp space embeds into an lp space of dimension n to the power o(1), with distortion at most D and without requiring linearity. Exact embeddings, by contrast, require worst-case dimension of order n squared when p is not 2.","sparkFr":"Piste pour l'algorithmique des métriques : réduire la dimension à distorsion contrôlée allégerait le traitement des nuages de points.","sparkEn":"A reason to look in metric algorithms: reducing dimension at controlled distortion would lighten the handling of point clouds."},{"id":"095","titleEn":"Hyperbolicity cones without semidefinite lifts","titleFr":"Cônes hyperboliques sans relèvement semidéfini","claim":"Disproves the Projected Lax conjecture: some hyperbolicity cones are not spectrahedral shadows. The examples admit no exact finite affine semidefinite lift, regardless of the number of auxiliary variables or the real coefficients used. This also disproves the generalized Lax conjecture that every hyperbolicity cone is spectrahedral.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Hyperbolicity Cones Without Semidefinite Lifts","href":"preprints/Hyperbolicity-Cones-Without-Semidefinite-Lifts-October-5-2026/nonliftable-hyperbolicity.pdf"},{"title":"A nonspectrahedral hyperbolicity cone","href":"preprints/A-Nonspectrahedral-Hyperbolicity-Cone-September-24-2026/nonspectrahedral-hyperbolicity-cone.pdf"},{"title":"An Exact Semidefinite Lift of a Nonspectrahedral Hyperbolicity Cone","href":"preprints/An-Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone-October-5-2026/Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone.pdf"}],"plainFr":"Un cône hyperbolique regroupe les directions permises par un polynôme d'un certain type, et une ombre spectrahédrique est une projection d'un cône de matrices positives. Le manuscrit affirme que certains de ces cônes n'admettent aucune telle représentation finie, même avec des variables auxiliaires.","plainEn":"A hyperbolicity cone gathers the directions allowed by a polynomial of a certain type, and a spectrahedral shadow is a projection of a cone of positive matrices. The manuscript asserts that some of these cones admit no such finite representation, even with auxiliary variables.","expertFr":"Le manuscrit réfute la conjecture de Lax projetée : certains cônes d'hyperbolicité fermés ne sont pas des ombres spectrahédriques. Ils n'admettent aucun relèvement semidéfini affine fini exact, quel que soit le nombre de variables auxiliaires et quels que soient les coefficients réels, ce qui réfute aussi la conjecture de Lax généralisée.","expertEn":"The manuscript refutes the Projected Lax conjecture: some closed hyperbolicity cones are not spectrahedral shadows. They admit no exact finite affine semidefinite lift, whatever the number of auxiliary variables and whatever the real coefficients, which also refutes the generalized Lax conjecture.","sparkFr":"Piste pour l'optimisation semidéfinie : certains cônes hyperboliques échapperaient aux programmes semidéfinis, même après projection.","sparkEn":"A reason to look in semidefinite optimization: some hyperbolicity cones would escape semidefinite programs, even after projection."},{"id":"096","titleEn":"The Gaussian propeller conjecture in every dimension","titleFr":"La conjecture de l'hélice gaussienne en toute dimension","claim":"Proves that the sum of squared Gaussian first moments of any finite measurable partition is at most 9/(8π). In dimension at least two, three planar sectors of angle 2π/3, extended orthogonally, attain the bound. Combined with the separate Unique Games theorem, this proves NP-hardness of improving the loss factor (8π/9)(1-1/k) for identity-target kernel clustering with fixed k ≥ 3 on rational centered positive semidefinite inputs.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":2002,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Gaussian propeller bound in every dimension","href":"preprints/The-Gaussian-Propeller-Bound-in-Every-Dimension-September-24-2026/main.pdf"}],"plainFr":"On découpe l'espace en un nombre fini de régions et l'on mesure le centre de masse de chacune pour un poids en cloche gaussienne. Le manuscrit affirme que la somme des carrés de ces centres est au plus neuf sur huit pi, valeur atteinte par trois secteurs d'un tiers de tour lorsque la dimension vaut au moins deux.","plainEn":"One cuts space into finitely many regions and measures the center of mass of each for a Gaussian bell weight. The manuscript asserts that the sum of the squares of these centers is at most nine over eight pi, a value attained by three sectors of one third of a turn when the dimension is at least two.","expertFr":"Le manuscrit affirme que la somme des carrés des moments gaussiens d'une partition finie vaut au plus 9/(8 pi), atteint en dimension au moins deux par trois secteurs d'angle 2 pi/3 étendus orthogonalement. Avec les jeux uniques, améliorer le facteur (8 pi/9)(1−1/k) du partitionnement par noyau à cible identité, pour k fixé au moins 3, est NP-difficile sur des matrices rationnelles centrées semidéfinies positives.","expertEn":"The manuscript asserts that the sum of squared Gaussian moments of a finite partition is at most 9/(8 pi), attained in dimension at least two by three sectors of angle 2 pi/3 extended orthogonally. With Unique Games, improving the factor (8 pi/9)(1−1/k) for identity-target kernel clustering, at fixed k at least 3, is NP-hard on rational centered positive semidefinite matrices.","sparkFr":"Piste algorithmique : la borne est reliée à la difficulté NP d'améliorer un facteur pour un partitionnement par noyau.","sparkEn":"An algorithmic reason to look: the bound is tied to the NP-hardness of improving a factor for kernel clustering."},{"id":"097","titleEn":"The Euclidean Steinitz–Bergström bound","titleFr":"La borne euclidienne de Steinitz–Bergström","claim":"Proves that any finite sequence in the Euclidean unit ball of ℝd admits signs keeping every partial sum within C d, independently of length. Consequently every zero-sum family can be reordered with the same bound on unsigned partial sums. A matching lower bound gives the optimal order S_2(d)= ( d).","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Euclidean Steinitz–Bergström theorem","href":"preprints/The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026/The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026.pdf"}],"plainFr":"On choisit des signes pour une suite de vecteurs de la boule unité afin que les sommes partielles restent près de l'origine. Le manuscrit affirme qu'on peut les garder dans un multiple absolu de la racine de la dimension, quelle que soit la longueur de la suite.","plainEn":"One chooses signs for a sequence of vectors in the unit ball so that the partial sums stay near the origin. The manuscript asserts that they can be kept within an absolute multiple of the square root of the dimension, whatever the length of the sequence.","expertFr":"Le manuscrit affirme que toute suite finie de la boule unité euclidienne de dimension d admet des signes tels que chaque somme partielle ait une norme au plus C fois la racine de d, avec C absolu indépendant de la longueur. Toute famille de somme nulle se réordonne avec la même borne, et une borne inférieure de même ordre fixe la constante de Steinitz euclidienne à l'ordre de la racine de d.","expertEn":"The manuscript asserts that any finite sequence in the Euclidean unit ball of dimension d admits signs so that every partial sum has norm at most C times the square root of d, with C absolute and independent of the length. Every zero-sum family can be reordered with the same bound, and a matching lower bound places the Euclidean Steinitz constant at the order of the square root of d.","sparkFr":"Piste pour l'équilibrage algorithmique de vecteurs : l'ordre dit comment signer une suite sans laisser les sommes s'échapper.","sparkEn":"A reason to look in algorithmic vector balancing: the order says how to sign a sequence without letting the sums escape."},{"id":"098","titleEn":"Compact counterexamples to bi-Lipschitz dimension reduction","titleFr":"Contre-exemples compacts à la réduction de dimension bi-lipschitzienne","claim":"Every infinite-dimensional real Banach space contains a compact doubling set that admits no bi-Lipschitz embedding into any finite-dimensional normed space. The doubling constant is universal. This answers the Lang–Plaut problem negatively, even for compact subsets of Hilbert space.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A doubling Hilbert subset with no finite-dimensional bi-Lipschitz embedding","href":"preprints/A-doubling-Hilbert-subset-with-no-finite-dimensional-bi-Lipschitz-embedding-September-25-2026/main.pdf"}],"plainFr":"Un ensemble doublant ne grossit pas trop quand on double l'échelle d'observation. Le manuscrit affirme que tout espace de Banach réel de dimension infinie contient un compact de ce type, à constante universelle, qui ne se plonge de façon bi-lipschitzienne dans aucun espace normé de dimension finie.","plainEn":"A doubling set does not grow too fast when the scale of observation is doubled. The manuscript asserts that every infinite-dimensional real Banach space contains a compact set of this type, with a universal constant, that does not embed bi-Lipschitz into any finite-dimensional normed space.","expertFr":"Le manuscrit affirme que tout espace de Banach réel de dimension infinie contient un compact doublant, à constante de doublement universelle, sans plongement bi-lipschitzien dans un espace normé réel de dimension finie. Cela répond négativement au problème de Lang–Plaut, y compris pour des compacts de l'espace de Hilbert.","expertEn":"The manuscript asserts that every infinite-dimensional real Banach space contains a compact doubling set, with a universal doubling constant, and with no bi-Lipschitz embedding into any finite-dimensional real normed space. This answers the Lang–Plaut problem negatively, including for compact subsets of Hilbert space.","sparkFr":"L'intérêt est structural en géométrie des espaces de Banach : le doublement n'implique pas une dimension finie bi-lipschitzienne.","sparkEn":"The interest is structural in Banach-space geometry: doubling does not imply finite bi-Lipschitz dimension."},{"id":"099","titleEn":"The sharp exponential scale of edit-distance distortion","titleFr":"L'échelle exponentielle de la distorsion de la distance d'édition","claim":"Determines the least distortion of embedding edit distance on words of length at most d into real ℓ1: it is ( (√( d\\, d))). Insertions, deletions and substitutions have unit cost. The constants are uniform over all finite alphabets with at least two symbols, even when the alphabet grows with d; binary words already force the lower bound.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Edit Distance in l1: Matching Bounds up to Constants in the Exponent","href":"preprints/Edit-Distance-in-l1-Matching-Bounds-up-to-Constants-in-the-Exponent-September-27-2026/paper.pdf"},{"title":"Finite-Circle Obstructions, Binary Codes, and Histogram Embeddings for Edit Distance","href":"preprints/Finite-Circle-Obstructions-Binary-Codes-and-Histogram-Embeddings-for-Edit-Distance-September-27-2026/paper.pdf"},{"title":"Tree Constructions for the l1 Distortion of Binary Edit Distance","href":"preprints/Tree-Constructions-for-the-l1-Distortion-of-Binary-Edit-Distance-September-27-2026/paper.pdf"}],"plainFr":"La distance d'édition compte insertions, suppressions et substitutions, chacune au coût un. Le manuscrit affirme que la distorsion minimale vers l'espace des sommes d'écarts absolus, pour les mots de longueur au plus d, suit une échelle exponentielle déjà forcée par les mots binaires.","plainEn":"Edit distance counts insertions, deletions and substitutions between two words, each at unit cost. The manuscript asserts that the least distortion of an embedding into the space of sums of absolute deviations, for words of length at most d, follows a precise exponential scale, already forced by the binary alphabet.","expertFr":"Le manuscrit situe cette distorsion minimale vers l1 réel, uniformément pour les alphabets finis d'au moins deux symboles, entre deux bornes de la forme exponentielle en la racine d'un produit de logarithmes de d, à constantes absolues. La borne inférieure vaut déjà pour des mots binaires d'une longueur commune, même si l'alphabet peut par ailleurs croître avec d.","expertEn":"The manuscript places this least distortion into real l1, uniformly over finite alphabets of at least two symbols, between two bounds of exponential form in the square root of a product of logarithms of d, with absolute constants. The lower bound already holds for binary words of one common length, even though the alphabet may otherwise grow with d.","sparkFr":"Piste pour la comparaison de chaînes : cette distorsion borne ce que l'espace l1 peut préserver de la distance d'édition.","sparkEn":"A reason to look in string comparison: this distortion bounds what l1 space can preserve of edit distance."},{"id":"100","titleEn":"Cylinder coverings below the half-area bound","titleFr":"Recouvrement cylindrique du tétraèdre sous la borne de demi-aire","claim":"Covers the entire closed regular tetrahedron by finitely many cylinders with compact triangular perpendicular bases whose total area is less than half its smallest orthogonal projection area. This disproves Bang's half-area cylinder-covering bound and the stronger directionwise normalized conjecture in dimension three.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Finite angular cylinder covers below the half-area bound","href":"preprints/Finite-angular-cylinder-covers-below-the-half-area-bound-September-27-2026/main.pdf"},{"title":"Finite cylinder approximation of ruled sets","href":"preprints/Finite-cylinder-approximation-of-ruled-sets-September-27-2026/main.pdf"},{"title":"Slope-field perturbations of the two-cylinder covering","href":"preprints/Slope-field-perturbations-of-the-two-cylinder-covering-September-27-2026/main.pdf"},{"title":"Finite triangular approximation of radial sweeps","href":"preprints/Finite-triangular-approximation-of-radial-sweeps-September-27-2026/main.pdf"}],"plainFr":"On cherche à recouvrir un tétraèdre par des cylindres à base triangulaire, en additionnant les aires de ces bases. Le manuscrit affirme qu'un nombre fini de cylindres suffit avec une aire totale strictement inférieure à la moitié de la plus petite ombre orthogonale, ce qui dépasse la borne de Bang.","plainEn":"One seeks to cover a tetrahedron by cylinders with triangular bases, adding the areas of those bases. The manuscript asserts that finitely many cylinders suffice with total area strictly less than half the smallest orthogonal shadow, which breaks Bang's bound.","expertFr":"Le manuscrit affirme qu'un tétraèdre régulier fermé admet un recouvrement fini par des cylindres à bases perpendiculaires triangulaires compactes, d'aire totale inférieure à la moitié de sa plus petite aire de projection orthogonale. Cela réfute la borne de demi-aire de Bang et la forme normalisée par directions en dimension trois, et, par invariance affine, vaut pour tout tétraèdre non dégénéré.","expertEn":"The manuscript asserts that a closed regular tetrahedron admits a finite covering by cylinders with compact triangular perpendicular bases, of total area less than half its least orthogonal projection area. This refutes Bang's half-area bound and the directionwise normalized form in dimension three and, by affine invariance, holds for every nondegenerate tetrahedron.","sparkFr":"L'intérêt est structural en géométrie convexe : une borne d'aire sur les cylindres est déjà fausse pour le tétraèdre.","sparkEn":"The interest is structural in convex geometry: an area bound on cylinders already fails for the tetrahedron."},{"id":"101","titleEn":"The sharp simplex conjecture for isotropic constants","titleFr":"La conjecture du simplexe pour la constante isotrope","claim":"Proves that simplices uniquely maximize the isotropic constant among convex bodies in every dimension, resolving the strong isotropic constant conjecture. Also establishes the sharp entropy lower bound for log-concave probability densities, with equality precisely for invertible affine images of products of one-sided exponential laws.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1887,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"A sharp entropy bound and the simplex inequality for isotropic constants","href":"preprints/A-sharp-entropy-bound-and-the-simplex-inequality-for-isotropic-constants-October-5-2026/isotropic-simplex.pdf"}],"plainFr":"La constante isotrope mesure, après centrage et mise à l'échelle, à quel point un corps convexe s'écarte d'une forme ronde. Le manuscrit affirme que les simplexes sont, en chaque dimension, les seuls à la maximiser, et il donne une borne d'entropie optimale pour les densités log-concaves.","plainEn":"The isotropic constant measures, after centering and scaling, how far a convex body is from a round shape. The manuscript asserts that simplices are, in each dimension, the only maximizers, and it gives a sharp entropy bound for log-concave densities.","expertFr":"Le manuscrit affirme que, en chaque dimension, les simplexes maximisent uniquement la constante isotrope parmi les corps convexes. L'entropie d'une densité log-concave en dimension m vaut au moins m plus un demi-logarithme du déterminant de covariance, avec égalité pour les images affines inversibles de produits de lois exponentielles unilatères.","expertEn":"The manuscript asserts the strong isotropic constant conjecture: in each dimension, simplices uniquely maximize this constant among convex bodies. It also asserts that a log-concave probability density in dimension m has entropy at least m plus half the logarithm of the covariance determinant, with equality precisely for invertible affine images of products of one-sided exponential laws.","sparkFr":"Piste pour les probabilités log-concaves : la constante isotrope et l'entropie contrôlent la forme de ces mesures.","sparkEn":"A reason to look in log-concave probability: the isotropic constant and the entropy control the shape of these measures."},{"id":"102","titleEn":"The Unique Games Conjecture and optimal approximation thresholds","titleFr":"La conjecture des jeux uniques et les seuils d'approximation","claim":"Proves Khot's Unique Games Conjecture. Independent direct reductions also establish NP-hardness, on unweighted graphs, of approximation beyond the Goemans–Williamson ratio for Max-Cut, below factor two for Vertex Cover, and within any fixed constant factor for Min-UnCut and directed feedback vertex set. These direct proofs use established PCP and Label Cover hardness results.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":2002,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The Unique Games Theorem","href":"preprints/The-Unique-Games-Theorem-September-23-2026/paper.pdf"},{"title":"A Direct Proof of Optimal Max-Cut Hardness","href":"preprints/A-Direct-Proof-of-Optimal-Max-Cut-Hardness-September-23-2026/paper.pdf"},{"title":"The Factor-Two Hardness Threshold for Vertex Cover","href":"preprints/The-Factor-Two-Hardness-Threshold-for-Vertex-Cover-September-23-2026/paper.pdf"},{"title":"Constant-factor hardness of Min-UnCut","href":"preprints/Constant-factor-hardness-of-Min-UnCut-September-23-2026/paper.pdf"},{"title":"Constant-factor hardness of directed feedback vertex set","href":"preprints/Constant-factor-hardness-of-directed-feedback-vertex-set-September-23-2026/paper.pdf"}],"plainFr":"Un jeu unique demande d'étiqueter des sommets de sorte que chaque contrainte n'autorise qu'une correspondance entre étiquettes. Le manuscrit affirme la conjecture de Khot, et avec elle la difficulté NP d'approcher certaines coupes et couvertures au-delà des seuils classiques.","plainEn":"A unique game asks one to label vertices so that each constraint allows only one correspondence between labels. The manuscript asserts Khot's conjecture, and with it the NP-hardness of approximating certain cuts and covers past the classical thresholds.","expertFr":"Le manuscrit affirme les jeux uniques : pour epsilon et delta entre 0 et 1/2, une réduction polynomiale mène de 3SAT à un jeu d'alphabet fixé, de complétude au moins 1 moins epsilon et de correction au plus delta. Des réductions directes rendent NP-difficiles Max-Cut au-delà de Goemans–Williamson, la couverture de sommets sous le facteur deux, et Min-UnCut ainsi que le feedback vertex set dirigé à facteur constant.","expertEn":"The manuscript asserts Unique Games: for epsilon and delta between 0 and 1/2, a deterministic polynomial reduction takes 3SAT to a game on a fixed alphabet, with completeness at least 1 minus epsilon and soundness at most delta. Direct reductions make NP-hard Max-Cut past Goemans–Williamson, vertex cover below factor two, and Min-UnCut and directed feedback vertex set at any fixed constant.","sparkFr":"Piste pour l'informatique théorique : le manuscrit relie un jeu d'étiquetage à des seuils d'approximation NP-difficiles.","sparkEn":"A reason to look in theoretical computer science: the manuscript ties a labeling game to NP-hard approximation thresholds."},{"id":"103","titleEn":"Exact derandomization of logarithmic space: L= RL= BPL","titleFr":"Dérandomisation de l'espace logarithmique : L égale RL égale BPL","claim":"Proves L= RL= BPL, resolving derandomization for bounded-error logarithmic-space computation. An effective compiler converts each randomized polynomial-time logarithmic-space machine deciding a language with one-sided or two-sided error into a deterministic logarithmic-space decider with explicit polynomial running-time bounds.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1979,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Exact derandomization of logarithmic space: L = RL = BPL","href":"preprints/Exact-Derandomization-of-Logarithmic-Space-L-equals-RL-equals-BPL-September-23-2026/paper.pdf"}],"plainFr":"Certaines machines décident un langage avec très peu de mémoire et un peu de hasard. Le manuscrit affirme que tout langage ainsi décidé, avec erreur d'un seul côté ou des deux, l'est aussi sans hasard et en espace logarithmique.","plainEn":"Some machines decide a language with very little memory and a little randomness. The manuscript asserts that every language decided in this way, with one-sided or two-sided error, is also decided without randomness and in logarithmic space.","expertFr":"Le manuscrit affirme l'égalité L = RL = BPL, donc la dérandomisation du calcul randomisé en temps polynomial et en espace logarithmique, à erreur bornée. Un compilateur effectif transforme chaque machine de ce type, à erreur unilatère ou bilatère, en un décideur déterministe en espace logarithmique, avec des bornes explicites de temps polynomial.","expertEn":"The manuscript asserts the equality L = RL = BPL, hence derandomization of polynomial-time bounded-error logarithmic-space computation. An effective compiler turns each such machine, with one-sided or two-sided error, into a deterministic logarithmic-space decider, with explicit polynomial running-time bounds.","sparkFr":"Piste pour l'informatique : le manuscrit affirme que le hasard n'augmente pas la puissance de cet espace logarithmique.","sparkEn":"A reason to look in computing: the manuscript asserts that randomness does not increase the power of this logarithmic space."},{"id":"104","titleEn":"Quasipolynomial algorithms for mean-payoff, stochastic and parity games","titleFr":"Algorithmes quasi-polynomiaux pour des jeux de paiement moyen et de parité","claim":"Gives deterministic algorithms using 2^O(( (L+2))^2) bit operations, for complete binary input length L, for ordinary mean-payoff games and two separate extensions. They compute exact values and optimal positional strategies in ordinary games, the nonnegative expectation-of-liminf value set in turn-based stochastic games, and the winning set for nonnegative liminf mean payoff conjoined with parity. Signed rewards, rational chance probabilities, and parity priorities are unrestricted and binary-encoded.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Turn-Based Stochastic Mean-Payoff Games in Deterministic Quasipolynomial Time","href":"preprints/Turn-Based-Stochastic-Mean-Payoff-Games-in-Deterministic-Quasipolynomial-Time-October-5-2026/stochastic-mean-payoff-games.pdf"},{"title":"Mean-payoff parity games in quasipolynomial time","href":"preprints/Mean-payoff-parity-games-in-quasipolynomial-time-October-5-2026/mean-payoff-parity.pdf"},{"title":"Deterministic quasipolynomial-time mean-payoff games","href":"preprints/Deterministic-quasipolynomial-time-mean-payoff-games-September-25-2026/paper.pdf"},{"title":"Randomized quasipolynomial-time mean-payoff games","href":"preprints/Randomized-quasipolynomial-time-mean-payoff-games-September-25-2026/paper.pdf"}],"plainFr":"Dans ces jeux, deux joueurs déplacent un pion et le gain se lit sur une moyenne à long terme, parfois avec du hasard ou une condition de parité. Le manuscrit affirme des algorithmes déterministes quasi-polynomiaux qui calculent les valeurs exactes et les stratégies positionnelles optimales.","plainEn":"In these games, two players move a token and the payoff is read from a long-run average, sometimes with chance or a parity condition. The manuscript asserts deterministic quasipolynomial algorithms that compute exact values and optimal positional strategies.","expertFr":"Le manuscrit donne des algorithmes déterministes en deux puissance O du carré d'un logarithme de la taille binaire, pour le paiement moyen et deux extensions. Ils calculent valeurs et stratégies positionnelles, les liminf non négatifs des jeux stochastiques, et le gagnant d'un liminf non négatif joint à la parité, données signées et probabilités rationnelles en binaire.","expertEn":"The manuscript gives deterministic algorithms using two to the power O of the square of a logarithm of the binary length, for mean-payoff games and two extensions. They compute values and positional strategies, the nonnegative liminf expectations of stochastic games, and the winning set of a nonnegative liminf conjoined with parity, for binary-encoded signed data and rational probabilities.","sparkFr":"Piste pour la vérification et les jeux sur graphes : ces algorithmes visent à décider qui gagne, en temps quasi-polynomial.","sparkEn":"A reason to look in verification and graph games: these algorithms aim to decide who wins, in quasipolynomial time."},{"id":"105","titleEn":"Perfect completeness for 2-to-1 games","titleFr":"Complétude parfaite pour les jeux deux-pour-un","claim":"Proves Khot's 2-to-1 Games Conjecture with perfect completeness: for every fixed rational δ∈(0,1), it is NP-hard to distinguish satisfiable games from games whose optimum is at most δ, on explicit unweighted instances. The alphabet depends only on δ, and every right-hand label has exactly two preimages under each constraint map.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Perfect completeness for 2-to-1 games","href":"preprints/Perfect-completeness-for-2-to-1-games-September-23-2026/paper.pdf"}],"plainFr":"Dans un jeu deux-pour-un, chaque contrainte donne à toute étiquette de droite exactement deux étiquettes de gauche. Le manuscrit affirme qu'il est NP-difficile de distinguer un jeu entièrement satisfaisable d'un jeu dont la meilleure valeur reste sous un seuil rationnel fixé.","plainEn":"In a two-to-one game, each constraint gives every right-hand label exactly two left-hand labels. The manuscript asserts that it is NP-hard to distinguish a fully satisfiable game from a game whose best value stays below a fixed rational threshold.","expertFr":"Le manuscrit affirme la conjecture des jeux deux-pour-un de Khot avec complétude parfaite. Pour tout rationnel delta strictement entre 0 et 1, il est NP-difficile de distinguer les jeux satisfaisables de ceux de valeur au plus delta, sur un alphabet qui ne dépend que de delta et sur une liste explicite non pondérée de contraintes, chaque étiquette à droite ayant exactement deux antécédents.","expertEn":"The manuscript asserts Khot's two-to-one Games Conjecture with perfect completeness. For every rational delta strictly between 0 and 1, it is NP-hard to distinguish satisfiable games from games of value at most delta, over an alphabet depending only on delta and on an explicit unweighted list of constraints, each right-hand label having exactly two preimages.","sparkFr":"Piste pour l'inapproximabilité : cette forme parfaite de difficulté NP sert de levier vers d'autres seuils d'approximation.","sparkEn":"A reason to look in inapproximability: this perfect-completeness form of NP-hardness is a lever toward other approximation thresholds."},{"id":"106","titleEn":"Hardness of coloring three-colorable graphs","titleFr":"Difficulté de colorier les graphes trois-coloriables","claim":"It is NP-hard to color a three-colorable graph using any fixed number c ≥ 3 of colors. More strongly, for every fixed 0 δ 1/3, a deterministic polynomial-time reduction from 3SAT produces simple unweighted graphs that are three-colorable in the satisfiable case and have no independent set of size δ n otherwise, where n is the number of vertices.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Hardness of finding large independent sets in three-colorable graphs","href":"preprints/Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026/Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026.pdf"}],"plainFr":"Colorier un graphe, c'est attribuer des couleurs aux sommets pour que deux voisins en reçoivent de différentes. Le manuscrit affirme qu'il est NP-difficile, pour tout nombre de couleurs fixé au moins égal à trois, de colorier un graphe pourtant trois-coloriable.","plainEn":"Coloring a graph means assigning colors to vertices so that neighbors receive different ones. The manuscript asserts that it is NP-hard, for every fixed number of colors at least three, to color a graph that is nevertheless three-colorable.","expertFr":"Pour tout delta fixé strictement entre 0 et 1/3, le manuscrit affirme une réduction déterministe polynomiale depuis 3SAT vers des graphes simples non pondérés, trois-coloriables dans le cas satisfaisable et sans ensemble indépendant de taille delta fois le nombre de sommets sinon. Trouver un coloriage propre avec un nombre fixé de couleurs au moins égal à trois, sur un graphe trois-coloriable, est donc NP-difficile.","expertEn":"For every fixed delta strictly between 0 and 1/3, the manuscript asserts a deterministic polynomial reduction from 3SAT to simple unweighted graphs that are three-colorable in the satisfiable case and have no independent set of size delta times the number of vertices otherwise. Finding a proper coloring with any fixed number of colors at least three, on a three-colorable graph, is therefore NP-hard.","sparkFr":"Piste pour l'algorithmique des graphes : même sous la promesse de trois couleurs, la coloration resterait NP-difficile.","sparkEn":"A reason to look in graph algorithms: even under a promise of three colors, coloring would remain NP-hard."},{"id":"107","titleEn":"Matrix multiplication with exponent at most 9/4","titleFr":"Multiplication matricielle d'exposant au plus 9/4","claim":"Proves ω≤9/4 over ℂ, giving O_ε(n^9/4+ε) arithmetic operations for square matrix multiplication. In characteristic zero, some inner dimension na with a > 0.465 permits n^2+o(1) rectangular multiplication. Further square bounds give ω < 2.258 outside finitely many positive characteristics and ω < 2.371054886006746 over every fixed field.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1969,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"An Upper Bound of 9/4 for the Matrix Multiplication Exponent","href":"preprints/Matrix-Multiplication-Nine-Fourths-October-2-2026/paper.pdf"},{"title":"Complex Matrix Multiplication Below 2.258 and Rectangular Bounds","href":"preprints/Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026/Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026.pdf"},{"title":"Staggered extraction for exact matrix multiplication over every field","href":"preprints/Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026/Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026.pdf"}],"plainFr":"Multiplier deux grandes matrices carrées est une opération centrale du calcul. Le manuscrit affirme que, sur les nombres complexes, l'exposant de ce produit est au plus 9/4, et il indique d'autres bornes pour des produits rectangulaires ou d'autres corps.","plainEn":"Multiplying two large square matrices is a central operation of computation. The manuscript asserts that over the complex numbers the exponent of this product is at most 9/4, and it states further bounds for rectangular products or other fields.","expertFr":"Le manuscrit affirme que l'exposant matriciel sur les complexes vaut au plus 9/4, donc un coût en n puissance 9/4 plus epsilon. En caractéristique nulle, une dimension intérieure n puissance a avec a supérieur à 0,465 permet un produit rectangulaire en n puissance 2+o(1) ; le texte donne aussi ω inférieur à 2,258 hors d'un nombre fini de caractéristiques, et inférieur à 2,371054886006746 sur tout corps.","expertEn":"The manuscript asserts that the matrix exponent over the complex numbers is at most 9/4, hence a cost of n to the power 9/4 plus epsilon. In characteristic zero an inner dimension n to the power a with a above 0.465 allows rectangular multiplication in n to the power 2+o(1); the text also gives a bound below 2.258 outside finitely many characteristics and below 2.371054886006746 over every field.","sparkFr":"Piste pour le calcul scientifique : l'exposant borne le coût algébrique du produit de matrices, sans implémentation affirmée.","sparkEn":"A reason to look in scientific computing: the exponent bounds the algebraic cost of matrix products, with no implementation asserted."},{"id":"108","titleEn":"A cubic permanent–determinant lower bound","titleFr":"Borne cubique entre le permanent et le déterminant","claim":"Proves an (n^3) lower bound for the border determinantal complexity of the n× n permanent over ℂ. Even coefficientwise limits of determinants of affine-linear matrices require matrix size at least cn^3, for an absolute c > 0 and all sufficiently large n; the same bound therefore holds for exact representations.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1913,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A cubic lower bound for border determinantal complexity of the permanent","href":"preprints/A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026/A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026.pdf"}],"plainFr":"Le permanent ressemble au déterminant, mais sans les signes qui rendent celui-ci plus maniable. Le manuscrit affirme que, même en autorisant des limites terme à terme, écrire le permanent comme un déterminant exige une matrice dont la taille croît au moins comme le cube du côté.","plainEn":"The permanent resembles the determinant, but without the signs that make the latter more tractable. The manuscript asserts that even if term-by-term limits are allowed, writing the permanent as a determinant requires a matrix whose size grows at least like the cube of the side.","expertFr":"Le manuscrit affirme une minoration d'ordre n au cube pour la complexité déterminantale de bord du permanent sur les complexes, limites coefficient par coefficient comprises. La même borne vaut pour les représentations exactes et pour les nombres de sommets et d'arêtes des programmes de branchement algébriques affines linéaires.","expertEn":"The manuscript asserts a lower bound of order n cubed for the border determinantal complexity of the n by n permanent over the complex numbers, including coefficientwise limits of determinants of affine-linear matrices. The same cubic bound holds for exact representations and for the numbers of vertices and edges in affine-linear algebraic branching programs, including limits with a fixed budget.","sparkFr":"Piste pour la complexité algébrique : la borne sépare le permanent des déterminants de petite taille, même à la limite.","sparkEn":"A reason to look in algebraic complexity: the bound separates the permanent from small determinants, even in the limit."},{"id":"109","titleEn":"Integer multiplication below n n","titleFr":"Multiplication d'entiers plus rapide que n log n","claim":"Multiplies two n-bit integers exactly at every input length in deterministic worst-case time O(n( n)^1- ), with =2^-182, on one fixed finite-alphabet Turing machine with finitely many one-dimensional tapes. This disproves the Schönhage–Strassen n n optimality conjecture in the ordinary multitape bit model.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1969,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Integer multiplication below n log n","href":"preprints/Integer-multiplication-below-n-log-n-September-23-2026/paper.pdf"}],"plainFr":"Multiplier deux entiers donnés par leurs bits est une brique de l'arithmétique des machines. Le manuscrit affirme un algorithme déterministe exact, sur une machine de Turing à plusieurs rubans, un peu plus rapide que l'ordre n log n que Schönhage et Strassen jugeaient optimal.","plainEn":"Multiplying two integers given by their bits is a building block of machine arithmetic. The manuscript asserts an exact deterministic algorithm, on a multitape Turing machine, a little faster than the order n log n that Schönhage and Strassen judged optimal.","expertFr":"Le manuscrit affirme la multiplication exacte de deux entiers de n bits, à toute longueur, en temps de pire cas d'ordre n fois (log n) puissance 1 moins 2 puissance −182, sur une machine de Turing fixée à rubans. Cela réfute, dans ce modèle multitape, la conjecture d'optimalité n log n de Schönhage et Strassen.","expertEn":"The manuscript asserts exact multiplication of two n-bit integers, at every length, in deterministic worst-case time of order n times (log n) to the power 1 minus epsilon, with epsilon equal to 2 to the power −182, on one fixed finite-alphabet Turing machine with finitely many one-dimensional tapes. This refutes, in this ordinary multitape model, the n log n optimality conjecture of Schönhage and Strassen.","sparkFr":"Piste pour l'arithmétique informatique : le manuscrit annonce un gain très mince sur le coût binaire de la multiplication.","sparkEn":"A reason to look in computer arithmetic: the manuscript announces a very thin gain on the bit cost of multiplication."},{"id":"110","titleEn":"Optimal-order randomized k-server on arbitrary metrics","titleFr":"k-serveur randomisé d'ordre optimal sur toute métrique","claim":"Establishes a randomized competitive ratio O( ^2(k+1)) for k-server on every metric space, matching the worst-case lower-bound order. One policy serves every finite oblivious request sequence, including on infinite unbounded metrics. On finite rational metrics, a uniform implementation has polynomial preprocessing and per-request bit cost in the input length and (t+1) at request t, with a finite instance-dependent additive movement constant.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1988,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Squared-logarithmic randomized k-server on arbitrary metrics","href":"preprints/Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026/Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026.pdf"},{"title":"Uniform computation of the squared-logarithmic k-server bound","href":"preprints/Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026/Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026.pdf"}],"plainFr":"Le k-serveur consiste à déplacer k agents pour honorer des requêtes révélées au fur et à mesure. Le manuscrit affirme une stratégie aléatoire dont le surcoût est l'ordre du carré du logarithme de k, sur toute métrique, ce qui rejoint l'ordre de la borne inférieure connue.","plainEn":"The k-server problem consists in moving k agents in a distance space to serve requests revealed over time. The manuscript asserts a random strategy whose overhead is of order the square of the logarithm of k, on every metric space, matching the order of the known lower bound.","expertFr":"Le manuscrit affirme un rapport randomisé de l'ordre du carré du logarithme de k+1 pour le k-serveur sur toute métrique, contre toute suite finie de requêtes oblivieuses, même infinie et non bornée. Sur les métriques rationnelles finies, le coût binaire par requête est polynomial, avec une constante additive de mouvement liée à l'instance, nulle si les départs sont distincts.","expertEn":"The manuscript asserts a randomized ratio of order the square of the logarithm of k+1 for k-server on every metric, against every finite oblivious sequence, even on infinite unbounded spaces. On finite rational metrics the per-request bit cost is polynomial, with an additive movement constant tied to the instance, vanishing if the starts are distinct.","sparkFr":"Piste pour les algorithmes en ligne : le rapport mesure le surcoût de servir des requêtes sans connaître l'avenir.","sparkEn":"A reason to look in online algorithms: the ratio measures the overhead of serving requests without knowing the future."},{"id":"111","titleEn":"One-sample matroid prophet inequalities against an almighty adversary","titleFr":"Inégalité de prophète à un échantillon sur les matroïdes","claim":"For every finite matroid known in advance, gives a distribution-independent online rule using one independent sample per element and earning a universal constant fraction of the expected offline optimum. Values are independent and nonnegative, with finite expected optimum. The guarantee holds even when the arrival-order adversary sees all samples, values, and the rule's entire random seed; no polynomial-time implementation is asserted.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1977,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"One Sample Suffices for Matroid Prophet Inequalities against an Almighty Adversary","href":"preprints/One-Sample-Suffices-for-Matroid-Prophet-Inequalities-against-an-Almighty-Adversary-September-23-2026/final.pdf"}],"plainFr":"Un algorithme en ligne découvre des valeurs une à une et doit décider aussitôt, sous les contraintes d'un matroïde, sans connaître leurs lois. Le manuscrit affirme qu'un seul échantillon indépendant par élément garantit une fraction universelle de l'optimum hors ligne, même face à un adversaire qui voit tout le hasard.","plainEn":"An online algorithm discovers values one by one and must decide at once, under the constraints of a matroid, without knowing their laws. The manuscript asserts that one independent sample per element guarantees a universal fraction of the offline optimum, even against an adversary who sees all the randomness.","expertFr":"Pour tout matroïde fini connu d'avance, une règle à un échantillon indépendant par élément, sans les lois, garantit une fraction universelle de l'optimum hors ligne espéré, pour des valeurs indépendantes non négatives. La garantie tient si l'adversaire voit échantillons, valeurs et graine ; le rapport affirmé est 2 puissance −310, sans temps polynomial revendiqué.","expertEn":"For every finite matroid known in advance, a rule with one independent sample per element and no knowledge of the laws guarantees a universal fraction of the expected offline optimum, for independent nonnegative values. The guarantee holds if the adversary sees samples, values and the seed; the asserted ratio is 2 to the power −310, with no polynomial time claimed.","sparkFr":"Piste pour le choix en ligne sous contrainte : un échantillon par élément remplacerait la connaissance des lois de valeur.","sparkEn":"A reason to look at constrained online choice: one sample per element would replace knowledge of the value laws."},{"id":"112","titleEn":"Beyond the square-root exponent for depth-three circuits","titleFr":"Circuits de profondeur trois au-delà de l'exposant racine carrée","claim":"Constructs a single language in deterministic polynomial time whose n-bit membership function requires 2^ω( n) total gates in unbounded-fan-in OR–AND–OR circuits, at every sufficiently large input length. This crosses the square-root-exponent threshold for explicit depth-three Boolean circuit lower bounds.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1985,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Beyond the Square-Root Exponent for Depth-Three Boolean Circuits","href":"preprints/Beyond-the-Square-Root-Exponent-for-Depth-Three-Boolean-Circuits-September-23-2026/main.pdf"}],"plainFr":"Un circuit de profondeur trois combine des ou et des et pour accepter un mot binaire. Le manuscrit affirme un langage en temps polynomial dont la fonction sur n bits exige, dans tout tel circuit à entrées non bornées, bien plus que deux à la puissance racine de n portes.","plainEn":"A depth-three circuit combines ors and ands to accept or reject a binary word. The manuscript asserts a polynomial-time language whose function on n bits requires, in every such circuit of unbounded fan-in, a number of gates two to a power well beyond the square root of n.","expertFr":"Le manuscrit construit un langage du temps polynomial déterministe dont la fonction d'appartenance sur n bits exige deux puissance omega de la racine de n portes au total, dans tout circuit ou-et-ou à fan-in non borné et pour toute longueur assez grande. La borne compte toutes les portes, couche du bas comprise, et franchit le seuil d'exposant racine carrée pour les minorations explicites en profondeur trois.","expertEn":"The manuscript constructs a deterministic polynomial-time language whose membership function on n bits requires two to the power omega of the square root of n gates in total, in every unbounded-fan-in or-and-or circuit and at every sufficiently large length. The bound counts all gates, bottom layer included, and crosses the square-root exponent threshold for explicit depth-three lower bounds.","sparkFr":"Piste pour la complexité des circuits : le texte donne une minoration explicite au-delà de l'exposant racine carrée.","sparkEn":"A reason to look in circuit complexity: the text gives an explicit lower bound beyond the square-root exponent."},{"id":"113","titleEn":"Approximate counting and entropy of perfect matchings","titleFr":"Comptage approximatif et entropie des couplages parfaits","claim":"Gives a fully polynomial randomized approximation scheme for counting perfect matchings in arbitrary finite simple graphs, with exact detection of zero counts. Also proves the perfect-matching entropy conjecture of Anari, Oveis Gharan, and Vinzant, bounding the maximum entropy of a matching law at every feasible edge-marginal vector in a loopless labelled multigraph, including boundary points.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1965,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A Fully Polynomial Randomized Approximation Scheme for Perfect Matchings in General Graphs","href":"preprints/A-Fully-Polynomial-Randomized-Approximation-Scheme-for-Perfect-Matchings-in-General-Graphs-September-23-2026/main.pdf"},{"title":"Entropy and Face Dimension of the Perfect-Matching Polytope","href":"preprints/Entropy-and-Face-Dimension-of-the-Perfect-Matching-Polytope-September-23-2026/main.pdf"}],"plainFr":"Un couplage parfait apparie tous les sommets d'un graphe sans réutiliser une arête. Le manuscrit affirme un algorithme aléatoire de coût polynomial qui approche le nombre de ces appariements, en reconnaissant exactement l'absence de solution, et une borne d'entropie sur les lois de couplage.","plainEn":"A perfect matching pairs every vertex of a graph without reusing an edge. The manuscript asserts a random algorithm of polynomial cost that approximates the number of such pairings, recognizing exactly when none exist, and an entropy bound on matching laws.","expertFr":"Le manuscrit donne un schéma randomisé pleinement polynomial pour compter les couplages parfaits des graphes simples finis, renvoyant zéro avec certitude s'il n'en existe aucun. Il affirme aussi la conjecture d'entropie d'Anari, Oveis Gharan et Vinzant pour toute loi de couplage à marginales réalisables, bord compris, dans un multigraphe étiqueté sans boucle.","expertEn":"The manuscript gives a fully polynomial randomized scheme for counting perfect matchings in finite simple graphs, returning zero with certainty when none exist. It also asserts the entropy conjecture of Anari, Oveis Gharan and Vinzant for every matching law with feasible marginals, boundary included, in a loopless labelled multigraph.","sparkFr":"Piste pour le comptage combinatoire : approcher le nombre de couplages parfaits est un problème classique d'échantillonnage.","sparkEn":"A reason to look in combinatorial counting: approximating the number of perfect matchings is a classical sampling problem."},{"id":"114","titleEn":"Approximate counting of common integer polymatroid bases","titleFr":"Comptage approximatif des bases entières communes de polymatroïdes","claim":"Gives a fully polynomial randomized approximation scheme for counting common integer bases of two integral polymatroids of equal total rank, supplied by exact rank-value oracles. Capacities are binary-encoded, each integer vector counts once, and oracle calls and bit operations outside the oracles are polynomial on every execution. For matroids presented by independence oracles, the results also cover common independent sets of prescribed, unrestricted, or maximum cardinality, even when the ranks differ.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1935,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An FPRAS for Common Integer Polymatroid Bases with Binary Capacities","href":"preprints/An-FPRAS-for-Common-Integer-Polymatroid-Bases-with-Binary-Capacities-October-5-2026/polymatroid-fpras.pdf"},{"title":"Approximate counting of common bases of two matroids","href":"preprints/Approximate-counting-of-common-bases-of-two-matroids-September-23-2026/main.pdf"}],"plainFr":"Un polymatroïde décrit, par une fonction de rang, quels vecteurs entiers sont admissibles, et une base commune sature les deux rangs totaux. Le manuscrit affirme un algorithme aléatoire pleinement polynomial qui compte ces bases lorsque les rangs totaux coïncident, en interrogeant des oracles de rang.","plainEn":"A polymatroid describes, through a rank function, which integer vectors are admissible, and a common base saturates both total ranks. The manuscript asserts a fully polynomial random algorithm that counts these bases when the total ranks agree, by querying rank oracles.","expertFr":"Le manuscrit donne un schéma pleinement polynomial comptant les bases entières communes de deux polymatroïdes de même rang total, via des oracles de rang exacts et des capacités binaires. Le travail hors oracles est polynomial à chaque exécution, et, pour un oracle d'indépendance, le comptage couvre aussi les indépendants de taille prescrite, libre ou maximale.","expertEn":"The manuscript gives a fully polynomial scheme counting common integer bases of two polymatroids of equal total rank, via exact rank oracles and binary capacities. Work outside the oracles is polynomial on every run, and, for an independence oracle, the count also covers independent sets of prescribed, free or maximum size.","sparkFr":"Piste pour l'optimisation combinatoire : compter des bases communes prépare l'échantillonnage sous des contraintes de rang.","sparkEn":"A reason to look in combinatorial optimization: counting common bases prepares sampling under rank constraints."},{"id":"115","titleEn":"Sampling and counting contingency tables with arbitrary margins","titleFr":"Tables de contingence : échantillonnage uniforme et comptage","claim":"For nonnegative integer matrices with prescribed row and column sums, gives exact uniform sampling in expected polynomial bit time and almost-uniform sampling in worst-case polynomial bit time. The dimensions and binary-encoded margins are unrestricted. Also gives a fully polynomial randomized approximation scheme for counting such tables with arbitrary individual cell bounds, including structural zeros, with polynomial cost on every execution.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Exact Uniform Sampling of Contingency Tables with Arbitrary Margins","href":"preprints/Exact-Uniform-Sampling-of-Contingency-Tables-with-Arbitrary-Margins-September-24-2026/main.pdf"},{"title":"An FPRAS for Cell-Bounded Contingency Tables","href":"preprints/An-FPRAS-for-Cell-Bounded-Contingency-Tables-September-24-2026/main.pdf"}],"plainFr":"Une table de contingence est un tableau d'entiers positifs ou nuls dont les sommes de lignes et de colonnes sont imposées. Le manuscrit affirme un tirage exactement uniforme en temps binaire espéré polynomial, et une approximation du nombre de tables même avec des bornes sur chaque case.","plainEn":"A contingency table is an array of nonnegative integers whose row and column sums are prescribed. The manuscript asserts an exactly uniform draw in expected polynomial bit time, and an approximation of the number of tables even with bounds on each cell.","expertFr":"Sans hypothèse de positivité ni de dimension fixée, le manuscrit donne un tirage uniforme exact des tables à marges binaires, de temps espéré polynomial, et un tirage presque uniforme de temps polynomial au pire. Il donne aussi un schéma pleinement polynomial pour les compter avec des bornes de cases quelconques, zéros structurels compris.","expertEn":"For arbitrary binary-encoded margins, with no positivity, balance or fixed-dimension assumption, the manuscript gives an exact uniform draw of expected polynomial bit time and an almost-uniform draw of worst-case polynomial time. It also gives a fully polynomial randomized approximation scheme for counting with arbitrary individual cell bounds, structural zeros included, at polynomial cost on every execution.","sparkFr":"Piste pour la statistique des tableaux : tirer des tables à marges fixées sert aux tests d'indépendance, et le texte en borne le coût.","sparkEn":"A reason to look in the statistics of tables: drawing tables with fixed margins serves independence tests, and the text bounds the cost."},{"id":"116","titleEn":"Uniform black-box noncommutative identity testing across characteristics","titleFr":"Test d'identité non commutatif uniforme selon la caractéristique","claim":"For each characteristic, constructs in deterministic polynomial bit time a polynomial-dimensional matrix tuple detecting every nonzero division-free noncommutative formula of bounded size over any field of that characteristic. Rational formulas over ℚ also admit polynomial-size hitting lists whenever they have a defined rational-matrix evaluation.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Uniform Matrix Hitting Points in Every Positive Characteristic","href":"preprints/Uniform-Matrix-Hitting-Points-in-Every-Positive-Characteristic-October-4-2026/uniform-matrix-hitting-points-positive-characteristic.pdf"},{"title":"One Rational Matrix Hitting Point for Noncommutative Formulas","href":"preprints/One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026/One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026.pdf"},{"title":"Polynomial Hitting Lists for Noncommutative Rational Formulas","href":"preprints/Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026/Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026.pdf"}],"plainFr":"Une formule non commutative combine des variables sans supposer qu'elles commutent, et l'on veut savoir si elle est identiquement nulle. Le manuscrit affirme, pour chaque caractéristique, des matrices de taille polynomiale qui détectent toute formule non nulle sans division et de taille bornée.","plainEn":"A noncommutative formula combines variables without assuming that they commute, and one wants to know whether it is identically zero. The manuscript asserts, for each characteristic, matrices of polynomial size that detect every nonzero division-free formula of bounded size.","expertFr":"Pour chaque caractéristique, le manuscrit construit en temps polynomial déterministe des matrices qui détectent toute formule non commutative sans division, non nulle et de taille bornée, sur tout corps de cette caractéristique. La dimension est d'ordre n au cube fois s à la sixième, et les formules rationnelles ont des listes tests polynomiales si une évaluation matricielle rationnelle est définie.","expertEn":"For each characteristic, the manuscript builds in deterministic polynomial time matrices that detect every nonzero division-free noncommutative formula of bounded size over any field of that characteristic. The dimension is of order n cubed times s to the sixth, and rational formulas have polynomial hitting lists if a rational matrix evaluation is defined.","sparkFr":"Piste pour le calcul algébrique : un test matriciel évite de développer une formule non commutative pour décider si elle est nulle.","sparkEn":"A reason to look in algebraic computation: a matrix test avoids expanding a noncommutative formula to decide whether it is zero."},{"id":"117","titleEn":"Uniform sparsest cut: hardness and semidefinite gaps","titleFr":"Coupe la plus creuse uniforme : difficulté et écarts semidéfinis","claim":"Proves that approximating Uniform Sparsest Cut within any fixed constant factor is NP-hard, even with nonnegative rational capacities and unit demands. The Goemans–Linial semidefinite relaxation also has integrality gaps of order at least √( n)/( n)^3, approaching the square-root-logarithmic upper bound.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1994,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Constant-factor hardness of uniform sparsest cut","href":"preprints/Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026/Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026.pdf"},{"title":"Near-square-root logarithmic integrality gaps for uniform sparsest cut","href":"preprints/Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026/Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026.pdf"}],"plainFr":"Cette coupe cherche un partage des sommets qui sépare peu d'arêtes au regard des paires qu'il sépare. Le manuscrit affirme qu'approcher sa valeur à un facteur constant fixé est NP-difficile, et que la relaxation par matrices positives laisse un écart encore voisin de la meilleure borne supérieure connue.","plainEn":"This cut looks for a split of the vertices that separates few edges relative to the pairs it separates. The manuscript asserts that approximating its value within any fixed constant factor is NP-hard, and that the positive-matrix relaxation still leaves a gap close to the best known upper bound.","expertFr":"Pour tout facteur supérieur à 1, approcher la coupe la plus creuse uniforme est NP-difficile, même à capacités rationnelles et demande unité. La relaxation semidéfinie de Goemans–Linial a un écart au moins de l'ordre de la racine de log n sur le cube d'un logarithme itéré, proche de la borne supérieure en racine de logarithme.","expertEn":"The manuscript asserts that for every factor C above 1, approximating Uniform Sparsest Cut is NP-hard, even with nonnegative rational capacities and unit demand between every pair of vertices. The Goemans–Linial semidefinite relaxation has integrality gaps at least of order the square root of the logarithm of n divided by the cube of an iterated logarithm, an order approaching the square-root-logarithmic upper bound.","sparkFr":"Piste pour l'algorithmique des graphes : la difficulté et l'écart semidéfini limitent les garanties d'approximation de cette coupe.","sparkEn":"A reason to look in graph algorithms: the hardness and the semidefinite gap limit the approximation guarantees for this cut."},{"id":"118","titleEn":"Bin packing and unbounded configuration-LP gaps","titleFr":"Empaquetage en bacs : écarts non bornés du programme de configurations","claim":"Disproves the modified integer round-up conjecture of Scheithauer and Terno: the integral bin-packing optimum can exceed its configuration linear-programming value by an arbitrarily large additive constant. Approximating the optimum within any fixed additive constant is also NP-hard, even when every item exceeds 1/6 and each bin holds at most five items.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Additive hardness and unbounded configuration gaps in bin packing","href":"preprints/Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026/Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026.pdf"}],"plainFr":"Il s'agit de ranger des objets dans le moins de bacs possible de capacité un. Le manuscrit affirme que l'optimum entier peut dépasser une relaxation linéaire classique d'une constante arbitrairement grande, et qu'approcher cet optimum à une constante additive près est NP-difficile.","plainEn":"The task is to pack items into as few bins of capacity one as possible. The manuscript asserts that the integral optimum can exceed a classical linear relaxation by an arbitrarily large constant, and that approximating this optimum within an additive constant is NP-hard.","expertFr":"Le manuscrit réfute l'arrondi entier modifié de Scheithauer et Terno : l'optimum du bin packing peut dépasser le programme de configurations d'une constante additive arbitraire. Distinguer, à constante additive fixée près, le nombre de bacs nécessaire est NP-difficile, même si chaque objet dépasse un sixième et si chaque bac en contient au plus cinq.","expertEn":"The manuscript refutes the modified integer round-up of Scheithauer and Terno: the bin-packing optimum can exceed the configuration program by an arbitrary additive constant. Distinguishing the needed number of bins up to any fixed additive constant is NP-hard, even if every item exceeds one sixth and each bin holds at most five.","sparkFr":"Piste pour la recherche opérationnelle : l'écart borne ce que la relaxation de configurations dit réellement de l'optimum entier.","sparkEn":"A reason to look in operations research: the gap bounds what the configuration relaxation really says about the integral optimum."},{"id":"119","titleEn":"The Courtade–Kumar and Hellinger conjectures","titleFr":"Les conjectures de Courtade–Kumar et de Hellinger","claim":"Proves the Courtade–Kumar conjecture: among Boolean functions of independent uniform bits, a single coordinate retains the most mutual information after independent bit-flip noise. A stronger theorem treats randomized binary summaries at fixed initial information. The Hellinger conjecture is also proved for every Boolean output bias and noise correlation.","nature":"dynamique","domain":"information","complexity":"frontiere","problemYear":1988,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Sharp binary-information contraction on the discrete cube","href":"preprints/Sharp-binary-information-contraction-on-the-discrete-cube-September-24-2026/main.pdf"},{"title":"Hellinger contraction with arbitrary Boolean output bias","href":"preprints/Hellinger-contraction-with-arbitrary-Boolean-output-bias-September-24-2026/main.pdf"}],"plainFr":"On brouille les bits d'un mot aléatoire par des retournements indépendants, puis on cherche quelle fonction garde le plus d'information. Le manuscrit affirme qu'une seule coordonnée suffit, et il établit aussi la conjecture de Hellinger pour tout biais et toute corrélation de bruit.","plainEn":"One scrambles each bit of a random word by independent flips, then asks which function of the word keeps the most information. The manuscript asserts that the best choice is to keep a single coordinate, and it also establishes the Hellinger conjecture for every output bias and every noise correlation.","expertFr":"Le manuscrit affirme la conjecture de Courtade–Kumar : parmi les fonctions booléennes de bits uniformes indépendants, une seule coordonnée maximise l'information mutuelle après un bruit indépendant de retournement. Un énoncé plus fort concerne les résumés binaires randomisés à information initiale fixée, et la conjecture de Hellinger est affirmée pour tout biais booléen de sortie et toute corrélation de bruit.","expertEn":"The manuscript asserts the Courtade–Kumar conjecture: among Boolean functions of independent uniform bits, a single coordinate maximizes mutual information after independent bit-flip noise. A stronger statement concerns randomized binary summaries at fixed initial information, and the Hellinger conjecture is asserted for every Boolean output bias and every noise correlation.","sparkFr":"Piste pour la théorie de l'information : le résultat compare ce qu'un canal bruité peut conserver d'un message en bits.","sparkEn":"A reason to look in information theory: the result compares what a noisy channel can retain of a bit message."},{"id":"120","titleEn":"Almost-linear-time exact matching and prescribed-degree factors in general graphs","titleFr":"Couplage maximum en temps presque linéaire","claim":"Gives a randomized algorithm finding an exact maximum-cardinality matching in any simple undirected graph in (n+m)^1+o(1) word time, with success probability at least 2/3. The time bound holds on every computation path. The same guarantees apply to finding a spanning subgraph with prescribed admissible vertex degrees, or deciding that none exists.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Almost-Linear-Time Maximum-Cardinality Matching in General Graphs","href":"preprints/Almost-Linear-Time-Maximum-Cardinality-Matching-in-Sparse-General-Graphs-September-24-2026/main.pdf"}],"plainFr":"Un couplage maximum apparie le plus grand nombre possible de sommets sans partager une arête. Le manuscrit affirme un algorithme aléatoire qui en trouve un dans un graphe simple en temps presque linéaire en la taille du graphe, avec probabilité de succès au moins deux tiers.","plainEn":"A maximum matching pairs as many vertices as possible without sharing an edge. The manuscript asserts a random algorithm that finds one in a simple graph in near-linear time in the size of the graph, with success probability at least two thirds.","expertFr":"Le manuscrit donne un algorithme randomisé trouvant un couplage maximum dans tout graphe simple en temps (n+m) puissance 1+o(1), avec probabilité au moins deux tiers, borne valable sur chaque chemin. Les mêmes garanties valent pour décider et construire un sous-graphe couvrant de degrés admissibles prescrits.","expertEn":"The manuscript gives a randomized algorithm that finds a maximum-cardinality matching in any simple undirected graph in time n plus m, the sum to the power 1 plus o(1), in the logarithmic-word model, with probability at least two thirds, the bound holding on every computation path. The same guarantees apply to deciding and constructing a spanning subgraph whose prescribed degrees are admissible.","sparkFr":"Piste pour l'algorithmique des graphes : le couplage maximum deviendrait presque linéaire, avec une probabilité de succès fixée.","sparkEn":"A reason to look in graph algorithms: maximum matching would become near-linear, with a fixed success probability."},{"id":"121","titleEn":"Almost-linear approximation of edit distance","titleFr":"Approximation presque linéaire de la distance d'édition","claim":"For every fixed rational ε∈(0,1), gives a randomized (1+ε) approximation to unit-cost edit distance in worst-case expected time N^1+o(1), with success probability at least 2/3. The strings have total length N and polynomially bounded integer symbols. This is an asymptotic guarantee at fixed accuracy.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"An Almost-Linear Approximation Scheme for Edit Distance","href":"preprints/An-Almost-Linear-Approximation-Scheme-for-Edit-Distance-September-24-2026/paper.pdf"}],"plainFr":"La distance d'édition est le nombre minimal de modifications élémentaires entre deux chaînes. Le manuscrit affirme que, pour une précision relative rationnelle fixée, un algorithme aléatoire l'approche en temps espéré presque linéaire en la longueur totale.","plainEn":"Edit distance is the least number of elementary edits between two strings. The manuscript asserts that, for a fixed rational relative accuracy, a random algorithm approximates it in expected near-linear time in the total length.","expertFr":"Pour tout rationnel epsilon strictement entre 0 et 1, le manuscrit donne une approximation randomisée de facteur 1 plus epsilon de la distance d'édition à coût unitaire, en temps espéré de pire cas N puissance 1 plus o(1), avec succès au moins deux tiers. Les chaînes ont longueur totale N et symboles entiers de taille polynomiale, et l'algorithme renvoie zéro de façon déterministe lorsqu'elles sont égales.","expertEn":"For every rational epsilon strictly between 0 and 1, the manuscript gives a randomized approximation of factor 1 plus epsilon to unit-cost edit distance, in worst-case expected time N to the power 1 plus o(1), with success at least two thirds. The strings have total length N and polynomially bounded integer symbols, and the algorithm returns zero deterministically when they are equal.","sparkFr":"Piste pour la comparaison de séquences : la distance d'édition serait approximable en temps presque linéaire à précision fixée.","sparkEn":"A reason to look in sequence comparison: edit distance would be approximable in near-linear time at fixed accuracy."},{"id":"122","titleEn":"Quantitative trace-reconstruction bounds with a uniform decoder","titleFr":"Reconstruction de traces : bornes quantitatives et décodeur uniforme","claim":"At every fixed deletion probability in (0,1), reconstructing an arbitrary length-n binary string requires n^ ( n) independent traces, ruling out polynomial-sample reconstruction. A uniform decoder achieves quasipolynomial sample and running-time bounds for known fixed rational retention probabilities. When the deletion probability is at most n^-ε for fixed ε > 0, both bounds become polynomial in the input and parameter encoding.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Uniform quasipolynomial-time trace reconstruction","href":"preprints/Uniform-quasipolynomial-time-trace-reconstruction-October-5-2026/uniform-trace-reconstruction.pdf"},{"title":"A latest-anchor induction with spectrally compact masks for worst-case trace reconstruction","href":"preprints/A-latest-anchor-induction-with-spectrally-compact-masks-for-worst-case-trace-reconstruction-October-5-2026/paper.pdf"},{"title":"Quantitative lower bounds for trace reconstruction","href":"preprints/quantitative-lower-bounds-for-trace-reconstruction-September-24-2026/paper.pdf"}],"plainFr":"Une trace est une copie binaire où des symboles ont été effacés au hasard. Le manuscrit affirme qu'à taux d'effacement fixé il faut plus qu'un nombre polynomial de traces, tandis qu'un décodeur uniforme suffit en budget quasi-polynomial si la rétention est connue.","plainEn":"A trace is a copy of a binary string in which symbols have been deleted at random. The manuscript asserts that at a fixed deletion rate more than a polynomial number of traces is required to reconstruct every string, while a uniform decoder succeeds with a quasipolynomial budget when the retention probability is known.","expertFr":"À probabilité d'effacement fixée entre 0 et 1, reconstruire toute chaîne binaire de longueur n exige un nombre de traces n puissance un logarithme, donc plus que polynomial. Un décodeur uniforme a des bornes quasi-polynomiales si la rétention rationnelle est connue et fixée, et des bornes polynomiales si l'effacement vaut au plus n puissance moins epsilon.","expertEn":"At a fixed deletion probability between 0 and 1, reconstructing every binary string of length n requires a number of traces n to a logarithmic power, hence more than polynomial. A uniform decoder has quasipolynomial bounds if the rational retention is known and fixed, and polynomial bounds if deletion is at most n to the power minus epsilon.","sparkFr":"Piste pour les codes correcteurs : le nombre de copies effacées pilote la possibilité de retrouver une chaîne binaire.","sparkEn":"A reason to look in coding theory: the number of deleted copies governs whether a binary string can be recovered."},{"id":"124","titleEn":"Polynomial-time scheduling on three identical machines","titleFr":"Ordonnancement polynomial sur trois machines identiques","claim":"Resolves the three-processor unit-job scheduling problem of Garey and Johnson: a deterministic polynomial-time algorithm minimizes makespan for nonpreemptive unit-length jobs with arbitrary precedence constraints on three identical parallel machines. For an explicitly given precedence graph, it decides deadline feasibility exactly and constructs a feasible schedule.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Polynomial-Time Algorithm for Three-Machine Unit-Job Scheduling","href":"preprints/A-polynomial-time-algorithm-for-three-machine-unit-job-scheduling-September-24-2026/paper.pdf"}],"plainFr":"On place des tâches de durée un, soumises à des précédences, sur trois machines identiques, sans les interrompre. Le manuscrit affirme un algorithme déterministe polynomial qui finit le plus tôt possible et décide exactement si une échéance peut être tenue.","plainEn":"One places unit-length jobs, subject to precedence constraints, on three identical machines, without interrupting them. The manuscript asserts a deterministic polynomial algorithm that finishes as early as possible and decides exactly whether a deadline can be met.","expertFr":"Le manuscrit résout le problème unitaire à trois processeurs de Garey et Johnson : un algorithme déterministe en temps polynomial minimise la durée totale de tâches non préemptives de longueur un, à précédences arbitraires, sur trois machines parallèles identiques. Pour un graphe de précédence donné explicitement, il décide exactement si une échéance est réalisable et construit un ordonnancement qui la respecte.","expertEn":"The manuscript resolves the three-processor unit-job problem of Garey and Johnson: a deterministic polynomial-time algorithm minimizes the makespan of nonpreemptive unit-length jobs with arbitrary precedence constraints on three identical parallel machines. For an explicitly given precedence graph, it decides exactly whether a deadline is feasible and constructs a schedule that meets it.","sparkFr":"Piste pour l'ordonnancement : sur trois machines identiques, les précédences de durée un deviendraient traitables en temps polynomial.","sparkEn":"A reason to look in scheduling: on three identical machines, unit-time precedence constraints would become polynomial-time tractable."},{"id":"125","titleEn":"The metric k-median approximation threshold and recovery","titleFr":"Seuil d'approximation du k-médian métrique","claim":"Gives a deterministic polynomial-time (1+2/e+ε)-approximation for finite rational metric k-median with specified candidate facilities, for every fixed ε > 0. Assuming P NP, the optimal infimum approximation factor is 1+2/e.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Single-exponential recovery and bounded-price strictness for metric k-median","href":"preprints/Single-Exponential-Recovery-and-Bounded-Price-Strictness-for-Metric-k-Median-September-24-2026/paper.pdf"},{"title":"The approximation threshold for metric k-median","href":"preprints/The-Approximation-Threshold-for-Metric-k-Median-September-24-2026/main.pdf"}],"plainFr":"Le k-médian choisit k centres afin de limiter la somme des distances des clients au centre le plus proche, dans une métrique finie. Le manuscrit affirme une approximation polynomiale de facteur un plus deux divisé par e, à epsilon près, et que ce seuil est optimal si P diffère de NP.","plainEn":"Metric k-median chooses k centers so as to limit the sum of distances from clients to the nearest center, in a finite metric. The manuscript asserts a polynomial approximation of factor one plus two divided by e, up to epsilon, and that this threshold is optimal if P differs from NP.","expertFr":"Le manuscrit donne, pour tout epsilon positif fixé, une approximation déterministe en temps polynomial de facteur 1 plus 2/e plus epsilon pour le k-médian métrique rationnel fini à sites candidats prescrits. En supposant que P diffère de NP, l'infimum optimal des facteurs d'approximation est exactement 1 plus 2/e.","expertEn":"The manuscript gives, for every fixed positive epsilon, a deterministic polynomial-time approximation of factor 1 plus 2/e plus epsilon for finite rational metric k-median with prescribed candidate sites. Assuming that P differs from NP, the optimal infimum of approximation factors is exactly 1 plus 2/e.","sparkFr":"Piste pour l'algorithmique de localisation : le facteur un plus deux sur e serait le seuil optimal du k-médian métrique.","sparkEn":"A reason to look in location algorithms: the factor one plus two over e would be the optimal threshold for metric k-median."},{"id":"126","titleEn":"Exponential semidefinite complexity of perfect matching","titleFr":"Taille semidéfinie exponentielle du polytope des couplages parfaits","claim":"Proves that every exact semidefinite lift of the perfect matching polytope has exponential size, answering Rothvoss's polynomial-size lift question negatively. The bound holds even for the positive semidefinite rank of its odd-cut slack matrix after any fixed shift 0 ρ 1, allowing arbitrary real positive semidefinite factors.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1965,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":true,"pdfs":[{"title":"Exponential PSD rank of positively shifted matching matrices","href":"preprints/Exponential-PSD-rank-of-positively-shifted-matching-matrices-October-5-2026/shifted-matching-psd.pdf"}],"plainFr":"Ce polytope rassemble les combinaisons convexes des appariements qui couvrent chaque sommet une fois. Le manuscrit affirme que toute formulation exacte par matrices semidéfinies a une taille exponentielle, même après un décalage fixé des inégalités de coupes impaires.","plainEn":"This polytope gathers the convex combinations of the pairings that cover each vertex once. The manuscript asserts that every exact formulation by semidefinite matrices has exponential size, even after a fixed shift of the odd-cut inequalities.","expertFr":"Tout relèvement semidéfini exact du polytope des couplages parfaits a, selon le manuscrit, une taille exponentielle, contre l'espoir polynomial de Rothvoss. Pour tout décalage fixé entre 0 et 1, le rang semidéfini positif de la matrice de mou des coupes impaires croît comme deux puissance un ordre linéaire de n.","expertEn":"The manuscript asserts that every exact semidefinite lift of the perfect matching polytope has exponential size, a negative answer to Rothvoss's question on polynomial size. For every fixed shift strictly between 0 and 1, the slack matrix indexed by odd cuts and perfect matchings has real positive semidefinite rank two to a linear order in n, as even n tends to infinity.","sparkFr":"Piste pour l'optimisation semidéfinie : le couplage parfait échapperait aux formulations exactes de taille polynomiale.","sparkEn":"A reason to look in semidefinite optimization: perfect matching would escape exact formulations of polynomial size."},{"id":"127","titleEn":"Average sensitivity of polynomial threshold functions","titleFr":"Sensibilité moyenne des fonctions de seuil polynomiales","claim":"Proves that a degree-at-most-d polynomial threshold function on the uniform n-dimensional Boolean cube has average sensitivity at most 8d n, uniformly for 1≤ d≤ n. Average sensitivity counts expected output changes under single-bit flips. This establishes the asymptotic Gotsman–Linial conjecture, allowing polynomial zeros with sign (0)=1.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1988,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Average sensitivity of polynomial threshold functions","href":"preprints/Average-Sensitivity-of-Polynomial-Threshold-Functions-September-25-2026/main.pdf"}],"plainFr":"Une telle fonction répond selon le signe d'un polynôme évalué sur des bits. Le manuscrit affirme que, sur le cube booléen équitable, le nombre moyen de bits dont le retournement change la réponse est au plus huit fois le degré fois la racine du nombre de bits.","plainEn":"Such a function answers according to the sign of a polynomial evaluated on bits. The manuscript asserts that on the fair Boolean cube, the average number of bits whose flip changes the answer is at most eight times the degree times the square root of the number of bits.","expertFr":"Le manuscrit affirme qu'une fonction de seuil polynomiale de degré au plus d, sur le cube booléen uniforme de dimension n, a une sensibilité moyenne au plus 8 d fois la racine de n, pour tout d entre 1 et n. Cela établit la forme asymptotique de la conjecture de Gotsman–Linial, l'espérance portant sur les changements après retournement d'un seul bit, avec la convention que le signe de zéro vaut un.","expertEn":"The manuscript asserts that a polynomial threshold function of degree at most d, on the uniform Boolean cube of dimension n, has average sensitivity at most 8 d times the square root of n, for every d between 1 and n. This establishes the asymptotic form of the Gotsman–Linial conjecture, the expectation being over changes after a single bit flip, with the convention that the sign of zero is one.","sparkFr":"Piste pour l'apprentissage booléen : la sensibilité moyenne borne la stabilité d'un classificateur défini par le signe d'un polynôme.","sparkEn":"A reason to look in Boolean learning: average sensitivity bounds the stability of a classifier defined by the sign of a polynomial."},{"id":"128","titleEn":"A factor-two approximation for shortest common superstring","titleFr":"Approximation de facteur deux pour la plus courte surchaîne commune","claim":"Gives a deterministic polynomial-time algorithm constructing a common superstring of length at most twice the optimum for every finite family of explicitly represented strings. The running time is polynomial in the full encoded input length, including symbol labels.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Polynomial-Time 2-Approximation for Shortest Common Superstring","href":"preprints/A-Polynomial-Time-2-Approximation-for-Shortest-Common-Superstring-September-24-2026/paper.pdf"}],"plainFr":"Une surchaîne commune est un mot qui contient chaque chaîne d'une famille comme bloc d'un seul tenant. Le manuscrit affirme un algorithme déterministe polynomial qui en construit une de longueur au plus deux fois la plus courte possible.","plainEn":"A common superstring is a word that contains each string of a family as one contiguous block. The manuscript asserts a deterministic polynomial algorithm that builds one of length at most twice the shortest possible.","expertFr":"Le manuscrit donne un algorithme déterministe qui, pour toute famille finie de chaînes ordinaires explicites, produit une surchaîne commune de longueur au plus deux fois l'optimum, en temps polynomial dans la taille encodée totale, étiquettes de symboles comprises. La garantie concerne cet algorithme, et non la procédure gloutonne classique de chevauchement maximal.","expertEn":"The manuscript gives a deterministic algorithm that, for every finite family of explicit ordinary strings, outputs a common superstring of length at most twice the optimum, in time polynomial in the total encoded size, symbol labels included. The guarantee concerns this algorithm, not the classical greedy procedure of maximum overlap.","sparkFr":"Piste pour l'assemblage de séquences : le facteur deux borne le surcoût d'une surchaîne calculée en temps polynomial.","sparkEn":"A reason to look in sequence assembly: the factor two bounds the overhead of a superstring computed in polynomial time."},{"id":"129","titleEn":"Exponential state costs for two-way automata","titleFr":"Coût exponentiel en états des automates à double sens","claim":"Proves exponential lower bounds both for complementing two-way nondeterministic finite automata and for simulating one-way nondeterministic automata by two-way deterministic ones. The latter resolves the Sakoda–Sipser state-succinctness conjecture over growing finite alphabets; both results rule out polynomial state bounds independent of alphabet size.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"An exponential state lower bound for two-way nondeterministic complementation","href":"preprints/An-exponential-state-lower-bound-for-two-way-nondeterministic-complementation-September-25-2026/paper.pdf"},{"title":"An exponential two-way deterministic state lower bound for one-way liveness","href":"preprints/An-exponential-two-way-deterministic-state-lower-bound-for-one-way-liveness-September-25-2026/main.pdf"}],"plainFr":"Un automate fini accepte ou refuse des mots. Le manuscrit affirme que complémenter un automate non déterministe à double sens, ou simuler de façon déterministe un automate non déterministe à sens unique, peut exiger un nombre exponentiel d'états, sans borne polynomiale indépendante de l'alphabet.","plainEn":"A finite automaton accepts or rejects words with finitely many states. The manuscript asserts that complementing a two-way nondeterministic automaton, or deterministically simulating a one-way nondeterministic one, can require exponentially many states, with no polynomial bound independent of the alphabet.","expertFr":"Le manuscrit affirme des bornes exponentielles pour complémenter les automates finis non déterministes à double sens, et pour simuler ceux à sens unique non déterministes par des automates déterministes à double sens. Pour n au moins 4, un automate à n états a un complément d'au moins 12 fois 2 puissance (n-4)/127, moins 1, états ; cela résout la conjecture de Sakoda et Sipser pour des alphabets finis croissants.","expertEn":"The manuscript asserts exponential bounds for complementing two-way nondeterministic finite automata, and for simulating one-way nondeterministic automata by two-way deterministic ones. For every n at least 4, some n-state automaton has a complement of at least 12 times 2 to the power (n-4)/127, minus 1, states; this resolves the Sakoda–Sipser conjecture for growing finite alphabets.","sparkFr":"L'intérêt est surtout structurel : cela limite en principe la mémoire de machines qui relisent un mot dans les deux sens.","sparkEn":"The interest is mainly structural: it limits, in principle, the memory of machines that reread a word both ways."},{"id":"130","titleEn":"Exact Fourier transforms below n n","titleFr":"Transformée de Fourier discrète exacte à exposant légèrement réduit","claim":"Gives a deterministic length-n discrete Fourier transform algorithm using O(n( n)^1-δ) operations for every n, with explicit δ=10^-13. The model uses exact complex arithmetic, unrestricted coefficients and a supplied root of unity, and counts scalar preparation and logarithmic-word indexing.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"An explicit power saving for the exact discrete Fourier transform","href":"preprints/An-explicit-power-saving-for-the-exact-discrete-Fourier-transform-September-25-2026/main.pdf"},{"title":"Finite tensor savings and exact Fourier circuits","href":"preprints/Finite-tensor-savings-and-exact-Fourier-circuits-September-25-2026/main.pdf"}],"plainFr":"La transformée de Fourier discrète réécrit une suite finie selon des fréquences. Le manuscrit affirme un algorithme déterministe qui la calcule exactement pour toute longueur, avec une économie d'exposant égale à dix puissance moins treize, en arithmétique complexe exacte et avec une racine de l'unité fournie.","plainEn":"The discrete Fourier transform rewrites a finite sequence by frequencies. The manuscript asserts a deterministic algorithm that computes it exactly at every length, with an exponent saving of ten to the minus thirteen, in exact complex arithmetic and with a supplied root of unity.","expertFr":"Le manuscrit affirme, pour toute longueur n, une transformée de Fourier discrète déterministe dont le coût suit la forme écrite : n fois un facteur en n, élevé à la puissance 1 moins un delta égal à dix puissance moins treize. Le modèle compte l'arithmétique complexe exacte, des coefficients libres, une racine fournie, la préparation scalaire et l'indexation sur des mots logarithmiques.","expertEn":"The manuscript asserts, for every length n, a deterministic discrete Fourier transform whose cost follows the written shape: n times a factor in n, raised to the power 1 minus a delta equal to ten to the minus thirteen. The model counts exact complex arithmetic, free coefficients, a supplied root, scalar preparation and logarithmic-word indexing.","sparkFr":"Quelqu'un qui compte des opérations exactes sur des suites de fréquences pourrait y regarder ; aucun usage concret n'est affirmé.","sparkEn":"Someone counting exact operations on frequency sequences might look; no concrete use is asserted."},{"id":"131","titleEn":"Rapid mixing of graph switches for every degree sequence","titleFr":"Mélange rapide des échanges d'arêtes pour toute suite de degrés","claim":"Resolves the simple-undirected Kannan–Tetali–Vempala conjecture: the lazy edge-switch chain mixes in O(n^8) time for every graphical labeled degree sequence. The same degree-constrained graphs can also be sampled exactly uniformly by an almost-surely terminating algorithm with expected polynomial bit running time.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Polynomial mixing of the switch chain for every graphical degree sequence","href":"preprints/Polynomial-Mixing-of-the-Switch-Chain-for-Every-Graphical-Degree-Sequence-September-25-2026/main.pdf"}],"plainFr":"Un graphe simple relie des sommets par des arêtes, ici à degrés imposés. Le manuscrit affirme que la chaîne paresseuse d'échanges d'arêtes se mélange en temps polynomial pour toute suite graphique, et qu'un tirage exactement uniforme finit presque sûrement en temps binaire polynomial en espérance.","plainEn":"A simple graph joins vertices by edges, here with prescribed degrees. The manuscript asserts that the lazy edge-switch chain mixes in polynomial time for every graphical degree sequence, and that an exactly uniform draw finishes almost surely in expected polynomial bit time.","expertFr":"Le manuscrit affirme la conjecture de Kannan, Tetali et Vempala pour les graphes simples non orientés : la chaîne paresseuse qui propose des échanges sur quatre sommets se mélange en variation totale, à distance un quart, en au plus 2n puissance 8. Un échantillonneur exact, uniforme, à bits non biaisés, termine presque sûrement en temps binaire polynomial en espérance, pour tout vecteur de degrés graphique étiqueté.","expertEn":"The manuscript asserts the simple undirected Kannan–Tetali–Vempala conjecture: the lazy chain proposing switches on four vertices mixes in total variation, at distance one quarter, in at most 2n to the 8. An exactly uniform sampler, using unbiased bits, terminates almost surely in expected polynomial bit time, for every graphical labeled degree vector.","sparkFr":"Cela pourrait intéresser qui veut tirer au sort un réseau à degrés fixés ; le texte ne décrit aucun déploiement.","sparkEn":"It might interest someone drawing a network with fixed degrees at random; the text describes no deployment."},{"id":"132","titleEn":"A superquadratic separation of sensitivity and block sensitivity","titleFr":"Écart surquadratique entre sensibilité et sensibilité par blocs","claim":"Constructs total Boolean functions with block sensitivity bs (f)≥ s(f)^α for a fixed α > 2, disproving the quadratic strengthening of the Sensitivity Conjecture. Here s(f) counts influential individual-bit flips, while block sensitivity allows disjoint groups of bits to change together.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1988,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A superquadratic separation between sensitivity and block sensitivity","href":"preprints/A-superquadratic-separation-between-sensitivity-and-block-sensitivity-September-25-2026/paper.pdf"}],"plainFr":"Une fonction booléenne totale répond oui ou non à chaque suite de bits. Le manuscrit affirme qu'il en existe dont la sensibilité par blocs, qui retourne ensemble des groupes disjoints de bits, dépasse toute constante fois le carré de la sensibilité bit à bit.","plainEn":"A total Boolean function answers yes or no on every string of bits. The manuscript asserts that some have block sensitivity, flipping disjoint groups of bits together, growing faster than any constant times the square of bit-by-bit sensitivity.","expertFr":"Le manuscrit affirme des fonctions booléennes totales non constantes, de sensibilité par blocs non bornée, au moins égale à la sensibilité ordinaire élevée à une puissance fixée strictement supérieure à 2. Cela réfute le renforcement quadratique de la conjecture de sensibilité, où la sensibilité compte les bits influents isolés.","expertEn":"The manuscript asserts nonconstant total Boolean functions of unbounded block sensitivity, at least ordinary sensitivity raised to a fixed power strictly greater than 2. This disproves the quadratic strengthening of the Sensitivity Conjecture, where sensitivity counts influential single-bit flips.","sparkFr":"L'intérêt est structurel, dans l'étude de l'influence des bits sur une fonction oui-non.","sparkEn":"The interest is structural, in the study of how bits influence a yes-no function."},{"id":"133","titleEn":"The computational complexity of Weisfeiler–Leman refinement","titleFr":"Complexité du raffinement de Weisfeiler et Leman","claim":"Proves unconditional n^ (k) deterministic time lower bounds for joint and separate k-dimensional Weisfeiler–Leman equivalence, for sufficiently large fixed k in the specified sequential adjacency-matrix models. With dimension as input, joint equivalence is EXPTIME-complete even on subcubic graphs; deciding whether refinement identifies a graph is also EXPTIME-complete.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Parity lifts and bounded-treewidth witnesses for Weisfeiler–Leman equivalence","href":"preprints/Parity-lifts-and-bounded-treewidth-witnesses-for-Weisfeiler-Leman-equivalence-September-25-2026/paper.pdf"},{"title":"The complexity of identifying a graph by Weisfeiler–Leman refinement","href":"preprints/The-complexity-of-identifying-a-graph-by-Weisfeiler-Leman-refinement-September-25-2026/paper.pdf"},{"title":"Unconditional time lower bounds for Weisfeiler–Leman equivalence","href":"preprints/Unconditional-time-lower-bounds-for-Weisfeiler-Leman-equivalence-September-25-2026/paper.pdf"},{"title":"Variable-dimension Weisfeiler–Leman equivalence on general and subcubic graphs","href":"preprints/Variable-dimension-Weisfeiler-Leman-equivalence-on-general-and-subcubic-graphs-September-25-2026/paper.pdf"}],"plainFr":"Ce raffinement compare des graphes en enrichissant peu à peu la couleur des sommets. Le manuscrit affirme que certaines équivalences, en grande dimension fixée, exigent un temps très élevé, et que si la dimension est dans l'entrée le problème est parmi les plus durs en temps exponentiel.","plainEn":"This refinement compares graphs by gradually enriching vertex colors. The manuscript asserts that certain equivalences, in large fixed dimension, require very high time, and that if the dimension is part of the input the problem is among the hardest in exponential time.","expertFr":"Le manuscrit affirme des bornes de temps déterministe de la forme n élevé à une puissance dépendant de k, pour l'équivalence de Weisfeiler–Leman jointe ou séparée, lorsque k fixé est assez grand. Si la dimension est en entrée, l'équivalence jointe est complète pour EXPTIME même sur les graphes sous-cubiques, comme décider si le raffinement identifie un graphe.","expertEn":"The manuscript asserts deterministic time lower bounds of the form n to a power depending on k, for joint or separate Weisfeiler–Leman equivalence, when fixed k is large enough. If the dimension is an input, joint equivalence is EXPTIME-complete even on subcubic graphs, as is deciding whether refinement identifies a graph.","sparkFr":"L'intérêt est structurel : il s'agit du coût de calcul d'un test classique d'indiscernabilité de graphes.","sparkEn":"The interest is structural: it is the computational cost of a classical test of graph indistinguishability."},{"id":"134","titleEn":"Generalized star height at most three","titleFr":"Hauteur d'étoile généralisée bornée de façon uniforme","claim":"Every regular language over a finite alphabet has a generalized regular expression with at most three nested Kleene stars, allowing union, concatenation and complement over the same alphabet. This establishes an absolute bound independent of automaton size, resolving the uniform-boundedness version of the generalized star-height problem.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Finite Monoid Computations and a Uniform Generalized Star-Height Bound","href":"preprints/Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026/Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026.pdf"},{"title":"Generalized Star Height at Most Four","href":"preprints/Generalized-Star-Height-at-Most-Four-September-25-2026/Generalized-Star-Height-at-Most-Four-September-25-2026.pdf"},{"title":"Generalized Star Height at Most Three","href":"preprints/Generalized-Star-Height-at-Most-Three-September-25-2026/article.pdf"}],"plainFr":"Un langage régulier est un ensemble de mots reconnu par un automate fini, et une étoile marque la répétition libre. Le manuscrit affirme que tout langage régulier sur un alphabet fini admet une expression généralisée, complément compris, dont le nombre d'étoiles emboîtées est borné par une constante absolue.","plainEn":"A regular language is a set of words recognized by a finite automaton, and a star marks free repetition. The manuscript asserts that every regular language over a finite alphabet has a generalized expression, complement included, whose number of nested stars is bounded by an absolute constant.","expertFr":"Le manuscrit affirme une borne uniforme, indépendante de la taille de l'automate : l'énoncé dit au plus trois étoiles de Kleene emboîtées, avec union, concaténation et complément, tandis que le résumé dit une hauteur d'étoile au plus treize. Le résumé représente les calculs d'un monoïde fini par des mises à jour affines, retrouvées par douze découpages successifs.","expertEn":"The manuscript asserts a uniform bound independent of automaton size: the claim says at most three nested Kleene stars, with union, concatenation and complement, while the abstract says star height at most thirteen. The abstract represents finite monoid computations as affine updates, recovered through twelve successive splits.","sparkFr":"L'intérêt est structurel, dans la théorie des expressions qui décrivent les langages réguliers.","sparkEn":"The interest is structural, inside the theory of expressions that describe regular languages."},{"id":"135","titleEn":"Homogeneous depth-five lower bounds for iterated matrix multiplication","titleFr":"Bornes homogènes de profondeur cinq pour le produit itéré de matrices","claim":"Over every characteristic-zero field, the (1,1) entry of a product of n independent n× n variable matrices requires n^ ( n) gates in homogeneous depth-five sum–product circuits. This sharp bound allows shared gates and bottom linear forms involving all variables.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1969,"yearKnown":true,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Homogeneous depth-five lower bounds for iterated matrix multiplication","href":"preprints/Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026/Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026.pdf"}],"plainFr":"Il s'agit du coefficient en haut à gauche du produit de matrices carrées de variables. Le manuscrit affirme que, sur un corps de caractéristique nulle, un circuit homogène de profondeur cinq en exige un nombre de portes d'ordre net, même avec partage des portes.","plainEn":"The object is the top-left entry of a product of square matrices of variables. The manuscript asserts that, over a field of characteristic zero, a homogeneous depth-five circuit requires a sharp number of gates for it, even with gate sharing.","expertFr":"Le manuscrit affirme que, sur tout corps de caractéristique nulle, l'entrée (1,1) du produit de n matrices n par n de variables exige, en profondeur cinq homogène, le nombre net de portes écrit dans le texte, formes linéaires arbitraires et partage compris. Sur tout corps, pour n au moins 2, une construction par blocs atteint le même ordre de grandeur.","expertEn":"The manuscript asserts that, over every characteristic-zero field, the (1,1) entry of a product of n independent n by n variable matrices needs, in homogeneous depth five, the sharp gate count written in the text, with arbitrary linear forms and sharing. Over every field, for n at least 2, a block construction reaches the same order of magnitude.","sparkFr":"L'intérêt est structurel : il borne le coût algébrique d'un produit de matrices de variables.","sparkEn":"The interest is structural: it bounds the algebraic cost of a product of variable matrices."},{"id":"136","titleEn":"A quasilinear PCP theorem for PPAD","titleFr":"Un théorème PCP quasi linéaire pour la classe PPAD","claim":"Resolves the quasilinear PCP-for-PPAD conjecture. An End-of-Line instance of length N reduces to numerical circuit constraints of total length N( N)^O(1) such that any polynomially encoded rational assignment satisfying all but a fixed fraction to fixed accuracy yields an endpoint solution. Such assignments always exist, giving robust local verification with only quasilinear size overhead.","nature":"informatique","domain":"information","complexity":"frontiere","problemYear":1991,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"The PCP-for-PPAD conjecture: a quasilinear reduction","href":"preprints/The-PCP-for-PPAD-conjecture-a-quasilinear-reduction-September-25-2026/paper.pdf"}],"plainFr":"PPAD rassemble des problèmes de recherche, comme trouver l'extrémité d'un chemin. Le manuscrit affirme qu'une telle instance se réduit à un circuit de taille seulement quasi linéaire, où une affectation presque satisfaisante révèle déjà une solution.","plainEn":"PPAD gathers search problems, such as finding the end of a path. The manuscript asserts that such an instance reduces to a circuit of only quasilinear size, where a nearly satisfying assignment already reveals a solution.","expertFr":"Le manuscrit affirme la conjecture PCP quasi linéaire pour PPAD de Babichenko, Papadimitriou et Rubinstein. Une instance Fin-de-ligne de longueur N se réduit en temps polynomial à un circuit de longueur quasi linéaire, et toute affectation rationnelle courte qui rate seulement une fraction fixée des portes, à précision fixée, donne une extrémité ; de telles affectations existent.","expertEn":"The manuscript asserts the quasilinear PCP-for-PPAD conjecture of Babichenko, Papadimitriou and Rubinstein. An End-of-Line instance of length N reduces in polynomial time to a quasilinear circuit, and any short rational assignment that misses only a fixed fraction of the gates, to a fixed accuracy, yields an endpoint; such assignments exist.","sparkFr":"Cela pourrait intéresser qui étudie la vérification locale de problèmes de recherche ; aucun usage industriel n'est affirmé.","sparkEn":"It might interest someone studying local checks of search problems; no industrial use is asserted."},{"id":"137","titleEn":"One-tape time simulation in two-fifths-power space","titleFr":"Simulation d'une machine à un ruban en espace de puissance deux cinquièmes","claim":"Determines the halting and finite-control outcome of a fixed deterministic one-writable-tape machine up to time T using O(T^2/5 ^C(T+2)) space, improving the square-root exponent. Heads move at most one cell per step; finitely many read-only input heads are allowed. Initial contents are independent of T, and contents and input symbols have polylogarithmic-space access. Simulation time is unrestricted.","nature":"algebre","domain":"formes","complexity":"frontiere","problemYear":1992,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Simulating One-Tape Time in Two-Fifths-Power Space","href":"preprints/Simulating-One-Tape-Time-in-Two-Fifths-Power-Space-September-25-2026/article.pdf"}],"plainFr":"Une machine à un ruban inscriptible lit et écrit une bande, une case à la fois. Le manuscrit affirme que l'on peut connaître son arrêt et son état jusqu'au temps donné, en un espace de l'ordre de ce temps à la puissance deux cinquièmes, à un facteur polylogarithmique près.","plainEn":"A machine with one writable tape reads and writes a strip, one cell at a time. The manuscript asserts that one can learn its halting and state up to a given time, in space on the order of that time to the power two fifths, up to a polylogarithmic factor.","expertFr":"Le manuscrit affirme qu'une machine déterministe fixée, à un ruban inscriptible, se simule jusqu'au temps T au moins 2 en un espace de l'ordre de T puissance 2/5 fois un polylogarithme, sans borne sur le temps de simulation. Des têtes de lecture en nombre fixé sont permises, et cela améliore l'exposant racine carrée, répondant à la question de Williams pour ce modèle.","expertEn":"The manuscript asserts that a fixed deterministic one-writable-tape machine can be simulated up to time T at least 2 in space on the order of T to the power 2/5 times a polylogarithm, with no bound on simulation time. A fixed number of read-only heads is allowed, and this improves the square-root exponent, answering Williams's question for this model.","sparkFr":"L'intérêt est structurel : il compare le temps d'une machine à ruban et l'espace d'une simulation.","sparkEn":"The interest is structural: it compares a tape machine's time with the space of a simulation."},{"id":"138","titleEn":"Subset Sum in O(2^0.49n) time","titleFr":"Somme de sous-ensembles en temps deux puissance 0,49 n","claim":"Gives a uniform randomized classical algorithm for worst-case Subset Sum in ordinary O(2^0.49n) word-RAM time on polynomial-bit inputs, where n counts the integers. The time bound holds on every execution and success probability is at least 2/3 on every input. Inputs may repeat positive integers; words have O(n+b) bits for maximum input bit length b.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1972,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":false,"pdfs":[{"title":"Subset Sum in Time O(2^0.49n)","href":"preprints/Subset-Sum-in-Time-2-power-0-49n-October-4-2026/subset-sum.pdf"},{"title":"A Low-Space Algorithm for Worst-Case Subset Sum","href":"preprints/A-Low-Space-Algorithm-for-Worst-Case-Subset-Sum-September-26-2026/paper.pdf"}],"plainFr":"Le problème de la somme de sous-ensembles demande si certains entiers d'une liste atteignent une cible. Le manuscrit affirme un algorithme classique aléatoire qui le résout, au pire, en un temps de l'ordre de deux élevé à 0,49 fois le nombre d'entiers, avec succès au moins deux fois sur trois.","plainEn":"Subset Sum asks whether some integers from a list reach a target. The manuscript asserts a randomized classical algorithm that solves the worst case in time on the order of two to the power 0.49 times the number of integers, with success at least two times out of three.","expertFr":"Le manuscrit affirme un algorithme classique aléatoire uniforme pour la somme de sous-ensembles, de temps de l'ordre de 2 puissance 0,49 n sur toute exécution, pour des entrées à bits polynomiaux, répétitions permises. La probabilité de succès est au moins 2/3 sur toute entrée, et les mots ont une taille de l'ordre du nombre d'entiers plus la plus grande longueur binaire.","expertEn":"The manuscript asserts a uniform randomized classical algorithm for Subset Sum, with time on the order of 2 to the power 0.49 n on every execution, for polynomial-bit inputs, repeats allowed. The success probability is at least 2/3 on every input, and words have size on the order of the number of integers plus the largest bit length.","sparkFr":"Quelqu'un qui étudie la recherche sur des sommes d'entiers pourrait y regarder ; aucun système concret n'est décrit.","sparkEn":"Someone studying search over integer sums might look; no concrete system is described."},{"id":"139","titleEn":"Subpolynomial query complexity for log-concave sampling","titleFr":"Échantillonnage log-concave en un nombre sous-polynomial de requêtes","claim":"For C2 potentials with a supplied minimizer and I ^2V 2I, proves that sampling within total variation 1/10 requires only C_ε d^ε exact value-and-gradient queries for every fixed ε > 0. The bound holds on every run, with unrestricted computation between queries. A logarithmic lower bound also holds, so the optimal power-law exponent in this oracle model is zero.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1974,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"Subpolynomial query complexity for well-conditioned log-concave sampling","href":"preprints/Subpolynomial-query-complexity-for-well-conditioned-log-concave-sampling-September-26-2026/article.pdf"}],"plainFr":"Il s'agit de tirer au sort selon une loi lisse en cloche déformée, en grande dimension. Le manuscrit affirme qu'une précision fixe s'atteint par des lectures de la fonction et de sa pente, en un nombre qui croît plus lentement que toute puissance positive de la dimension.","plainEn":"The task is to sample a smooth, deformed bell-shaped law in high dimension. The manuscript asserts that a fixed accuracy is reached by readings of the function and its slope, fewer than every positive power of the dimension.","expertFr":"Le manuscrit affirme que, pour tout epsilon positif fixé, atteindre la variation totale 1/10 pour un potentiel deux fois dérivable, à minimiseur connu et à hessienne entre l'identité et son double, coûte au plus une constante fois d puissance epsilon requêtes exactes, à chaque essai. Le calcul entre les requêtes est libre, et une borne logarithmique montre que l'exposant optimal en la dimension est nul.","expertEn":"The manuscript asserts that, for every fixed positive epsilon, reaching total variation 1/10 for a twice differentiable potential, with known minimizer and Hessian between the identity and its double, costs at most a constant times d to that epsilon in exact queries, on every run. Computation between queries is free, and a logarithmic bound shows that the optimal dimension exponent is zero.","sparkFr":"Cela pourrait intéresser qui borne le nombre de mesures pour échantillonner une loi en cloche ; rien n'est déployé.","sparkEn":"It might interest someone bounding measurements for a bell-shaped sampler; nothing is deployed."},{"id":"140","titleEn":"Memory–sample lower bounds for noiseless Gaussian regression","titleFr":"Mémoire et échantillons pour la régression gaussienne sans bruit","claim":"For fixed A > 0, a one-pass learner with Ad^2 persistent bits needs _A(d (1/ε)) noiseless Gaussian samples to recover a unit vector to angular error 0 ε≤1/10 with probability 2/3, uniformly in accuracy for large d. Computation and randomized updates are unrestricted, but output uses only the terminal state, stopping index and fresh randomness.","nature":"probabilites","domain":"hasard","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Memory and precision in noiseless Gaussian regression","href":"preprints/Memory-and-precision-in-noiseless-Gaussian-regression-September-27-2026/paper.pdf"},{"title":"Posterior replicas and conditional information in Gaussian regression","href":"preprints/Posterior-replicas-and-conditional-information-in-Gaussian-regression-September-27-2026/paper.pdf"},{"title":"Localization costs and information growth for exact Gaussian observations","href":"preprints/Localization-costs-and-information-growth-for-exact-Gaussian-observations-September-27-2026/paper.pdf"},{"title":"Projection moments, positive cap domination, and Riesz estimates on the sphere","href":"preprints/Projection-moments-positive-cap-domination-and-Riesz-estimates-on-the-sphere-September-27-2026/paper.pdf"},{"title":"Replacing Gaussian observations in memory-constrained inference","href":"preprints/Replacing-Gaussian-observations-in-memory-constrained-inference-September-27-2026/paper.pdf"},{"title":"Subsphere methods for memory-sample lower bounds in noiseless Gaussian regression","href":"preprints/Subsphere-methods-for-memory-sample-lower-bounds-in-noiseless-Gaussian-regression-September-27-2026/paper.pdf"}],"plainFr":"Il s'agit d'estimer une direction inconnue par des mesures linéaires gaussiennes exactes, avec peu de mémoire. Le manuscrit affirme qu'une mémoire de l'ordre du carré de la dimension force encore le nombre de mesures à croître avec la dimension et la précision angulaire.","plainEn":"The task is to estimate an unknown direction from exact Gaussian linear measurements, with little memory. The manuscript asserts that memory on the order of the square of the dimension still forces the number of measurements to grow with the dimension and the angular accuracy.","expertFr":"Le manuscrit affirme que, pour tout A positif fixé, au plus A fois d au carré bits entre des mesures gaussiennes exactes imposent le minorant d'échantillons écrit en A, d et l'inverse de la précision. Il s'agit d'un vecteur unitaire uniforme, à erreur angulaire epsilon avec 0<epsilon≤1/10, et probabilité au moins 2/3 ; la sortie ne lit que l'état final, l'indice d'arrêt et du hasard frais.","expertEn":"The manuscript asserts that, for every fixed positive A, at most A times d squared bits between exact Gaussian measurements force the written sample lower bound in A, d and the reciprocal of the accuracy. The target is a uniform unit vector, at angular error epsilon with 0<epsilon≤1/10, and probability at least 2/3; the output reads only the final state, the stopping index and fresh randomness.","sparkFr":"Quelqu'un qui limite la mémoire d'un estimateur pourrait y regarder ; le texte ne propose pas de méthode utilisable.","sparkEn":"Someone limiting an estimator's memory might look; the text offers no usable method."},{"id":"141","titleEn":"Existential–universal real sentences in the counting hierarchy","titleFr":"Phrases existentielles réelles dans la hiérarchie de comptage","claim":"Proves that the existential theory of the reals lies in the counting hierarchy. More generally, truth of existential–universal real sentences can be decided at one fixed level of that hierarchy, even when their integer polynomials are specified by arithmetic circuits.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Existential–universal real sentences in the counting hierarchy","href":"preprints/Existential-universal-real-sentences-in-the-counting-hierarchy-October-4-2026/etr-counting-hierarchy.pdf"}],"plainFr":"Une phrase existentielle sur les réels demande s'il existe des nombres réels satisfaisant des équations polynomiales. Le manuscrit affirme que décider de telles phrases, et plus généralement des phrases existentielles puis universelles, se place à un niveau fixé de la hiérarchie de comptage.","plainEn":"An existential sentence over the reals asks whether some real numbers satisfy polynomial equations. The manuscript asserts that deciding such sentences, and more generally existential-then-universal ones, sits at one fixed level of the counting hierarchy.","expertFr":"Le manuscrit affirme que la théorie existentielle des réels appartient à la hiérarchie de comptage. Plus généralement, la vérité des phrases existentielles-universelles sur les réels se décide à un niveau fixé de cette hiérarchie, même lorsque les polynômes à coefficients entiers sont donnés par des circuits arithmétiques.","expertEn":"The manuscript asserts that the existential theory of the reals lies in the counting hierarchy. More generally, the truth of existential-universal sentences over the reals can be decided at one fixed level of that hierarchy, even when the integer polynomials are given by arithmetic circuits.","sparkFr":"L'intérêt est structurel, pour qui classe la difficulté logique des énoncés sur les nombres réels.","sparkEn":"The interest is structural, for anyone classifying the logical difficulty of statements about real numbers."},{"id":"142","titleEn":"Deterministic polynomial factorization over prime fields","titleFr":"Factorisation déterministe des polynômes sur les corps premiers","claim":"Gives a uniform deterministic algorithm that completely factors every nonzero dense degree-n polynomial over a prime field 𝔽p, including multiplicities, in bit complexity polynomial in (n+1) p. The prime is supplied in binary. No randomness, integer-factorization or primitive-root oracle, or GRH assumption is required.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Deterministic Polynomial Factorization over Prime Fields","href":"preprints/Deterministic-Polynomial-Factorization-over-Prime-Fields-October-4-2026/Deterministic-Polynomial-Factorization-over-Prime-Fields.pdf"}],"plainFr":"Factoriser un polynôme, c'est l'écrire comme produit de facteurs plus simples, ici modulo un nombre premier. Le manuscrit affirme un procédé déterministe qui le fait complètement, multiplicités comprises, sans tirage au sort et sans hypothèse de Riemann.","plainEn":"Factoring a polynomial means writing it as a product of simpler factors, here modulo a prime. The manuscript asserts a deterministic procedure that does this completely, multiplicities included, with no random draws and no Riemann hypothesis.","expertFr":"Le manuscrit affirme un algorithme déterministe uniforme qui factorise tout polynôme non nul dense de degré n sur le corps à p éléments, multiplicités comprises, en un coût binaire polynomial en (n+1) p. Ni aléatoire, ni oracle de factorisation entière ou de racine primitive, ni hypothèse de Riemann généralisée ne sont requis ; le résumé invoque une région sans zéro de Hecke.","expertEn":"The manuscript asserts a uniform deterministic algorithm factoring every nonzero dense degree-n polynomial over the field with p elements, multiplicities included, at bit cost polynomial in (n+1) p. No randomness, integer-factorization or primitive-root oracle, or generalized Riemann hypothesis is required; the abstract invokes a Hecke zero-free region.","sparkFr":"Quelqu'un qui factorise des polynômes modulo un premier pourrait y regarder ; aucun logiciel n'est proposé.","sparkEn":"Someone factoring polynomials modulo a prime might look; no software is proposed."},{"id":"143","titleEn":"Hilbert's sixteenth problem: uniform bounds for limit cycles","titleFr":"Seizième problème de Hilbert : bornes uniformes sur les cycles limites","claim":"Resolves the uniform boundedness assertion in Hilbert's sixteenth problem: the number of isolated periodic orbits of a real planar polynomial vector field is bounded by a finite constant depending only on its degree. For classical quintic Liénard systems, the exact maximum is two limit cycles.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":1900,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Uniform bounds for planar polynomial limit cycles","href":"preprints/uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026/uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026.pdf"},{"title":"Two limit cycles for quintic Liénard systems","href":"preprints/two-limit-cycles-for-quintic-lienard-systems-September-24-2026/two-limit-cycles-for-quintic-lienard-systems-September-24-2026.pdf"}],"plainFr":"Un cycle limite est une orbite fermée isolée d'un champ de vitesses dans le plan. Le manuscrit affirme que, pour un champ polynomial, leur nombre ne dépend que du degré par une borne finie, et que certains systèmes classiques de degré cinq en ont au plus deux.","plainEn":"A limit cycle is an isolated closed orbit of a velocity field in the plane. The manuscript asserts that, for a polynomial field, their number depends on the degree only through a finite bound, and that certain classical degree-five systems have at most two.","expertFr":"Le manuscrit affirme que le nombre d'orbites périodiques isolées d'un champ polynomial réel du plan est borné par une constante finie ne dépendant que du degré : c'est la bornitude uniforme du seizième problème de Hilbert. Pour les systèmes de Liénard quintiques classiques, le maximum exact est deux ; le résumé sépare des développements asymptotiques puis compte en dimension finie.","expertEn":"The manuscript asserts that the number of isolated periodic orbits of a real planar polynomial vector field is bounded by a finite constant depending only on the degree, the uniform boundedness assertion in Hilbert's sixteenth problem. For classical quintic Liénard systems the exact maximum is two; the abstract separates asymptotic expansions and then counts in finite dimension.","sparkFr":"Cela pourrait intéresser qui compte les oscillations isolées d'un système polynomial plan ; aucune application n'est affirmée.","sparkEn":"It might interest someone counting isolated oscillations of a planar polynomial system; no application is asserted."},{"id":"144","titleEn":"Banach’s simple Lebesgue-spectrum problem","titleFr":"Le problème du spectre de Lebesgue simple de Banach","claim":"Resolves the probability-preserving form of Banach's simple Lebesgue-spectrum problem within smooth dynamics. A smooth volume-preserving diffeomorphism of the standard-volume three-torus has simple Lebesgue spectrum on its entire complex mean-zero L2 space: the bilateral iterates of one real observable form an orthonormal basis of that space.","nature":"algebre","domain":"hasard","complexity":"frontiere","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A smooth three-torus diffeomorphism with simple Lebesgue spectrum","href":"preprints/A-smooth-three-torus-diffeomorphism-with-simple-Lebesgue-spectrum-September-23-2026/paper.pdf"}],"plainFr":"Il s'agit d'une transformation lisse qui conserve le volume sur un tore à trois dimensions. Le manuscrit affirme qu'une seule grandeur réelle, décalée dans les deux sens du temps, forme une base orthonormée de toutes les fonctions de carré intégrable et de moyenne nulle.","plainEn":"The object is a smooth transformation that preserves volume on a three-dimensional torus. The manuscript asserts that one real quantity, shifted both ways in time, forms an orthonormal basis of all square-integrable functions of mean zero.","expertFr":"Le manuscrit affirme une solution, en dynamique lisse préservant une probabilité, du problème du spectre de Lebesgue simple de Banach. Un difféomorphisme infiniment lisse du tore de dimension trois, qui conserve le volume standard, a un opérateur de Koopman à spectre de Lebesgue simple sur tout l'espace L2 de moyenne nulle : les itérés bilatères d'une observable réelle en forment une base orthonormée.","expertEn":"The manuscript asserts a solution, in smooth probability-preserving dynamics, of Banach's simple Lebesgue-spectrum problem. An infinitely smooth diffeomorphism of the three-dimensional torus, preserving standard volume, has a Koopman operator with simple Lebesgue spectrum on the whole mean-zero L2 space: the bilateral iterates of one real observable form an orthonormal basis.","sparkFr":"L'intérêt est structurel, dans l'étude du mélange des transformations qui conservent un volume.","sparkEn":"The interest is structural, in the study of mixing for transformations that preserve a volume."},{"id":"145","titleEn":"Rokhlin’s multiple-mixing problem","titleFr":"Le problème de mélange multiple de Rokhlin","claim":"Proves that every invertible mixing probability-preserving transformation is mixing of all finite orders, resolving Rokhlin's multiple-mixing problem for a single transformation. Correlations among any finite collection of measurable sets converge to the product of their measures whenever all pairwise time separations diverge.","nature":"dynamique","domain":"hasard","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Rokhlin's multiple-mixing problem for one transformation","href":"preprints/Rokhlins-multiple-mixing-problem-for-one-transformation-September-23-2026/paper.pdf"}],"plainFr":"Une transformation mélangeante rend, à la longue, indépendants des événements éloignés dans le temps. Le manuscrit affirme que si elle est inversible et mélange déjà les paires, alors elle mélange aussi toute collection finie d'événements dès que tous les écarts de temps deviennent grands.","plainEn":"A mixing transformation eventually makes events far apart in time independent. The manuscript asserts that if it is invertible and already mixes pairs, then it also mixes every finite collection of events once all the time gaps become large.","expertFr":"Le manuscrit affirme que toute transformation inversible, préservant une probabilité et mélangeante, est mélangeante de tout ordre fini. Les corrélations d'une collection finie d'ensembles mesurables tendent vers le produit des mesures dès que toutes les séparations temporelles deux à deux divergent, ce qui résout le problème de Rokhlin pour une seule transformation.","expertEn":"The manuscript asserts that every invertible mixing probability-preserving transformation is mixing of every finite order. Correlations of any finite collection of measurable sets tend to the product of the measures once all pairwise time separations diverge, resolving Rokhlin's problem for a single transformation.","sparkFr":"L'intérêt est structurel : le mélange des paires entraîne ici celui de tout nombre fini d'événements.","sparkEn":"The interest is structural: pairwise mixing yields here the mixing of any finite number of events."},{"id":"146","titleEn":"Positive metric entropy for the standard map","titleFr":"Entropie métrique positive pour l'application standard","claim":"Proves that the standard sine map on the two-dimensional torus has positive metric entropy with respect to area for every sufficiently large positive parameter. This establishes Sinai's positive-parameter-measure conjecture for the original family, with the stronger conclusion of a full parameter tail.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Positive Metric Entropy for the Standard Map at Large Parameters","href":"preprints/Positive-Metric-Entropy-for-the-Standard-Map-at-Large-Parameters-September-23-2026/paper.pdf"}],"plainFr":"L'application standard est une transformation du tore à deux dimensions, selon un paramètre et un sinus. Le manuscrit affirme que, pour l'aire, son entropie métrique est positive dès que ce paramètre positif est assez grand.","plainEn":"The standard map is a transformation of the two-dimensional torus, depending on a parameter and a sine. The manuscript asserts that, for area, its metric entropy is positive as soon as this positive parameter is large enough.","expertFr":"Le manuscrit affirme que l'application standard en sinus du tore bidimensionnel a une entropie métrique positive pour l'aire normalisée, pour tout paramètre positif assez grand. Cela donne une queue entière de paramètres et répond ainsi, sous une forme plus forte, à la conjecture de Sinai d'une mesure positive de paramètres.","expertEn":"The manuscript asserts that the standard sine map of the two-dimensional torus has positive metric entropy for normalized area, for every sufficiently large positive parameter. This gives a full tail of parameters and thus answers, in a stronger form, Sinai's conjecture of a positive measure of parameters.","sparkFr":"Cela pourrait intéresser qui relie un paramètre sur le tore à l'imprévisibilité du mouvement ; aucun système physique n'est traité.","sparkEn":"It might interest someone linking a parameter on the torus to unpredictability of motion; no physical system is treated."},{"id":"147","titleEn":"The near-boundary Birkhoff conjecture","titleFr":"La conjecture de Birkhoff près du bord","claim":"Resolves the near-boundary Birkhoff conjecture for smooth strictly convex planar billiards of positive curvature. Such a billiard is an ellipse whenever a full grazing annulus is continuously foliated by individually invariant essential curves. A continuous physical collar of smooth closed convex caustics also suffices.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Continuous Phase Foliations Create Analytic Caustic Collars","href":"preprints/Continuous-Phase-Foliations-Create-Analytic-Caustic-Collars-September-24-2026/paper.pdf"},{"title":"Rigidity of Smooth Billiards with a Continuous Caustic Collar","href":"preprints/Rigidity-of-Smooth-Billiards-with-a-Continuous-Caustic-Collar-September-24-2026/paper.pdf"}],"plainFr":"Un billard strictement convexe est une table lisse où une bille se réfléchit sur le bord. Le manuscrit affirme que si une couronne entière près du bord est feuilletée par des courbes invariantes, ou si un collier de caustiques fermées existe, alors la table est une ellipse.","plainEn":"A strictly convex billiard is a smooth table on which a ball reflects off the boundary. The manuscript asserts that if a full annulus near the boundary is foliated by invariant curves, or if a collar of closed caustics exists, then the table is an ellipse.","expertFr":"Le manuscrit affirme que le billard plan lisse, strictement convexe et de courbure positive, est une ellipse si une couronne rasante est feuilletée par des courbes essentielles invariantes, ou si un collier de caustiques convexes lisses existe. Le résumé ajoute qu'un tel feuilletage force un bord analytique, puis une rigidité du collier physique.","expertEn":"The manuscript asserts that the smooth strictly convex planar billiard of positive curvature is an ellipse if a grazing annulus is foliated by invariant essential curves, or if a collar of smooth convex caustics exists. The abstract adds that such a foliation forces an analytic boundary, then a physical-collar rigidity.","sparkFr":"Quelqu'un qui se demande quand une table de billard convexe est une ellipse pourrait y regarder ; rien n'est construit.","sparkEn":"Someone asking when a convex billiard table is an ellipse might look; nothing is built."},{"id":"148","titleEn":"The entropy-rate dimension formula for self-similar measures","titleFr":"Dimension par taux d'entropie des mesures autosimilaires","claim":"For every self-similar measure on the line generated by finitely many contracting similarities, proves _ Hμ= \\1,h_RW/ \\, where h_RW is the entropy rate of random composed maps and χ the average logarithmic contraction. This resolves the entropy-rate dimension conjecture without a separation assumption, allowing exact overlaps and unequal contraction ratios.","nature":"dynamique","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The entropy-rate dimension formula for self-similar measures on the line","href":"preprints/The-entropy-rate-dimension-formula-for-self-similar-measures-on-the-line-September-24-2026/main.pdf"}],"plainFr":"Une mesure autosimilaire est une masse sur la droite, recopiée à petite échelle par un nombre fini de similitudes. Le manuscrit affirme que sa dimension est le minimum entre un et le rapport d'un taux d'entropie de marche aléatoire à une contraction moyenne, même en cas de recouvrements exacts.","plainEn":"A self-similar measure is a mass on the line, copied at small scale by finitely many similarities. The manuscript asserts that its dimension is the minimum of one and the ratio of a random-walk entropy rate to an average contraction, even when exact overlaps occur.","expertFr":"Le manuscrit affirme que la dimension de Hausdorff de toute mesure autosimilaire réelle finie égale le minimum de un et du taux d'entropie de la marche aléatoire des compositions, divisé par l'exposant de Lyapunov. Les recouvrements exacts sont permis, et les rapports de contraction peuvent être inégaux ou négatifs, sans hypothèse de séparation.","expertEn":"The manuscript asserts that the Hausdorff dimension of every finite real self-similar measure equals the minimum of one and the entropy rate of the random walk of compositions, divided by the Lyapunov exponent. Exact overlaps are allowed, and the contraction ratios may be unequal or negative, with no separation assumption.","sparkFr":"Cela pourrait intéresser qui estime la dimension d'une masse faite de recopies contractantes ; aucun calcul appliqué n'est donné.","sparkEn":"It might interest someone estimating the dimension of a mass made of contracting copies; no applied computation is given."},{"id":"149","titleEn":"Classwise permanence for weakly reversible mass-action systems","titleFr":"Permanence des systèmes d'action de masse faiblement réversibles","claim":"Proves the permanence conjecture for every finite weakly reversible mass-action system with fixed positive rate constants. Every positive stoichiometric compatibility class, even an unbounded one, has a common compact convex forward-invariant absorbing set. All positive trajectories in that class therefore eventually share positive lower and finite upper concentration bounds.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Uniform Permanence in Weakly Reversible Mass-Action Systems","href":"preprints/Uniform-Permanence-in-Weakly-Reversible-Mass-Action-Systems-October-5-2026/permanence.pdf"},{"title":"Boundedness and persistence of weakly reversible mass-action systems","href":"preprints/Boundedness-and-persistence-of-weakly-reversible-mass-action-systems-September-25-2026/paper.pdf"}],"plainFr":"Un système d'action de masse fait évoluer des concentrations selon des réactions à taux fixés. Le manuscrit affirme que, s'il est faiblement réversible, chaque classe positive possède un ensemble compact qui attire toutes les trajectoires positives, lesquelles restent ensuite entre des bornes communes.","plainEn":"A mass-action system lets concentrations evolve under reactions with fixed rates. The manuscript asserts that if it is weakly reversible, every positive class has a compact set that attracts all positive trajectories, which thereafter stay between common bounds.","expertFr":"Le manuscrit affirme la conjecture de permanence pour tout système d'action de masse fini, faiblement réversible, à taux positifs fixés. Chaque classe de compatibilité stœchiométrique positive, même non bornée, admet un compact convexe invariant vers le futur qui absorbe toute trajectoire positive en temps fini, d'où ensuite des bornes de concentration strictement positives et finies, communes à la classe.","expertEn":"The manuscript asserts the permanence conjecture for every finite weakly reversible mass-action system with fixed positive rates. Every positive stoichiometric compatibility class, even an unbounded one, has a compact convex forward-invariant set that absorbs every positive trajectory in finite time, giving thereafter common strictly positive and finite concentration bounds.","sparkFr":"Quelqu'un qui suit des concentrations dans un schéma de réactions pourrait y regarder ; aucun réseau chimique réel n'est étudié.","sparkEn":"Someone tracking concentrations in a reaction scheme might look; no real chemical network is studied."},{"id":"150","titleEn":"Weak mixing of triangular billiards with an irrational angle","titleFr":"Mélange faible des billards triangulaires à angle irrationnel","claim":"Proves that the billiard flow in every nondegenerate Euclidean triangle with at least one angle irrational relative to π is weakly mixing for normalized area times uniform direction. This strengthens ergodicity on the entire irrational-angle class, with no genericity or Diophantine restrictions.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":1761,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Weak mixing of triangular billiards with an irrational angle","href":"preprints/Weak-mixing-of-triangular-billiards-with-an-irrational-angle-October-5-2026/weak-mixing-triangular-billiards.pdf"},{"title":"Ergodicity of triangular billiards with an irrational angle","href":"preprints/Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026/Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026.pdf"}],"plainFr":"Un billard triangulaire fait rebondir une bille à vitesse constante dans un triangle. Le manuscrit affirme que, dès qu'un angle n'est pas un multiple rationnel d'un demi-tour, le mouvement est faiblement mélangeant pour l'aire et la direction.","plainEn":"A triangular billiard bounces a ball at constant speed inside a triangle. The manuscript asserts that as soon as one angle is not a rational multiple of a half-turn, the motion is weakly mixing for area and direction.","expertFr":"Le manuscrit affirme que le flot de billard à vitesse unité, dans tout triangle euclidien non dégénéré ayant au moins un angle irrationnel relativement à π, est faiblement mélangeant pour la mesure de Liouville normalisée. Cela renforce l'ergodicité sur toute cette classe, sans généricité ni condition diophantienne ; de façon équivalente, le produit du flot par lui-même est ergodique.","expertEn":"The manuscript asserts that the unit-speed billiard flow in every nondegenerate Euclidean triangle with at least one angle irrational relative to pi is weakly mixing for normalized Liouville measure. This strengthens ergodicity on that whole class, with no genericity or Diophantine condition; equivalently, the product of the flow with itself is ergodic.","sparkFr":"Cela pourrait intéresser qui se demande si un billard triangulaire mélange les trajectoires ; aucune table réelle n'est mesurée.","sparkEn":"It might interest someone asking whether a triangular billiard mixes trajectories; no real table is measured."},{"id":"151","titleEn":"A C1 counterexample to the entropy conjecture","titleFr":"Un contre-exemple de classe C1 à la conjecture d'entropie","claim":"Constructs a noninvertible C1 self-map of a compact smooth manifold with zero topological entropy but eigenvalue 2 on second homology. This disproves the homological entropy lower bound for general C1 self-maps: homological growth need not force positive orbit complexity.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A C^1 Counterexample to the Entropy Conjecture","href":"preprints/A-C1-Counterexample-to-the-Entropy-Conjecture-September-25-2026/article.pdf"}],"plainFr":"L'entropie topologique mesure la complexité des orbites d'une transformation. Le manuscrit affirme qu'une application une fois continûment dérivable, non inversible, peut avoir une entropie nulle tout en doublant une direction de l'homologie de degré deux.","plainEn":"Topological entropy measures how complicated the orbits of a transformation are. The manuscript asserts that a once continuously differentiable, noninvertible map can have zero entropy while doubling a direction in degree-two homology.","expertFr":"Le manuscrit affirme un contre-exemple C1 à la conjecture d'entropie de Shub : une application non inversible d'une variété lisse compacte sans bord, d'entropie topologique nulle, dont l'action sur la seconde homologie réelle admet 2 pour valeur propre. L'entropie est donc strictement plus petite que le logarithme du rayon spectral homologique.","expertEn":"The manuscript asserts a C1 counterexample to Shub's entropy conjecture: a noninvertible self-map of a compact smooth manifold without boundary, of zero topological entropy, whose action on second real homology has eigenvalue 2. The entropy is therefore strictly smaller than the logarithm of the homological spectral radius.","sparkFr":"L'intérêt est structurel : une croissance homologique n'impose pas ici une complexité positive des orbites.","sparkEn":"The interest is structural: homological growth does not here force positive orbit complexity."},{"id":"152","titleEn":"Zero entropy does not guarantee a smooth positive-volume model","titleFr":"L'entropie nulle ne garantit pas un modèle lisse de volume positif","claim":"Constructs a zero-entropy ergodic invertible transformation of a standard nonatomic probability space that is not measurably conjugate to any C∞ diffeomorphism preserving a strictly positive smooth probability density on a compact finite-dimensional manifold. One example rules out every finite dimension.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":1956,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A zero-entropy system without a smooth positive-volume model","href":"preprints/A-finite-entropy-system-without-a-smooth-positive-volume-model-September-25-2026/paper.pdf"}],"plainFr":"Il s'agit d'une transformation inversible qui conserve une probabilité sans atomes et la parcourt de façon ergodique. Le manuscrit affirme qu'une entropie nulle ne suffit pas à la réaliser comme déformation lisse conservant une densité strictement positive sur une variété compacte.","plainEn":"The object is an invertible transformation that preserves a nonatomic probability and traverses it ergodically. The manuscript asserts that zero entropy does not suffice to realize it as a smooth deformation preserving a strictly positive density on a compact manifold.","expertFr":"Le manuscrit affirme une transformation inversible ergodique, d'entropie de Kolmogorov–Sinai nulle, sans modèle lisse de volume positif : elle n'est conjuguée à aucun difféomorphisme infiniment lisse conservant une densité strictement positive sur une variété compacte. Un seul exemple exclut toute dimension finie, y compris les variétés non orientables ou à bord lisse.","expertEn":"The manuscript asserts an ergodic invertible transformation of zero Kolmogorov–Sinai entropy with no smooth positive-volume model: it is conjugate to no infinitely smooth diffeomorphism preserving a strictly positive density on a compact manifold. A single example rules out every finite dimension, including nonorientable manifolds and those with smooth boundary.","sparkFr":"L'intérêt est structurel : l'entropie nulle n'ouvre pas, à elle seule, un modèle lisse de volume positif.","sparkEn":"The interest is structural: zero entropy alone does not open a smooth positive-volume model."},{"id":"153","titleEn":"Arithmetic classification and non-Pisot singularity for Bernoulli convolutions","titleFr":"Classification arithmétique des convolutions de Bernoulli","claim":"Classifies singular and absolutely continuous unbiased Bernoulli convolutions for every λ∈(0,1) by an infinite, one-sided approximation condition using explicit finite sets of algebraic units. It also proves singularity at reciprocals of every quartic Salem number in (1,2), giving examples beyond reciprocal Pisot parameters.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-03","lean":false,"pdfs":[{"title":"Arithmetic classification and non-Pisot singularity for Bernoulli convolutions","href":"preprints/Arithmetic-classification-and-non-Pisot-singularity-for-Bernoulli-convolutions-October-3-2026/paper.pdf"}],"plainFr":"La convolution de Bernoulli est la loi d'une somme aléatoire de puissances d'un paramètre entre zéro et un. Le manuscrit affirme un critère par approximations infinies qui sépare les cas singuliers des cas à densité, et des exemples singuliers au-delà des paramètres de Pisot.","plainEn":"A Bernoulli convolution is the law of a random sum of powers of a parameter between zero and one. The manuscript asserts a criterion by infinite approximations that separates singular cases from cases with a density, and singular examples beyond Pisot parameters.","expertFr":"Le manuscrit affirme une classification, pour tout paramètre entre 0 et 1, des convolutions de Bernoulli non biaisées, par une condition infinie d'approximation unilatère par des unités algébriques explicites, et non par un test fini. La singularité vaut aussi au réciproque de tout nombre de Salem quartique entre 1 et 2, et au réciproque d'une racine non de Pisot d'un polynôme explicite de degré 31.","expertEn":"The manuscript asserts a classification, for every parameter between 0 and 1, of unbiased Bernoulli convolutions, by an infinite one-sided approximation condition using explicit algebraic units, not by a finite test. Singularity also holds at the reciprocal of every quartic Salem number between 1 and 2, and at the reciprocal of a non-Pisot root of an explicit degree-31 polynomial.","sparkFr":"L'intérêt est structurel, dans l'arithmétique des mesures construites par des séries aléatoires.","sparkEn":"The interest is structural, in the arithmetic of measures built by random series."},{"id":"154","titleEn":"Pointwise multiple ergodic averages for mixing transformations","titleFr":"Moyennes ergodiques multiples ponctuelles des transformations mélangeantes","claim":"Proves almost-everywhere convergence of consecutive multiple ergodic averages of every finite length for invertible mixing probability-preserving transformations. For each fixed tuple of bounded functions, the limit is the product of their integrals, along all positive averaging lengths. No mixing rate or standardness assumption on the probability space is required.","nature":"dynamique","domain":"hasard","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Pointwise Multiple Ergodic Averages for Mixing Transformations","href":"preprints/Pointwise-Multiple-Ergodic-Averages-for-Mixing-Transformations-October-4-2026/multiple-ergodic-averages.pdf"},{"title":"Pointwise convergence of fourfold ergodic averages for mixing transformations","href":"preprints/Pointwise-convergence-of-fourfold-ergodic-averages-for-mixing-transformations-October-4-2026/fourfold-ergodic-averages.pdf"},{"title":"Triple ergodic averages with distinct integer slopes","href":"preprints/Triple-ergodic-averages-with-distinct-integer-slopes-October-4-2026/triple-ergodic-distinct-slopes.pdf"},{"title":"Pointwise convergence of triple ergodic averages for mixing transformations","href":"preprints/Pointwise-convergence-of-triple-ergodic-averages-for-mixing-transformations-October-4-2026/pointwise-triple-ergodic-averages-mixing-transformations.pdf"}],"plainFr":"Une moyenne ergodique multiple suit, le long d'une trajectoire, le produit de plusieurs observations décalées. Le manuscrit affirme que, pour une transformation inversible et mélangeante, ces moyennes de toute longueur finie convergent presque partout vers le produit des moyennes séparées.","plainEn":"A multiple ergodic average follows, along a trajectory, the product of several shifted observations. The manuscript asserts that, for an invertible mixing transformation, these averages of every finite length converge almost everywhere to the product of the separate averages.","expertFr":"Le manuscrit affirme la convergence presque partout des moyennes ergodiques multiples consécutives de toute longueur finie, pour toute transformation inversible mélangeante qui préserve une probabilité. Pour chaque longueur au moins égale à 2 et chaque famille finie fixée de fonctions mesurables bornées, la limite est le produit des intégrales, sans taux de mélange et sans supposer l'espace standard.","expertEn":"The manuscript asserts almost-everywhere convergence of consecutive multiple ergodic averages of every finite length, for every invertible mixing transformation that preserves a probability. For each length at least 2 and each fixed finite family of bounded measurable functions, the limit is the product of the integrals, with no mixing rate and without assuming the space to be standard.","sparkFr":"L'intérêt est structurel : il concerne la convergence, le long des trajectoires, de moyennes multiples.","sparkEn":"The interest is structural: it concerns convergence, along trajectories, of multiple averages."},{"id":"155","titleEn":"A counterexample to periodic tiling in dimension three","titleFr":"Un contre-exemple au pavage périodique en dimension trois","claim":"Constructs a finite translational tile in ℤ3 that tiles space but admits no fully periodic tiling, disproving the periodic tiling conjecture in the smallest possible lattice dimension. Its unit-cube thickening gives the same counterexample in ℝ3, even with arbitrary real translation vectors.","nature":"combinatoire","domain":"formes","complexity":"lecture","problemYear":1961,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A translational tile with no fully periodic tiling in dimension three","href":"preprints/A-translational-tile-with-no-fully-periodic-tiling-in-dimension-three-September-23-2026/paper.pdf"}],"plainFr":"Une tuile par translations est une forme finie qui recouvre l'espace par décalages, sans trou ni chevauchement. Le manuscrit affirme qu'en dimension trois une tuile finie peut paver sans jamais admettre un pavage entièrement périodique.","plainEn":"A translational tile is a finite shape that covers space by shifts, without gaps or overlaps. The manuscript asserts that in dimension three a finite tile can tile while never admitting a fully periodic tiling.","expertFr":"Le manuscrit affirme une tuile translationnelle finie du réseau entier de dimension trois qui admet des pavages mais aucun pavage entièrement périodique, dans la plus petite dimension de réseau possible pour un tel contre-exemple. Son épaississement par le cube unité donne le même phénomène dans l'espace réel de dimension trois, même avec des translations réelles arbitraires.","expertEn":"The manuscript asserts a finite translational tile of the three-dimensional integer lattice that admits tilings but no fully periodic tiling, in the smallest lattice dimension possible for such a counterexample. Its thickening by the unit cube gives the same phenomenon in three-dimensional real space, even with arbitrary real translations.","sparkFr":"Quelqu'un qui cherche un pavage de l'espace par une seule forme finie pourrait y regarder ; aucun motif matériel n'est proposé.","sparkEn":"Someone seeking a tiling of space by one finite shape might look; no material pattern is proposed."},{"id":"156","titleEn":"Borsuk's conjecture fails in dimension nine","titleFr":"La conjecture de Borsuk échoue en dimension neuf","claim":"Constructs a compact subset of ℝ9 that cannot be covered by ten sets of strictly smaller diameter, disproving Borsuk's covering assertion already in dimension nine. The example consists of rank-one orthogonal projectors onto lines in ℝ4, with the Frobenius metric.","nature":"algebre","domain":"structures","complexity":"lecture","problemYear":1933,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A nine-dimensional counterexample to Borsuk's covering assertion","href":"preprints/A-nine-dimensional-counterexample-to-Borsuks-covering-assertion-September-23-2026/paper.pdf"}],"plainFr":"La conjecture de Borsuk demandait de couvrir tout corps borné par des morceaux de diamètre strictement plus petit, en nombre fixé par la dimension. Le manuscrit affirme qu'en dimension neuf un compact fait de projecteurs ne se laisse pas couvrir par dix tels morceaux.","plainEn":"Borsuk's conjecture asked that every bounded body be covered by pieces of strictly smaller diameter, in a number fixed by the dimension. The manuscript asserts that in dimension nine a compact set made of projectors cannot be covered by ten such pieces.","expertFr":"Le manuscrit affirme que l'ensemble compact des projecteurs orthogonaux de rang un sur l'espace de dimension quatre, pour la métrique de Frobenius, ne peut pas être couvert par dix ensembles de diamètre strictement plus petit. Cela donne un contre-exemple à la conjecture de Borsuk déjà en dimension neuf.","expertEn":"The manuscript asserts that the compact set of rank-one orthogonal projectors on four-dimensional space, in the Frobenius metric, cannot be covered by ten sets of strictly smaller diameter. This gives a counterexample to Borsuk's conjecture already in dimension nine.","sparkFr":"L'intérêt est structurel, autour du nombre de morceaux qu'il faut pour réduire un diamètre.","sparkEn":"The interest is structural, around how many pieces it takes to reduce a diameter."},{"id":"157","titleEn":"Graph coloring, clique minors, and Colin de Verdière invariants","titleFr":"Coloration, mineurs de cliques et invariant de Colin de Verdière","claim":"Disproves Hadwiger's conjecture even for fractional coloring: arbitrarily large finite simple graphs with independence number at most two satisfy _f(G) h(G), where h(G) is the largest clique-minor order. Also disproves the fractional Colin de Verdière chromatic bound _f(G)≤μ(G)+1. In the positive direction, every finite nonempty graph satisfies _list(G)≤ C h(G) for a universal constant C.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1943,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A counterexample to Hadwiger's conjecture","href":"preprints/A-counterexample-to-Hadwigers-conjecture-September-23-2026/paper.pdf"},{"title":"A counterexample to the Colin de Verdière chromatic conjecture","href":"preprints/A-counterexample-to-the-Colin-de-Verdiere-chromatic-conjecture-September-23-2026/paper.pdf"},{"title":"A linear list-coloring bound in terms of the Hadwiger number","href":"preprints/A-linear-list-coloring-bound-in-terms-of-the-Hadwiger-number-September-23-2026/paper.pdf"}],"plainFr":"Colorier un graphe, c'est donner aux sommets des couleurs distinctes dès qu'une arête les relie. Le manuscrit affirme que ce nombre peut dépasser la plus grande clique obtenue par contractions, même en version fractionnaire, pour des graphes sans trois sommets deux à deux non reliés.","plainEn":"Coloring a graph means giving vertices different colors whenever an edge joins them. The manuscript asserts that this number can exceed the largest clique obtained by contractions, even in a fractional version, for graphs with no three pairwise nonadjacent vertices.","expertFr":"Le manuscrit affirme des graphes arbitrairement grands, sans trois sommets deux à deux libres, dont le nombre chromatique, même fractionnaire, dépasse le nombre de Hadwiger. Il réfute ainsi la conjecture de Hadwiger et une borne fractionnaire liée à Colin de Verdière, tout en majorant le nombre chromatique par listes par une constante fois le nombre de Hadwiger.","expertEn":"The manuscript asserts arbitrarily large graphs, with no three pairwise free vertices, whose chromatic number, even the fractional one, exceeds the Hadwiger number. It thus disproves Hadwiger's conjecture and a fractional bound tied to Colin de Verdière, while bounding list chromatic number by a constant times the Hadwiger number.","sparkFr":"Quelqu'un qui compare couleurs et contractions dans un réseau pourrait y regarder ; aucun réseau concret n'est colorié.","sparkEn":"Someone comparing colors and contractions in a network might look; no concrete network is colored."},{"id":"158","titleEn":"The Euclidean plane cannot be colored with five colors","titleFr":"Le plan euclidien ne se colore pas avec cinq couleurs","claim":"Proves that every five-coloring of the Euclidean plane has a monochromatic pair at distance one, with no restriction on the color classes. This advances the Hadwiger–Nelson problem: together with the classical seven-coloring, only six and seven remain possible chromatic numbers of the plane.","nature":"analyse","domain":"formes","complexity":"lecture","problemYear":1943,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The Euclidean plane is not five-colorable","href":"preprints/The-Euclidean-plane-is-not-five-colorable-September-23-2026/paper.pdf"}],"plainFr":"Colorier le plan, c'est attribuer une couleur à chaque point. Le manuscrit affirme que cinq couleurs forcent toujours deux points de même couleur à distance un, si bien qu'il ne reste comme possibilités que six ou sept couleurs.","plainEn":"Coloring the plane means giving a color to every point. The manuscript asserts that five colors always force two points of the same color at distance one, so that only six or seven colors remain possible.","expertFr":"Le manuscrit affirme que toute coloration du plan euclidien en cinq couleurs possède une paire monochrome à distance un, sans hypothèse de régularité sur les classes de couleur. Avec la coloration classique en sept couleurs, le nombre chromatique du plan est donc six ou sept.","expertEn":"The manuscript asserts that every five-coloring of the Euclidean plane has a monochromatic pair at distance one, with no regularity assumption on the color classes. Together with the classical seven-coloring, the chromatic number of the plane is therefore six or seven.","sparkFr":"Cela pourrait intéresser qui se demande combien de couleurs séparent les points du plan distants d'une unité.","sparkEn":"It might interest someone asking how many colors separate points of the plane at unit distance."},{"id":"159","titleEn":"Erdős’s reciprocal-sum conjecture and quasipolynomial Szemerédi bounds","titleFr":"Conjecture des réciproques d'Erdős et bornes de type Szemerédi","claim":"Proves Erdős's conjecture that every set of positive integers with divergent reciprocal sum contains arithmetic progressions of every finite length. Quantitatively, for each fixed k ≥ 3, every subset of \\1, ,N\\ with no nonconstant k-term progression has size at most C_kN [-c_k( N)^ε_k], with positive constants depending only on k.","nature":"combinatoire","domain":"nombres","complexity":"frontiere","problemYear":1975,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Quasipolynomial Bounds for Arithmetic Progressions","href":"preprints/Quasipolynomial-Bounds-for-Arithmetic-Progressions-September-23-2026/paper.pdf"}],"plainFr":"Une progression arithmétique est une suite d'entiers à écart constant. Le manuscrit affirme que tout ensemble d'entiers positifs dont la somme des inverses diverge contient de telles progressions de toute longueur finie, avec une borne quantitative pour les ensembles qui les évitent.","plainEn":"An arithmetic progression is a sequence of integers with a constant gap. The manuscript asserts that every set of positive integers whose reciprocals diverge in sum contains such progressions of every finite length, with a quantitative bound for sets that avoid them.","expertFr":"Le manuscrit affirme la conjecture d'Erdős : toute somme divergente de réciproques d'entiers positifs force des progressions arithmétiques de toute longueur finie. Pour chaque longueur k au moins 3, un sous-ensemble de 1 à N sans progression non constante de longueur k a une taille au plus C_k N fois le facteur d'économie écrit dans le texte, à constantes ne dépendant que de k.","expertEn":"The manuscript asserts Erdős's conjecture: every divergent sum of reciprocals of positive integers forces arithmetic progressions of every finite length. For each length k at least 3, a subset of 1 through N with no nonconstant k-term progression has size at most C_k N times the saving factor written in the text, with constants depending only on k.","sparkFr":"Quelqu'un qui cherche des progressions dans les entiers pourrait y regarder ; aucun calcul numérique n'est fourni.","sparkEn":"Someone looking for progressions among the integers might look; no numerical computation is supplied."},{"id":"160","titleEn":"Superexponential van der Waerden numbers","titleFr":"Nombres de van der Waerden à croissance surexponentielle","claim":"Resolves Erdős's superexponential-growth question for van der Waerden numbers. If W_r(k) is the least interval length forcing a monochromatic k-term progression in every r-coloring, then W_r(k) k^ck _2 r for an absolute c > 0, all r ≥ 2 and sufficiently large k, uniformly in r. In particular, W_r(k)^1/k→∞ for each fixed r.","nature":"combinatoire","domain":"structures","complexity":"frontiere","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Quantitative Superexponential Bounds for van der Waerden Numbers","href":"preprints/Quantitative-Superexponential-Bounds-for-van-der-Waerden-Numbers-September-23-2026/paper.pdf"}],"plainFr":"Le nombre de van der Waerden est la longueur qui force, dans toute coloration à un nombre fixé de couleurs, une progression monochrome donnée. Le manuscrit affirme que cette longueur croît plus vite que toute exponentielle pure en la longueur de la progression.","plainEn":"The van der Waerden number is the length that forces, in every coloring with a fixed number of colors, a given monochromatic progression. The manuscript asserts that this length grows faster than every pure exponential in the progression length.","expertFr":"Le manuscrit affirme des constantes absolues c positives et K_0 telles que, pour tout k au moins égal à K_0 et tout nombre de couleurs r au moins égal à 2, le nombre W_r(k) satisfait la minoration surexponentielle écrite dans le texte, uniforme en r. En particulier, sa racine k-ième tend vers l'infini pour chaque r fixé, y compris deux couleurs.","expertEn":"The manuscript asserts absolute constants c positive and K_0 such that, for every k at least K_0 and every number of colors r at least 2, the number W_r(k) satisfies the superexponential lower bound written in the text, uniformly in r. In particular, its k-th root tends to infinity for each fixed r, including two colors.","sparkFr":"Cela pourrait intéresser qui colore les entiers pour éviter une progression monochrome ; aucun coloriage n'est donné.","sparkEn":"It might interest someone coloring the integers to avoid a monochromatic progression; no coloring is given."},{"id":"161","titleEn":"Counterexamples to Sidorenko’s conjecture and the forcing conjecture","titleFr":"Contre-exemples aux conjectures de Sidorenko et de forçage","claim":"Disproves Sidorenko's conjecture with a connected bipartite pattern on 35 vertices and 66 edges that occurs less frequently than in a random graph of the same edge density. The same pattern disproves the forcing conjecture of Skokan and Thoma: matching its density and the edge density of a constant graphon need not force quasirandomness.","nature":"combinatoire","domain":"calcul","complexity":"avance","problemYear":1986,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A counterexample to Sidorenko's conjecture","href":"preprints/A-counterexample-to-Sidorenkos-conjecture-September-23-2026/paper.pdf"}],"plainFr":"La conjecture de Sidorenko attendait qu'un motif biparti apparaisse au moins aussi souvent que dans un graphe aléatoire de même densité. Le manuscrit affirme qu'un motif connexe à 35 sommets et 66 arêtes apparaît moins souvent, et ne force pas non plus le caractère quasialéatoire.","plainEn":"Sidorenko's conjecture expected a bipartite pattern to appear at least as often as in a random graph of the same density. The manuscript asserts that a connected pattern with 35 vertices and 66 edges appears less often, and also fails to force quasirandomness.","expertFr":"Le manuscrit affirme un contre-exemple à la conjecture de Sidorenko par un graphe biparti connexe à 35 sommets et 66 arêtes, dont la densité d'homomorphismes dans un certain graphe simple fini est inférieure à la borne conjecturée. Le même motif réfute la conjecture de forçage de Skokan et Thoma : égaler, à une densité fixée, la densité d'arêtes d'un graphon constant et celle du motif n'impose pas le quasialéatoire.","expertEn":"The manuscript asserts a counterexample to Sidorenko's conjecture by a connected bipartite graph on 35 vertices and 66 edges, whose homomorphism density in some finite simple graph lies below the conjectured bound. The same pattern disproves the forcing conjecture of Skokan and Thoma: matching, at one fixed density, the edge density of a constant graphon and the pattern density need not force quasirandomness.","sparkFr":"L'intérêt est structurel, autour de la fréquence d'un motif dans un grand réseau.","sparkEn":"The interest is structural, around how often a pattern appears in a large network."},{"id":"162","titleEn":"Counterexamples to Ryser’s covering conjecture","titleFr":"Contre-exemples à la conjecture de couverture de Ryser","claim":"Disproves Ryser's covering conjecture by constructing intersecting (q+1)-partite, (q+1)-uniform hypergraphs with covering number q+1, rather than the predicted bound q, for every sufficiently large prime q. A separate construction over extension fields also disproves Gyárfás's monochromatic tree-cover conjecture.","nature":"combinatoire","domain":"nombres","complexity":"avance","problemYear":1971,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Balanced counterexamples to Ryser's conjecture at prime orders","href":"preprints/Balanced-Counterexamples-to-Rysers-Conjecture-at-Prime-Orders-September-27-2026/paper.pdf"},{"title":"A counterexample to Ryser's covering conjecture","href":"preprints/A-Counterexample-to-Rysers-Covering-Conjecture-September-23-2026/paper.pdf"}],"plainFr":"Un hypergraphe uniforme regroupe des blocs de même taille, répartis ici en plusieurs parts. Le manuscrit affirme que, pour tout nombre premier assez grand, un exemple intersectant a un nombre de couverture égal au nombre de parts, et non la borne plus petite conjecturée.","plainEn":"A uniform hypergraph groups blocks of equal size, here split into several parts. The manuscript asserts that, for every large enough prime, an intersecting example has covering number equal to the number of parts, rather than the smaller conjectured bound.","expertFr":"Pour tout premier q assez grand, le manuscrit affirme un hypergraphe fini intersectant, à q+1 parts et à blocs de taille q+1, de nombre de couverture q+1, avec exactement q+1 sommets non isolés dans chaque part. Cela réfute la conjecture de Ryser, et une construction séparée sur des corps d'extension réfute aussi la conjecture de Gyárfás sur les couvertures par arbres monochromes.","expertEn":"For every large enough prime q, the manuscript asserts a finite intersecting hypergraph, with q+1 parts and blocks of size q+1, of covering number q+1, with exactly q+1 nonisolated vertices in each part. This disproves Ryser's conjecture, and a separate construction over extension fields also disproves Gyárfás's conjecture on covers by monochromatic trees.","sparkFr":"L'intérêt est structurel, dans les questions de couverture par blocs d'un hypergraphe.","sparkEn":"The interest is structural, in questions of covering by blocks of a hypergraph."},{"id":"164","titleEn":"Hindman’s finite sums and products conjecture","titleFr":"Sommes et produits finis de la conjecture de Hindman","claim":"Proves Hindman's finite sums and products conjecture: every finite coloring of the positive integers contains sets of any prescribed finite size whose nonempty subset sums and nonempty subset products all have one common color.","nature":"combinatoire","domain":"calcul","complexity":"frontiere","problemYear":1972,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Monochromatic finite sums and products in the positive integers","href":"preprints/Monochromatic-finite-sums-and-products-in-the-positive-integers-September-23-2026/paper.pdf"}],"plainFr":"Colorier les entiers positifs, c'est les répartir en un nombre fini de couleurs. Le manuscrit affirme qu'il existe toujours un ensemble fini de taille prescrite dont toutes les sommes de parties non vides, et tous les produits analogues, ont une même couleur.","plainEn":"Coloring the positive integers means splitting them into finitely many colors. The manuscript asserts that there is always a finite set of any prescribed size whose nonempty subset sums, and whose analogous products, all have one common color.","expertFr":"Le manuscrit affirme la conjecture des sommes et produits finis de Hindman. Pour toute coloration finie des entiers positifs et tout entier positif k, un ensemble à k éléments a toutes ses sommes de sous-ensembles non vides et tous ses produits de sous-ensembles non vides d'une même couleur.","expertEn":"The manuscript asserts Hindman's finite sums and products conjecture. For every finite coloring of the positive integers and every positive integer k, some k-element set has all its nonempty subset sums and all its nonempty subset products of one common color.","sparkFr":"Cela pourrait intéresser qui colore les entiers en cherchant sommes et produits monochromes ; aucun procédé chiffré n'est donné.","sparkEn":"It might interest someone coloring the integers in search of monochromatic sums and products; no quantified procedure is given."},{"id":"165","titleEn":"The Harary–Hill and Zarankiewicz crossing-number formulas","titleFr":"Formules de croisement de Harary–Hill et de Zarankiewicz","claim":"Resolves the Harary–Hill conjecture and Turán's brickyard problem in the Zarankiewicz formulation, determining the crossing numbers of every complete and complete bipartite graph. The result proves the optimality of the classical drawings among all plane drawings with continuous edge arcs.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1941,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The crossing number of complete graphs","href":"preprints/The-crossing-number-of-complete-graphs-September-23-2026/paper.pdf"},{"title":"The crossing number of complete bipartite graphs","href":"preprints/The-crossing-number-of-complete-bipartite-graphs-September-23-2026/paper.pdf"}],"plainFr":"Le nombre de croisement est le minimum de croisements d'arêtes dans un dessin plan d'un graphe. Le manuscrit affirme la valeur exacte pour tous les graphes complets et tous les graphes bipartis complets, ainsi que l'optimalité des dessins classiques.","plainEn":"The crossing number is the minimum of edge crossings in a plane drawing of a graph. The manuscript asserts the exact value for every complete graph and every complete bipartite graph, together with the optimality of the classical drawings.","expertFr":"Le manuscrit affirme la conjecture de Harary et Hill et le problème de la briqueterie de Turán dans la formulation de Zarankiewicz, donc les nombres de croisement ordinaires de tout graphe complet et de tout graphe biparti complet. Les dessins classiques sont optimaux parmi les dessins à arcs continus ; le résumé énonce la formule de Harary–Hill pour le graphe complet.","expertEn":"The manuscript asserts the Harary–Hill conjecture and Turán's brickyard problem in the Zarankiewicz formulation, hence the ordinary crossing numbers of every complete graph and every complete bipartite graph. The classical drawings are optimal among drawings with continuous arcs; the abstract states the Harary–Hill formula for the complete graph.","sparkFr":"Quelqu'un qui dessine un réseau complet en comptant les croisements pourrait y regarder ; aucun plan concret n'est tracé.","sparkEn":"Someone drawing a complete network while counting crossings might look; no concrete plan is drawn."},{"id":"166","titleEn":"The higher-dimensional Erdős distinct-distances conjecture","titleFr":"Distances distinctes d'Erdős en dimension supérieure","claim":"For every fixed d ≥ 3, any n ≥ 2 distinct points in ℝd determine at least c_dn^2/d distinct distances, with c_d 0 depending only on dimension. This matches the integer-grid order and resolves the higher-dimensional Erdős distinct-distances conjecture with a constant-factor bound.","nature":"combinatoire","domain":"formes","complexity":"frontiere","problemYear":1946,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The higher-dimensional Erdős distinct-distances conjecture","href":"preprints/The-higher-dimensional-Erdos-distinct-distances-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Il s'agit du nombre de distances différentes réalisées par un nuage fini de points. Le manuscrit affirme qu'en dimension fixée au moins égale à trois, ce nombre est au moins de l'ordre du nombre de points élevé à la puissance deux divisée par la dimension.","plainEn":"The question is how many different distances a finite cloud of points determines. The manuscript asserts that in any fixed dimension at least three, this number is at least on the order of the number of points raised to two divided by the dimension.","expertFr":"Pour tout entier d au moins égal à 3, le manuscrit affirme que tout ensemble de n au moins 2 points distincts de l'espace réel de dimension d détermine au moins c_d fois n puissance 2/d distances distinctes, avec c_d strictement positif ne dépendant que de d. L'ordre est celui de la grille entière, ce qui résout la conjecture d'Erdős en dimension supérieure à un facteur constant près.","expertEn":"For every integer d at least 3, the manuscript asserts that every set of n at least 2 distinct points in real d-dimensional space determines at least c_d times n to the power 2/d distinct distances, with c_d strictly positive depending only on d. The order matches the integer grid, resolving the higher-dimensional Erdős conjecture up to a constant factor.","sparkFr":"Cela pourrait intéresser qui compte les distances dans un nuage de points ; aucune mesure physique n'est faite.","sparkEn":"It might interest someone counting distances in a point cloud; no physical measurement is made."},{"id":"167","titleEn":"Planar distinct distances and unit-distance bounds","titleFr":"Distances distinctes dans le plan et paires à distance unité","claim":"Proves the weak pinned Erdős distance conjecture: for every fixed ε > 0, all but o(n) points of any n-point planar set determine at least n^1-ε distinct nonzero distances. A complementary theorem bounds the number of unit-distance pairs by O(n^4/3-δ) for an absolute δ > 0.","nature":"combinatoire","domain":"formes","complexity":"lecture","problemYear":1946,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The weak pinned planar distance theorem","href":"preprints/The-weak-pinned-planar-distance-theorem-September-23-2026/paper.pdf"},{"title":"A power saving for planar unit distances","href":"preprints/A-power-saving-for-planar-unit-distances-September-23-2026/paper.pdf"}],"plainFr":"Dans un nuage fini de points du plan, on compte les distances vues depuis chaque point, et les paires distantes d'exactement une unité. Le manuscrit affirme que presque tous les points voient beaucoup de distances, et que les paires à distance un sont un peu moins nombreuses que la borne classique.","plainEn":"In a finite cloud of planar points, one counts distances seen from each point, and pairs exactly one unit apart. The manuscript asserts that almost every point sees many distances, and that unit-distance pairs are somewhat fewer than the classical bound.","expertFr":"Le manuscrit affirme la conjecture faible d'Erdős sur les distances épinglées : pour tout epsilon positif fixé, tous les points d'un ensemble plan de n points, sauf un nombre négligeable devant n, déterminent au moins n puissance 1 moins epsilon distances non nulles distinctes. Un théorème complémentaire borne les paires à distance un par un ordre n puissance 4/3 moins un delta absolu positif.","expertEn":"The manuscript asserts the weak pinned Erdős distance conjecture: for every fixed positive epsilon, all but a negligible number of the n points determine at least n to the power 1 minus epsilon distinct nonzero distances. A complementary theorem bounds unit-distance pairs by an order n to the power 4/3 minus an absolute positive delta.","sparkFr":"Quelqu'un qui compte les distances dans un dessin plan pourrait y regarder ; aucun relevé n'est fourni.","sparkEn":"Someone counting distances in a planar drawing might look; no survey is supplied."},{"id":"168","titleEn":"Combinatorial invariance of Kazhdan–Lusztig polynomials","titleFr":"Invariance combinatoire des polynômes de Kazhdan–Lusztig","claim":"Resolves the full combinatorial invariance conjecture: isomorphic Bruhat intervals in arbitrary Coxeter systems have identical equal-parameter Kazhdan–Lusztig polynomials. Thus the abstract order of the interval determines the polynomial, even across different Coxeter systems.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Combinatorial invariance of Kazhdan–Lusztig polynomials","href":"preprints/Combinatorial-Invariance-of-Kazhdan-Lusztig-Polynomials-September-24-2026/paper.pdf"}],"plainFr":"Un intervalle de Bruhat est un morceau de l'ordre qui organise un système de Coxeter. Le manuscrit affirme que si deux tels intervalles ont le même ordre abstrait, alors leur polynôme de Kazhdan–Lusztig, à paramètres égaux, est le même.","plainEn":"A Bruhat interval is a piece of the order organizing a Coxeter system. The manuscript asserts that if two such intervals have the same abstract order, then their equal-parameter Kazhdan–Lusztig polynomial is the same.","expertFr":"Le manuscrit affirme la conjecture d'invariance combinatoire complète : des intervalles de Bruhat isomorphes, dans des systèmes de Coxeter quelconques, ont les mêmes polynômes de Kazhdan–Lusztig à paramètres égaux. L'ordre abstrait de l'intervalle détermine donc le polynôme, même d'un système de Coxeter à un autre.","expertEn":"The manuscript asserts the full combinatorial invariance conjecture: isomorphic Bruhat intervals in arbitrary Coxeter systems have the same equal-parameter Kazhdan–Lusztig polynomials. The abstract order of the interval therefore determines the polynomial, even from one Coxeter system to another.","sparkFr":"L'intérêt est structurel, à l'intérieur de l'algèbre des ordres de Coxeter.","sparkEn":"The interest is structural, inside the algebra of Coxeter orders."},{"id":"169","titleEn":"Shareshian–Wachs elementary positivity","titleFr":"Positivité élémentaire de Shareshian et Wachs","claim":"Resolves the elementary-positivity part of the Shareshian–Wachs conjecture: the chromatic quasisymmetric function of every natural unit interval graph has elementary-basis coefficients in N[q]. The coefficients count explicitly described permutations, giving a combinatorial explanation of positivity.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Elementary positivity of chromatic quasisymmetric functions","href":"preprints/Elementary-Positivity-of-Chromatic-Quasisymmetric-Functions-September-24-2026/paper.pdf"}],"plainFr":"Une fonction chromatique quasi symétrique encode les coloriages d'un graphe d'intervalles, avec un paramètre qui compte des inversions. Le manuscrit affirme que, dans la base élémentaire, ses coefficients sont des polynômes à coefficients entiers positifs en ce paramètre.","plainEn":"A chromatic quasisymmetric function encodes the colorings of an interval graph, with a parameter that counts inversions. The manuscript asserts that, in the elementary basis, its coefficients are polynomials in that parameter with positive integer coefficients.","expertFr":"Le manuscrit affirme que la fonction chromatique quasi symétrique de tout graphe d'intervalles unité naturel est positive sur la base élémentaire, à coefficients dans les polynômes à coefficients entiers naturels en q. Ces coefficients comptent des permutations décrites explicitement, ce qui résout la partie de positivité élémentaire de la conjecture de Shareshian et Wachs.","expertEn":"The manuscript asserts that the chromatic quasisymmetric function of every natural unit interval graph is positive on the elementary basis, with coefficients in the polynomials with natural-number coefficients in q. These coefficients count explicitly described permutations, resolving the elementary-positivity part of the Shareshian–Wachs conjecture.","sparkFr":"L'intérêt est structurel, autour du signe des coefficients qui comptent des coloriages.","sparkEn":"The interest is structural, around the sign of coefficients that count colorings."},{"id":"170","titleEn":"Sharp logarithmic exponents for off-diagonal Ramsey numbers","titleFr":"Exposants logarithmiques nets des nombres de Ramsey hors diagonale","claim":"For every fixed integer s ≥ 5, proves r(s,t)=t^s-1/( t)^s-2+o(1) as t→∞, determining the logarithmic exponent and matching the classical upper bound at that scale. Here r(s,t) is the least number of vertices forcing an s-clique or a t-vertex independent set.","nature":"combinatoire","domain":"calcul","complexity":"avance","problemYear":1930,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The sharp logarithmic exponent of r(5,t)","href":"preprints/The-Sharp-Logarithmic-Exponent-of-r-5-t-September-24-2026/paper.pdf"},{"title":"Sharp logarithmic exponents for fixed off-diagonal Ramsey numbers","href":"preprints/Sharp-Logarithmic-Exponents-for-Fixed-Off-Diagonal-Ramsey-Numbers-September-24-2026/paper.pdf"}],"plainFr":"Le nombre de Ramsey hors diagonale est la taille qui force une clique fixée ou un grand ensemble sans arête. Le manuscrit affirme l'exposant logarithmique exact de cette taille lorsque la clique est fixée à au moins cinq sommets et que l'ensemble sans arête grandit.","plainEn":"An off-diagonal Ramsey number is the size that forces a fixed clique or a large edgeless set. The manuscript asserts the exact logarithmic exponent of this size when the clique is fixed at five or more vertices and the edgeless set grows.","expertFr":"Pour tout entier s au moins égal à 5, le manuscrit affirme que r(s,t) égale t puissance s moins 1, divisé par un facteur logarithmique en t élevé à la puissance s moins 2 plus un petit o, quand t tend vers l'infini. Cela fixe l'exposant logarithmique au niveau de la borne supérieure classique : r(s,t) force une clique de taille s ou un ensemble indépendant de taille t.","expertEn":"For every integer s at least 5, the manuscript asserts that r(s,t) equals t to the power s minus 1, divided by a logarithmic factor in t raised to the power s minus 2 plus a little-o, as t tends to infinity. This fixes the logarithmic exponent at the classical upper bound: r(s,t) forces a clique of size s or an independent set of size t.","sparkFr":"L'intérêt est structurel, dans l'estimation de la taille qui force une clique ou un ensemble sans arête.","sparkEn":"The interest is structural, in estimating the size that forces a clique or an edgeless set."},{"id":"171","titleEn":"The hypercube Ramsey conjecture","titleFr":"La conjecture de Ramsey pour l'hypercube","claim":"Resolves the Burr–Erdős hypercube Ramsey conjecture: the two-color Ramsey number of the n-dimensional cube is (2^n). Thus every red-blue coloring of a complete graph on a universal constant times the cube's number of vertices contains a monochromatic copy of the cube.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The hypercube Ramsey number has linear order","href":"preprints/The-hypercube-Ramsey-number-has-linear-order-September-23-2026/paper.pdf"}],"plainFr":"L'hypercube de dimension n est le graphe des sommets d'un cube binaire, en nombre une puissance de deux. Le manuscrit affirme que toute coloration en deux couleurs d'un graphe complet assez grand, un multiple universel de ce nombre, contient une copie monochrome de ce cube.","plainEn":"The n-dimensional hypercube is the graph of the vertices of a binary cube, a power of two many of them. The manuscript asserts that every two-coloring of a large enough complete graph, a universal multiple of that number, contains a monochromatic copy of this cube.","expertFr":"Le manuscrit affirme la conjecture de Ramsey de Burr et Erdős pour l'hypercube : le nombre de Ramsey à deux couleurs du cube binaire de dimension n est au plus une constante absolue fois 2 puissance n. Toute coloration rouge-bleu du graphe complet sur ce nombre de sommets contient donc une copie monochrome du cube.","expertEn":"The manuscript asserts the Burr–Erdős Ramsey conjecture for the hypercube: the two-color Ramsey number of the n-dimensional binary cube is at most an absolute constant times 2 to the n. Every red-blue coloring of the complete graph on that many vertices therefore contains a monochromatic copy of the cube.","sparkFr":"Cela pourrait intéresser qui cherche une copie monochrome d'un cube dans un graphe colorié ; aucun dessin n'est fourni.","sparkEn":"It might interest someone seeking a monochromatic cube in a colored graph; no drawing is supplied."},{"id":"172","titleEn":"Classification of finite Euclidean Ramsey configurations","titleFr":"Classification des configurations finies de Ramsey euclidiennes","claim":"Classifies finite point configurations that occur monochromatically, at their original scale, in every finite coloring of sufficiently high-dimensional Euclidean space. The characterization is an algebraic condition over the coordinate field. It also disproves the Leader–Russell–Walters conjecture that every such configuration is a subset of a finite transitive set.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1930,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A classification of finite Euclidean Ramsey configurations","href":"preprints/A-classification-of-finite-Euclidean-Ramsey-configurations-September-23-2026/paper.pdf"}],"plainFr":"Une configuration est de Ramsey si toute coloration finie d'un espace assez grand en contient une copie monochrome à la même échelle. Le manuscrit affirme une condition algébrique qui les caractérise, et qu'elles ne sont pas toutes tirées d'un ensemble fini transitif.","plainEn":"A configuration is Ramsey if every finite coloring of a high enough space contains a monochromatic copy at the same scale. The manuscript asserts an algebraic condition that characterizes them, and that they are not all taken from a finite transitive set.","expertFr":"Le manuscrit affirme une classification par une condition tensorielle nécessaire et suffisante sur le corps des coordonnées, pour des copies monochromes à l'échelle d'origine. Tout ensemble subtransitif non vide et tout ensemble d'au plus cinq points sur un cercle sont de Ramsey, mais certains quadrilatères cycliques de Ramsey ne sont pas subtransitifs, contre la conjecture de Leader, Russell et Walters.","expertEn":"The manuscript asserts a classification by a necessary and sufficient tensor condition on the coordinate field, for monochromatic copies at the original scale. Every nonempty subtransitive set and every set of at most five points on a circle is Ramsey, but some Ramsey cyclic quadrilaterals are not subtransitive, against the Leader–Russell–Walters conjecture.","sparkFr":"Cela pourrait intéresser qui colore l'espace pour éviter une forme monochrome ; aucune coloration concrète n'est construite.","sparkEn":"It might interest someone coloring space to avoid a monochromatic shape; no concrete coloring is constructed."},{"id":"173","titleEn":"Seymour’s second-neighborhood conjecture","titleFr":"La conjecture du second voisinage de Seymour","claim":"Proves Seymour's second-neighborhood conjecture: every nonempty finite oriented graph has a vertex with at least as many vertices at directed distance exactly two as at directed distance one. Oriented graphs may be arbitrary apart from the exclusion of loops and oppositely directed edge pairs.","nature":"combinatoire","domain":"formes","complexity":"avance","problemYear":1977,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A proof of Seymour’s second-neighborhood conjecture","href":"preprints/A-proof-of-Seymours-second-neighborhood-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Un graphe orienté donne un sens à chaque arête, sans boucle ni paire d'arêtes opposées. Le manuscrit affirme que, s'il est fini et non vide, un sommet a au moins autant de sommets à distance dirigée deux qu'à distance dirigée un.","plainEn":"An oriented graph gives a direction to each edge, with no loop and no pair of opposite edges. The manuscript asserts that if it is finite and nonempty, some vertex has at least as many vertices at directed distance two as at directed distance one.","expertFr":"Le manuscrit affirme la conjecture du second voisinage de Seymour : tout graphe orienté fini non vide a un sommet avec au moins autant de sommets à distance dirigée exactement deux qu'à distance dirigée un. Hors l'exclusion des boucles et des paires d'arêtes de sens opposés, le graphe orienté peut être quelconque.","expertEn":"The manuscript asserts Seymour's second-neighborhood conjecture: every nonempty finite oriented graph has a vertex with at least as many vertices at directed distance exactly two as at directed distance one. Apart from excluding loops and oppositely directed edge pairs, the oriented graph may be arbitrary.","sparkFr":"Quelqu'un qui compte les voisins à un ou deux pas dans un réseau orienté pourrait y regarder ; aucun réseau réel n'est étudié.","sparkEn":"Someone counting neighbors one or two steps away in a directed network might look; no real network is studied."},{"id":"174","titleEn":"Deterministic construction of strong thin spanning trees","titleFr":"Arbres couvrants fortement minces, construits de façon déterministe","claim":"Resolves the strong thin-tree conjecture constructively. Every finite loopless k-edge-connected multigraph on at least two vertices has a spanning tree containing at most a universal C/k fraction of the edges of every cut. Such a tree can be found deterministically in polynomial time, even with binary-encoded parallel-edge multiplicities.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The strong thin tree conjecture","href":"preprints/The-strong-thin-tree-conjecture-September-23-2026/paper.pdf"},{"title":"A polynomial-time construction of strong thin trees","href":"preprints/A-polynomial-time-construction-of-strong-thin-trees-September-23-2026/paper.pdf"}],"plainFr":"Un arbre couvrant relie tous les sommets d'un réseau sans former de cycle. Le manuscrit affirme que si le réseau reste connexe malgré la perte de nombreuses arêtes, un tel arbre peut ne prendre qu'une petite fraction de chaque coupe, et se trouver sans tirage au sort en temps polynomial.","plainEn":"A spanning tree joins every vertex of a network without forming a cycle. The manuscript asserts that if the network stays connected despite the loss of many edges, such a tree can take only a small fraction of every cut, and can be found with no random draws in polynomial time.","expertFr":"Le manuscrit affirme la conjecture forte des arbres minces : tout multigraphe fini sans boucle, à connexité d'arêtes k, a un arbre couvrant qui prend au plus une fraction C/k de chaque coupe, C universelle. Cet arbre se calcule de façon déterministe en temps polynomial, même si les multiplicités d'arêtes parallèles sont codées en binaire.","expertEn":"The manuscript asserts the strong thin-tree conjecture: every finite loopless multigraph of edge-connectivity k has a spanning tree taking at most a fraction C/k of each cut, with C universal. This tree is computed deterministically in polynomial time, even if parallel-edge multiplicities are encoded in binary.","sparkFr":"Cela pourrait intéresser qui cherche un sous-réseau léger sur chaque coupe ; aucun réseau industriel n'est traité.","sparkEn":"It might interest someone seeking a subnetwork that is light on every cut; no industrial network is treated."},{"id":"175","titleEn":"Talagrand’s expectation thresholds, discrete convexity, and graph decompositions","titleFr":"Seuils d'espérance de Talagrand et décompositions de graphes","claim":"Proves that integral and fractional expectation thresholds differ by at most a universal factor, and resolves Talagrand's discrete-convexity conjecture. An application proves the Ascoli–He–Park–Talagrand graph-decomposition conjecture: every graph's edges split into a universally bounded number of fixed pieces, each with containment threshold at most a universal constant times the original graph's integral expectation threshold. The pieces' embeddings need not agree on shared vertices.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Graph Decompositions at the Integral Expectation Threshold","href":"preprints/Graph-Decompositions-at-the-Integral-Expectation-Threshold-October-5-2026/graph-threshold-decompositions.pdf"},{"title":"Integral and fractional expectation thresholds are equivalent","href":"preprints/Integral-and-fractional-expectation-thresholds-are-equivalent-September-23-2026/paper.pdf"},{"title":"Talagrand’s discrete-convexity conjecture","href":"preprints/Talagrands-discrete-convexity-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Un seuil d'espérance marque la densité à partir de laquelle un motif a de bonnes chances d'apparaître au hasard. Le manuscrit affirme que les versions entière et fractionnaire de ce seuil ne diffèrent que d'un facteur universel, et qu'un graphe se découpe en un nombre borné de morceaux de seuils comparables.","plainEn":"An expectation threshold marks the density from which a pattern is likely to appear at random. The manuscript asserts that the integral and fractional versions of this threshold differ only by a universal factor, and that a graph splits into a bounded number of pieces of comparable thresholds.","expertFr":"Le manuscrit affirme que seuils d'espérance entier et fractionnaire diffèrent d'au plus un facteur universel, et résout la conjecture de convexité discrète de Talagrand. Les arêtes de tout graphe se partagent en un nombre borné de pièces, de seuil au plus une constante universelle fois le seuil entier du graphe, sans que les plongements s'accordent sur les sommets communs.","expertEn":"The manuscript asserts that integral and fractional expectation thresholds differ by at most a universal factor, and resolves Talagrand's discrete-convexity conjecture. The edges of every graph split into a bounded number of pieces, of threshold at most a universal constant times the graph's integral threshold, without the embeddings agreeing on shared vertices.","sparkFr":"Quelqu'un qui découpe un réseau avant de le chercher dans un hôte aléatoire pourrait y regarder ; aucun essai n'est mené.","sparkEn":"Someone splitting a network before seeking it in a random host might look; no trial is run."},{"id":"176","titleEn":"The second Kahn–Kalai conjecture with an edge-count bound","titleFr":"Seconde conjecture de Kahn et Kalai, avec le nombre d'arêtes","claim":"Proves the second Kahn–Kalai conjecture: for every finite simple graph H with h ≥ 1 edges and at most n vertices, its appearance threshold in G(n,p) is at most C p_ E(n,H)(1+ _2 h), with universal C. Here p_ E is the least density at which every subgraph of H has expected copy count at least 1/2.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The second Kahn–Kalai conjecture","href":"preprints/The-second-Kahn-Kalai-conjecture-September-24-2026/paper.pdf"}],"plainFr":"Le seuil d'apparition d'un graphe est la densité à partir de laquelle un graphe aléatoire le contient. Le manuscrit affirme que ce seuil ne dépasse le seuil d'espérance des sous-motifs que d'un facteur universel lié au nombre d'arêtes.","plainEn":"The appearance threshold of a graph is the density from which a random graph contains it. The manuscript asserts that this threshold exceeds the expectation threshold of the subpatterns only by a universal factor tied to the number of edges.","expertFr":"Le manuscrit affirme la seconde conjecture de Kahn et Kalai : pour un graphe simple H à au moins une arête et au plus n sommets, le seuil d'une copie dans G(n,p) est au plus C fois p_E(n,H) fois le facteur écrit, un plus un terme en le nombre d'arêtes. Ici p_E est la plus petite densité où chaque sous-graphe de H a au moins une demi-copie en espérance.","expertEn":"The manuscript asserts the second Kahn–Kalai conjecture: for a simple graph H with at least one edge and at most n vertices, the threshold of a copy in G(n,p) is at most C times p_E(n,H) times the written factor, one plus a term in the number of edges. Here p_E is the least density at which every subgraph of H has at least half a copy in expectation.","sparkFr":"Cela pourrait intéresser qui estime quand un motif surgit dans un réseau aléatoire ; aucune simulation n'est décrite.","sparkEn":"It might interest someone estimating when a pattern appears in a random network; no simulation is described."},{"id":"177","titleEn":"Bounded-degree coboundary expanders","titleFr":"Expandeurs de cobord à degré borné","claim":"Constructs arbitrarily large finite d-dimensional simplicial complexes, for every d ≥ 3, with uniformly bounded vertex degrees and uniform 𝔽2 coboundary expansion in every degree below d. Together with the known graph and two-dimensional cases, this establishes the existence of such expanders in every positive dimension.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Bounded-degree coboundary expanders in every dimension","href":"preprints/Bounded-degree-coboundary-expanders-in-every-dimension-September-24-2026/paper.pdf"}],"plainFr":"Un complexe simplicial assemble des points, des arêtes et des blocs de dimension plus haute. Le manuscrit affirme qu'il en existe d'arbitrairement grands, en toute dimension au moins trois, à nombre de voisins borné, et qui se dilatent uniformément au sens du cobord à coefficients deux.","plainEn":"A simplicial complex assembles points, edges and higher-dimensional blocks. The manuscript asserts that there exist arbitrarily large ones, in every dimension at least three, with a bounded number of neighbors, which expand uniformly in the coboundary sense with coefficients two.","expertFr":"Pour tout entier d au moins égal à 3, le manuscrit affirme des complexes simpliciaux finis de dimension d, arbitrairement grands, à degrés de sommets uniformément bornés et à expansion de cobord uniforme sur le corps à deux éléments, en tout degré strictement inférieur à d. Avec les cas connus des graphes et de la dimension deux, de tels expandeurs existent en toute dimension positive.","expertEn":"For every integer d at least 3, the manuscript asserts arbitrarily large finite d-dimensional simplicial complexes, with uniformly bounded vertex degrees and uniform coboundary expansion over the two-element field, in every degree strictly below d. Together with the known cases of graphs and of dimension two, such expanders exist in every positive dimension.","sparkFr":"L'intérêt est structurel, autour d'assemblages qui restent dilatants malgré un degré borné.","sparkEn":"The interest is structural, around assemblies that stay expanding despite a bounded degree."},{"id":"178","titleEn":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","titleFr":"Graphes de Ramanujan non bipartis, en tout degré fixé","claim":"For every fixed d ≥ 3, constructs a simple d-regular nonbipartite Ramanujan graph on every sufficiently large even number n of vertices, with every nonconstant adjacency eigenvalue strictly between -2√(d-1) and 2√(d-1). A deterministic algorithm outputs the full adjacency list in polynomial bit time, with exponent depending on d.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1988,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","href":"preprints/Deterministic-nonbipartite-Ramanujan-graphs-in-every-fixed-degree-September-23-2026/paper.pdf"}],"plainFr":"Un graphe régulier relie chaque sommet au même nombre de voisins. Le manuscrit affirme que, pour tout degré fixé au moins trois et tout nombre pair de sommets assez grand, un procédé déterministe construit un graphe simple non biparti dont les valeurs propres non triviales restent dans l'intervalle de Ramanujan.","plainEn":"A regular graph joins every vertex to the same number of neighbors. The manuscript asserts that, for every fixed degree at least three and every large enough even number of vertices, a deterministic procedure builds a simple nonbipartite graph whose nontrivial eigenvalues stay in the Ramanujan range.","expertFr":"Pour tout degré fixé d au moins 3, le manuscrit affirme un algorithme déterministe qui, pour tout nombre pair de sommets assez grand, écrit la liste d'adjacence d'un graphe simple non biparti d-régulier de Ramanujan, en temps binaire polynomial. Toute valeur propre non constante est strictement entre moins deux fois la racine carrée de (d moins 1) et deux fois cette racine.","expertEn":"For every fixed degree d at least 3, the manuscript asserts a deterministic algorithm that, for every large enough even number of vertices, writes the adjacency list of a simple nonbipartite d-regular Ramanujan graph, in polynomial bit time. Every nonconstant eigenvalue lies strictly between minus twice the square root of (d minus 1) and twice that root.","sparkFr":"Quelqu'un qui construit des réseaux réguliers très dilatants pourrait y regarder ; aucun réseau matériel n'est proposé.","sparkEn":"Someone building highly expanding regular networks might look; no material network is proposed."},{"id":"179","titleEn":"The circulant Hadamard and Barker-sequence conjectures","titleFr":"Conjectures de Hadamard circulant et des suites de Barker","claim":"Proves that real circulant Hadamard matrices exist exactly in orders 1 and 4, resolving the circulant Hadamard conjecture. Together with classical Barker-sequence results, this shows that binary sequences whose nontrivial aperiodic autocorrelations have magnitude at most 1 exist at lengths n > 1 exactly when n∈\\2,3,4,5,7,11,13\\.","nature":"combinatoire","domain":"structures","complexity":"lecture","problemYear":1961,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The circulant Hadamard conjecture","href":"preprints/The-circulant-Hadamard-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Une matrice de Hadamard circulante est un tableau carré de signes, constant sur les diagonales cycliques, à lignes orthogonales. Le manuscrit affirme que de tels tableaux réels n'existent qu'en tailles un et quatre, et en déduit les longueurs possibles de certaines suites binaires à très petite autocorrélation.","plainEn":"A circulant Hadamard matrix is a square table of signs, constant on cyclic diagonals, with orthogonal rows. The manuscript asserts that such real tables exist only in sizes one and four, and deduces the possible lengths of certain binary sequences with very small autocorrelation.","expertFr":"Le manuscrit affirme que les matrices de Hadamard circulantes réelles existent exactement aux ordres 1 et 4. Joint aux résultats classiques sur les suites de Barker, les suites binaires d'autocorrélation apériodique non triviale au plus 1 n'existent, au-delà de la longueur 1, qu'aux longueurs 2, 3, 4, 5, 7, 11 et 13.","expertEn":"The manuscript asserts that real circulant Hadamard matrices exist exactly in orders 1 and 4. Together with classical results on Barker sequences, binary sequences of nontrivial aperiodic autocorrelation at most 1 exist, beyond length 1, only at lengths 2, 3, 4, 5, 7, 11 and 13.","sparkFr":"Cela pourrait intéresser qui cherche des suites binaires à faible autocorrélation ; aucune transmission n'est décrite.","sparkEn":"It might interest someone seeking binary sequences of small autocorrelation; no transmission is described."},{"id":"180","titleEn":"Barnette’s Hamiltonian-cycle conjecture","titleFr":"La conjecture des cycles hamiltoniens de Barnette","claim":"Proves that every finite simple cubic bipartite planar 3-vertex-connected graph has a Hamiltonian cycle, resolving Barnette's conjecture. Equivalently, every three-edge path in a finite simple cubic 3-vertex-connected bipartite Pfaffian graph lies in a Hamiltonian cycle.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Paired states and Hamiltonian cycles in cubic bipartite planar graphs","href":"preprints/Paired-states-and-Hamiltonian-cycles-in-cubic-bipartite-planar-graphs-September-24-2026/paper.pdf"}],"plainFr":"Un cycle hamiltonien visite chaque sommet d'un graphe une fois avant de revenir au départ. Le manuscrit affirme que tout graphe fini simple, cubique, biparti, planaire et encore connexe après la suppression de deux sommets, en possède un.","plainEn":"A Hamiltonian cycle visits every vertex of a graph once before returning to the start. The manuscript asserts that every finite simple cubic bipartite planar graph that stays connected after deleting two vertices has one.","expertFr":"Le manuscrit affirme la conjecture de Barnette : tout graphe fini simple, cubique, biparti, planaire et 3-connexe par les sommets possède un cycle hamiltonien. De façon équivalente, tout chemin de trois arêtes d'un graphe fini simple, cubique, 3-connexe par les sommets, biparti et pfaffien, est contenu dans un cycle hamiltonien.","expertEn":"The manuscript asserts Barnette's conjecture: every finite simple cubic bipartite planar graph that is 3-connected at the vertices has a Hamiltonian cycle. Equivalently, every three-edge path in a finite simple cubic graph that is 3-connected at the vertices, bipartite and Pfaffian, lies in a Hamiltonian cycle.","sparkFr":"Quelqu'un qui cherche un tour de tous les sommets dans un réseau cubique planaire pourrait y regarder ; aucun plan concret n'est traité.","sparkEn":"Someone seeking a tour of all vertices in a cubic planar network might look; no concrete plan is treated."},{"id":"181","titleEn":"The Erdős–Gallai cycle-decomposition conjecture","titleFr":"La conjecture de décomposition en cycles d'Erdős et Gallai","claim":"Proves that the edges of every finite simple undirected graph on n vertices can be partitioned into at most Cn simple cycles and single edges, for an absolute constant C. This resolves the Erdős–Gallai cycle-decomposition conjecture, bounding the number of pieces linearly even for dense graphs.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A linear cycle-and-edge decomposition of every graph","href":"preprints/A-linear-cycle-and-edge-decomposition-of-every-graph-September-24-2026/main.pdf"}],"plainFr":"Décomposer un graphe, c'est répartir ses arêtes en morceaux sans arête commune. Le manuscrit affirme que, pour tout graphe fini simple, des cycles simples et des arêtes seules suffisent, en nombre au plus proportionnel au nombre de sommets.","plainEn":"Decomposing a graph means splitting its edges into pieces with no edge in common. The manuscript asserts that, for every finite simple graph, simple cycles and single edges suffice, in a number at most proportional to the number of vertices.","expertFr":"Le manuscrit affirme que les arêtes de tout graphe simple non orienté fini à n sommets se partitionnent en au plus C n cycles simples et arêtes seules, pour une constante absolue C. Cela résout positivement la conjecture de décomposition en cycles d'Erdős et Gallai, avec une borne linéaire même si le graphe est dense.","expertEn":"The manuscript asserts that the edges of every finite simple undirected graph on n vertices partition into at most C n simple cycles and single edges, for an absolute constant C. This resolves positively the Erdős–Gallai cycle-decomposition conjecture, with a linear bound even if the graph is dense.","sparkFr":"L'intérêt est structurel : il borne le nombre de cycles et d'arêtes seules qui recouvrent un réseau.","sparkEn":"The interest is structural: it bounds how many cycles and single edges cover a network."},{"id":"182","titleEn":"Power savings for intersective polynomial differences and prime arguments","titleFr":"Gains de puissance pour les différences de polynômes intersectifs","claim":"For every fixed intersective integer polynomial h of degree k ≥ 2 with positive leading coefficient, proves that a subset of \\1, ,N\\ avoiding nonzero values h(1),h(2), as differences has size O_h(N^1-c_k), with c_k 0 depending only on degree. Here intersective means having a root modulo every modulus. For prime arguments, a power saving also holds when h has a unit root modulo every modulus, with exponent allowed to depend on h.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A power saving for intersective polynomial differences with an exponent depending only on the degree","href":"preprints/A-power-saving-for-intersective-polynomial-differences-with-an-exponent-depending-only-on-the-degree-October-5-2026/power-saving-intersective-polynomial-differences.pdf"},{"title":"A Power Saving for Polynomial Differences at Prime Arguments","href":"preprints/A-Power-Saving-for-Polynomial-Differences-at-Prime-Arguments-October-5-2026/prime-argument-polynomial-differences.pdf"},{"title":"A power saving for square-difference-free sets","href":"preprints/A-power-saving-for-square-difference-free-sets-September-24-2026/paper.pdf"}],"plainFr":"Un polynôme entier intersectif possède une racine modulo tout entier positif. Le manuscrit affirme qu'un ensemble d'entiers jusqu'à une borne qui évite, comme différences, les valeurs non nulles d'un tel polynôme de degré au moins deux, perd une puissance positive de cette borne.","plainEn":"An intersective integer polynomial has a root modulo every positive integer. The manuscript asserts that a set of integers up to a bound which avoids, as differences, the nonzero values of such a polynomial of degree at least two, loses a positive power of that bound.","expertFr":"Le manuscrit affirme qu'éviter comme différences les valeurs non nulles d'un polynôme entier intersectif de degré au moins 2 et de coefficient dominant positif force une taille au plus N puissance 1 moins un exposant positif ne dépendant que du degré. Pour des arguments premiers, un gain analogue subsiste s'il y a une racine unité modulo tout module, l'exposant pouvant alors dépendre du polynôme.","expertEn":"The manuscript asserts that avoiding, as differences, the nonzero values of an intersective integer polynomial of degree at least 2 and positive leading coefficient forces size at most N to the power 1 minus a positive exponent depending only on the degree. For prime arguments, a similar saving remains if there is a unit root modulo every modulus, the exponent then possibly depending on the polynomial.","sparkFr":"Quelqu'un qui évite certaines différences polynomiales parmi les entiers pourrait y regarder ; aucun crible appliqué n'est décrit.","sparkEn":"Someone avoiding certain polynomial differences among the integers might look; no applied sieve is described."},{"id":"183","titleEn":"Power savings for planar halving lines and k-sets","titleFr":"Gains de puissance pour les droites médianes planes","claim":"Improves the planar halving-line bound to O(n^4/3-ε) for sets with no three collinear and an absolute ε > 0. More generally, an n-point set with no three collinear has O(n(k+1)^1/3-ε_0) strictly separable k-subsets for 1≤ k≤ n/2, with an absolute ε_0 0. The constants and positive exponents are nonquantitative.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A power saving for planar halving lines","href":"preprints/A-power-saving-for-planar-halving-lines-September-25-2026/main.pdf"}],"plainFr":"Une droite médiane coupe un nuage pair de points du plan, sans trois alignés, en deux moitiés égales. Le manuscrit affirme que le nombre de telles coupures, et plus généralement celui de certains sous-ensembles séparables, gagne une puissance sur la borne classique.","plainEn":"A halving line cuts an even cloud of planar points, with no three on a line, into two equal halves. The manuscript asserts that the number of such cuts, and more generally that of certain separable subsets, gains a power over the classical bound.","expertFr":"Le manuscrit affirme qu'un grand ensemble plan d'un nombre pair n de points, sans trois alignés, a au plus C fois n puissance 4/3 moins epsilon paires médianes, pour des constantes absolues positives. Le nombre de k-sous-ensembles strictement séparables est du même type, n fois (k+1) puissance 1/3 moins un exposant positif, et les constantes restent non quantitatives.","expertEn":"The manuscript asserts that a large planar set of an even number n of points, with no three collinear, has at most C times n to the power 4/3 minus epsilon halving pairs, for positive absolute constants. The number of strictly separable k-subsets is of the same type, n times (k+1) to the power 1/3 minus a positive exponent, and the constants stay nonquantitative.","sparkFr":"Cela pourrait intéresser qui partage un nuage de points par une droite ; aucun relevé géométrique n'est donné.","sparkEn":"It might interest someone splitting a point cloud by a line; no geometric survey is given."},{"id":"184","titleEn":"Correspondence coloring with a fixed forbidden subgraph","titleFr":"Coloration par correspondance sans un sous-graphe fixé","claim":"Proves the Alon–Krivelevich–Sudakov coloring conjecture in correspondence-coloring form: graphs avoiding any fixed subgraph F need O_F( / ) colors when their maximum degree Δ is sufficiently large. Also proves the Ajtai–Erdős–Komlós–Szemerédi independence conjecture: for fixed r ≥ 4, every n-vertex Kr-free graph of average degree d ≥ 2 has an independent set of size _r(n d/d).","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1975,"yearKnown":true,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Correspondence coloring graphs with a forbidden clique","href":"preprints/Correspondence-Coloring-Graphs-with-a-Forbidden-Clique-October-5-2026/correspondence-coloring-forbidden-clique.pdf"},{"title":"A logarithmic independence bound for clique-free graphs","href":"preprints/A-Logarithmic-Independence-Bound-for-Clique-Free-Graphs-September-25-2026/paper.pdf"}],"plainFr":"La coloration par correspondance attribue des couleurs de façon plus exigeante, selon des listes locales. Le manuscrit affirme que, si un motif fixé est interdit et le degré assez grand, le nombre de couleurs suit l'ordre écrit en ce degré, et que, sans grande clique, un grand ensemble sans arête existe.","plainEn":"Correspondence coloring assigns colors more demandingly, from local lists. The manuscript asserts that if a fixed pattern is forbidden and the degree is large enough, the number of colors follows the order written in that degree, and that a large edgeless set exists outside a clique.","expertFr":"Le manuscrit affirme la conjecture d'Alon, Krivelevich et Sudakov en coloration par correspondance : sans sous-graphe fixé et à grand degré, le nombre de couleurs suit l'ordre écrit, dépendant seulement de ce sous-graphe, y compris pour les colorations ordinaire et par listes. Pour r au moins 4, un graphe sans clique de taille r, de degré moyen au moins 2, a un ensemble indépendant de la taille écrite.","expertEn":"The manuscript asserts the Alon–Krivelevich–Sudakov conjecture in correspondence coloring: without a fixed subgraph, and for large degree, the number of colors is the written order, depending only on that subgraph; ordinary and list coloring included. For r at least 4, a graph with no clique of size r and average degree at least 2 has an independent set of the size written in the number of vertices and that degree.","sparkFr":"Quelqu'un qui colore un réseau privé d'un motif donné pourrait y regarder ; aucun graphe concret n'est colorié.","sparkEn":"Someone coloring a network that avoids a given pattern might look; no concrete graph is colored."},{"id":"185","titleEn":"Counterexamples to infinite matroid intersection and packing/covering","titleFr":"Contre-exemples à l'intersection infinie de matroïdes","claim":"Disproves the unrestricted infinite matroid intersection and packing/covering conjectures in ZFC, using two self-dual partitional matroids on a countably infinite ground set. The same examples answer Joó’s partitional-matroid question negatively. They are neither finitary nor cofinitary, so Nash-Williams’ original finitary conjecture remains outside the result.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1935,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Counterexample to the Infinite Matroid Packing/Covering Conjecture","href":"preprints/A-Counterexample-to-the-Infinite-Matroid-Packing-Covering-Conjecture-September-24-2026/paper.pdf"}],"plainFr":"Un matroïde abstrait les familles indépendantes, à la façon de vecteurs sans relation. Le manuscrit affirme que, sur un ensemble infini dénombrable, deux matroïdes partitionnels autoduals peuvent n'admettre ni témoin d'intersection ni partage entre paquetage et couverture.","plainEn":"A matroid abstracts independent families, in the manner of vectors with no relation. The manuscript asserts that, on a countably infinite set, two self-dual partitional matroids may admit neither an intersection witness nor a split between packing and covering.","expertFr":"Le manuscrit affirme, dans ZFC, deux matroïdes partitionnels autoduals sur un ensemble dénombrable, sans témoin d'intersection ni partition de paquetage et de couverture. Cela réfute les conjectures non restreintes, répond non à Joó, et laisse ouverte la conjecture finitaire de Nash-Williams, car les exemples ne sont ni finitaires ni cofinitaires.","expertEn":"The manuscript asserts, in ZFC, two self-dual partitional matroids on a countable set, with neither an intersection witness nor a packing and covering partition. This disproves the unrestricted conjectures, answers Joó in the negative, and leaves Nash-Williams' finitary conjecture open, since the examples are neither finitary nor cofinitary.","sparkFr":"L'intérêt est structurel, dans la théorie de l'indépendance sur des ensembles infinis.","sparkEn":"The interest is structural, in the theory of independence on infinite sets."},{"id":"186","titleEn":"Uniform influence and sharp thresholds for graph and hypergraph properties","titleFr":"Influence uniforme et seuils nets des propriétés de graphes","claim":"Proves the Friedgut–Kalai threshold-width conjectures for graphs and fixed-uniformity hypergraphs. For fixed 0 ε 1/2, every nontrivial increasing relabeling-invariant property crosses from probability ε to 1-ε within width O(( n)^-2) for graphs and O_r(( n)^-r/(r-1)) for r-uniform hypergraphs, r ≥ 3. The hypergraph influence bound also applies to nonmonotone properties.","nature":"combinatoire","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A uniform influence bound for hypergraph properties","href":"preprints/A-uniform-influence-bound-for-hypergraph-properties-October-5-2026/hypergraph-influences.pdf"},{"title":"A Sharp Threshold Bound for Monotone Graph Properties","href":"preprints/A-Sharp-Threshold-Bound-for-Monotone-Graph-Properties-September-25-2026/paper.pdf"}],"plainFr":"Une propriété croissante de graphes, une fois vraie, le reste si l'on ajoute des arêtes, et elle ignore les noms des sommets. Le manuscrit affirme que sa probabilité passe d'une petite valeur à une valeur proche de un dans une fenêtre très étroite, quand le graphe aléatoire se densifie.","plainEn":"An increasing graph property, once true, stays true if edges are added, and it ignores the names of the vertices. The manuscript asserts that its probability passes from a small value to a value near one inside a very narrow window, as the random graph grows denser.","expertFr":"Le manuscrit affirme les conjectures de largeur de seuil de Friedgut et Kalai : une propriété croissante invariante par réétiquetage passe d'une probabilité epsilon à son complément dans une fenêtre de l'ordre de l'inverse d'un facteur en n, à la puissance 2 pour les graphes et r sur r moins 1 pour les hypergraphes. La borne d'influence hypergraphique vaut aussi sans monotonie, uniformément en la densité.","expertEn":"The manuscript asserts the threshold-width conjectures of Friedgut and Kalai: an increasing relabeling-invariant property passes from a probability epsilon to its complement in a window on the order of the reciprocal of a factor in n, to the power 2 for graphs and r over r minus 1 for hypergraphs. The hypergraph influence bound also holds without monotonicity, uniformly in the density.","sparkFr":"Cela pourrait intéresser qui voit un trait de réseau aléatoire apparaître d'un coup ; aucune expérience n'est décrite.","sparkEn":"It might interest someone watching a random-network feature appear all at once; no experiment is described."},{"id":"187","titleEn":"Snaky in 21 Maker moves","titleFr":"Snaky en vingt et un coups de Maker","claim":"Settles the Snaky achievement problem: Maker can force the six-cell Snaky shape within 21 of its own moves on the initially empty infinite square board. Maker moves first, each player claims one free cell per turn, and translations, rotations and reflections count as wins.","nature":"algebre","domain":"structures","complexity":"lecture","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Snaky in 21 Maker moves","href":"preprints/Snaky-in-21-Maker-moves-September-25-2026/article.pdf"}],"plainFr":"Snaky est une forme de six cases, et deux joueurs réclament tour à tour une case libre d'un damier. Le manuscrit affirme que le premier, Maker, peut forcer cette forme, à rotation ou retournement près, en au plus vingt et un de ses propres coups sur le damier infini.","plainEn":"Snaky is a six-cell shape, and two players take turns claiming a free cell of a board. The manuscript asserts that the first player, Maker, can force this shape, up to rotation or reflection, within at most twenty-one of that player's own moves on the infinite board.","expertFr":"Le manuscrit affirme que Maker force l'hexomino Snaky en au plus 21 de ses coups, contre tout jeu légal de Breaker, sur le damier carré infini initialement vide ; translations, rotations et réflexions comptent comme succès. La même borne vaut sur un carré de côté 17, et Maker peut confiner ses cases à un damier fixé de 251 cases.","expertEn":"The manuscript asserts that Maker forces the Snaky hexomino within at most 21 of Maker's moves, against any legal play by Breaker, on the initially empty infinite square board; translations, rotations and reflections count as success. The same bound holds on a square of side 17, and Maker can confine the claimed cells to a fixed board of 251 cells.","sparkFr":"Quelqu'un qui joue à réclamer des cases sur un damier pourrait y regarder ; aucune partie réelle n'est commentée.","sparkEn":"Someone playing at claiming cells on a board might look; no real match is discussed."},{"id":"188","titleEn":"The sharp terminal leave in random triangle removal","titleFr":"Reliquat terminal de la suppression aléatoire de triangles","claim":"Starting from the complete graph on n vertices, repeatedly delete a uniformly chosen remaining triangle. The terminal edge count is asymptotic to n^3/2/(2 2), with mean-square convergence after normalization by n3/2. This proves the triangle case of the Joos–Kühn sharp-constant conjecture.","nature":"logique","domain":"hasard","complexity":"avance","problemYear":1927,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The sharp terminal leave in random triangle removal","href":"preprints/The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026/The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026.pdf"}],"plainFr":"On part du graphe où tous les sommets sont reliés, puis l'on retire les trois arêtes d'un triangle encore présent, choisi au hasard, jusqu'à épuisement. Le manuscrit affirme que le nombre d'arêtes restantes suit une puissance trois demis du nombre de sommets, à une constante nette près.","plainEn":"One starts from the graph in which all vertices are joined, then deletes the three edges of a still present triangle, chosen at random, until none remain. The manuscript asserts that the number of edges left follows a three-halves power of the number of vertices, up to a sharp constant.","expertFr":"Le manuscrit affirme que, dans cette suppression uniforme répétée sur le graphe complet à n sommets, le nombre d'arêtes restantes divisé par n puissance 3/2 converge en moyenne quadratique vers la constante écrite dans le résumé. Cela prouve le cas des triangles de la conjecture de constante nette de Joos et Kühn, y compris la convergence en probabilité et celle de l'espérance normalisée.","expertEn":"The manuscript asserts that, in this repeated uniform removal on the complete graph on n vertices, the number of edges left divided by n to the power 3/2 converges in mean square to the constant written in the abstract. This proves the triangle case of the sharp-constant conjecture of Joos and Kühn, including convergence in probability and that of the normalized expectation.","sparkFr":"Cela pourrait intéresser qui suit ce qu'il reste après le retrait de triangles au hasard ; aucune expérience n'est faite.","sparkEn":"It might interest someone tracking what remains after random triangles are removed; no experiment is run."},{"id":"189","titleEn":"Cycle–clique Ramsey numbers","titleFr":"Nombres de Ramsey des cycles et des cliques","claim":"Proves the Erdős–Faudree–Rousseau–Schelp conjecture: R(C_m,K_n)=(m-1)(n-1)+1 for every m≥ n≥3, except R(C_3,K_3)=6. This is the exact threshold forcing a red m-cycle or a blue n-clique in every red–blue coloring of a complete graph.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1946,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Cycle--clique Ramsey numbers","href":"preprints/Cycle-clique-Ramsey-numbers-September-25-2026/Cycle-clique-Ramsey-numbers-September-25-2026.pdf"}],"plainFr":"Dans une coloration rouge et bleue de toutes les arêtes, on cherche un cycle rouge ou une clique bleue. Le manuscrit affirme le seuil exact qui force l'un ou l'autre, dès que le cycle est au moins aussi long que la clique, sauf le petit cas de taille trois.","plainEn":"In a red and blue coloring of all the edges, one looks for a red cycle or a blue clique. The manuscript asserts the exact threshold that forces one or the other, once the cycle is at least as long as the clique, except the small case of size three.","expertFr":"Le manuscrit affirme que le nombre de Ramsey du cycle de longueur m contre la clique de taille n vaut (m-1)(n-1)+1 pour tous les entiers m au moins n au moins 3, sauf le cas m = n = 3, où il vaut 6. La preuve réduit les cas restants à 3099 motifs finis de paramètres, exclus par deux mises en œuvre exactes de règles d'inférence déjà prouvées, avec programmes et traces de déduction.","expertEn":"The manuscript asserts that the Ramsey number of the cycle of length m against the clique of size n equals (m-1)(n-1)+1 for all integers m at least n at least 3, except the case m = n = 3, where it equals 6. The proof reduces the remaining cases to 3099 finite parameter patterns, excluded by two exact implementations of already proved inference rules, with programs and deduction traces.","sparkFr":"Quelqu'un qui colore les arêtes pour forcer un cycle ou une clique pourrait y regarder ; aucun coloriage dessiné n'est joint.","sparkEn":"Someone coloring edges to force a cycle or a clique might look; no drawn coloring is attached."},{"id":"190","titleEn":"Polynomial removal fails for ordered binary matrices","titleFr":"L'élimination polynomiale échoue pour les matrices binaires ordonnées","claim":"Disproves polynomial ordered binary matrix removal with one fixed 66×66 zero–one pattern. Matrices can require many binary-entry changes to become pattern-free while their copy density is smaller than every proposed polynomial bound in that distance. Copies preserve row and column orders and match both zeros and ones.","nature":"algebre","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Polynomial removal fails for ordered binary matrices","href":"preprints/Polynomial-removal-fails-for-ordered-binary-matrices-September-25-2026/paper.pdf"}],"plainFr":"Une matrice binaire ordonnée est un tableau de zéros et de uns, et une copie en respecte l'ordre des lignes et des colonnes. Le manuscrit affirme qu'un motif fixe de 66 lignes et 66 colonnes peut rester très rare tout en exigeant trop de changements d'entrées pour toute borne polynomiale proposée.","plainEn":"An ordered binary matrix is a table of zeros and ones, and a copy respects the order of the rows and of the columns. The manuscript asserts that a fixed pattern of 66 rows and 66 columns can stay very rare while demanding too many entry changes for every proposed polynomial bound.","expertFr":"Le manuscrit affirme qu'une matrice binaire fixe de taille 66 par 66 n'admet aucune borne polynomiale d'élimination ordonnée. On peut devoir changer beaucoup d'entrées, dans les deux sens, pour effacer toute copie respectant les ordres des lignes et des colonnes, alors que la densité de ces copies est plus petite que toute borne polynomiale en cette distance.","expertEn":"The manuscript asserts that a fixed binary matrix of size 66 by 66 admits no polynomial bound for ordered removal. One may have to change many entries, in either direction, to erase every copy that respects row and column orders, while the density of those copies is smaller than every polynomial bound in that distance.","sparkFr":"L'intérêt est structurel, autour du coût pour effacer un motif dans un tableau de zéros et de uns.","sparkEn":"The interest is structural, around the cost of erasing a pattern in a table of zeros and ones."},{"id":"191","titleEn":"A power improvement in the Heilbronn triangle lower bound","titleFr":"Un gain de puissance pour le triangle de Heilbronn","claim":"For every sufficiently large n, constructs n points in the unit square such that every triangle has area at least n^-2+c for one absolute c > 0. This disproves the conjectured almost-n−2 upper bound in Heilbronn's triangle problem, which asks how large the smallest determined triangle can be.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A power improvement in the Heilbronn triangle lower bound","href":"preprints/A-power-improvement-in-the-Heilbronn-triangle-lower-bound-September-25-2026/main.pdf"}],"plainFr":"Le problème de Heilbronn demande de placer des points dans un carré afin que le plus petit triangle formé soit aussi grand que possible. Le manuscrit affirme que, pour tout nombre de points assez grand, une aire au moins égale à une puissance un peu meilleure que l'inverse du carré est possible.","plainEn":"Heilbronn's problem asks how to place points in a square so that the smallest triangle formed is as large as possible. The manuscript asserts that, for every large enough number of points, an area at least a power slightly better than the reciprocal of the square is possible.","expertFr":"Pour tout n assez grand, le manuscrit affirme n points du carré unité dont tout triangle déterminé a une aire au moins égale à n élevé à la puissance moins 2 plus une constante absolue strictement positive. Le résumé donne deux constantes absolues positives, l'exposant de gain étant fixé mais extrêmement petit, et réfute ainsi la majoration presque par l'inverse du carré de n.","expertEn":"For every large enough n, the manuscript asserts n points of the unit square such that every triangle they determine has area at least n raised to the power minus 2 plus an absolute constant strictly positive. The abstract gives two positive absolute constants, the saving exponent being fixed but extremely small, and thus disproves the near-bound by the reciprocal of the square of n.","sparkFr":"Cela pourrait intéresser qui espace des points dans un carré pour éviter un triangle trop plat ; aucun placement chiffré n'est donné.","sparkEn":"It might interest someone spacing points in a square to avoid a too-flat triangle; no numerical placement is given."},{"id":"192","titleEn":"Boolean functions violate the square-root degree bound by arbitrary factors","titleFr":"Fonctions booléennes hors de la borne en racine carrée","claim":"Disproves the proposed square-root bound relating a Boolean function's linear Fourier coefficients to its polynomial degree. For every C > 0, there is a sign-valued Boolean function f with _i f(\\i\\) C√( (f)). Thus its total signed correlation with individual input bits can exceed the proposed bound by an arbitrary factor.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"Unbounded Violations of the Square-Root Degree Bound","href":"preprints/Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026/Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026.pdf"}],"plainFr":"Une fonction booléenne attribue un signe à chaque combinaison de bits, et son degré mesure la complexité du polynôme qui la représente. Le manuscrit affirme que sa corrélation totale avec les bits pris un à un peut dépasser, d'un facteur arbitraire, la borne en racine carrée du degré proposée par Gopalan et Servedio.","plainEn":"A Boolean function assigns a sign to every combination of bits, and its degree measures how complex the representing polynomial is. The manuscript asserts that the total correlation with individual bits can exceed, by an arbitrary factor, the square-root-of-degree bound proposed by Gopalan and Servedio.","expertFr":"Le manuscrit affirme réfuter la conjecture de racine carrée de Gopalan–Servedio, même à un facteur constant arbitraire. Pour tout réel positif, il existe une fonction booléenne non constante à valeurs de signe dont la somme des valeurs absolues des coefficients de Fourier linéaires dépasse ce facteur fois la racine carrée du degré multilinéaire.","expertEn":"The manuscript asserts a disproof of the Gopalan–Servedio square-root conjecture, even up to an arbitrary constant factor. For every positive real number there is a nonconstant sign-valued Boolean function whose sum of absolute linear Fourier coefficients exceeds that factor times the square root of the multilinear degree.","sparkFr":"La piste reste interne à l'analyse de Fourier discrète, et le manuscrit ne revendique aucun usage hors des mathématiques.","sparkEn":"The lead stays inside discrete Fourier analysis, and the manuscript claims no use outside mathematics."},{"id":"193","titleEn":"Serre’s intersection-multiplicity conjecture","titleFr":"Positivité de la multiplicité d'intersection de Serre","claim":"Proves strict positivity of Serre's intersection multiplicity ^R(M,N) for nonzero finitely generated modules over any regular local ring, provided M _R N has finite length and M+ N= R. This resolves the positivity conjecture, including ramified mixed characteristic.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1955,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Positivity of Serre's Intersection Multiplicity","href":"preprints/Positivity-of-Serres-Intersection-Multiplicity-September-23-2026/paper.pdf"}],"plainFr":"Lorsque deux modules se croisent dans un anneau local régulier, la multiplicité de Serre en compte l'intersection. Le manuscrit affirme qu'elle est strictement positive si les dimensions se complètent et si le produit a une longueur finie, y compris en caractéristique mixte ramifiée.","plainEn":"When two modules meet inside a regular local ring, Serre's multiplicity offers an algebraic count of their intersection. The manuscript asserts that this number is strictly positive whenever the dimensions are complementary and the tensor product has finite length, including in ramified mixed characteristic.","expertFr":"Le manuscrit affirme la conjecture de positivité de Serre pour tout anneau local régulier, ramification mixte comprise. Si deux modules non nuls de type fini ont un produit tensoriel de longueur finie et des dimensions complémentaires, leur multiplicité d'intersection est strictement positive.","expertEn":"The manuscript asserts Serre's positivity conjecture for every regular local ring, including ramified mixed characteristic. If two nonzero finitely generated modules have tensor product of finite length and complementary dimensions, their intersection multiplicity is strictly positive.","sparkFr":"L'intérêt est structurel en algèbre commutative, et aucune passerelle hors des mathématiques n'est affirmée.","sparkEn":"The interest is structural in commutative algebra, and no bridge outside mathematics is asserted."},{"id":"194","titleEn":"Lech’s multiplicity conjecture","titleFr":"La conjecture de multiplicité de Lech","claim":"Proves e(R)≤ e(S) for every flat local homomorphism of nonzero Noetherian local rings, where e is Hilbert–Samuel multiplicity. This resolves Lech's conjecture in every dimension and characteristic.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Lech's multiplicity conjecture","href":"preprints/Lechs-multiplicity-conjecture-September-23-2026/paper.pdf"}],"plainFr":"La multiplicité de Hilbert–Samuel mesure la taille asymptotique d'un anneau local noethérien. Le manuscrit affirme qu'elle ne peut pas diminuer le long d'un homomorphisme local plat entre anneaux locaux noethériens non nuls, en toute dimension et toute caractéristique.","plainEn":"Hilbert–Samuel multiplicity measures the asymptotic size of a Noetherian local ring. The manuscript asserts that it cannot decrease along a flat local homomorphism of nonzero Noetherian local rings, in every dimension and every characteristic.","expertFr":"Le manuscrit affirme que la multiplicité de Hilbert–Samuel de la source est au plus celle du but, pour tout homomorphisme local plat d'anneaux locaux noethériens non nuls. Le résultat vaut en dimension arbitraire, sans restriction sur les corps résiduels ni les caractéristiques.","expertEn":"The manuscript asserts that the Hilbert–Samuel multiplicity of the source is at most that of the target, for every flat local homomorphism of nonzero Noetherian local rings. The result holds in arbitrary dimension, with no restriction on residue fields or characteristics.","sparkFr":"La piste reste interne à la théorie des multiplicités, sans usage appliqué revendiqué par le manuscrit.","sparkEn":"The lead stays inside multiplicity theory, with no applied use claimed by the manuscript."},{"id":"195","titleEn":"A counterexample to the small Cohen–Macaulay module conjecture","titleFr":"Contre-exemple au petit module de Cohen–Macaulay","claim":"Constructs a three-dimensional complete Noetherian normal local domain over ℂ with no nonzero finitely generated maximal Cohen–Macaulay module. A three-dimensional local domain essentially of finite type over ℂ has the same property, disproving the domain form of the small Cohen–Macaulay module conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1921,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A Complete Local Domain without a Small Cohen–Macaulay Module","href":"preprints/A-Complete-Local-Domain-Without-a-Small-Cohen-Macaulay-Module-September-23-2026/paper.pdf"}],"plainFr":"Un module de Cohen–Macaulay maximal est un objet aussi régulier que son anneau le permet. Le manuscrit affirme un domaine local normal complet de dimension trois sur les complexes, sans aucun tel module non nul de type fini, et un domaine de type essentiellement fini avec le même défaut.","plainEn":"A maximal Cohen–Macaulay module is an algebraic object as regular as its ring allows. The manuscript asserts a three-dimensional complete normal local domain containing the complex numbers with no nonzero finitely generated example, and a domain essentially of finite type over the complexes with the same failure.","expertFr":"Le manuscrit affirme un domaine local noethérien normal complet de dimension trois, de corps résiduel les complexes, sans module de Cohen–Macaulay maximal non nul de type fini. Un domaine local de dimension trois essentiellement de type fini sur les complexes a la même propriété, ce qui réfute la forme domaine de la petite conjecture.","expertEn":"The manuscript asserts a three-dimensional complete Noetherian normal local domain over the complexes, with residue field the complexes, and no nonzero finitely generated maximal Cohen–Macaulay module. A three-dimensional local domain essentially of finite type over the complexes has the same property, disproving the domain form of the small conjecture.","sparkFr":"L'intérêt est structurel en algèbre commutative, et le manuscrit n'affirme aucun usage hors de ce cadre.","sparkEn":"The interest is structural in commutative algebra, and the manuscript asserts no use outside that frame."},{"id":"196","titleEn":"A counterexample to Kaplansky’s zero-divisor conjecture","titleFr":"Contre-exemple aux diviseurs de zéro de Kaplansky","claim":"Constructs a finitely presented torsion-free group G whose group algebra F_2[G] has nonzero zero divisors, disproving Kaplansky's zero-divisor conjecture. The group has a finite two-dimensional classifying space.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1970,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A Torsion-Free Group Algebra with Zero Divisors","href":"preprints/A-Torsion-Free-Group-Algebra-with-Zero-Divisors-September-23-2026/paper.pdf"}],"plainFr":"L'algèbre d'un groupe rassemble les combinaisons finies de ses éléments. Le manuscrit affirme qu'un groupe sans torsion, finiment présenté, à espace classifiant fini de dimension deux, peut pourtant y avoir des diviseurs de zéro non nuls sur le corps à deux éléments.","plainEn":"A group algebra over a field gathers finite combinations of group elements, with a natural multiplication. The manuscript asserts that a finitely presented torsion-free group with a finite two-dimensional classifying space can still produce nonzero zero-divisors over the two-element field.","expertFr":"Le manuscrit affirme un groupe de présentation finie et sans torsion dont l'algèbre sur le corps à deux éléments possède des diviseurs de zéro non nuls, ce qui réfute la conjecture de Kaplansky. Ce groupe admet un espace classifiant fini de dimension deux.","expertEn":"The manuscript asserts a finitely presented torsion-free group whose algebra over the two-element field has nonzero zero-divisors, disproving Kaplansky's zero-divisor conjecture. The group admits a finite two-dimensional classifying space.","sparkFr":"La piste est interne à l'algèbre des groupes, et aucun usage hors des mathématiques n'est revendiqué.","sparkEn":"The lead is internal to group algebras, and no use outside mathematics is claimed."},{"id":"197","titleEn":"A torsion-free group algebra that is not directly finite","titleFr":"Algèbre de groupe sans torsion non directement finie","claim":"Constructs a finitely presented torsion-free nonsofic group whose group algebra over 𝔽2 is not directly finite, disproving Kaplansky's conjecture even without torsion. Companion examples give injective nonsurjective cellular automata on all configurations, refuting Gottschalk's surjunctivity conjecture. Another counterexample is an integral group-ring matrix, invertible over the rational group ring, with Fuglede–Kadison determinant strictly between zero and one, disproving the unrestricted Determinant Conjecture.","nature":"algebre","domain":"calcul","complexity":"avance","problemYear":1970,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A Torsion-Free Group Algebra That Is Not Directly Finite","href":"preprints/A-Torsion-Free-Group-Algebra-That-Is-Not-Directly-Finite-October-4-2026/direct-finiteness.pdf"},{"title":"A Counterexample to Kaplansky's Direct-Finiteness Conjecture in Characteristic Two","href":"preprints/A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Characteristic-Two-September-23-2026/paper.pdf"},{"title":"A Counterexample to the Group-Ring Determinant Conjecture","href":"preprints/A-Counterexample-to-the-Group-Ring-Determinant-Conjecture-September-23-2026/paper.pdf"},{"title":"A Counterexample to Kaplansky's Direct-Finiteness Conjecture in Odd Characteristic","href":"preprints/A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Odd-Characteristic-September-26-2026/paper.pdf"}],"plainFr":"Une algèbre est directement finie si tout inverse d'un côté l'est des deux. Le manuscrit affirme qu'un groupe sans torsion, finiment présenté et non sofique, échoue à cela sur le corps à deux éléments, avec des contre-exemples voisins pour des automates et un déterminant.","plainEn":"An algebra is directly finite when every one-sided inverse is automatically two-sided. The manuscript asserts a finitely presented torsion-free nonsofic group whose algebra over the two-element field fails this, with companion counterexamples for automata and for a determinant.","expertFr":"Le manuscrit affirme un groupe sans torsion, de présentation finie et non sofique, à complexe classifiant fini de dimension deux, dont l'algèbre sur le corps à deux éléments n'est pas directement finie. Il affirme aussi des automates cellulaires injectifs non surjectifs, et une matrice entière de groupe, inversible sur l'anneau rationnel, de déterminant de Fuglede–Kadison strictement entre zéro et un.","expertEn":"The manuscript asserts a finitely presented torsion-free nonsofic group, with a finite two-dimensional classifying complex, whose algebra over the two-element field is not directly finite. It also asserts injective nonsurjective cellular automata, and an integral group-ring matrix, invertible over the rational group ring, with Fuglede–Kadison determinant strictly between zero and one.","sparkFr":"L'intérêt annoncé reste structurel, entre algèbres de groupes et automates, sans déploiement affirmé.","sparkEn":"The stated interest stays structural, between group algebras and automata, with no deployment asserted."},{"id":"198","titleEn":"A counterexample to finitistic-dimension finiteness","titleFr":"Contre-exemple à la finitude de la dimension finitiste","claim":"Constructs a finite-dimensional complex algebra whose finite-dimensional modules have unbounded finite projective dimensions. This disproves the little finitistic-dimension conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An algebra of infinite little finitistic dimension","href":"preprints/An-algebra-of-infinite-little-finitistic-dimension-September-23-2026/paper.pdf"}],"plainFr":"La dimension projective compte les étapes nécessaires pour reconstruire un module à partir de modules libres. Le manuscrit affirme qu'une algèbre de dimension finie sur les complexes peut avoir des modules de dimension finie dont ces dimensions projectives finies ne sont pas bornées.","plainEn":"Projective dimension counts the steps needed to rebuild a module from free modules. The manuscript asserts a finite-dimensional algebra over the complex numbers whose finite-dimensional modules have unbounded finite projective dimensions.","expertFr":"Le manuscrit affirme une algèbre de dimension finie sur les complexes dont les modules de dimension finie ont des dimensions projectives finies non bornées. Cela réfute la petite conjecture de dimension finitiste.","expertEn":"The manuscript asserts a finite-dimensional algebra over the complexes whose finite-dimensional modules have unbounded finite projective dimensions. This disproves the little finitistic-dimension conjecture.","sparkFr":"L'intérêt est structurel en algèbre homologique, et le manuscrit n'affirme aucun usage extérieur.","sparkEn":"The interest is structural in homological algebra, and the manuscript asserts no outside use."},{"id":"199","titleEn":"Counterexamples to Auslander–Reiten, Tachikawa and related homological conjectures","titleFr":"Contre-exemples à Auslander–Reiten, Tachikawa et Nakayama","claim":"Constructs finite-dimensional algebras over a characteristic-two rational-function field that disprove the Auslander–Reiten and Gorenstein-projective conjectures, and Tachikawa's second conjecture. An associated endomorphism algebra also disproves the classical, generalized and strong Nakayama conjectures, the Auslander–Gorenstein conjecture, and the Wakamatsu tilting conjecture. The counterexamples persist under every extension of the base field.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An explicit counterexample to the Auslander-Reiten conjecture","href":"preprints/An-explicit-counterexample-to-the-Auslander-Reiten-conjecture-September-23-2026/paper.pdf"},{"title":"A counterexample to Tachikawa's second conjecture","href":"preprints/A-counterexample-to-Tachikawas-second-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Certaines conjectures lient la projectivité d'un module à la disparition de ses extensions. Le manuscrit affirme des algèbres de dimension finie, en caractéristique deux, qui en réfutent plusieurs, formes de Nakayama comprises, et qui survivent à toute extension du corps.","plainEn":"Some conjectures tie the projectivity of a module to the vanishing of its extensions. The manuscript asserts finite-dimensional algebras in characteristic two that refute several such statements, including forms of Nakayama's conjecture, and that the counterexamples survive every extension of the base field.","expertFr":"Le manuscrit affirme réfuter, en caractéristique deux, Auslander–Reiten, la projectivité de Gorenstein et la seconde conjecture de Tachikawa, via un module dont les extensions positives avec lui-même et l'algèbre s'annulent. Une algèbre d'endomorphismes réfute aussi trois formes de Nakayama, Auslander–Gorenstein et Wakamatsu, après toute extension du corps.","expertEn":"The manuscript asserts a disproof, in characteristic two, of Auslander–Reiten, Gorenstein projectivity and Tachikawa's second conjecture, via a module whose positive extensions against itself and the algebra vanish. An endomorphism algebra also disproves three forms of Nakayama, Auslander–Gorenstein and Wakamatsu tilting, after every base-field extension.","sparkFr":"L'intérêt est structurel pour les algèbres d'Artin, sans application hors des mathématiques affirmée.","sparkEn":"The interest is structural for Artin algebras, with no application outside mathematics asserted."},{"id":"200","titleEn":"Eisenbud–Green–Harris and lex-plus-powers","titleFr":"Eisenbud–Green–Harris et les idéaux lex-plus-puissances","claim":"Proves the Eisenbud–Green–Harris and lex-plus-powers conjectures over every characteristic-zero field. Any homogeneous ideal containing a regular sequence, of arbitrary length and degrees at least two, admits a lex-plus-powers ideal with the same Hilbert function and no smaller graded Betti numbers.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Artinian Lex-Plus-Powers Betti Theorem","href":"preprints/The-Artinian-Lex-Plus-Powers-Betti-Theorem-September-23-2026/paper.pdf"},{"title":"Commuting Division-Coefficient Forms and the Artinian Eisenbud--Green--Harris Conjecture","href":"preprints/Commuting-Division-Coefficient-Forms-and-the-Artinian-Eisenbud-Green-Harris-Conjecture-September-23-2026/paper.pdf"}],"plainFr":"La fonction de Hilbert d'un idéal homogène mesure, degré par degré, la taille du quotient. Le manuscrit affirme qu'en caractéristique nulle, un idéal contenant une suite régulière de degrés au moins deux admet un idéal lex-plus-puissances de même fonction et de nombres de Betti pas plus petits.","plainEn":"The Hilbert function of a homogeneous ideal measures, degree by degree, the size of the quotient. The manuscript asserts that in characteristic zero, an ideal containing a regular sequence of degrees at least two admits a lex-plus-powers ideal with the same function and no smaller Betti numbers.","expertFr":"Le manuscrit affirme les conjectures d'Eisenbud–Green–Harris et lex-plus-puissances sur tout corps de caractéristique nulle, pour des suites régulières homogènes de longueur positive quelconque et de degrés au moins deux. L'idéal lex-plus-puissances correspondant a la même fonction de Hilbert et un nombre de Betti gradué au moins aussi grand en chaque degré homologique et interne.","expertEn":"The manuscript asserts the Eisenbud–Green–Harris and lex-plus-powers conjectures over every characteristic-zero field, for homogeneous regular sequences of any positive length and degrees at least two. The corresponding lex-plus-powers ideal has the same Hilbert function and at least as large a graded Betti number in every homological and internal degree.","sparkFr":"La piste reste dans la combinatoire des idéaux homogènes, et le manuscrit n'affirme pas d'usage extérieur.","sparkEn":"The lead stays in the combinatorics of homogeneous ideals, and the manuscript asserts no outside use."},{"id":"201","titleEn":"A counterexample to Kurosh’s division-ring problem","titleFr":"Contre-exemple au problème des corps gauches de Kurosh","claim":"Constructs a countable characteristic-zero division ring that is algebraic over its center and generated by two elements over that center, but has infinite dimension over it. This answers Kurosh's division-ring problem on local finiteness negatively.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1941,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A Counterexample to Kurosh’s Division-Ring Problem","href":"preprints/A-Counterexample-to-Kuroshs-Division-Ring-Problem-September-23-2026/paper.pdf"}],"plainFr":"Un corps gauche permet la division, mais pas forcément la commutation des produits. Le manuscrit affirme un exemple dénombrable de caractéristique nulle, algébrique sur son centre et engendré par deux éléments au-dessus de ce centre, mais de dimension infinie sur lui.","plainEn":"A division ring allows division, but not necessarily commutation of products. The manuscript asserts a countable example of characteristic zero that is algebraic over its center and generated by two elements over that center, yet infinite-dimensional over it.","expertFr":"Le manuscrit affirme un corps gauche dénombrable de caractéristique nulle, algébrique sur son centre, engendré par deux éléments comme algèbre sur ce centre, et de dimension infinie sur lui. Cela répond négativement au problème de Kurosh sur la finitude locale des corps gauches.","expertEn":"The manuscript asserts a countable division ring of characteristic zero, algebraic over its center, generated by two elements as an algebra over that center, and infinite-dimensional over it. This answers Kurosh's problem on local finiteness of division rings in the negative.","sparkFr":"L'intérêt est structurel en algèbre non commutative, sans pont hors des mathématiques affirmé.","sparkEn":"The interest is structural in noncommutative algebra, with no bridge outside mathematics asserted."},{"id":"202","titleEn":"The blockwise Alperin weight conjecture","titleFr":"La conjecture des poids d'Alperin, bloc par bloc","claim":"Proves the numerical blockwise Alperin weight conjecture for every prime and every finite group: the number of irreducible Brauer characters in a block equals the number of conjugacy classes of its weights.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1929,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Blockwise Alperin Weight Conjecture","href":"preprints/The-Blockwise-Alperin-Weight-Conjecture-September-23-2026/paper.pdf"}],"plainFr":"Dans la théorie des représentations des groupes finis en caractéristique positive, un bloc regroupe certaines représentations. Le manuscrit affirme que, pour tout nombre premier et tout groupe fini, le nombre de caractères de Brauer irréductibles d'un bloc égale le nombre de classes de conjugaison de ses poids.","plainEn":"In the representation theory of finite groups in positive characteristic, a block groups certain representations together. The manuscript asserts that, for every prime and every finite group, the number of irreducible Brauer characters in a block equals the number of conjugacy classes of its weights.","expertFr":"Le manuscrit affirme la forme numérique de la conjecture des poids d'Alperin, bloc par bloc, pour tout groupe fini et tout premier. Pour chaque bloc, le nombre de caractères de Brauer irréductibles égale le nombre de classes de conjugaison de poids de ce bloc.","expertEn":"The manuscript asserts the numerical blockwise Alperin weight conjecture for every finite group and every prime. For each block, the number of irreducible Brauer characters equals the number of conjugacy classes of weights of that block.","sparkFr":"La piste reste interne à la théorie modulaire des groupes finis, sans usage extérieur revendiqué.","sparkEn":"The lead stays inside modular representation theory of finite groups, with no outside use claimed."},{"id":"203","titleEn":"Donovan's conjecture over fields and complete mixed-characteristic DVRs","titleFr":"La conjecture de Donovan sur les blocs de groupes finis","claim":"Proves Donovan's conjecture: over each fixed algebraically closed field of characteristic p, blocks of finite groups with bounded defect-group order have only finitely many Morita-equivalence classes, for every prime p. Also proves the integral form over each fixed complete mixed-characteristic discrete valuation ring with algebraically closed residue field.","nature":"algebre","domain":"nombres","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Donovan's Conjecture over Algebraically Closed Fields","href":"preprints/Donovans-Conjecture-over-Algebraic-Closures-of-Prime-Fields-September-24-2026/main.pdf"},{"title":"Integral Donovan Finiteness over Witt Vectors","href":"preprints/Integral-Donovan-Finiteness-over-Witt-Vectors-September-25-2026/main.pdf"}],"plainFr":"Deux blocs de groupes finis sont équivalents au sens de Morita lorsqu'ils ont la même théorie des modules. Le manuscrit affirme qu'à corps algébriquement clos et ordre du groupe de défaut borné, il n'y a qu'un nombre fini de telles classes pour tout premier, ainsi qu'une forme entière sur certains anneaux de valuation.","plainEn":"Two blocks of finite groups are Morita equivalent when they have the same module theory. The manuscript asserts that, over an algebraically closed field and for bounded defect-group order, only finitely many such classes occur for every prime, together with an integral form over certain valuation rings.","expertFr":"Le manuscrit affirme la conjecture de Donovan : sur chaque corps algébriquement clos de caractéristique positive, les blocs d'ordre de défaut borné ne forment qu'un nombre fini de classes de Morita, y compris pour le premier deux et sans hypothèse d'abélianité. Il affirme aussi la forme entière sur chaque anneau de valuation discrète complet de caractéristique mixte à corps résiduel algébriquement clos.","expertEn":"The manuscript asserts Donovan's conjecture: over each algebraically closed field of positive characteristic, blocks of bounded defect order form only finitely many Morita classes, including the prime two and with no abelian hypothesis. It also asserts the integral form over each complete mixed-characteristic discrete valuation ring with algebraically closed residue field.","sparkFr":"L'intérêt est structurel en théorie des blocs, et le manuscrit n'affirme aucun déploiement.","sparkEn":"The interest is structural in block theory, and the manuscript asserts no deployment."},{"id":"204","titleEn":"Tensor saturation for even spin groups","titleFr":"Saturation tensorielle pour les groupes de spin pairs","claim":"Proves saturation factor one for Spin (2n), n ≥ 2: for three dominant integral weights whose sum lies in the root lattice, an invariant at any common positive integral dilation already gives an invariant at the original weights. This resolves the type-D part of the simply-laced saturation conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Tensor saturation for even spin groups","href":"preprints/Tensor-Saturation-for-Even-Spin-Groups-September-24-2026/Tensor-Saturation-for-Even-Spin-Groups-September-24-2026.pdf"}],"plainFr":"Un invariant tensoriel combine trois représentations d'un groupe de spin en un scalaire. Le manuscrit affirme que, pour les spins pairs de rang au moins deux, un invariant après dilatation entière commune en donne déjà un aux poids d'origine si leur somme est dans le réseau des racines.","plainEn":"A tensor invariant combines three representations of a spin group into a scalar. The manuscript asserts that, for even spin groups of rank at least two, an invariant after any common integral dilation already yields one at the original weights, whenever their sum lies in the root lattice.","expertFr":"Le manuscrit affirme le facteur de saturation un pour les groupes de spin pairs de rang au moins deux. Si trois poids entiers dominants ont une somme dans le réseau des racines, un invariant tensoriel non nul après une dilatation entière positive commune implique un invariant aux poids d'origine, ce qui règle la partie de type D de la conjecture simplement lacée.","expertEn":"The manuscript asserts saturation factor one for even spin groups of rank at least two. If three dominant integral weights sum into the root lattice, a nonzero tensor invariant after a positive integral dilation yields one at the original weights, resolving the type-D part of the simply-laced saturation conjecture.","sparkFr":"La piste est interne à la théorie des représentations, sans application hors des mathématiques affirmée.","sparkEn":"The lead is internal to representation theory, with no application outside mathematics asserted."},{"id":"205","titleEn":"Saxl’s conjecture and universal tensor squares","titleFr":"La conjecture de Saxl et les carrés tensoriels","claim":"Proves Saxl's conjecture: the tensor square of every staircase representation contains every irreducible complex representation of the corresponding symmetric group. More generally, every Sn with n∉\\2,4,9\\ has an irreducible representation whose tensor square contains all irreducibles.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Universal Tensor Squares for Symmetric Groups","href":"preprints/Universal-Tensor-Squares-for-Symmetric-Groups-September-24-2026/main.pdf"},{"title":"A Cyclic Polytabloid Proof of Saxl's Conjecture","href":"preprints/A-Cyclic-Polytabloid-Proof-of-Saxls-Conjecture-September-24-2026/paper.pdf"}],"plainFr":"Le carré tensoriel d'une représentation la combine avec elle-même. Le manuscrit affirme que, hors de trois petites exceptions, une irréductible complexe du groupe symétrique a un carré contenant toutes les autres, et qu'il en va de même de chaque représentation en escalier.","plainEn":"The tensor square of a representation is that representation combined with itself. The manuscript asserts that, for the symmetric group outside three small exceptions, some irreducible complex representation has a square containing every irreducible, and that this holds for every staircase representation.","expertFr":"Le manuscrit affirme que le carré tensoriel de chaque représentation en escalier contient toute irréductible complexe du groupe symétrique correspondant. Plus généralement, hors des degrés deux, quatre et neuf, un groupe symétrique possède une irréductible dont le carré tensoriel contient toutes les irréductibles.","expertEn":"The manuscript asserts that the tensor square of every staircase representation contains every complex irreducible of the corresponding symmetric group. More generally, outside degrees two, four and nine, a symmetric group has an irreducible whose tensor square contains all irreducibles.","sparkFr":"L'intérêt reste structurel en théorie des représentations symétriques, sans usage extérieur revendiqué.","sparkEn":"The interest stays structural in symmetric representation theory, with no outside use claimed."},{"id":"206","titleEn":"Finite lattice representation and undecidability","titleFr":"Treillis finis de congruences et indécidabilité","claim":"Some finite lattices are not congruence lattices of any finite algebra, answering the finite lattice representation problem negatively. Moreover, no algorithm decides whether a finite lattice has such a representation, or whether it is a full subgroup interval of a finite group.","nature":"algebre","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Finite congruence lattices: characterization and undecidability","href":"preprints/Finite-Congruence-Lattices-Characterization-and-Undecidability-September-24-2026/paper.pdf"},{"title":"A negative solution to the finite lattice representation problem","href":"preprints/A-Negative-Solution-to-the-Finite-Lattice-Representation-Problem-September-24-2026/paper.pdf"}],"plainFr":"Le treillis des congruences d'une algèbre finie classe les identifications compatibles avec les opérations. Le manuscrit affirme que certains treillis finis n'en proviennent pas, et qu'aucun algorithme ne décide cela, ni si un treillis est un intervalle complet de sous-groupes d'un groupe fini.","plainEn":"The congruence lattice of a finite algebra organizes ways of identifying elements while respecting the operations. The manuscript asserts that some finite lattices arise from no finite algebra, and that no algorithm decides this property, nor whether a finite lattice is a full subgroup interval of a finite group.","expertFr":"Le manuscrit affirme une caractérisation par graphes colorés des treillis finis non vides qui sont treillis complets de congruences d'algèbres finies, et l'indécidabilité de cette représentation. Il affirme aussi l'indécidabilité de la reconnaissance des intervalles complets de sous-groupes dans les groupes finis, donc une réponse négative au problème de représentation.","expertEn":"The manuscript asserts a colored-graph characterization of the finite nonempty lattices that are full congruence lattices of finite algebras, and the undecidability of this representation. It also asserts that recognizing full subgroup intervals in finite groups is undecidable, hence a negative answer to the representation problem.","sparkFr":"Même si l'indécidabilité évoque le calcul, le manuscrit n'affirme qu'un fait de structure, sans procédure utilisable hors des mathématiques.","sparkEn":"Although undecidability evokes computation, the manuscript asserts only a structural fact, with no procedure claimed for use outside mathematics."},{"id":"207","titleEn":"The ℓ¹-Bass conjecture for all discrete groups","titleFr":"La conjecture de Bass en norme un pour les groupes discrets","claim":"Proves the ℓ1-Bass conjecture for every discrete group: Hattori–Stallings traces of idempotent matrices over ℓ^1(G) are supported on finitely many finite-order conjugacy classes. The algebraic companion proves the integral Bass trace conjecture and Kaplansky's idempotent conjecture for torsion-free groups over every commutative unital characteristic-zero domain.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1970,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The ℓ¹-Bass Conjecture for Discrete Groups","href":"preprints/The-l1-Bass-Conjecture-for-Discrete-Groups-October-5-2026/l1-bass-conjecture.pdf"},{"title":"The Bass trace conjecture and the characteristic-zero Kaplansky idempotent conjecture","href":"preprints/The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026/The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026.pdf"}],"plainFr":"Une matrice égale à son carré possède une trace qui indique sur quelles classes du groupe elle repose. Le manuscrit affirme que, pour tout groupe discret, cette trace dans l'algèbre de norme un ne charge qu'un nombre fini de classes d'éléments d'ordre fini, avec un compagnon algébrique pour les groupes sans torsion.","plainEn":"A matrix equal to its square has a trace recording which conjugacy classes of the group support it. The manuscript asserts that, for every discrete group, this trace in the norm-one algebra charges only finitely many classes of finite-order elements, with an algebraic companion for torsion-free groups.","expertFr":"Le manuscrit affirme que, pour tout groupe discret, la trace de Hattori–Stallings d'une matrice idempotente sur l'algèbre complexe de norme un ne charge qu'un nombre fini de classes d'ordre fini. Le compagnon affirme la trace intégrale de Bass et les idempotents de Kaplansky pour les groupes sans torsion, sur tout anneau intègre commutatif unitaire de caractéristique nulle.","expertEn":"The manuscript asserts that, for every discrete group, the Hattori–Stallings trace of an idempotent matrix over the complex norm-one algebra meets only finitely many finite-order classes. Its companion asserts the integral Bass trace conjecture and Kaplansky's idempotents for torsion-free groups, over every commutative unital characteristic-zero domain.","sparkFr":"L'intérêt est structurel en K-théorie des algèbres de groupes, sans application hors des mathématiques affirmée.","sparkEn":"The interest is structural in the K-theory of group algebras, with no application outside mathematics asserted."},{"id":"208","titleEn":"Finite symmetric tensor categories and the Verlinde tower","titleFr":"Catégories tensorielles symétriques finies et tour de Verlinde","claim":"Proves that every finite symmetric tensor category over an algebraically closed field k of characteristic p > 0 admits a k-linear exact faithful strong symmetric monoidal fiber functor to a higher Verlinde category Ver_p^n. The level may depend on the category, and the theorem includes characteristic two, resolving the finite case of the Benson–Etingof–Ostrik conjecture.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Fiber functors for finite symmetric tensor categories in positive characteristic","href":"preprints/Fiber-functors-for-finite-symmetric-tensor-categories-in-positive-characteristic-September-24-2026/paper.pdf"}],"plainFr":"Une catégorie tensorielle symétrique finie combine des objets de façon associative, commutative et dualisable. Le manuscrit affirme que chacune, sur un corps algébriquement clos de caractéristique positive, se plonge exactement et fidèlement dans une catégorie de Verlinde supérieure, même en caractéristique deux.","plainEn":"A finite symmetric tensor category is a setting in which objects combine associatively, commutatively and with duals. The manuscript asserts that each one, over an algebraically closed field of positive characteristic, embeds exactly and faithfully into a higher Verlinde category, including in characteristic two.","expertFr":"Le manuscrit affirme le cas fini de la conjecture de Benson–Etingof–Ostrik. Toute catégorie tensorielle symétrique finie sur un corps algébriquement clos de caractéristique positive admet un foncteur fibre linéaire, exact, fidèle et fortement monoïdal symétrique vers une catégorie de Verlinde supérieure de niveau fini, éventuellement dépendant de la catégorie.","expertEn":"The manuscript asserts the finite case of the Benson–Etingof–Ostrik conjecture. Every finite symmetric tensor category over an algebraically closed field of positive characteristic admits an exact faithful strong symmetric monoidal linear fiber functor to a finite higher Verlinde category, whose level may depend on the category.","sparkFr":"La piste reste interne à la théorie tensorielle en caractéristique positive, sans usage extérieur revendiqué.","sparkEn":"The lead stays inside tensor category theory in positive characteristic, with no outside use claimed."},{"id":"209","titleEn":"Integral counterexamples to Gersten’s conjecture","titleFr":"Contre-exemples intégraux à la conjecture de Gersten","claim":"Disproves unrestricted integral Gersten injectivity in degrees 3 and 5. Two explicit two-dimensional ramified regular local rings of mixed characteristic (0,5) have nonzero integral K-theory classes that vanish over their fraction fields.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1957,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"An integral counterexample to Gersten's conjecture","href":"preprints/An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026/An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026.pdf"},{"title":"An integral degree-three Gersten counterexample","href":"preprints/An-Integral-Degree-Three-Gersten-Counterexample-September-26-2026/paper.pdf"}],"plainFr":"La K-théorie attache des groupes à un anneau, parfois censés s'injecter dans ceux du corps des fractions. Le manuscrit affirme que cette injectivité intégrale échoue en degrés trois et cinq, pour deux anneaux locaux réguliers ramifiés de dimension deux, en caractéristique mixte zéro et cinq.","plainEn":"Algebraic K-theory attaches groups to a ring, and one sometimes expects them to inject into those of the fraction field. The manuscript asserts that unrestricted integral injectivity fails in degrees three and five, for two two-dimensional ramified regular local rings of mixed characteristic zero and five.","expertFr":"Le manuscrit affirme deux anneaux locaux réguliers ramifiés explicites, de dimension deux et de caractéristique mixte zéro et cinq, avec des classes entières de K-théorie non nulles qui s'annulent sur le corps des fractions, en degrés trois et cinq. En particulier, l'application en degré cinq vers le corps des fractions a un noyau non nul, ce qui réfute la forme intégrale sans restriction de Gersten.","expertEn":"The manuscript asserts two explicit two-dimensional ramified regular local rings of mixed characteristic zero and five, with nonzero integral K-theory classes that vanish over the fraction field, in degrees three and five. In particular, the degree-five map to the fraction field has a nonzero kernel, disproving Gersten's conjecture in unrestricted integral form.","sparkFr":"L'intérêt est structurel en K-théorie algébrique, et le manuscrit ne propose pas de pont hors des mathématiques.","sparkEn":"The interest is structural in algebraic K-theory, and the manuscript offers no bridge outside mathematics."},{"id":"210","titleEn":"Foulkes' conjecture for sixth powers and quadratic stabilization","titleFr":"Le sixième cas de la conjecture de Foulkes","claim":"Proves the sixth case of Foulkes’ conjecture: Sym ^6( Sym ^bV) embeds equivariantly in Sym ^b( Sym ^6V) for every b ≥ 6 and finite-dimensional complex V. More generally, the canonical multiplication map Sym ^b( Sym ^aV)→ Sym ^a( Sym ^bV) is surjective for a ≥ 2 and b≥ a(a-1), giving dimension-independent quadratic stabilization.","nature":"geometrie-algebrique","domain":"calcul","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Foulkes' conjecture for the sixth symmetric power","href":"preprints/Foulkes-Conjecture-for-the-Sixth-Symmetric-Power-September-25-2026/main.pdf"},{"title":"Quadratic stabilization of the canonical Foulkes--Howe map","href":"preprints/Quadratic-Stabilization-of-the-Canonical-Foulkes-Howe-Map-September-25-2026/paper.pdf"}],"plainFr":"Les puissances symétriques décrivent les polynômes homogènes, avec l'action du groupe linéaire. Le manuscrit affirme qu'une puissance sixième s'injecte de façon équivariante dans la construction inverse dès l'exposant six, et qu'une stabilisation rend surjective une multiplication canonique.","plainEn":"Symmetric powers describe homogeneous polynomials, with the linear group acting. The manuscript asserts that a sixth power embeds equivariantly into the reverse construction from exponent six on, and that a stabilization makes a canonical multiplication surjective.","expertFr":"Le manuscrit affirme, pour tout entier au moins six et tout espace complexe de dimension finie, une injection équivariante de la puissance symétrique sixième d'une puissance symétrique dans la construction renversée. Plus généralement, la multiplication canonique est surjective lorsque le premier exposant vaut au moins deux et le second est au moins le produit de ce premier exposant par lui-même diminué de un.","expertEn":"The manuscript asserts, for every integer at least six and every finite-dimensional complex space, an equivariant injection of the sixth symmetric power of a symmetric power into the reversed construction. More generally, the canonical multiplication is surjective when the first exponent is at least two and the second is at least that first exponent times itself minus one.","sparkFr":"La piste est interne à la théorie des invariants, sans usage hors des mathématiques affirmé par le manuscrit.","sparkEn":"The lead is internal to invariant theory, with no use outside mathematics asserted by the manuscript."},{"id":"211","titleEn":"The geometric phase diagram, diffusion, and spectra of random planar maps","titleFr":"Transition géométrique des cartes planaires aléatoires","claim":"Critical Fortuin–Kasteleyn planar maps converge to Liouville quantum gravity spheres for 0 q≤4 and to the Brownian continuum random tree for q > 4, establishing the surface-to-tree geometric transition. For FK–Ising and spanning-tree-weighted maps, stationary random walks converge to Liouville Brownian motion on the limiting sphere. The FK–Ising spectral result also gives convergence of eigenvalues and heat traces, using the stated Brownian/LQG inputs.","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Random Walks on Critical FK–Ising Maps and Liouville Brownian Motion","href":"preprints/Random-Walks-on-Critical-FK-Ising-Maps-and-Liouville-Brownian-Motion-October-5-2026/fk-ising-walk-limit.pdf"},{"title":"Spectral convergence for critical FK–Ising planar maps","href":"preprints/Spectral-convergence-for-critical-FK-Ising-planar-maps-October-5-2026/spectral-convergence-critical-fk-ising-planar-maps.pdf"},{"title":"A Linear Clock for Random Walk on Tree-Weighted Planar Maps","href":"preprints/A-Linear-Clock-for-Random-Walk-on-Tree-Weighted-Planar-Maps-October-5-2026/linear-clock-random-walk-tree-weighted-planar-maps.pdf"},{"title":"Canonical conformal limits of subcritical FK planar maps","href":"preprints/Canonical-conformal-limits-of-subcritical-FK-planar-maps-September-24-2026/main.pdf"},{"title":"The critical Liouville quantum sphere and geometric limits of FK maps at q=4","href":"preprints/The-critical-Liouville-quantum-sphere-and-geometric-limits-of-FK-maps-at-q-equals-4-September-24-2026/main.pdf"},{"title":"Metric-measure limits of subcritical FK and spanning-tree planar maps","href":"preprints/Metric-measure-limits-of-subcritical-FK-and-spanning-tree-planar-maps-September-24-2026/main.pdf"}],"plainFr":"Une carte planaire critique est un graphe aléatoire sans croisement, pondéré selon Fortuin et Kasteleyn. Le manuscrit affirme un passage des sphères de Liouville à l'arbre brownien continu au-delà du paramètre quatre, plus une convergence de marches et, pour Ising, de données spectrales.","plainEn":"A critical planar map is a random crossing-free graph, weighted in the Fortuin–Kasteleyn way. The manuscript asserts a passage from Liouville spheres to the Brownian continuum tree past parameter four, plus convergence of walks and, for Ising, of spectral data.","expertFr":"Le manuscrit affirme la convergence vers des sphères de Liouville jusqu'au paramètre quatre, dans la plage indiquée depuis zéro, et vers l'arbre continu brownien au-delà. Pour Ising et les poids d'arbres couvrants, les marches stationnaires tendent vers le mouvement brownien de Liouville, et le spectre d'Ising donne valeurs propres et traces de chaleur.","expertEn":"The manuscript asserts that critical Fortuin–Kasteleyn planar maps converge to Liouville spheres for the parameter at most four in the stated range starting from zero, and to the Brownian continuum random tree beyond it. For Ising maps and spanning-tree-weighted maps, stationary walks converge to Liouville Brownian motion, and the Ising spectral result also gives eigenvalues and heat traces.","sparkFr":"On peut entrevoir un lien avec la physique statistique, mais le manuscrit n'affirme qu'un théorème de convergence, sans déploiement physique.","sparkEn":"One may glimpse a link with statistical physics, but the manuscript asserts only a convergence theorem, with no physical deployment."},{"id":"212","titleEn":"Planar first-passage geometry and the absence of bigeodesics","titleFr":"Absence de bigéodésiques en premier passage planaire","claim":"Proves that planar first-passage percolation has no doubly infinite geodesic for iid nonnegative nonatomic edge weights when the minimum of four weights has finite second moment. For exponential weights, the limit shape is strictly convex with C1 boundary. Differentiability also holds for every Gamma law with positive shape and rate.","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1957,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"No bigeodesics in planar first-passage percolation","href":"preprints/No-bigeodesics-in-planar-first-passage-percolation-September-24-2026/main.pdf"},{"title":"Strict convexity and differentiability of the planar exponential first-passage limit shape","href":"preprints/Strict-convexity-and-differentiability-of-the-planar-exponential-first-passage-limit-shape-September-24-2026/main.pdf"}],"plainFr":"Le premier passage donne à chaque arête un temps aléatoire, puis cherche les chemins les plus rapides. Le manuscrit affirme qu'en plan, sous un moment sur quatre poids, aucune géodésique n'est infinie des deux côtés, et que la forme limite est régulière pour les lois exponentielles et gamma indiquées.","plainEn":"First passage gives each edge a random time, then seeks the fastest paths. The manuscript asserts that in the plane, under a moment condition on four weights, no geodesic is infinite both ways, and that the limit shape is regular for the stated exponential and gamma laws.","expertFr":"Le manuscrit affirme l'absence presque sûre de géodésique doublement infinie pour des poids non négatifs, indépendants et non atomiques, si le minimum de quatre poids a un second moment fini. Pour les poids exponentiels la forme limite est strictement convexe à bord dérivable, et la dérivabilité vaut encore pour toute loi gamma de forme et de taux positifs.","expertEn":"The manuscript asserts that there is almost surely no doubly infinite geodesic for nonnegative iid nonatomic edge weights, once the minimum of four weights has a finite second moment. For exponential weights the limit shape is strictly convex with continuously differentiable boundary, and differentiability also holds for every gamma law of positive shape and rate.","sparkFr":"La piste reste dans la géométrie aléatoire planaire, et le manuscrit ne revendique aucun usage appliqué.","sparkEn":"The lead stays in planar random geometry, and the manuscript claims no applied use."},{"id":"213","titleEn":"Critical percolation on every quasi-transitive graph","titleFr":"Percolation critique sur les graphes quasi transitifs","claim":"Resolves the Benjamini–Schramm criticality conjecture for bond percolation on every infinite connected locally finite quasi-transitive graph with p_c 1: at the critical probability, there is almost surely no infinite cluster. The family also establishes this conclusion for both nearest-neighbor bond and site percolation on ℤ3.","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1957,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Critical bond and site percolation on the cubic lattice","href":"preprints/Critical-bond-and-site-percolation-on-the-cubic-lattice-September-24-2026/paper.pdf"},{"title":"No percolation at criticality on quasi-transitive graphs","href":"preprints/No-percolation-at-criticality-on-quasi-transitive-graphs-September-24-2026/paper.pdf"}],"plainFr":"La percolation garde ou efface au hasard les arêtes ou les sommets d'un graphe infini. Le manuscrit affirme qu'au seuil critique il n'y a presque sûrement aucun amas infini sur les graphes quasi transitifs de seuil inférieur à un, ni pour les sites et liens voisins du réseau cubique.","plainEn":"Percolation randomly keeps or deletes edges or vertices of an infinite graph. The manuscript asserts that at criticality there is almost surely no infinite cluster on quasi-transitive graphs whose threshold is below one, nor for neighbors of the cubic lattice.","expertFr":"Le manuscrit affirme la conjecture de criticalité de Benjamini–Schramm pour la percolation de liens sur tout graphe infini connexe, localement fini et quasi transitif, dès que la probabilité critique est strictement inférieure à un. La même absence d'amas infini à la criticité vaut pour la percolation de liens et de sites plus proches voisins sur le réseau entier de dimension trois.","expertEn":"The manuscript asserts the Benjamini–Schramm criticality conjecture for bond percolation on every infinite connected locally finite quasi-transitive graph whose critical probability is strictly less than one. The same absence of an infinite cluster at criticality holds for nearest-neighbor bond and site percolation on the three-dimensional integer lattice.","sparkFr":"L'intérêt reste structurel en percolation, et le manuscrit n'affirme aucun modèle hors des mathématiques.","sparkEn":"The interest stays structural in percolation, and the manuscript asserts no model outside mathematics."},{"id":"214","titleEn":"The Benjamini–Schramm nonuniqueness conjecture","titleFr":"Non-unicité des amas selon Benjamini et Schramm","claim":"Proves p_c p_u for Bernoulli bond percolation on every infinite connected locally finite nonamenable quasi-transitive graph, resolving the Benjamini–Schramm nonuniqueness conjecture. Thus there is a nonempty range of probabilities with infinitely many infinite clusters. A stronger operator bound also establishes the critical triangle condition.","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1957,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Nonuniqueness of percolation on nonamenable quasi-transitive graphs","href":"preprints/Nonuniqueness-of-percolation-on-nonamenable-quasi-transitive-graphs-September-24-2026/paper.pdf"}],"plainFr":"Sur un graphe infini, la percolation de liens peut produire un seul amas infini ou plusieurs à la fois. Le manuscrit affirme que, sur tout graphe quasi transitif non moyennable, connexe et localement fini, tout un intervalle de probabilités donne presque sûrement une infinité d'amas infinis.","plainEn":"On an infinite graph, bond percolation may produce one infinite cluster or many at once. The manuscript asserts that on every nonamenable connected locally finite quasi-transitive graph, a whole interval of probabilities yields almost surely infinitely many infinite clusters.","expertFr":"Le manuscrit affirme que la probabilité critique est strictement inférieure au seuil de non-unicité pour la percolation de liens de Bernoulli sur tout graphe infini connexe, localement fini, non moyennable et quasi transitif. Une borne d'opérateurs plus forte établit aussi la condition du triangle critique au sens de la conjecture de seuil de Hutchcroft.","expertEn":"The manuscript asserts that the critical probability lies strictly below the nonuniqueness threshold for Bernoulli bond percolation on every infinite connected locally finite nonamenable quasi-transitive graph. A stronger operator bound also establishes the critical triangle condition in the sense of Hutchcroft's threshold conjecture.","sparkFr":"L'intérêt reste structurel en percolation sur les graphes, sans usage hors des mathématiques affirmé.","sparkEn":"The interest stays structural in percolation on graphs, with no use outside mathematics asserted."},{"id":"215","titleEn":"Canonical O(3) continuum limit and exact O(4) mass asymptotics","titleFr":"Limite continue du modèle O(3) et masse du modèle O(4)","claim":"Constructs the canonical continuum limit of the two-dimensional nearest-neighbor O(3) model: a non-Gaussian local relativistic theory with a unique vacuum and a positive mass gap. For the square-lattice O(4) model, determines the exact leading asymptotic of the full transfer gap, m_lat(β) 32e^π/4-1/2 β\\,e^-πβ. The family also proves exponential spin-correlation decay for two-dimensional nearest-neighbor O(n) models with n ≥ 3 at every positive temperature.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":2000,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The canonical massive continuum limit of the two-dimensional O(3) model","href":"preprints/The-canonical-massive-continuum-limit-of-the-two-dimensional-O3-model-October-4-2026/massive-continuum-o3.pdf"},{"title":"An Isolated Particle Pole for the Two-Dimensional O(3) Spin Field","href":"preprints/An-Isolated-Particle-Pole-for-the-Two-Dimensional-O3-Spin-Field-October-4-2026/o3-particle-pole.pdf"},{"title":"Exact mass asymptotics for the two-dimensional O(4) lattice model","href":"preprints/Exact-mass-asymptotics-for-the-two-dimensional-O4-lattice-model-October-5-2026/exact-mass-o4.pdf"},{"title":"Sharp mass bounds for the two-dimensional O(4) model","href":"preprints/Sharp-mass-bounds-for-the-two-dimensional-O4-model-September-23-2026/paper.pdf"},{"title":"Exponential decay in two-dimensional classical O(n) models","href":"preprints/Exponential-decay-in-two-dimensional-classical-On-models-September-23-2026/paper.pdf"}],"plainFr":"Ces modèles placent en chaque site un spin de longueur fixe, lié à ses voisins. Le manuscrit affirme une limite continue massive et non gaussienne à trois composantes, une asymptotique exacte du trou spectral à quatre, et une décroissance exponentielle des corrélations dès trois composantes.","plainEn":"These models place a fixed-length spin at each site, tied to its neighbors. The manuscript asserts a massive non-Gaussian continuum limit in three components, an exact spectral-gap asymptotic in four, and exponential decay of correlations from three components on.","expertFr":"Le manuscrit affirme une limite continue canonique du modèle planaire voisin à trois composantes : théorie locale non gaussienne, vide unique et trou de masse positif. Il affirme aussi l'asymptotique exacte de tête du trou de transfert à quatre composantes, et la décroissance exponentielle des corrélations dès trois composantes, à toute température positive.","expertEn":"The manuscript asserts a canonical continuum limit of the planar nearest-neighbor three-component model: a non-Gaussian local relativistic theory with a unique vacuum and a positive mass gap. It also asserts the exact leading asymptotic of the full transfer gap of the square-lattice four-component model, and exponential spin-correlation decay for at least three components at every positive temperature.","sparkFr":"Le vocabulaire est celui de la physique mathématique, mais le manuscrit n'affirme pas de mesure expérimentale ni d'usage industriel.","sparkEn":"The vocabulary is that of mathematical physics, but the manuscript asserts neither an experimental measurement nor an industrial use."},{"id":"216","titleEn":"Critical and near-critical XY scaling and BKT universality","titleFr":"Échelle critique du modèle XY et singularité essentielle","claim":"For the square-lattice nearest-neighbor cosine XY model, proves critical axis correlations C_β_c(r) Ar^-1/4( r)^1/8 and the Berezinskii–Kosterlitz–Thouless essential singularity √(β_c-β) ξ(β)→ B, with A,B 0 after the free-box thermodynamic limit. For finite square-symmetric interactions containing nearest neighbors, discrete Gaussian heights converge to Gaussian fields throughout the rough phase, including its threshold, along geometric torus sizes. Critical center-magnetization and spin-field conclusions retain th","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1955,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The critical logarithmic correction for the planar XY model","href":"preprints/The-critical-logarithmic-correction-for-the-planar-XY-model-October-5-2026/paper.pdf"},{"title":"Critical Center Magnetization in the Planar XY Model","href":"preprints/Critical-Center-Magnetization-in-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"The Critical Spin Field of the Planar XY Model","href":"preprints/The-Critical-Spin-Field-of-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"Essential Singularity of the Correlation Length in the Planar XY Model","href":"preprints/Essential-Singularity-of-the-Correlation-Length-in-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"The critical correlation exponent of the planar XY model","href":"preprints/The-critical-correlation-exponent-of-the-planar-XY-model-September-24-2026/paper.pdf"},{"title":"BKT universality for height and planar spin fields","href":"preprints/BKT-universality-for-height-and-planar-spin-fields-September-24-2026/paper.pdf"}],"plainFr":"Le modèle cosinus place un angle en chaque site du réseau carré. Le manuscrit affirme la correction logarithmique critique des corrélations d'axe et la singularité essentielle de Berezinskii, Kosterlitz et Thouless, ainsi que des hauteurs discrètes tendant vers des champs gaussiens dans la phase rugueuse.","plainEn":"The cosine model places an angle at each site of the square lattice. The manuscript asserts the critical logarithmic correction of axis correlations and the Berezinskii–Kosterlitz–Thouless essential singularity, with discrete heights tending to Gaussian fields in the rough phase.","expertFr":"Le manuscrit affirme des corrélations critiques d'axe du type constante positive fois distance à la puissance moins un quart, fois un logarithme à la puissance un huitième, puis la singularité essentielle après la limite en boîte libre. Pour des interactions finies carré-symétriques contenant les voisins, les hauteurs discrètes tendent vers des champs gaussiens sur toute la phase rugueuse, seuil et tores compris.","expertEn":"The manuscript asserts critical axis correlations given by a positive constant times distance to the power minus one quarter times a logarithm to the power one eighth, then the essential singularity after the free-box limit. For finite square-symmetric interactions containing the neighbors, discrete heights tend to Gaussian fields throughout the rough phase, including the threshold and the stated tori.","sparkFr":"Le nom de la transition est célèbre en physique, mais le manuscrit n'affirme qu'un théorème d'échelle, sans prétendre à une expérience.","sparkEn":"The name of the transition is famous in physics, but the manuscript asserts only a scaling theorem, with no claim of an experiment."},{"id":"217","titleEn":"The low-temperature Sherrington–Kirkpatrick fluctuation law","titleFr":"Fluctuations froides du modèle de Sherrington–Kirkpatrick","claim":"For every fixed inverse temperature β > 1, determines the fluctuation scale and limiting law of the zero-field Gaussian Sherrington–Kirkpatrick log partition function. Its variance is asymptotic to c_β n^1/3, with c_β 0, confirming the predicted n1/6 standard-deviation scale. Exact centering and standardization give full-sequence convergence to a uniquely characterized nondegenerate law.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1975,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The low-temperature Sherrington–Kirkpatrick free-energy limiting law","href":"preprints/The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026/The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026.pdf"},{"title":"The low-temperature Sherrington–Kirkpatrick fluctuation scale","href":"preprints/The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026/The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026.pdf"}],"plainFr":"Ce verre de spin couple chaque paire de spins binaires par un nombre gaussien, sans champ. Le manuscrit affirme qu'au-dessus de la température inverse un, le logarithme de la fonction de partition fluctue comme la racine sixième de la taille, vers une loi non dégénérée.","plainEn":"This spin glass couples every pair of binary spins by a Gaussian number, with no field. The manuscript asserts that above inverse temperature one, the log partition function fluctuates like the one-sixth power of the size, toward a nondegenerate law.","expertFr":"Le manuscrit affirme que, pour toute température inverse fixée supérieure à un, la variance du logarithme de la fonction de partition gaussienne sans champ est asymptotique à une constante positive fois la taille à la puissance un tiers. Après centrage et réduction exacts, toute la suite converge vers une loi non dégénérée caractérisée de façon unique.","expertEn":"The manuscript asserts that, for every fixed inverse temperature above one, the variance of the zero-field Gaussian log partition function is asymptotic to a positive constant times size to the power one third. After exact centering and scaling, the full sequence converges to a uniquely characterized nondegenerate law.","sparkFr":"On peut songer aux verres de spin, mais le manuscrit n'affirme qu'une loi de fluctuations, sans usage hors des mathématiques.","sparkEn":"One may think of spin glasses, but the manuscript asserts only a fluctuation law, with no use outside mathematics."},{"id":"218","titleEn":"Conformal universality for weakly interacting and random-bond Ising models","titleFr":"Universalité conforme de faibles perturbations d'Ising","claim":"Weak finite-range square-symmetric even multispin perturbations of the square-lattice Ising model preserve critical bulk spin and energy limits; weak square-symmetric contour interactions also yield chordal SLE3 interface limits. With sufficiently weak iid bond disorder of any fixed bounded nondegenerate mean-zero law, critical spin interfaces converge to the same law in probability over environments.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Quenched SLE₃ limits for general weak random-bond Ising models","href":"preprints/Quenched-SLE3-limits-for-general-weak-random-bond-Ising-models-October-5-2026/general-weak-random-bond-ising.pdf"},{"title":"Quenched SLE₃ Universality for the Weak Random-Bond Ising Model","href":"preprints/Quenched-SLE3-Universality-for-the-Weak-Random-Bond-Ising-Model-October-5-2026/quenched-sle3-weak-random-bond-ising.pdf"},{"title":"Logarithmic Relative Fluctuations in the Weakly Disordered Planar Ising Model","href":"preprints/Logarithmic-Relative-Fluctuations-in-the-Weakly-Disordered-Planar-Ising-Model-October-5-2026/critical-relative-second-moment-weak-random-bond-ising.pdf"},{"title":"Conformal universality of bulk Ising correlations under weak interactions","href":"preprints/Conformal-universality-of-bulk-Ising-correlations-under-weak-interactions-September-23-2026/paper.pdf"},{"title":"SLE3 universality for weak finite-range Ising interactions","href":"preprints/SLE3-universality-for-weak-finite-range-Ising-interactions-September-23-2026/paper.pdf"},{"title":"Buffered comparison and stopping-band resolution in critical Ising","href":"preprints/Buffered-comparison-and-stopping-band-resolution-in-critical-Ising-September-23-2026/paper.pdf"}],"plainFr":"Le modèle d'Ising place un spin plus ou moins sur une grille. Le manuscrit affirme que de faibles perturbations paires préservent les limites critiques de spin et d'énergie, que de faibles contours donnent des interfaces d'indice trois, et qu'un faible désordre de liens laisse la même loi.","plainEn":"The Ising model places a plus or minus spin on a grid. The manuscript asserts that weak even perturbations preserve critical spin and energy limits, that weak contours yield interfaces of index three, and that weak bond disorder leaves the same law.","expertFr":"Le manuscrit affirme que de faibles perturbations paires, finies et carré-symétriques, préservent les limites critiques de volume, et que de faibles contours donnent des interfaces chordales d'indice trois. Un désordre de liens indépendant, borné, centré, non dégénéré et assez faible laisse la même loi en probabilité sur les environnements, au seuil d'aimantation spontanée.","expertEn":"The manuscript asserts that weak finite square-symmetric even perturbations preserve the critical bulk limits, and that weak contours yield chordal interfaces of index three. Sufficiently weak iid bounded centered nondegenerate bond disorder leaves the same law in probability over environments, at the spontaneous-magnetization threshold.","sparkFr":"Le lien avec les interfaces critiques est mathématique, et le manuscrit ne revendique aucune réalisation matérielle.","sparkEn":"The link with critical interfaces is mathematical, and the manuscript claims no material realization."},{"id":"219","titleEn":"GOE bulk universality for regular graphs with weak Anderson disorder","titleFr":"Universalité de l'ensemble orthogonal pour les graphes réguliers","claim":"For every fixed degree d ≥ 3, the bulk adjacency-eigenvalue point process of a uniform simple random d-regular graph converges to the Gaussian orthogonal ensemble law, including for cubic graphs. The same fixed-energy universality persists under sufficiently weak fixed iid uniform diagonal disorder, throughout compact bands strictly inside the clean spectral edges.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":1958,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Fixed-energy universality for weak Anderson disorder on random regular graphs","href":"preprints/Fixed-energy-universality-for-weak-Anderson-disorder-on-random-regular-graphs-October-5-2026/fixed-energy-universality-weak-anderson-disorder-random-regular-graphs.pdf"},{"title":"GOE bulk universality for fixed-degree random regular graphs","href":"preprints/GOE-bulk-universality-for-fixed-degree-random-regular-graphs-September-23-2026/paper.pdf"}],"plainFr":"Un graphe régulier aléatoire donne le même nombre de voisins à chaque sommet. Le manuscrit affirme que, dès le degré trois, les valeurs propres fines suivent l'ensemble orthogonal gaussien, même sous un faible désordre diagonal à l'intérieur de la bande spectrale.","plainEn":"A random regular graph gives every vertex the same number of neighbors. The manuscript asserts that from degree three on, the fine eigenvalues follow the Gaussian orthogonal ensemble, even under weak diagonal disorder inside the spectral band.","expertFr":"Le manuscrit affirme que, pour tout degré fixé au moins trois, les valeurs propres d'adjacence dans le volume convergent vers l'ensemble orthogonal gaussien, cubes compris. Cela persiste à énergie fixée sous un désordre diagonal uniforme, faible et fixé, dans tout compact intérieur aux bords spectraux propres.","expertEn":"The manuscript asserts that, for every fixed degree at least three, the bulk adjacency-eigenvalue point process of a uniform simple random graph converges to the Gaussian orthogonal ensemble law, cubic graphs included. The same fixed-energy universality persists under sufficiently weak fixed iid uniform diagonal disorder, throughout compact sets strictly inside the clean spectral edges.","sparkFr":"L'intérêt est structurel pour les spectres de graphes aléatoires, sans application hors des mathématiques affirmée.","sparkEn":"The interest is structural for spectra of random graphs, with no application outside mathematics asserted."},{"id":"220","titleEn":"Directional zero–one laws beyond iid environments and iid ballisticity","titleFr":"Lois directionnelles du tout ou rien, et ballisticité","claim":"On ℤd, d ≥ 3, directional escape has probability zero or one for iid strictly elliptic nearest-neighbor environments, and for stationary ergodic finite-range-dependent environments under uniform ellipticity. In iid uniformly elliptic environments with d ≥ 2, almost-sure directional transience implies a deterministic limiting velocity with positive projection in that direction, resolving the ballisticity conjecture.","nature":"nombres","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A directional zero–one law for finite-range-dependent random environments","href":"preprints/A-directional-zero-one-law-for-finite-range-dependent-random-environments-October-5-2026/directional-zero-one-finite-range.pdf"},{"title":"A directional zero–one law under strict ellipticity","href":"preprints/A-directional-zero-one-law-under-strict-ellipticity-September-23-2026/paper.pdf"},{"title":"Directional transience implies ballisticity","href":"preprints/Directional-transience-implies-ballisticity-September-23-2026/paper.pdf"}],"plainFr":"Une marche en milieu aléatoire choisit ses pas selon des règles figées au hasard. Le manuscrit affirme qu'en dimension au moins trois la fuite directionnelle a probabilité nulle ou un, et que dès la dimension deux une fuite presque sûre impose une vitesse de projection positive.","plainEn":"A walk in a random environment chooses steps by randomly frozen rules. The manuscript asserts that in dimension at least three directional escape has probability zero or one, and that from dimension two almost-sure escape forces a velocity of positive projection.","expertFr":"Le manuscrit affirme une loi du tout ou rien directionnelle en dimension au moins trois, pour des pas voisins en milieu indépendant strictement elliptique et pour des milieux ergodiques à portée finie uniformément elliptiques. Dès la dimension deux, en milieu indépendant uniformément elliptique, la transience directionnelle presque sûre donne une vitesse limite de projection positive.","expertEn":"The manuscript asserts a directional zero-one law in dimension at least three, for neighbor steps in iid strictly elliptic environments and for finite-range ergodic environments under uniform ellipticity. From dimension two, in iid uniformly elliptic environments, almost-sure directional transience yields a limiting velocity of positive projection.","sparkFr":"La ballisticité reste ici un énoncé de marches aléatoires, et le manuscrit n'affirme aucun modèle de transport réel.","sparkEn":"Ballisticity remains here a statement about random walks, and the manuscript asserts no real transport model."},{"id":"221","titleEn":"The Mézard–Parisi formula for diluted spin glasses","titleFr":"La formule de cavité de Mézard et Parisi pour les modèles dilués","claim":"Proves the Mézard–Parisi hierarchical cavity formula for Poisson-diluted even-arity Ising models satisfying the Panchenko–Talagrand factorization and positivity assumptions, with only first-moment integrability. The limiting free energy equals the infimum over finite-depth hierarchical trial laws. This includes the Viana–Bray model, symmetric diluted even-spin models, and weighted soft even-K satisfiability.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1985,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The Mézard–Parisi formula for diluted spin glasses","href":"preprints/The-Mezard-Parisi-formula-for-diluted-spin-glasses-September-23-2026/paper.pdf"}],"plainFr":"Un verre de spin dilué ne relie qu'une petite part aléatoire de groupes de spins. Le manuscrit affirme que, pour des modèles d'Ising pairs dilués à la Poisson sous les hypothèses dites, l'énergie libre limite est l'infimum d'une formule de cavité hiérarchique, y compris pour Viana et Bray.","plainEn":"A diluted spin glass lets only a small random fraction of groups of spins interact. The manuscript asserts that, for Poisson-diluted even-parity Ising models under the stated assumptions, the limiting free energy equals the infimum of a hierarchical cavity formula, including in particular the Viana–Bray model.","expertFr":"Le manuscrit affirme la formule de cavité de Mézard–Parisi pour les Ising pairs dilués selon Poisson, dans la classe de Panchenko–Talagrand, avec un seul moment d'ordre un. L'énergie libre limite est l'infimum des lois d'essai de profondeur finie, ce qui couvre Viana–Bray, les spins pairs dilués symétriques et la satisfaisabilité souple pondérée d'arité paire.","expertEn":"The manuscript asserts the Mézard–Parisi hierarchical cavity formula for Poisson-diluted even-parity Ising models in the Panchenko–Talagrand factorization and positivity class, with only first-moment integrability. The limiting free energy equals the infimum over finite-depth trial laws, including Viana–Bray, symmetric diluted even-spin models and weighted soft even-arity satisfiability.","sparkFr":"Le mot de satisfaisabilité apparaît dans l'énoncé, mais le manuscrit n'affirme qu'une égalité variationnelle, sans algorithme pratique.","sparkEn":"The word satisfiability appears in the statement, but the manuscript asserts only a variational equality, with no practical algorithm."},{"id":"222","titleEn":"Perceptron free energies and microscopic jamming exponents","titleFr":"Énergies libres du perceptron et lois de blocage","claim":"Determines finite-temperature variational free energies for Gaussian Ising perceptrons with bounded Borel log-potentials and Gaussian spherical perceptrons with bounded continuous potentials, at every positive pattern density. A spherical extension treats bi-orthogonally invariant disorder with compact limiting singular-value distributions and no outliers. At margin −1, the quadratic-penalty spherical model has a sharp feasibility threshold and limiting gap and force laws, with system size, zero temperature, and cr","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The free energy of the Ising random perceptron","href":"preprints/The-free-energy-of-the-Ising-random-perceptron-September-24-2026/The-free-energy-of-the-Ising-random-perceptron-September-24-2026.pdf"},{"title":"Microscopic jamming in the negative spherical perceptron","href":"preprints/Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026/Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026.pdf"},{"title":"The spherical perceptron with bi-orthogonally invariant disorder","href":"preprints/The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026/The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026.pdf"},{"title":"The free energy of the spherical random perceptron","href":"preprints/The-free-energy-of-the-spherical-random-perceptron-September-24-2026/The-free-energy-of-the-spherical-random-perceptron-September-24-2026.pdf"}],"plainFr":"Un perceptron impose des contraintes aléatoires à des spins ou à un vecteur sur la sphère. Le manuscrit affirme des énergies libres variationnelles à température finie, à toute densité positive, et, à la marge moins un, un seuil net avec des lois d'écart et de force.","plainEn":"A perceptron imposes random constraints on spins or on a spherical vector. The manuscript asserts finite-temperature variational free energies at every positive density, and at margin minus one a sharp threshold with gap and force laws.","expertFr":"Le manuscrit affirme l'énergie libre limite des perceptrons d'Ising gaussiens à log-potentiel borné et des perceptrons sphériques à potentiel continu borné, à toute densité positive. Une extension traite un désordre bi-orthogonalement invariant à spectre singulier compact sans aberration, et à la marge moins un la pénalité quadratique a un seuil net et des lois d'écart et de force.","expertEn":"The manuscript asserts limiting free energies of Gaussian Ising perceptrons with bounded log-potentials and of Gaussian spherical perceptrons with bounded continuous potentials, at every positive density. An extension treats bi-orthogonal invariant disorder with compact singular spectrum and no outliers, and at margin minus one the quadratic penalty has a sharp threshold and gap and force laws.","sparkFr":"Le nom rappelle d'anciens modèles de contraintes, mais le manuscrit n'affirme qu'un résultat variationnel, sans usage en apprentissage.","sparkEn":"The name recalls older constraint models, but the manuscript asserts only a variational result, with no use in learning."},{"id":"223","titleEn":"Random-cluster interfaces: critical, disordered, thermal, and natural-time scaling","titleFr":"Interfaces critiques du modèle d'amas aléatoires","claim":"Proves chordal SLEκ limits for critical square-lattice random-cluster interfaces for 0 q≤4, with =4π/ (- q/2): bounded Jordan domains are allowed for q ≥ 1, and smooth Jordan domains for q < 1, under the stated marked-boundary approximations. For 1≤ q≤4, complete nested plane loops converge to CLEκ.","nature":"physique-math","domain":"calcul","complexity":"avance","problemYear":2000,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Self-dual random-cluster interfaces below one","href":"preprints/Self-dual-random-cluster-interfaces-below-one-September-23-2026/paper.pdf"},{"title":"Quenched SLE Universality for Weakly Disordered FK–Ising Interfaces","href":"preprints/Quenched-SLE-Universality-for-Weakly-Disordered-FK-Ising-Interfaces-October-5-2026/quenched-fk-ising.pdf"},{"title":"Thermal FK–Ising interfaces and massive SLE","href":"preprints/Thermal-FK-Ising-interfaces-and-massive-SLE-October-5-2026/paper.pdf"},{"title":"Natural Occupation Measures for Critical Square-Lattice FK Interfaces","href":"preprints/Natural-Occupation-Measures-for-Critical-Square-Lattice-FK-Interfaces-October-5-2026/natural-occupation-measures-critical-square-lattice-fk-interfaces.pdf"},{"title":"Conformal Limits of Critical Square-Lattice Random-Cluster Interfaces","href":"preprints/Conformal-Limits-of-Critical-Square-Lattice-Random-Cluster-Interfaces-October-5-2026/paper.pdf"}],"plainFr":"Le modèle d'amas aléatoires relie les sites d'une grille, et ses interfaces séparent des régions. Le manuscrit affirme que les interfaces critiques du carré tendent vers des courbes conformes d'indice lié au poids, et les boucles emboîtées vers l'ensemble correspondant entre les poids un et quatre.","plainEn":"The random-cluster model links sites of a grid, and its interfaces separate regions. The manuscript asserts that critical square interfaces tend to conformal curves whose index depends on the weight, and nested loops to the matching ensemble for weights from one to four.","expertFr":"Le manuscrit affirme des limites chordales, d'indice donné explicitement par le poids, pour les interfaces critiques du réseau carré lorsque ce poids est au plus quatre dans la plage indiquée à partir de zéro. Les domaines de Jordan bornés sont permis à partir du poids un et les domaines lisses en dessous, et, de un à quatre, les boucles planes emboîtées complètes convergent vers l'ensemble de boucles de même indice.","expertEn":"The manuscript asserts chordal limits, with index given explicitly by the weight, for critical square-lattice interfaces when that weight is at most four in the stated range from zero. Bounded Jordan domains are allowed from weight one upward and smooth domains below, and, from one to four, complete nested plane loops converge to the loop ensemble of the same index.","sparkFr":"Ces courbes sont un objet de physique mathématique, et le manuscrit n'affirme pas de simulation ni d'usage industriel.","sparkEn":"These curves are an object of mathematical physics, and the manuscript asserts neither a simulation nor an industrial use."},{"id":"224","titleEn":"Critical and quenched near-critical universality for Poisson–Voronoi percolation","titleFr":"Formule de Cardy pour la percolation de Poisson–Voronoï","claim":"Proves Cardy's formula for annealed critical Poisson–Voronoi crossing probabilities in every bounded Jordan quadrilateral. With each model normalized by its own expected unit-square pivotal count, the conditional joint near-critical crossing-threshold laws for rational polygonal quads converge in environment probability to the triangular-lattice reference law. This establishes quenched near-critical universality for crossing thresholds.","nature":"physique-math","domain":"hasard","complexity":"avance","problemYear":1957,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"From critical crossings to quenched near-critical universality in Voronoi percolation","href":"preprints/From-critical-crossings-to-quenched-near-critical-universality-in-Voronoi-percolation-October-5-2026/critical-crossings-quenched-near-critical-universality-voronoi-percolation.pdf"},{"title":"A Pivotal Amplitude for Voronoi Percolation from Cardy's Formula","href":"preprints/A-Pivotal-Amplitude-for-Voronoi-Percolation-from-Cardys-Formula-October-5-2026/voronoi-pivotal-amplitude.pdf"},{"title":"Cardy’s formula for critical Poisson–Voronoi percolation","href":"preprints/Cardys-formula-for-critical-Poisson-Voronoi-percolation-September-23-2026/paper.pdf"}],"plainFr":"Cette percolation colorie les cellules d'un pavage aléatoire du plan. Le manuscrit affirme la formule de Cardy pour les traversées critiques moyennées dans tout quadrilatère borné simple, et, après normalisation, des seuils presque critiques qui suivent en probabilité la loi du réseau triangulaire.","plainEn":"This percolation colors the cells of a random tiling of the plane. The manuscript asserts Cardy's formula for averaged critical crossings in every bounded simple quadrilateral and, after normalization, near-critical thresholds that follow in probability the triangular-lattice law.","expertFr":"Le manuscrit affirme la formule de Cardy pour les traversées critiques recuites de tout quadrilatère de Jordan borné. Normalisées par le nombre moyen de pivots du carré unité, les lois conditionnelles des seuils presque critiques de quadrilatères polygonaux rationnels convergent en probabilité vers la loi du réseau triangulaire.","expertEn":"The manuscript asserts Cardy's formula for annealed critical crossing probabilities in every bounded Jordan quadrilateral. Each model normalized by its own expected number of pivotal sites for a unit-square crossing, the conditional joint laws of near-critical thresholds for rational polygonal quads converge in probability over the tessellation to the triangular-lattice reference law.","sparkFr":"La formule de traversée reste un énoncé de percolation continue, sans modèle physique affirmé par le manuscrit.","sparkEn":"The crossing formula remains a statement in continuum percolation, with no physical model asserted by the manuscript."},{"id":"225","titleEn":"Gaussian free field limits throughout the balanced six-vertex regime","titleFr":"Champ gaussien du modèle à six sommets équilibré","claim":"The balanced square-lattice six-vertex height field with a=b=1 and 0 c≤2 converges to a Gaussian free field, including at the endpoint c = 2. The plane state is defined by balanced-torus limits. For unit height increments and Green kernel -(2π)^-1 |x-y|, the exact variance multiplier is 1/ (c/2).","nature":"probabilites","domain":"hasard","complexity":"frontiere","problemYear":1981,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Gaussian free field limit of the balanced six-vertex model with variance multiplier 1/arcsin(c/2)","href":"preprints/The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026/The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026.pdf"}],"plainFr":"Le modèle à six sommets trace des flèches conservées, qui définissent une hauteur. Le manuscrit affirme que, dans le régime équilibré indiqué, cette hauteur tend vers un champ libre gaussien, y compris au bout du régime, avec un multiplicateur de variance exact.","plainEn":"The six-vertex model draws arrows on the square lattice that are conserved at each site and define a height. The manuscript asserts that, in the stated balanced regime, this height converges to a Gaussian free field, including at the endpoint of the regime, with an exact variance multiplier for the given normalization.","expertFr":"Le manuscrit affirme que le champ de hauteur à poids égaux à un sur les deux premières familles, et poids au plus deux sur la troisième dans la plage indiquée à partir de zéro, converge vers un multiple du champ libre gaussien, extrémité comprise. L'état du plan vient de limites de tores équilibrés, et le multiplicateur de variance est exact pour des sauts de hauteur unité et le noyau de Green indiqué.","expertEn":"The manuscript asserts that the height field with the first two weights equal to one, and the third at most two in the stated range from zero, converges to a multiple of the Gaussian free field, endpoint included. The plane state comes from balanced-torus limits, and the variance multiplier is exact for unit height jumps and the stated Green kernel.","sparkFr":"L'intérêt est structurel pour les champs de hauteur, et le manuscrit n'affirme aucun usage hors des mathématiques.","sparkEn":"The interest is structural for height fields, and the manuscript asserts no use outside mathematics."},{"id":"226","titleEn":"The double-dimer loop ensemble converges to CLE4","titleFr":"Boucles double-dimères et ensemble conforme d'indice quatre","claim":"Resolves the half-plane Temperleyan form of the double-dimer scaling-limit conjecture: the complete loop ensemble formed by two independent dimer coverings of the Temperleyan square lattice converges to nested CLE4. Convergence matches every macroscopic loop as an unparametrized curve, upgrading convergence of loop observables to convergence of the loops themselves.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The curve scaling limit of half-plane double dimers","href":"preprints/The-curve-scaling-limit-of-half-plane-double-dimers-September-23-2026/paper.pdf"}],"plainFr":"Deux couplages de dimères indépendants dessinent des boucles sur un réseau. Le manuscrit affirme que, sur le carré tempéréen du demi-plan, elles tendent vers l'ensemble conforme emboîté d'indice quatre, chaque grande boucle étant une courbe sans paramètre.","plainEn":"Two independent dimer coverings draw loops on a lattice. The manuscript asserts that on the Temperleyan square in the half-plane they tend to the nested conformal ensemble of index four, each large loop an unparametrized curve.","expertFr":"Le manuscrit affirme la forme tempéréenne de demi-plan de la conjecture de limite d'échelle double-dimère. L'ensemble complet formé par deux couplages indépendants converge vers l'ensemble de boucles emboîté d'indice quatre, le long de toute la limite de maille, en appariant chaque boucle macroscopique comme courbe non paramétrée.","expertEn":"The manuscript asserts the half-plane Temperleyan form of the double-dimer scaling-limit conjecture. The complete ensemble formed by two independent coverings converges to the nested loop ensemble of index four, along the full mesh limit, matching every macroscopic loop as an unparametrized curve.","sparkFr":"Ces boucles restent un objet de limite d'échelle, et le manuscrit ne revendique pas d'interprétation physique déployée.","sparkEn":"These loops remain a scaling-limit object, and the manuscript claims no deployed physical interpretation."},{"id":"227","titleEn":"Critical SK autocorrelation processes and dynamics across the temperature transition","titleFr":"Dynamique du verre de spin autour de la température critique","claim":"For zero-field Gaussian SK heat-bath dynamics with rate-one updates per spin, proves worst-start cutoff on the n scale for fixed 0≤β 1, mixing time n^2/3+o(1) at β = 1, and stretched-exponential mixing from a Gibbs-sampled fixed starting configuration for β > 1, in probability over disorder. At criticality, rescaled stationary and quench autocorrelation processes have universal random limits for Gaussian and Rademacher disorder; the quench limit relaxes to the stationary limit.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":1927,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Universality of critical quench autocorrelations in the Sherrington–Kirkpatrick model","href":"preprints/Universality-of-critical-quench-autocorrelations-in-the-Sherrington-Kirkpatrick-model-October-5-2026/main.pdf"},{"title":"Functional universality of critical SK autocorrelations","href":"preprints/Functional-universality-of-critical-SK-autocorrelations-October-5-2026/critical-sk-autocorrelations.pdf"},{"title":"A spectral gap throughout the high-temperature Sherrington–Kirkpatrick phase","href":"preprints/A-spectral-gap-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026/main.pdf"},{"title":"Cutoff throughout the high-temperature Sherrington–Kirkpatrick phase","href":"preprints/Cutoff-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026/paper.pdf"},{"title":"Critical slowing down in the Sherrington–Kirkpatrick model","href":"preprints/Critical-slowing-down-in-the-Sherrington-Kirkpatrick-model-September-24-2026/paper.pdf"},{"title":"Stretched-exponential barriers for typical SK initial states","href":"preprints/Stretched-exponential-barriers-for-typical-SK-initial-states-September-24-2026/paper.pdf"}],"plainFr":"Un bain de chaleur retourne les spins d'un verre de spin à des instants aléatoires. Le manuscrit affirme un mélange rapide à haute température, un temps intermédiaire à la criticité, un mélange très lent à basse température, et des limites universelles d'autocorrélation.","plainEn":"Heat-bath dynamics flips the spins of a spin glass at random times. The manuscript asserts fast mixing at high temperature, an intermediate time at criticality and much slower mixing at low temperature, together with universal limits for the stationary and quench autocorrelations.","expertFr":"Le manuscrit affirme, pour le bain gaussien sans champ, une coupure de pire départ à l'échelle de la taille sous l'inverse un, un temps d'ordre taille à la puissance deux tiers à la criticité, et un mélange étiré-exponentiel depuis Gibbs au-dessus. À la criticité, les autocorrélations stationnaires et de trempe ont des limites communes aux couplages gaussiens et de Rademacher, et la trempe rejoint l'équilibre.","expertEn":"The manuscript asserts, for the zero-field Gaussian heat bath, worst-start cutoff on the scale of the size below inverse temperature one, mixing of order size to the two thirds at criticality, and stretched-exponential mixing from a Gibbs start above. At criticality, stationary and quench autocorrelations share limits for Gaussian and Rademacher couplings, and the quench joins the stationary state.","sparkFr":"L'intérêt reste dans la dynamique des verres de spin mathématiques, sans matériau affirmé par le manuscrit.","sparkEn":"The interest stays in the dynamics of mathematical spin glasses, with no material asserted by the manuscript."},{"id":"228","titleEn":"Continuum phase transitions for radial pair potentials","titleFr":"Transition du premier ordre pour des potentiels de paires radiaux","claim":"Constructs stable distance-dependent pair interactions for three-dimensional classical particles with a first-order phase transition: the canonical free energy has a derivative jump at one inverse temperature throughout an open density interval. One potential has a divergent repulsive core; another is bounded and continuous with an integrable power-law tail, realizing the type of transition sought in Simon's continuum problem.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A continuum temperature singularity for a radial pair potential","href":"preprints/A-continuum-temperature-singularity-for-a-radial-pair-potential-September-24-2026/paper.pdf"},{"title":"A radial continuum phase transition with algebraic decay","href":"preprints/A-radial-continuum-phase-transition-with-algebraic-decay-September-24-2026/paper.pdf"}],"plainFr":"Un potentiel radial fait dépendre l'énergie classique seulement des distances. Le manuscrit affirme des interactions stables en dimension trois dont l'énergie libre saute de dérivée à une température inverse, sur un intervalle de densités, avec cœur divergent ou potentiel borné.","plainEn":"A radial potential lets classical energy depend only on distances. The manuscript asserts stable three-dimensional interactions whose free energy jumps in derivative at one inverse temperature, over a density interval, with a divergent core or a bounded potential.","expertFr":"Le manuscrit affirme un saut de dérivée descendant, à une température inverse finie, sur un intervalle ouvert de densités, pour des potentiels stables. L'un a un cœur divergent et une queue négligeable devant l'inverse du cube, l'autre est borné et continu à queue intégrable, du type cherché par Simon.","expertEn":"The manuscript asserts a downward derivative jump, at one finite inverse temperature, over an open density interval, for stable potentials. One has a divergent core and a tail negligible next to the inverse cube, and another is bounded and continuous with an integrable tail, of the type sought by Simon.","sparkFr":"Le problème vient de la mécanique statistique mathématique, et le manuscrit n'affirme pas de potentiel utilisé en laboratoire.","sparkEn":"The problem comes from mathematical statistical mechanics, and the manuscript asserts no potential used in a laboratory."},{"id":"229","titleEn":"Exact three- and four-state reconstruction thresholds and four-state tree capacity","titleFr":"Seuils exacts de reconstruction à trois et quatre états","claim":"Proves the exact reconstruction threshold dλ^2 1, with nonreconstruction at equality, for three-state symmetric and four-state ferromagnetic broadcasting on regular trees (d ≥ 2) and observed Poisson trees (mean d > 1 and d > 0, respectively), with Poisson advantage averaged without conditioning on survival. The three-state theorem allows both signs of λ and gives the exact weak-recovery threshold for the symmetric three-community stochastic block model.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The Reconstruction Threshold for the Ferromagnetic Four-State Potts Model","href":"preprints/The-Reconstruction-Threshold-for-the-Ferromagnetic-Four-State-Potts-Model-October-5-2026/four-state-potts.pdf"},{"title":"A Capacity Criterion for Four-State Potts Reconstruction on Trees","href":"preprints/A-Capacity-Criterion-for-Four-State-Potts-Reconstruction-on-Trees-October-5-2026/four-state-capacity.pdf"},{"title":"The exact reconstruction threshold for the three-state symmetric channel","href":"preprints/The-exact-reconstruction-threshold-for-the-three-state-symmetric-channel-September-25-2026/paper.pdf"}],"plainFr":"Sur un arbre, un message part de la racine et se brouille le long des arêtes. Le manuscrit affirme le seuil exact où les feuilles le révèlent encore, pour trois états symétriques et quatre états ferromagnétiques, y compris la récupération faible à trois communautés.","plainEn":"On a tree, a message leaves the root and is noised along the edges. The manuscript asserts the exact threshold at which the leaves still reveal it, for symmetric three-state and ferromagnetic four-state models, including weak recovery with three communities.","expertFr":"Le manuscrit affirme le seuil où le degré fois le carré du paramètre vaut un, sans reconstruction à l'égalité, pour trois états symétriques et quatre états ferromagnétiques, sur les arbres réguliers et de Poisson indiqués. Les deux signes sont permis à trois états, d'où le seuil exact de récupération faible du modèle par blocs à trois communautés.","expertEn":"The manuscript asserts the threshold where degree times the squared parameter equals one, with no reconstruction at equality, for symmetric three states and ferromagnetic four states, on the stated regular and Poisson trees. Both signs are allowed for three states, hence the exact weak-recovery threshold of the three-community block model.","sparkFr":"Le modèle par blocs évoque la détection de communautés, mais le manuscrit n'affirme qu'un seuil mathématique, sans données réelles.","sparkEn":"The block model suggests community detection, but the manuscript asserts only a mathematical threshold, with no real data."},{"id":"230","titleEn":"Exact Hausdorff gauges for SLE","titleFr":"Jauges de Hausdorff pour les courbes de Schramm–Loewner","claim":"Resolves Schramm’s Hausdorff-measure question for chordal SLEκ, 0 8. The explicit gauge r^d( (1/r))^(2-d)/2, d=1+ /8, gives almost surely positive finite measure to every trace segment γ([s,t]) with 0 s t ∞, and finite expected measure to the trace in every bounded disk.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":2000,"yearKnown":true,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"An exact Hausdorff gauge for SLE","href":"preprints/An-exact-Hausdorff-gauge-for-SLE-September-25-2026/An-exact-Hausdorff-gauge-for-SLE-September-25-2026.pdf"},{"title":"An explicit exact Hausdorff gauge for SLE","href":"preprints/An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026/An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026.pdf"}],"plainFr":"Une courbe de Schramm–Loewner est une courbe aléatoire du plan, mesurée par une jauge de Hausdorff. Le manuscrit affirme, pour chaque indice strictement entre zéro et huit, une jauge déterministe positive et finie sur chaque segment, de moyenne finie dans chaque disque.","plainEn":"A Schramm–Loewner curve is a random planar curve, measured by a Hausdorff gauge. The manuscript asserts, for each index strictly between zero and eight, a deterministic gauge positive and finite on every segment, with finite mean in every disk.","expertFr":"Le manuscrit affirme résoudre la question de mesure de Hausdorff de Schramm pour l'évolution chordale d'indice strictement entre zéro et huit. La jauge déterministe explicite, de dimension un plus l'indice divisé par huit, donne presque sûrement une mesure positive et finie à chaque segment de temps positif fini, et une mesure espérée finie à la trace dans chaque disque borné.","expertEn":"The manuscript asserts a resolution of Schramm's Hausdorff-measure question for chordal evolution of index strictly between zero and eight. The explicit deterministic gauge, of dimension one plus the index divided by eight, almost surely gives positive finite measure to every finite positive-time segment, and finite expected measure to the trace in every bounded disk.","sparkFr":"L'intérêt est structurel pour la géométrie des courbes aléatoires, sans application hors des mathématiques affirmée.","sparkEn":"The interest is structural for the geometry of random curves, with no application outside mathematics asserted."},{"id":"231","titleEn":"The free uniform spanning forest is a factor of IID","titleFr":"La forêt couvrante libre comme facteur d'étiquettes","claim":"On every infinite connected locally finite simple unweighted graph, the free uniform spanning forest is a factor of independent vertex labels, by one isomorphism-equivariant rule using no root. Translation-invariant strongly Rayleigh binary processes on every countable group, including invariant determinantal processes with Hermitian positive-contraction kernels, are also factors of IID.","nature":"algebre","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The free uniform spanning forest is a factor of IID","href":"preprints/The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026/The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026.pdf"}],"plainFr":"Une forêt couvrante libre relie au hasard les sommets d'un graphe infini, sans cycle. Le manuscrit affirme qu'elle se reconstruit sur tout graphe simple localement fini, depuis des étiquettes indépendantes et sans racine, et que certains processus invariants le peuvent aussi.","plainEn":"A free spanning forest randomly links vertices of an infinite graph, without cycles. The manuscript asserts that it is rebuilt, on every locally finite simple graph, from independent labels and with no root, as are certain invariant processes.","expertFr":"Le manuscrit affirme que la forêt couvrante uniforme libre est un facteur d'étiquettes indépendantes sur tout graphe infini connexe, localement fini, simple et non pondéré, par une règle sans racine. Il en va de même des processus fortement de Rayleigh invariants sur un groupe dénombrable, noyaux déterminantaux contractions comprises, sans moyennabilité.","expertEn":"The manuscript asserts that the free uniform spanning forest is a factor of independent labels on every infinite connected locally finite simple unweighted graph, by a root-free rule. The same holds for invariant strongly Rayleigh processes on a countable group, determinantal contraction kernels included, with no amenability assumption.","sparkFr":"La reconstruction par étiquettes reste un fait de probabilité sur les graphes, sans procédure appliquée revendiquée.","sparkEn":"Reconstruction from labels remains a fact of probability on graphs, with no applied procedure claimed."},{"id":"232","titleEn":"Gaussian fields and interfaces for triangular-lattice Lipschitz heights","titleFr":"Hauteurs lipschitziennes et champ libre gaussien","claim":"Proves Gaussian free field limits on bounded smooth simply connected domains for triangular-lattice height models: uniform odd heights with increments 0,±2 and two-arc boundary values ±1, and zero-boundary integer Lipschitz heights weighted by fixed x∈[1/ 2,1]. Uniform real Lipschitz heights also converge to a Gaussian field; at a tuned opposite-boundary amplitude, their interface converges to chordal SLE4, establishing Schramm’s real-field/interface predictions.","nature":"probabilites","domain":"hasard","complexity":"frontiere","problemYear":2000,"yearKnown":true,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"Gaussian free-field limits of weighted integer Lipschitz heights","href":"preprints/Gaussian-free-field-limits-of-weighted-integer-Lipschitz-heights-October-6-2026/paper.pdf"},{"title":"The Gaussian free field limit of integer Lipschitz heights with two-arc boundary data","href":"preprints/The-Gaussian-free-field-limit-of-integer-Lipschitz-heights-with-two-arc-boundary-data-October-6-2026/paper.pdf"},{"title":"Uniform real Lipschitz surfaces on the triangular lattice","href":"preprints/Uniform-real-Lipschitz-surfaces-on-the-triangular-lattice-October-6-2026/paper.pdf"}],"plainFr":"Une hauteur lipschitzienne sur le réseau triangulaire varie peu d'un voisin à l'autre. Le manuscrit affirme des limites de champ gaussien sur des domaines lisses, pour des hauteurs impaires ou entières pondérées, et une interface d'indice quatre pour des hauteurs réelles à bord ajusté.","plainEn":"A Lipschitz height on the triangular lattice varies little from neighbor to neighbor. The manuscript asserts Gaussian-field limits on smooth domains, for odd or weighted integer heights, and an interface of index four for real heights with tuned boundary.","expertFr":"Le manuscrit affirme le champ libre gaussien pour des hauteurs impaires d'incréments nuls ou plus ou moins deux, à bords opposés, et pour des hauteurs entières de bord nul d'un poids fixe dans l'intervalle indiqué. Les hauteurs réelles uniformes convergent aussi vers un champ gaussien, et un bord ajusté envoie leur interface vers la courbe chordale d'indice quatre.","expertEn":"The manuscript asserts the Gaussian free field for odd heights of increments zero or plus or minus two, with opposite boundaries, and for zero-boundary integer heights of a fixed weight in the stated interval. Uniform real heights also converge to a Gaussian field, and a tuned boundary sends their interface to the chordal curve of index four.","sparkFr":"L'intérêt est structurel pour les limites de champs discrets, et le manuscrit n'affirme aucun usage extérieur.","sparkEn":"The interest is structural for limits of discrete fields, and the manuscript asserts no outside use."},{"id":"233","titleEn":"The joint critical Ashkin–Teller current limit","titleFr":"Limite jointe des courants critiques d'Ashkin–Teller","claim":"Identifies the joint scaling limit of Ashkin–Teller heights and both complete current-cluster collections throughout the critical line, including the four-state Potts endpoint. In bounded Jordan domains with admissible lattice approximations and wired primal/free dual boundaries, the height converges to the predicted Gaussian free field, and the clusters to canonical recursive sets of that same field, retaining every nesting depth.","nature":"physique-math","domain":"calcul","complexity":"frontiere","problemYear":1952,"yearKnown":false,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"The joint scaling limit of critical Ashkin-Teller currents","href":"preprints/The-joint-scaling-limit-of-critical-Ashkin-Teller-currents-October-6-2026/main.pdf"}],"plainFr":"Le modèle d'Ashkin–Teller couple deux copies d'Ising le long d'une ligne critique. Le manuscrit affirme que hauteur et amas de courant tendent ensemble vers un champ gaussien et vers des ensembles récursifs de ce champ, y compris au point de Potts à quatre états.","plainEn":"The Ashkin–Teller model couples two copies of the Ising model along a line of critical parameters. The manuscript asserts that the height and both complete collections of current clusters converge together to a Gaussian free field and to recursive sets of that same field, including at the four-state Potts point.","expertFr":"Le manuscrit affirme cette limite jointe sur toute la ligne critique, point de Potts compris, dans tout domaine de Jordan borné à approximation admissible. Avec bord primal câblé et bord dual libre, la hauteur tend vers le champ prédit et les amas vers ses ensembles récursifs, à toute profondeur.","expertEn":"The manuscript asserts this joint limit throughout the critical line, four-state Potts endpoint included, in every bounded Jordan domain and for every admissible polygonal approximation. With wired primal boundary and free dual boundary, the height tends to the Gaussian free field of the predicted constant, and the clusters to canonical recursive two-valued local sets, at every nesting depth.","sparkFr":"La piste reste dans les limites d'échelle critiques, sans réalisation physique affirmée par le manuscrit.","sparkEn":"The lead stays in critical scaling limits, with no physical realization asserted by the manuscript."},{"id":"234","titleEn":"All-temperature pressure of orthogonally invariant Ising spin glasses","titleFr":"Pression des verres de spin orthogonalement invariants","claim":"Gives an exact variational formula for the limiting pressure of orthogonally invariant Ising spin glasses at every fixed temperature, both almost surely and in expectation. The coupling matrix is a Haar-random rotation of a deterministic spectrum converging to a compactly supported law, with extreme eigenvalues converging to its support edges. The zero-field ground-state energy follows as temperature tends to zero.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"All-temperature pressure for orthogonally invariant Ising spin glasses","href":"preprints/All-temperature-pressure-for-orthogonally-invariant-Ising-spin-glasses-September-25-2026/paper.pdf"}],"plainFr":"Ce verre de spin couple des variables binaires par une matrice tournée au hasard. Le manuscrit affirme une formule exacte de la pression limite à toute température, presque sûrement et en moyenne, puis l'énergie fondamentale sans champ quand la température s'annule.","plainEn":"This spin glass couples binary variables by a matrix whose eigen-directions are drawn uniformly among rotations. The manuscript asserts an exact variational formula for the limiting pressure at every fixed temperature, almost surely and on average, and deduces the zero-field ground-state energy as temperature vanishes.","expertFr":"Le manuscrit affirme cette formule pour une rotation de Haar d'un spectre à limite compacte, sans valeur propre aberrante. La convergence vaut en espérance et presque sûrement, aussi avec des champs convergeant en transport d'ordre un, et l'énergie fondamentale sans champ s'obtient à température nulle.","expertEn":"The manuscript asserts this formula when the matrix is a Haar rotation of a deterministic spectrum converging to a compactly supported law, with extreme eigenvalues tending to the edges of the support. Convergence holds in expectation and almost surely, including with deterministic fields whose empirical laws converge in first-moment transport, and the zero-field ground-state energy is obtained at zero temperature.","sparkFr":"L'énergie fondamentale reste ici un objet variationnel, et le manuscrit n'affirme aucun verre matériel.","sparkEn":"The ground-state energy remains here a variational object, and the manuscript asserts no material glass."},{"id":"235","titleEn":"Limiting random SAT thresholds, sharp variance and computability","titleFr":"Seuils du problème SAT aléatoire, variance et calculabilité","claim":"For random k-SAT with independent uniformly signed proper clauses sampled with replacement, proves finite positive limiting thresholds and hitting-time variance _k(n) for every fixed k ≥ 3, and computability of the 3-SAT threshold. We credit Gaia Carenini with priority for resolving the threshold-existence conjecture in her concurrent [ECCC TR26-229](https://eccc.weizmann.ac.il/report/2026/229/), made public October 5, 2026; this family supplies another proof and the sharper variance and computability results.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A Limiting Satisfiability Threshold for Every Fixed Clause Size","href":"preprints/A-Limiting-Satisfiability-Threshold-for-Every-Fixed-Clause-Size-September-25-2026/article.pdf"},{"title":"Linear Variance of the Random 3-SAT Hitting Time","href":"preprints/Linear-Variance-of-the-Random-3-SAT-Hitting-Time-October-5-2026/linear-variance-of-the-random-3-sat-hitting-time.pdf"},{"title":"Variance of the Random k-SAT Hitting Time","href":"preprints/Variance-of-the-Random-k-SAT-Hitting-Time-September-27-2026/article.pdf"},{"title":"Computing the Random 3-SAT Threshold","href":"preprints/Computing-the-Random-3-SAT-Threshold-September-27-2026/article.pdf"}],"plainFr":"Des clauses aléatoires demandent si des contraintes sur des bits peuvent toutes être vraies. Le manuscrit affirme, dès trois littéraux, un seuil limite fini et positif, une variance du temps d'atteinte et la calculabilité du seuil à trois, en créditant une priorité concurrente.","plainEn":"Random clauses ask whether constraints on bits can all be true. The manuscript asserts, from three literals on, a finite positive limiting threshold, a hitting-time variance and computability of the three-literal threshold, while crediting a concurrent priority.","expertFr":"Le manuscrit affirme ces seuils et cette variance pour tout entier fixé au moins trois, ainsi que la calculabilité du seuil à trois littéraux. Il crédite Gaia Carenini de la priorité sur l'existence du seuil, dans un rapport concurrent rendu public le 5 octobre 2026, et présente une autre preuve avec les résultats plus fins de variance et de calculabilité.","expertEn":"The manuscript asserts these thresholds and this variance for every fixed integer at least three, together with computability of the three-literal threshold. It credits Gaia Carenini with priority for the existence of the threshold, in a concurrent report made public on 5 October 2026, and gives another proof with the sharper variance and computability results.","sparkFr":"Le problème est classique en informatique théorique, mais le manuscrit n'affirme qu'un fait de seuil, sans usage algorithmique pratique.","sparkEn":"The problem is classical in theoretical computer science, but the manuscript asserts only a threshold fact, with no practical algorithmic use."},{"id":"236","titleEn":"The exact factor-of-IID threshold for free Ising spins on trees","titleFr":"Seuil de facteur d'étiquettes pour l'Ising libre sur l'arbre","claim":"Determines when the free zero-field ferromagnetic Ising state on the infinite d-regular tree is a factor of independent vertex labels: exactly when β≤(d-1)^-1/2, including equality, for d ≥ 3 and β ≥ 0. The construction uses no root and is almost surely equivariant for each fixed tree automorphism, resolving the ferromagnetic case of Lyons's question.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"The sharp factor-of-IID threshold for the free Ising model on regular trees","href":"preprints/The-sharp-factor-of-IID-threshold-for-the-free-Ising-model-on-regular-trees-September-26-2026/article.pdf"}],"plainFr":"Sur l'arbre régulier infini, l'Ising ferromagnétique libre pose des spins plus ou moins. Le manuscrit affirme qu'il se reconstruit par étiquettes indépendantes, sans racine, jusqu'à l'inverse de la racine du degré diminué de un, borne comprise.","plainEn":"On an infinite regular tree, the zero-field ferromagnetic Ising model assigns plus or minus spins. The manuscript asserts that this free measure can be rebuilt from independent labels, with no root, exactly up to the inverse temperature equal to the reciprocal square root of the degree minus one, equality included.","expertFr":"Le manuscrit affirme ce critère pour tout degré au moins trois et toute température inverse positive ou nulle, égalité comprise, ce qui règle le sens direct conjecturé par Nam, Sly et Zhang, la réciproque stricte étant connue. La construction est presque sûrement équivariante pour chaque automorphisme fixé de l'arbre, et répond au cas ferromagnétique de la question de Lyons.","expertEn":"The manuscript asserts this criterion for every degree at least three and every nonnegative inverse temperature, equality included, settling the direct implication conjectured by Nam, Sly and Zhang, the strict converse being known. The construction is almost surely equivariant for each fixed tree automorphism, and answers the ferromagnetic case of Lyons's question.","sparkFr":"Reconstruire des spins par des étiquettes reste un fait de probabilités sur les arbres, sans réseau réel affirmé.","sparkEn":"Rebuilding spins from labels remains a fact of probability on trees, with no real network asserted."},{"id":"237","titleEn":"The three-quarter exponent for honeycomb self-avoiding walk","titleFr":"L'exposant trois quarts des marches en nid d'abeille","claim":"Proves the diameter form of Nienhuis's predicted three-quarter exponent: a uniformly chosen n-step self-avoiding walk on the honeycomb lattice has diameter n^3/4+o(1). Its local mass and covering numbers have exponent 4/3. These estimates hold at every sufficiently large fixed length, simultaneously across scales, with arbitrarily high polynomial probability.","nature":"algebre","domain":"hasard","complexity":"avance","problemYear":1947,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"Radial transfer estimates and polygon length laws for honeycomb walks","href":"preprints/Radial-transfer-estimates-and-polygon-length-laws-for-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Critical honeycomb chords with prescribed boundary endpoints","href":"preprints/Critical-honeycomb-chords-with-prescribed-boundary-endpoints-September-26-2026/main.pdf"},{"title":"Cylinder loop weights and planar nesting","href":"preprints/Cylinder-loop-weights-and-planar-nesting-September-26-2026/main.pdf"},{"title":"Mass and covering exponents for fixed-length honeycomb walks","href":"preprints/Mass-and-covering-exponents-for-fixed-length-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Signed cylinder propagation and marked polygons on the honeycomb lattice","href":"preprints/Signed-cylinder-propagation-and-marked-polygons-on-the-honeycomb-lattice-September-26-2026/main.pdf"},{"title":"Cylinder amplitudes and logarithmic bridge-length windows on the honeycomb lattice","href":"preprints/Cylinder-amplitudes-and-logarithmic-bridge-length-windows-on-the-honeycomb-lattice-September-26-2026/main.pdf"}],"plainFr":"Une marche auto-évitante en nid d'abeille ne revisite aucun sommet. Le manuscrit affirme que son diamètre suit la longueur à la puissance trois quarts, et que masse et recouvrement ont l'exposant quatre tiers, avec une très forte probabilité.","plainEn":"A self-avoiding walk on the honeycomb lattice is a path that revisits no vertex. The manuscript asserts that the diameter of a uniform walk of a given length is of the order of that length to the power three quarters, and that mass and covering numbers have exponent four thirds, with very high probability.","expertFr":"Le manuscrit affirme l'exposant trois quarts de Nienhuis pour le diamètre, et quatre tiers pour la masse locale et le recouvrement, à toutes les échelles avec une probabilité polynomiale arbitrairement haute. Il affirme aussi des queues de diamètre d'exposants moins deux et moins deux tiers pour des polygones, d'où le même diamètre en probabilité.","expertEn":"The manuscript asserts the diameter form of the three-quarter exponent predicted by Nienhuis, with exponent four thirds for local mass and covering, simultaneously across scales and with arbitrarily high polynomial probability, at every large fixed length. It also asserts diameter tails of exponents minus two and minus two thirds for unrooted and length-weighted polygons, hence the same diameter in probability.","sparkFr":"L'intérêt est structurel pour les chemins aléatoires, et le manuscrit n'affirme aucune mesure hors des mathématiques.","sparkEn":"The interest is structural for random paths, and the manuscript asserts no measurement outside mathematics."},{"id":"238","titleEn":"Optimal logarithmic mixing of the Thorp shuffle","titleFr":"Mélange logarithmique optimal du battage de Thorp","claim":"Proves that the Thorp shuffle randomizes N=2^d labeled cards in ( N) physical shuffles, settling its optimal mixing order for power-of-two deck sizes. Convergence is in total variation from the worst initial ordering and concerns the entire permutation, not just individual card positions.","nature":"probabilites","domain":"hasard","complexity":"lecture","problemYear":1973,"yearKnown":true,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"Optimal-order mixing of the Thorp shuffle","href":"preprints/Optimal-order-mixing-of-the-Thorp-shuffle-September-26-2026/paper.pdf"},{"title":"Random coordinate frames and partial permutation laws","href":"preprints/Random-coordinate-frames-and-partial-permutation-laws-September-26-2026/main.pdf"},{"title":"From partial permutation information to Fourier bounds","href":"preprints/From-partial-permutation-information-to-Fourier-bounds-September-26-2026/main.pdf"},{"title":"Conditional information under deterministic coordinate sweeps","href":"preprints/Conditional-information-under-deterministic-coordinate-sweeps-September-26-2026/main.pdf"},{"title":"Conditional permutations in a revealed switching environment","href":"preprints/Conditional-permutations-in-a-revealed-switching-environment-September-26-2026/paper.pdf"},{"title":"Routing densities and representation contraction for Thorp sweeps","href":"preprints/Routing-densities-and-representation-contraction-for-Thorp-sweeps-September-26-2026/paper.pdf"}],"plainFr":"Le battage de Thorp mélange un paquet dont la taille est une puissance de deux. Le manuscrit affirme qu'un nombre de coups de l'ordre du logarithme rend toute la permutation proche de l'uniforme depuis le pire départ, et que cet ordre est optimal.","plainEn":"The Thorp shuffle is a precise way of mixing a deck whose number of cards is a power of two. The manuscript asserts that a number of shuffles proportional to the logarithm of the size brings the entire permutation close to uniform, from the worst initial order, and that this order of magnitude is optimal.","expertFr":"Le manuscrit affirme un mélange en un nombre de battages de l'ordre de l'exposant, pour une taille puissance de deux. Après mille six cents fois cet exposant, toute la permutation tend vers l'uniforme en variation totale, uniformément sur le départ, et le nombre d'issues donne une borne inférieure de deux fois l'exposant moins une constante.","expertEn":"The manuscript asserts that the shuffle on two to the stated power mixes in a number of complete shuffles of the order of that exponent. After one thousand six hundred times that exponent, the law of the entire permutation converges to uniform in total variation as the exponent tends to infinity, uniformly over the initial deck, while a support count gives a lower bound of twice the exponent minus a constant.","sparkFr":"Il s'agit d'un battage de cartes au sens mathématique, et le manuscrit ne revendique aucun usage de salon ni de machine.","sparkEn":"This is a card shuffle in the mathematical sense, and the manuscript claims no parlor use and no machine."},{"id":"239","titleEn":"Sharp singularity rates for symmetric random sign matrices","titleFr":"Singularité des matrices de signes symétriques","claim":"Determines the sharp exponential singularity rate of symmetric random sign matrices with independent entries on and above the diagonal. Uniform signs give ( A_n=0)=(1/2+o(1))^n; for fixed bias p∈(0,1) \\1/2\\, the rate is (p^2+(1-p)^2+o(1))^n. In the biased case, agreeing rows attain this rate.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-03","lean":false,"pdfs":[{"title":"The sharp exponential rate of singularity for symmetric Bernoulli matrices","href":"preprints/The-sharp-exponential-rate-of-singularity-for-symmetric-Bernoulli-matrices-October-3-2026/symmetric-bernoulli-singularity.pdf"},{"title":"The sharp singularity rate for biased symmetric sign matrices","href":"preprints/The-sharp-singularity-rate-for-biased-symmetric-sign-matrices-October-4-2026/biased-symmetric-sign-singularity.pdf"}],"plainFr":"Une matrice de signes symétrique est un tableau carré de plus et de moins, symétrique par rapport à la diagonale. Le manuscrit affirme le taux exponentiel exact de la probabilité qu'elle soit singulière, pour des signes uniformes comme pour un biais fixe autre qu'un demi.","plainEn":"A symmetric sign matrix is a square array of pluses and minuses, symmetric across the diagonal. The manuscript asserts the exact exponential rate of the probability that it is singular, for uniform signs as well as for a fixed bias other than one half.","expertFr":"Le manuscrit affirme que, pour des signes uniformes indépendants sur et au-dessus de la diagonale, la probabilité de singularité vaut un demi plus un terme négligeable, le tout à la puissance de la taille. Pour un biais fixé autre qu'un demi, le taux est le carré du biais plus le carré du complémentaire, plus un terme négligeable, à cette même puissance, et des lignes identiques atteignent ce taux.","expertEn":"The manuscript asserts that, for independent uniform signs on and above the diagonal, the singularity probability is one half plus a negligible term, all to the power of the size. For a fixed bias other than one half, the rate is the square of the bias plus the square of its complement, plus a negligible term, to that same power, and agreeing rows attain this rate.","sparkFr":"Le taux de singularité reste un fait d'aléa matriciel, sans application numérique revendiquée par le manuscrit.","sparkEn":"The singularity rate remains a fact of random matrices, with no numerical application claimed by the manuscript."},{"id":"240","titleEn":"Shelah's eventual categoricity and the prescribed-threshold obstruction","titleFr":"Catégoricité éventuelle de Shelah et obstruction de seuil","claim":"Proves Shelah's eventual categoricity conjecture in ZFC: for each bound on the Löwenheim–Skolem number, a uniform threshold makes categoricity of an abstract elementary class in one cardinal above that threshold imply categoricity throughout the same tail. Categoricity means uniqueness up to isomorphism at a given cardinality. Under the continuum hypothesis, a proposed specific Hanf threshold need not suffice.","nature":"logique","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A CH obstruction to a prescribed categoricity threshold","href":"preprints/A-CH-Obstruction-to-a-Prescribed-Categoricity-Threshold-September-24-2026/paper.pdf"},{"title":"Eventual categoricity for abstract elementary classes","href":"preprints/Eventual-Categoricity-for-Abstract-Elementary-Classes-September-24-2026/paper.pdf"}],"plainFr":"Une classe est catégorique à une taille si elle n'a, à isomorphisme près, qu'un modèle. Le manuscrit affirme qu'en théorie usuelle la catégoricité assez haut emplit une queue de cardinaux, mais que sous l'hypothèse du continu un seuil proposé peut échouer.","plainEn":"A class is categorical at a size if it has, up to isomorphism, only one model. The manuscript asserts that in ordinary set theory categoricity high enough fills a tail of cardinals, but that under the continuum hypothesis a proposed threshold may fail.","expertFr":"Le manuscrit affirme la catégoricité éventuelle de Shelah : chaque borne de Löwenheim–Skolem a un seuil qui étend la catégoricité d'un cardinal à toute la queue. Sous l'hypothèse du continu, une classe dénombrable est catégorique très haut mais a deux modèles non isomorphes au seuil proposé, forme non démontrable si la théorie est cohérente.","expertEn":"The manuscript asserts Shelah's eventual categoricity: each Löwenheim–Skolem bound has a threshold extending categoricity at one cardinal to the whole tail. Under the continuum hypothesis a countable class is categorical very high up but has two nonisomorphic models at the proposed threshold, a form unprovable if the theory is consistent.","sparkFr":"L'intérêt est structurel en théorie des modèles, et le manuscrit n'affirme aucun fondement utilisable hors des mathématiques.","sparkEn":"The interest is structural in model theory, and the manuscript asserts no foundation usable outside mathematics."},{"id":"241","titleEn":"Rigidity of the Turing degrees","titleFr":"Rigidité de l'ordre des degrés de Turing","claim":"Every order automorphism of the Turing degrees is the identity, resolving their rigidity problem. Thus no nontrivial relabeling of degrees preserves the ordering by relative computability.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Rigidity of the Turing degrees","href":"preprints/Rigidity-of-the-Turing-degrees-September-24-2026/paper.pdf"}],"plainFr":"Un degré de Turing regroupe les problèmes de calcul qui se résolvent les uns à partir des autres. Le manuscrit affirme que le seul automorphisme de cet ordre est l'identité, donc qu'aucun réétiquetage non trivial ne préserve la comparaison par calculabilité relative.","plainEn":"A Turing degree groups together computational problems that can be solved from one another. The manuscript asserts that the only automorphism of this order is the identity, so that no nontrivial relabeling preserves the comparison by relative computability.","expertFr":"Le manuscrit affirme que tout automorphisme d'ordre de l'ensemble ordonné complet des degrés de Turing est l'identité. Ainsi aucun réétiquetage non trivial des degrés ne préserve l'ordre par calculabilité relative, ce qui résout positivement le problème de rigidité.","expertEn":"The manuscript asserts that every order automorphism of the full partial order of Turing degrees is the identity. Thus no nontrivial relabeling of degrees preserves the ordering by relative computability, resolving the rigidity problem positively.","sparkFr":"La rigidité concerne l'ordre abstrait de la calculabilité, sans conséquence pratique affirmée par le manuscrit.","sparkEn":"The rigidity concerns the abstract order of computability, with no practical consequence asserted by the manuscript."},{"id":"242","titleEn":"Single-fold Diophantine representations and undecidability under an at-most-one-solution promise","titleFr":"Représentations diophantiennes à une seule solution auxiliaire","claim":"Every recursively enumerable set of tuples of natural numbers has a Diophantine representation with exactly one auxiliary solution for each member and none for nonmembers. This proves the single-fold conjecture and hence the finite-fold conjecture. Diophantine solvability over the nonnegative integers remains undecidable even with an at-most-one-solution promise.","nature":"nombres","domain":"nombres","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Single-fold Diophantine representations","href":"preprints/Single-fold-Diophantine-representations-September-24-2026/paper.pdf"}],"plainFr":"Une équation polynomiale peut décrire des entiers par une solution auxiliaire. Le manuscrit affirme que tout ensemble énumérable de listes en a exactement une par élément, si bien que savoir s'il existe une solution reste indécidable même sous la promesse d'au plus une solution.","plainEn":"A polynomial equation can describe integers by an auxiliary solution. The manuscript asserts that every enumerable set of lists has exactly one per member, so solvability stays undecidable even under a promise of at most one solution.","expertFr":"Le manuscrit affirme une représentation polynomiale avec exactement un tuple auxiliaire complet pour chaque élément et aucun pour les autres, ce qui prouve la conjecture à un seul pli et donc celle à nombre fini de plis. La résolubilité diophantienne sur les entiers non négatifs reste indécidable sous une promesse d'au plus une solution.","expertEn":"The manuscript asserts a polynomial representation with exactly one complete auxiliary tuple for each member and none for the others, which proves the single-fold conjecture and hence the finite-fold conjecture. Diophantine solvability over the nonnegative integers remains undecidable under an at-most-one-solution promise.","sparkFr":"L'indécidabilité est ici un fait de logique, et le manuscrit ne revendique aucun test pratique d'équations.","sparkEn":"Undecidability is here a fact of logic, and the manuscript claims no practical test of equations."},{"id":"243","titleEn":"Separating choiceless counting from polynomial time and witnessed choice","titleFr":"Le temps polynomial sans choix ne capture pas tout le temps polynomial","claim":"Confirms the Blass–Gurevich–Shelah noncapture conjecture: consistency of a linear system over 𝔽3 defines a polynomial-time query on unordered finite structures that choiceless polynomial time with counting cannot express. A separate result shows that adding witnessed symmetric choice strictly increases expressive power. Both separations hold for the full counting formalism, allowing hereditarily finite sets of arbitrary finite rank.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Choiceless polynomial time with counting does not capture polynomial time","href":"preprints/Choiceless-polynomial-time-with-counting-does-not-capture-polynomial-time-September-23-2026/paper.pdf"},{"title":"Witnessed symmetric choice is strictly stronger than choiceless polynomial time with counting","href":"preprints/Witnessed-symmetric-choice-is-strictly-stronger-than-choiceless-polynomial-time-with-counting-September-24-2026/paper.pdf"}],"plainFr":"Le calcul sans choix ne peut pas nommer librement les éléments d'une structure non ordonnée. Le manuscrit affirme qu'une cohérence linéaire sur le corps à trois éléments est polynomiale mais inexprimable avec comptage, et que le choix symétrique témoigné augmente l'expression.","plainEn":"Choiceless computation cannot freely name elements of an unordered structure. The manuscript asserts that linear consistency over the three-element field is polynomial-time but inexpressible with counting, and that witnessed symmetric choice increases expression.","expertFr":"Le manuscrit affirme la conjecture de non-capture de Blass, Gurevich et Shelah pour le formalisme complet, qui autorise les ensembles héréditairement finis de rang fini arbitraire. Ajouter le choix symétrique témoigné augmente strictement la puissance d'expression, et les deux séparations valent pour ce formalisme complet.","expertEn":"The manuscript asserts the noncapture conjecture of Blass, Gurevich and Shelah for the full formalism, which allows hereditarily finite sets of arbitrary finite rank. Adding witnessed symmetric choice strictly increases expressive power, and both separations hold for this full formalism.","sparkFr":"La séparation concerne la logique du calcul, et le manuscrit n'affirme aucun programme ni aucune machine.","sparkEn":"The separation concerns the logic of computation, and the manuscript asserts no program and no machine."},{"id":"244","titleEn":"The Partition Principle does not imply Choice","titleFr":"Le principe de partition n'implique pas l'axiome du choix","claim":"Assuming ZF is consistent, constructs a model in which every surjective image of a set injects into that set, yet the axiom of choice fails. Choice for ordinal-indexed families still holds. From any countable transitive model of ZFC, a separate construction gives a transitive symmetric extension with these properties and no new countable sequences of ground-model elements.","nature":"logique","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Partition Principle does not imply Choice","href":"preprints/The-Partition-Principle-does-not-imply-Choice-September-24-2026/partition-principle-without-choice.pdf"}],"plainFr":"Le choix prend un élément dans chaque ensemble, et le principe de partition réinjecte seulement une image. Le manuscrit affirme que, si la théorie sans choix est cohérente, ce principe peut valoir avec le choix sur les ordinaux, alors que l'axiome du choix échoue.","plainEn":"Choice picks an element from each set, and the partition principle only injects an image back. The manuscript asserts that if the theory without choice is consistent, the principle can hold together with ordinal choice, while full choice fails.","expertFr":"Le manuscrit affirme que la cohérence de la théorie sans choix implique celle de cette théorie avec le principe de partition, le choix pour les familles indexées par des ordinaux, et la négation de l'axiome du choix. Depuis tout modèle transitif dénombrable de la théorie avec choix, une extension symétrique transitive garde les mêmes ordinaux et n'ajoute aucune suite dénombrable d'éléments du modèle de base.","expertEn":"The manuscript asserts that consistency of the theory without choice implies consistency of that theory with the partition principle, choice for ordinal-indexed families, and the negation of the axiom of choice. From every countable transitive model of the theory with choice, a transitive symmetric extension keeps the same ordinals and adds no countable sequence of ground-model elements.","sparkFr":"L'intérêt est structurel en théorie des ensembles, sans conséquence hors des mathématiques affirmée.","sparkEn":"The interest is structural in set theory, with no consequence outside mathematics asserted."},{"id":"245","titleEn":"Weak normalization implies strong normalization in pure type systems","titleFr":"La normalisation faible implique la normalisation forte","claim":"Proves that weak normalization implies strong normalization for every pure type system: if every legal expression in every valid context has a β-normal form, every β-reduction sequence terminates. This resolves the β-Barendregt–Geuvers–Klop conjecture, including nonfunctional rules and open contexts.","nature":"logique","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Weak and strong normalization in pure type systems","href":"preprints/Weak-and-strong-normalization-in-pure-type-systems-September-25-2026/paper.pdf"}],"plainFr":"Réduire une expression typée, c'est la simplifier jusqu'à une forme qui ne bouge plus. Le manuscrit affirme que si toute expression légitime a une telle forme, toute suite de réductions s'arrête, même pour des règles non fonctionnelles et des contextes ouverts.","plainEn":"In a pure type system, reducing an expression means simplifying applications, and a normal form simplifies no further. The manuscript asserts that if every legitimate expression has a normal form, then every reduction sequence terminates, including with nonfunctional rules and open contexts.","expertFr":"Le manuscrit affirme que, dans tout système de types pur, la normalisation faible implique la normalisation forte, les deux propriétés portant sur toutes les expressions légales dans tous les contextes valides, la réduction agissant aussi dans les annotations de types. Aucune hypothèse de fonctionnalité n'est requise, ce qui résout la conjecture bêta de Barendregt, Geuvers et Klop.","expertEn":"The manuscript asserts that, in every pure type system, weak normalization implies strong normalization, both properties ranging over all legal expressions in all valid contexts, with reduction also acting inside type annotations. No functionality hypothesis is required, which resolves the beta conjecture of Barendregt, Geuvers and Klop.","sparkFr":"Le résultat concerne la théorie de la réécriture typée, et le manuscrit n'affirme aucun compilateur ni aucun logiciel.","sparkEn":"The result concerns typed rewriting theory, and the manuscript asserts no compiler and no software."},{"id":"246","titleEn":"Cannon's conjecture","titleFr":"La conjecture de Cannon sur les groupes à bord sphérique","claim":"Every word-hyperbolic group with boundary homeomorphic to S2 admits a proper cocompact isometric action on hyperbolic three-space with finite kernel, proving Cannon's conjecture. Every torsion-free such group is therefore the fundamental group of a closed hyperbolic three-manifold.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1990,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A Modulus Proof of Cannon’s Conjecture","href":"preprints/A-Modulus-Proof-of-Cannons-Conjecture-September-23-2026/paper.pdf"}],"plainFr":"Un groupe hyperbolique ressemble de loin à un espace de courbure négative. Le manuscrit affirme que si son bord est une sphère, il agit proprement et cocompactement sur l'espace hyperbolique de dimension trois, et sans torsion il est le groupe fondamental d'une variété fermée.","plainEn":"A hyperbolic group looks from afar like a negatively curved space. The manuscript asserts that if its boundary is a sphere, it acts properly and cocompactly on three-dimensional hyperbolic space, and without torsion it is the fundamental group of a closed manifold.","expertFr":"Le manuscrit affirme que tout groupe hyperbolique au sens des mots, de bord homéomorphe à la sphère de dimension deux, admet une action isométrique propre et cocompacte sur l'espace hyperbolique de dimension trois, à noyau fini. Tout tel groupe sans torsion est donc le groupe fondamental d'une variété hyperbolique fermée de dimension trois.","expertEn":"The manuscript asserts that every word-hyperbolic group whose boundary is homeomorphic to the two-sphere admits a proper cocompact isometric action on hyperbolic three-space with finite kernel. Every torsion-free such group is therefore the fundamental group of a closed hyperbolic three-manifold.","sparkFr":"Le lien avec les variétés est interne à la géométrie, et le manuscrit n'affirme aucun modèle d'espace physique.","sparkEn":"The link with manifolds is internal to geometry, and the manuscript asserts no model of physical space."},{"id":"247","titleEn":"An infinite finitely presented residually finite 2-group and a finitely presented nil algebra","titleFr":"Un 2-groupe infini, résiduellement fini et de présentation finie","claim":"Constructs an infinite finitely presented residually finite group whose elements all have finite 2-power order, answering the finitely presented Burnside problem negatively even in this class. The construction also yields an infinite-dimensional finitely presented nil associative 𝔽2-algebra and a finitely presented infinite-dimensional algebraic unitization, giving negative answers to the corresponding nilpotence and Kurosh finiteness questions.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1941,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An infinite finitely presented residually finite 2-group","href":"preprints/An-infinite-finitely-presented-residually-finite-2-group-October-5-2026/residually-finite-torsion.pdf"},{"title":"An infinite finitely presented periodic group","href":"preprints/An-infinite-finitely-presented-periodic-group-September-23-2026/paper.pdf"}],"plainFr":"Burnside demandait si un groupe finiment présenté, à éléments d'ordre fini, est forcément fini. Le manuscrit affirme un contre-exemple infini et résiduellement fini, d'ordres puissances de deux non bornées, ainsi qu'une algèbre nil infinie finiment présentée.","plainEn":"Burnside asked whether a finitely presented group of finite-order elements must be finite. The manuscript asserts an infinite residually finite counterexample of unbounded two-power orders, together with an infinite finitely presented nil algebra.","expertFr":"Le manuscrit affirme un groupe infini, finiment présenté et résiduellement fini, dont les ordres sont des puissances de deux finies et non bornées. Il en tire une algèbre nil associative infinie, finiment présentée sur le corps à deux éléments, et une unitarisation algébrique du même genre, contre Kurosh et la nilpotence.","expertEn":"The manuscript asserts an infinite finitely presented residually finite group of unbounded finite two-power orders. It also yields an infinite-dimensional finitely presented associative nil algebra over the two-element field, and an algebraic unitization of the same kind, against Kurosh and nilpotence.","sparkFr":"L'intérêt est structurel en théorie des groupes et des algèbres, sans réalisation hors des mathématiques affirmée.","sparkEn":"The interest is structural in the theory of groups and algebras, with no realization outside mathematics asserted."},{"id":"248","titleEn":"Thompson's group F is nonamenable","titleFr":"Le groupe de Thompson F n'est pas moyennable","claim":"Proves that Thompson's group F, the group of dyadic piecewise linear homeomorphisms of the interval, is nonamenable, resolving its longstanding amenability problem.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1965,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Thompson's group F is nonamenable","href":"preprints/Thompsons-group-F-is-nonamenable-September-23-2026/paper.pdf"}],"plainFr":"Le groupe de Thompson est formé des déformations linéaires par morceaux de l'intervalle, à coupures dyadiques. Le manuscrit affirme que ce groupe n'est pas moyennable, ce qui confirme la conjecture de Geoghegan et résout le problème de moyennabilité.","plainEn":"Thompson's group consists of the piecewise linear deformations of the interval with dyadic breaks. The manuscript asserts that this group is nonamenable, which confirms Geoghegan's conjecture and resolves the amenability problem.","expertFr":"Le manuscrit affirme que le groupe des homéomorphismes linéaires par morceaux dyadiques de l'intervalle n'est pas moyennable. Cela confirme la conjecture de Geoghegan.","expertEn":"The manuscript asserts that the group of dyadic piecewise linear homeomorphisms of the interval is nonamenable. This confirms Geoghegan's conjecture.","sparkFr":"La non-moyennabilité reste une propriété interne du groupe, et le manuscrit n'affirme aucun phénomène hors des mathématiques.","sparkEn":"Nonamenability remains an internal property of the group, and the manuscript asserts no phenomenon outside mathematics."},{"id":"249","titleEn":"A finitely generated Eilenberg–Ganea counterexample","titleFr":"Contre-exemple de type fini à la conjecture d'Eilenberg–Ganea","claim":"Constructs a finitely generated residually finite group with integral cohomological dimension two and geometric dimension three, disproving the Eilenberg–Ganea conjecture. It has no two-dimensional classifying space, even with infinitely many cells.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A finitely generated counterexample to the Eilenberg–Ganea conjecture","href":"preprints/A-finitely-generated-counterexample-to-the-Eilenberg-Ganea-conjecture-September-23-2026/paper.pdf"}],"plainFr":"La dimension cohomologique mesure un groupe, la dimension géométrique l'espace qui le classe. Le manuscrit affirme un groupe de type fini et résiduellement fini, de dimensions deux et trois, donc sans classifiant de dimension deux, même avec une infinité de cellules.","plainEn":"Cohomological dimension measures a group, geometric dimension the space that classifies it. The manuscript asserts a finitely generated residually finite group of dimensions two and three, hence no two-dimensional classifying space, even with infinitely many cells.","expertFr":"Le manuscrit affirme un groupe de type fini, résiduellement fini, de dimension cohomologique entière deux et de dimension géométrique trois. Cela réfute la conjecture d'Eilenberg–Ganea, y compris si l'on autorise une infinité de cellules dans un éventuel espace classifiant de dimension deux.","expertEn":"The manuscript asserts a finitely generated residually finite group of integral cohomological dimension two and geometric dimension three. This disproves the Eilenberg–Ganea conjecture, even if one allows infinitely many cells in a possible two-dimensional classifying space.","sparkFr":"L'écart entre les deux dimensions est un fait de topologie algébrique, sans modèle hors des mathématiques affirmé.","sparkEn":"The gap between the two dimensions is a fact of algebraic topology, with no model outside mathematics asserted."},{"id":"250","titleEn":"Boone–Higman embeddings with higher finiteness","titleFr":"Plongements de Boone–Higman dans des groupes simples","claim":"A finitely generated group has decidable word problem exactly when it embeds in a finitely presented simple group, proving the Boone–Higman conjecture. The target can have type F∞: a classifying space with finitely many cells in each dimension. A single group of type F∞ can also contain every finitely presented group.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1911,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Finite algebraic envelopes and the Boone–Higman conjecture","href":"preprints/Finite-algebraic-envelopes-and-the-Boone-Higman-conjecture-September-23-2026/paper.pdf"},{"title":"Simple F∞ overgroups of groups with decidable word problem","href":"preprints/Simple-F-infinity-overgroups-of-groups-with-decidable-word-problem-September-23-2026/paper.pdf"},{"title":"A universal group of type F∞","href":"preprints/A-universal-group-of-type-F-infinity-September-23-2026/paper.pdf"}],"plainFr":"Le problème des mots demande si un produit de générateurs vaut l'identité. Le manuscrit affirme qu'un groupe de type fini l'a décidable exactement s'il se plonge dans un groupe simple finiment présenté, à classifiant fini en chaque dimension.","plainEn":"The word problem asks whether one can decide that a product of generators equals the identity. The manuscript asserts that a finitely generated group has this problem decidable exactly when it embeds in a finitely presented simple group, and that the target can have a classifying space finite in each dimension.","expertFr":"Le manuscrit affirme la conjecture de Boone–Higman sous cette forme d'équivalence. La cible peut être de type fini en chaque dimension d'un espace classifiant, et un seul groupe de ce type peut contenir tous les groupes de présentation finie.","expertEn":"The manuscript asserts the Boone–Higman conjecture in this equivalence form. The target can be of finite type in each dimension of a classifying space, and a single group of that type can contain every finitely presented group.","sparkFr":"La décidabilité du problème des mots reste un critère algébrique, sans procédure pratique affirmée au-delà de l'énoncé.","sparkEn":"Decidability of the word problem remains an algebraic criterion, with no practical procedure asserted beyond the statement."},{"id":"251","titleEn":"Amenability, unitarizability, and strong Ulam stability","titleFr":"Moyennabilité, unitarisabilité et stabilité forte d'Ulam","claim":"Resolves Dixmier's problem for all discrete groups: amenability is equivalent to every uniformly bounded Hilbert-space representation being similar to a unitary representation. For countable discrete groups, amenability is also equivalent to strong Ulam stability: sufficiently accurate unitary approximate representations are uniformly close in operator norm to genuine representations on the same, possibly infinite-dimensional, Hilbert space.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Unitarizability implies amenability for discrete groups","href":"preprints/Unitarizability-Implies-Amenability-for-Countable-Groups-September-23-2026/paper.pdf"},{"title":"Strong Ulam Stability Characterizes Amenability","href":"preprints/Strong-Ulam-Stability-Characterizes-Amenability-October-5-2026/strong-ulam-stability.pdf"}],"plainFr":"Un groupe discret moyennable moyenne les fonctions bornées de façon invariante. Le manuscrit affirme que cela équivaut à unitariser toute représentation bornée, et, si le groupe est dénombrable, à stabiliser fortement les représentations presque unitaires.","plainEn":"A discrete group is amenable when it admits an invariant way of averaging bounded functions. The manuscript asserts that this is equivalent to making unitary, after a change of frame, every uniformly bounded representation, and, for countable groups, to a strong stability of nearly unitary representations.","expertFr":"Le manuscrit affirme que pour tout groupe discret la moyennabilité équivaut à rendre unitaire, après similitude, toute représentation uniformément bornée sur un Hilbert complexe, ce qui résout Dixmier. Pour les groupes dénombrables elle équivaut à la stabilité forte d'Ulam : d'assez bonnes approximations unitaires sont proches en norme de vraies représentations sur le même espace.","expertEn":"The manuscript asserts that for every discrete group amenability equals unitary similarity of every uniformly bounded representation on a complex Hilbert space, resolving Dixmier. For countable groups it equals strong Ulam stability: good enough unitary approximations are close in norm to genuine representations on the same space.","sparkFr":"La stabilité d'Ulam reste ici un énoncé d'analyse des groupes, sans correction numérique d'erreurs revendiquée.","sparkEn":"Ulam stability remains here a statement in group analysis, with no numerical error correction claimed."},{"id":"252","titleEn":"A torsion-free hyperbolic group that is neither residually finite nor linear over any field","titleFr":"Un groupe hyperbolique sans torsion, ni résiduel ni linéaire","claim":"Constructs a torsion-free word-hyperbolic group that is not residually finite, answering the residual-finiteness question negatively. One fixed nonidentity element is killed by every finite-dimensional linear representation over every commutative field, so the group is not linear over any such field.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A torsion-free hyperbolic group that is not residually finite","href":"preprints/a-torsion-free-hyperbolic-group-that-is-not-residually-finite-September-23-2026/paper.pdf"}],"plainFr":"Être résiduellement fini, c'est faire survivre chaque élément non trivial dans un quotient fini. Le manuscrit affirme un groupe hyperbolique sans torsion qui ne l'est pas, et dont un élément fixé meurt dans toute représentation matricielle sur tout corps.","plainEn":"To be residually finite is to keep every nontrivial element alive in some finite quotient. The manuscript asserts a torsion-free hyperbolic group that fails this, with one fixed element killed by every matrix representation over every commutative field.","expertFr":"Le manuscrit affirme un groupe hyperbolique au sens des mots, sans torsion et non résiduellement fini. Un élément distinct de l'identité est dans le noyau de toute représentation linéaire de dimension finie sur tout corps commutatif, de sorte que le groupe n'est linéaire sur aucun tel corps.","expertEn":"The manuscript asserts a word-hyperbolic group that is torsion-free and not residually finite. An element distinct from the identity lies in the kernel of every finite-dimensional linear representation over every commutative field, so the group is linear over no such field.","sparkFr":"L'intérêt est structurel en théorie des groupes hyperboliques, sans application hors des mathématiques affirmée.","sparkEn":"The interest is structural in the theory of hyperbolic groups, with no application outside mathematics asserted."},{"id":"253","titleEn":"An infinite finitely presented simple amenable group","titleFr":"Un groupe infini, simple, moyennable et finiment présenté","claim":"Constructs an infinite finitely presented simple amenable group, answering the longstanding question of whether these properties can occur simultaneously.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1929,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An infinite finitely presented simple amenable group","href":"preprints/An-Infinite-Finitely-Presented-Simple-Amenable-Group-September-23-2026/paper.pdf"}],"plainFr":"Un groupe simple n'a pas de quotient non trivial, un groupe moyennable admet des moyennes invariantes, et une présentation finie le décrit par peu de générateurs et de relations. Le manuscrit affirme qu'un groupe infini peut réunir ces trois propriétés.","plainEn":"A simple group has no nontrivial quotient, an amenable group admits invariant averages, and a finite presentation describes it by few generators and relations. The manuscript asserts that an infinite group can combine these three properties.","expertFr":"Le manuscrit affirme l'existence d'un groupe infini, de présentation finie, simple et moyennable. Cela répond positivement à la question de savoir si ces propriétés peuvent survenir simultanément.","expertEn":"The manuscript asserts the existence of an infinite finitely presented simple amenable group. This answers positively the question of whether these properties can occur simultaneously.","sparkFr":"La coexistence de ces propriétés est un fait interne de théorie des groupes, sans modèle hors des mathématiques affirmé.","sparkEn":"The coexistence of these properties is an internal fact of group theory, with no model outside mathematics asserted."},{"id":"254","titleEn":"Classifying spaces and geometric obstructions for Artin groups","titleFr":"Espaces classifiants et obstructions géométriques pour les groupes d'Artin","claim":"The Salvetti complex of every finite-rank Artin group is aspherical, proving the Artin K(π,1) conjecture. Arbitrary intersections of its parabolic subgroups are parabolic, proving the Parabolic Intersection Conjecture. An explicit Artin group admits no proper cocompact isometric action on any nonempty proper CAT(0) space.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1927,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Harmonic heights and the Artin K(pi,1) conjecture","href":"preprints/Harmonic-heights-and-the-Artin-K-pi-1-conjecture-September-23-2026/paper.pdf"},{"title":"An Artin group with no geometric CAT(0) action","href":"preprints/An-Artin-group-with-no-geometric-CAT-0-action-September-23-2026/paper.pdf"},{"title":"Parabolic intersections in Artin groups","href":"preprints/Parabolic-intersections-in-Artin-groups-September-23-2026/paper.pdf"}],"plainFr":"Un groupe d'Artin encode des symétries liées par des relations de tresses. Le manuscrit affirme que son complexe de Salvetti de rang fini est sans trou sphérique, et qu'un exemple n'agit pas proprement et cocompactement sur un espace propre non vide de courbure non positive.","plainEn":"An Artin group is a family of symmetries described by braid-like relations. The manuscript asserts that its standard Salvetti complex, in finite rank, is aspherical, and that an explicit example admits no proper cocompact action on any nonempty proper nonpositively curved space of the stated kind.","expertFr":"Le manuscrit affirme que le complexe de Salvetti de tout groupe d'Artin de rang fini est asphérique, donc que la conjecture K(pi,1) d'Artin vaut en rang fini, et que toute intersection de sous-groupes paraboliques est parabolique. Il affirme aussi qu'un groupe d'Artin explicite n'admet aucune action isométrique propre et cocompacte sur un espace CAT(0) propre non vide.","expertEn":"The manuscript asserts that the Salvetti complex of every finite-rank Artin group is aspherical, so the Artin K(pi,1) conjecture holds in finite rank, and that arbitrary intersections of parabolic subgroups are parabolic. It also asserts that an explicit Artin group admits no proper cocompact isometric action on any nonempty proper CAT(0) space.","sparkFr":"L'intérêt est structural : asphéricité et action géométrique de courbure non positive se sépareraient ici.","sparkEn":"The interest is structural: asphericity and a geometric nonpositively curved action would come apart here."},{"id":"255","titleEn":"Quasi-isometric recognition of virtually polycyclic groups","titleFr":"Reconnaissance quasi-isométrique des groupes virtuellement polycycliques","claim":"Proves that every finitely generated group quasi-isometric to a finitely generated virtually polycyclic group is virtually polycyclic, resolving the Eskin–Fisher–Whyte lattice-recognition conjecture. Equivalently, a group quasi-isometric to a lattice in a connected simply connected solvable Lie group is virtually a uniform lattice in some such Lie group, possibly a different one.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Quasi-isometric recognition of virtually polycyclic groups","href":"preprints/quasi-isometric-recognition-of-virtually-polycyclic-groups-September-24-2026/paper.pdf"}],"plainFr":"Deux groupes se ressemblent à grande échelle lorsque leurs distances ne diffèrent que par une distorsion contrôlée. Le manuscrit affirme que tout groupe de type fini ainsi comparable à un groupe virtuellement polycyclique de type fini est lui-même virtuellement polycyclique.","plainEn":"Two groups look alike at large scale when their distances differ only by a controlled distortion. The manuscript asserts that every finitely generated group comparable in this way to a finitely generated virtually polycyclic group is itself virtually polycyclic.","expertFr":"Le manuscrit affirme que tout groupe de type fini quasi-isométrique à un groupe virtuellement polycyclique de type fini l'est aussi, résolvant la conjecture d'Eskin, Fisher et Whyte. Équivalemment, un groupe quasi-isométrique à un réseau d'un groupe de Lie résoluble connexe simplement connexe est virtuellement un réseau uniforme dans un tel groupe, peut-être différent.","expertEn":"The manuscript asserts that every finitely generated group quasi-isometric to a finitely generated virtually polycyclic group is virtually polycyclic, resolving the Eskin–Fisher–Whyte lattice-recognition conjecture. Equivalently, a group quasi-isometric to a lattice in a connected simply connected solvable Lie group is virtually a uniform lattice in some such group, possibly a different one.","sparkFr":"La piste reste interne : la forme à grande échelle suffirait ici à reconnaître la polycyclicité virtuelle.","sparkEn":"The lead stays internal: large-scale shape would suffice here to recognize virtual polycyclicity."},{"id":"256","titleEn":"Nonsingular systems of equations over arbitrary groups","titleFr":"Systèmes non singuliers d'équations sur des groupes arbitraires","claim":"Proves that every finite system of equations over an arbitrary group whose exponent-sum matrix has full row rank over ℚ has a simultaneous solution in an overgroup, resolving Howie's conjecture. The coefficient group embeds in the presented quotient. A companion proves Kervaire's conjecture: adjoining one generator and one relation cannot trivialize a nontrivial group.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Nonsingular systems of equations over arbitrary groups","href":"preprints/Nonsingular-systems-of-equations-over-arbitrary-groups-October-5-2026/nonsingular-systems-over-arbitrary-groups.pdf"},{"title":"The Kervaire theorem for groups","href":"preprints/The-Kervaire-Theorem-for-Groups-September-24-2026/The-Kervaire-Theorem-for-Groups-September-24-2026.pdf"}],"plainFr":"Une équation sur un groupe demande si des produits de lettres inconnues peuvent valoir l'élément neutre. Le manuscrit affirme que tout système fini non singulier sur un groupe quelconque a une solution commune dans un groupe plus grand, où le groupe de départ se plonge.","plainEn":"An equation over a group asks whether products of unknown letters can equal the identity. The manuscript asserts that every finite nonsingular system over an arbitrary group has a common solution in a larger group, into which the original group embeds.","expertFr":"Le manuscrit affirme que tout système fini dont la matrice des sommes d'exposants a un rang de lignes plein sur les rationnels a une solution simultanée dans un surgroupe, résolvant Howie, le groupe des coefficients s'y plongeant. Un compagnon affirme la conjecture de Kervaire : un générateur et une relation de plus ne trivialisent pas un groupe non trivial.","expertEn":"The manuscript asserts that every finite system whose exponent-sum matrix has full row rank over the rationals has a simultaneous solution in an overgroup, resolving Howie's conjecture, with the coefficient group embedding in the presented quotient. A companion asserts Kervaire's conjecture: adjoining one generator and one relation cannot trivialize a nontrivial group.","sparkFr":"L'intérêt est structural : ces équations se résoudraient sans détruire le groupe de départ.","sparkEn":"The interest is structural: these equations would be solvable without destroying the original group."},{"id":"257","titleEn":"A hyperbolic group without a geometric CAT(0) action","titleFr":"Un groupe hyperbolique sans action géométrique CAT(0)","claim":"Answers negatively whether every word-hyperbolic group is a CAT(0) group. Constructs one with a finite classifying space but no proper cocompact isometric action on any proper complete CAT (0) space, in any dimension.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A hyperbolic group with no geometric CAT(0) action","href":"preprints/A-hyperbolic-group-with-no-geometric-CAT0-action-September-25-2026/paper.pdf"}],"plainFr":"Un groupe hyperbolique est un groupe dont les grands triangles restent fins, comme en courbure négative. Le manuscrit affirme qu'un tel groupe, avec un espace classifiant fini, peut n'admettre aucune action géométrique sur un espace complet de courbure non positive, propre, en aucune dimension.","plainEn":"A hyperbolic group is a group whose large triangles stay thin, as in negative curvature. The manuscript asserts that such a group, with a finite classifying space, may admit no geometric action on any proper complete nonpositively curved space, in any dimension.","expertFr":"Le manuscrit affirme qu'il existe un groupe hyperbolique au sens des mots, à espace classifiant fini, sans action isométrique propre et cocompacte sur aucun espace CAT(0) propre et complet, en toute dimension. Ainsi un complexe simplicial asphérique fini à inégalité linéaire de remplissage des disques n'a pas forcément de modèle fini localement CAT(0), ni localement CAT(-1).","expertEn":"The manuscript asserts a word-hyperbolic group with a finite classifying space and no proper cocompact isometric action on any proper complete CAT(0) space, in any dimension. Thus a finite aspherical simplicial complex with a linear disk-filling inequality need not have a finite locally CAT(0) model, nor a finite locally CAT(-1) model.","sparkFr":"La piste est interne : hyperbolie des mots et modèle localement CAT(0) fini ne coïncideraient pas.","sparkEn":"The lead is internal: word hyperbolicity and a finite locally CAT(0) model would not coincide."},{"id":"258","titleEn":"Gersten’s conjecture and virtual compact specialness of one-relator groups","titleFr":"Conjecture de Gersten et spécialité compacte virtuelle des groupes à un relateur","claim":"Proves Gersten's conjecture: every finitely generated one-relator group containing no Baumslag–Solitar subgroup BS(m,n), with m,n 0, is word-hyperbolic. It also proves that every word-hyperbolic one-relator group is virtually compact special.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1973,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"Baumslag-Solitar-free one-relator groups are hyperbolic","href":"preprints/Baumslag-Solitar-free-one-relator-groups-are-hyperbolic-September-25-2026/paper.pdf"},{"title":"Virtual compact specialness of hyperbolic one-relator groups","href":"preprints/Virtual-compact-specialness-of-hyperbolic-one-relator-groups-September-25-2026/paper.pdf"}],"plainFr":"Un groupe à un relateur est engendré par des lettres soumises à une seule relation. Le manuscrit affirme que, s'il est de type fini et ne contient aucun sous-groupe de Baumslag–Solitar, il est hyperbolique au sens des grands triangles fins.","plainEn":"A one-relator group is generated by letters subject to a single relation. The manuscript asserts that if it is finitely generated and contains no Baumslag–Solitar subgroup, then it is hyperbolic in the sense of thin large triangles.","expertFr":"Le manuscrit affirme la conjecture de Gersten : tout groupe à un relateur de type fini sans sous-groupe isomorphe à un groupe de Baumslag–Solitar BS(m,n), pour des entiers m et n non nuls, est hyperbolique au sens des mots. Il affirme aussi que tout groupe à un relateur hyperbolique au sens des mots est virtuellement compact spécial.","expertEn":"The manuscript asserts Gersten's conjecture: every finitely generated one-relator group with no subgroup isomorphic to a Baumslag–Solitar group BS(m,n), for nonzero integers m and n, is word-hyperbolic. It also asserts that every word-hyperbolic one-relator group is virtually compact special.","sparkFr":"L'intérêt est structural : une seule relation, sans sous-groupe de Baumslag–Solitar, forcerait l'hyperbolie.","sparkEn":"The interest is structural: one relation, without a Baumslag–Solitar subgroup, would force hyperbolicity."},{"id":"259","titleEn":"A group without fixed price","titleFr":"Un groupe sans prix fixe","claim":"Constructs a finitely generated group with two essentially free probability-measure-preserving actions of different costs, answering the general fixed-price problem negatively. Its Bernoulli action has cost bounded away from one, while a sequence of finite height extensions has costs tending to one.","nature":"algebre","domain":"hasard","complexity":"avance","problemYear":1991,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"A group without fixed price","href":"preprints/A-group-without-fixed-price-October-5-2026/unequal-costs-rank-100-amalgam.pdf"}],"plainFr":"Le coût d'une action mesure, de façon probabiliste, combien de générateurs libres elle consomme. Le manuscrit affirme qu'un groupe de type fini possède deux actions essentiellement libres, préservant une probabilité, dont les coûts diffèrent.","plainEn":"The cost of an action measures, in a probabilistic sense, how many free generators it consumes. The manuscript asserts that a finitely generated group has two essentially free probability-preserving actions whose costs differ.","expertFr":"Le manuscrit affirme un groupe de type fini, amalgame d'un groupe libre de rang 100 avec un produit direct, ayant deux actions essentiellement libres préservant une mesure de probabilité et de coûts distincts, contre le problème général du prix fixe de Gaboriau. L'action de Bernoulli a un coût borné loin de un, tandis que des extensions de hauteur finie ont des coûts tendant vers un.","expertEn":"The manuscript asserts a finitely generated group, an amalgam of a free group of rank 100 with a direct product, with two essentially free probability-measure-preserving actions of different costs, against Gaboriau's general fixed-price problem. Its Bernoulli action has cost bounded away from one, while finite-height extensions have costs tending to one.","sparkFr":"La piste est interne à la théorie mesurée : le coût ne serait pas un invariant du seul groupe.","sparkEn":"The lead stays in measured group theory: cost would not be an invariant of the group alone."},{"id":"260","titleEn":"Spacetime Penrose inequalities: enclosing area, charge, rotation, and anti-de Sitter extensions","titleFr":"Inégalités de Penrose d'espace-temps : aire, charge, rotation et anti-de Sitter","claim":"Proves the sharp enclosing-area spacetime Penrose inequality for smooth one-ended asymptotically flat initial data in every spatial dimension n ≥ 3, under dominant energy, weak future trapping, positive enclosing area, and the stated decay assumptions. It bounds invariant ADM mass below using minimum enclosing area, with equality rigidity under additional horizon hypotheses. Charged upper-area bounds treat dyonic three-dimensional data; the higher-dimensional purely electric extension uses the matched neutral theor","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1973,"yearKnown":true,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"The spacetime Penrose inequality with charge and original-data rigidity","href":"preprints/The-spacetime-Penrose-inequality-with-charge-and-original-data-rigidity-October-5-2026/paper.pdf"},{"title":"A Charged Reduction of the Spacetime Penrose Inequality in Spatial Dimensions at Least Four","href":"preprints/A-Charged-Reduction-of-the-Spacetime-Penrose-Inequality-in-Spatial-Dimensions-at-Least-Four-October-5-2026/paper.pdf"},{"title":"Spacetime Penrose inequalities: enclosing area, charge, and rigidity","href":"preprints/Spacetime-Penrose-inequalities-enclosing-area-charge-and-rigidity-October-5-2026/paper.pdf"},{"title":"The Kerr–Newman Penrose Inequality for Axisymmetric Electrovacuum Exteriors","href":"preprints/The-Kerr-Newman-Penrose-Inequality-for-Axisymmetric-Electrovacuum-Exteriors-October-5-2026/paper.pdf"},{"title":"Electromagnetic tails and the Kerr–Newman Penrose inequality","href":"preprints/Electromagnetic-tails-and-the-Kerr-Newman-Penrose-inequality-October-5-2026/paper.pdf"},{"title":"The nonmaximal anti-de Sitter Penrose Inequality and original-data rigidity","href":"preprints/The-nonmaximal-anti-de-Sitter-Penrose-Inequality-and-original-data-rigidity-October-5-2026/paper.pdf"}],"plainFr":"Une inégalité de Penrose compare la masse d'un espace-temps à l'aire d'une région qui piège la lumière. Le manuscrit affirme, sous les hypothèses d'énergie, de décroissance et de piégeage indiquées, une borne optimale par l'aire englobante minimale, y compris pour des données chargées en dimension trois.","plainEn":"A Penrose inequality compares the mass of a spacetime with the area of a region that traps light. The manuscript asserts, under the stated energy, decay, and trapping hypotheses, a sharp bound by the minimum enclosing area, including for charged three-dimensional data.","expertFr":"Le manuscrit affirme l'inégalité de Penrose d'espace-temps à aire englobante optimale pour des données lisses à une extrémité, asymptotiquement plates, en dimension au moins trois, sous énergie dominante, piégeage faible et les décroissances indiquées. Il traite aussi des bornes d'aire chargées dyoniques en dimension trois, reliant masse, charge et rayon d'aire, avec rigidité sous les hypothèses d'horizon.","expertEn":"The manuscript asserts the sharp enclosing-area spacetime Penrose inequality for smooth one-ended asymptotically flat data in spatial dimension at least three, under dominant energy, weak future trapping, and the stated decay. It also treats charged area bounds for dyonic three-dimensional data, relating mass, charge, and enclosing radius, with rigidity under the stated horizon hypotheses.","sparkFr":"Si le pont physique existe, il resterait une contrainte mathématique sur masse et aire, non une observation.","sparkEn":"If a physical bridge exists, it would remain a mathematical constraint on mass and area, not an observation."},{"id":"261","titleEn":"Localization and delocalization in the Anderson model","titleFr":"Localisation et délocalisation dans le modèle d'Anderson","claim":"Resolves the predicted spectral contrast for the lattice Anderson model with independent uniform site potentials. In dimension two, every positive disorder strength gives almost surely pure-point spectrum. In every fixed dimension d ≥ 3, sufficiently weak positive disorder gives purely absolutely continuous spectrum on a fixed open interval with nonzero spectral weight.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1958,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Absolutely Continuous Spectrum for Weak-Disorder Anderson Models in Dimensions at Least Three","href":"preprints/Absolutely-Continuous-Spectrum-for-Weak-Disorder-Anderson-Models-in-Dimensions-at-Least-Three-September-23-2026/paper.pdf"},{"title":"Pure-Point Spectrum for the Two-Dimensional Anderson Model at Every Positive Disorder","href":"preprints/Pure-Point-Spectrum-for-the-Two-Dimensional-Anderson-Model-at-Every-Positive-Disorder-September-23-2026/paper.pdf"}],"plainFr":"Le modèle d'Anderson place une particule sur un réseau dont l'énergie de chaque site varie au hasard. Le manuscrit affirme qu'en dimension deux tout désordre positif localise presque sûrement le spectre, tandis qu'en dimension au moins trois un désordre assez faible laisse une bande d'énergies délocalisées.","plainEn":"The Anderson model places a particle on a lattice whose energy at each site varies at random. The manuscript asserts that in dimension two every positive disorder almost surely localizes the spectrum, while in dimension at least three weak enough disorder leaves a band of delocalized energies.","expertFr":"Le manuscrit affirme que, pour le modèle d'Anderson sur le réseau à potentiels de site uniformes indépendants, tout désordre positif en dimension deux donne presque sûrement un spectre ponctuel pur. En chaque dimension fixée au moins trois, un désordre positif assez petit donne un spectre purement absolument continu, de poids non nul, sur un intervalle ouvert fixé indépendant de l'intensité du désordre.","expertEn":"The manuscript asserts that, for the lattice Anderson model with independent uniform site potentials, every positive disorder in dimension two gives almost surely pure-point spectrum. In each fixed dimension at least three, sufficiently small positive disorder gives purely absolutely continuous spectrum of nonzero weight on a fixed open interval independent of the disorder strength.","sparkFr":"La piste physique reste un contraste spectral mathématique, sans matériau ni expérience affirmés.","sparkEn":"The physical lead remains a mathematical spectral contrast, with no material or experiment asserted."},{"id":"262","titleEn":"Sharp finite-matrix Lieb–Thirring inequalities and all equality cases","titleFr":"Inégalités de Lieb–Thirring matricielles fines et tous les cas d'égalité","claim":"Proves the sharp one-dimensional Lieb–Thirring inequality for 1/2 γ 3/2 and arbitrary finite-matrix potentials W ≥ 0 with tr (W^γ+1/2) ∞: the optimal constant is the scalar one-bound-state value, independent of matrix size. All equality cases are direct sums, in one constant unitary basis, of scalar sech2 solitons with independent scales and centers, and zero channels.","nature":"physique-math","domain":"information","complexity":"frontiere","problemYear":1975,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Equality cases in the sharp one-dimensional matrix Lieb–Thirring inequality","href":"preprints/Equality-cases-in-the-sharp-one-dimensional-matrix-Lieb-Thirring-inequality-October-5-2026/sharp-one-dimensional-lieb-thirring-inequalities-matrix-potentials.pdf"},{"title":"Sharp one-dimensional Lieb–Thirring inequalities for matrix potentials","href":"preprints/Sharp-one-dimensional-Lieb-Thirring-inequalities-for-matrix-potentials-October-5-2026/sharp-matrix-lieb-thirring.pdf"},{"title":"Sharp one-dimensional Lieb–Thirring constants","href":"preprints/Sharp-One-Dimensional-Lieb-Thirring-Constants-September-23-2026/paper.pdf"}],"plainFr":"Une inégalité de Lieb–Thirring borne l'énergie retenue par un potentiel à l'aide d'une intégrale de sa taille. Le manuscrit affirme qu'en une dimension, pour des potentiels à valeurs matricielles finies, la meilleure constante est celle du cas à une seule valeur, et il décrit tous les cas d'égalité.","plainEn":"A Lieb–Thirring inequality bounds the energy held by a potential using an integral of its size. The manuscript asserts that in one dimension, for finite matrix-valued potentials, the best constant is the single-value one, and it describes every equality case.","expertFr":"Le manuscrit affirme l'inégalité de Lieb–Thirring optimale en dimension un, pour gamma strictement entre un demi et trois demis, et tout potentiel matriciel fini positif intégrable : la constante scalaire à un état lié ne dépend pas de la taille. Les égalités sont des sommes directes, dans une base unitaire fixe, de solitons en sécante hyperbolique carrée, d'échelles et centres libres, et de canaux nuls.","expertEn":"The manuscript asserts the sharp one-dimensional Lieb–Thirring inequality for gamma strictly between one half and three halves, for finite nonnegative matrix potentials of integrable trace: the best constant is the scalar one-bound-state value, independent of size. Equality holds for direct sums, in one fixed unitary basis, of scalar sech-squared solitons of free scales and centers, plus zero channels.","sparkFr":"L'intérêt est analytique : la constante optimale ne dépendrait pas de la taille de la matrice.","sparkEn":"The interest is analytic: the optimal constant would not depend on the matrix size."},{"id":"263","titleEn":"The ionization and generalized ionization conjectures","titleFr":"Conjectures d'ionisation et d'ionisation généralisée","claim":"For the full nonrelativistic Coulomb model with two electron spin states, proves that a molecule with M fixed nuclei of charges at least one and total charge Z strictly binds at most Z+CM electrons. Neutral-atom first ionization energies and radii containing all but an expected half-electron have universal positive upper and lower bounds. The energy cost of removing m electrons has Thomas–Fermi asymptotics as m→∞ and Z/m→∞; neutral-atom outer radii have the corresponding iterated-limit asymptotics, taking Z→∞ first","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Uniform excess charge for Coulomb molecules and the outer radius of neutral atoms","href":"preprints/Uniform-excess-charge-for-Coulomb-molecules-and-the-outer-radius-of-neutral-atoms-September-24-2026/paper.pdf"},{"title":"Generalized ionization energies for full Coulomb atoms","href":"preprints/Generalized-ionization-energies-for-full-Coulomb-atoms-September-24-2026/paper.pdf"},{"title":"Generalized outer-electron radii of neutral Coulomb atoms","href":"preprints/Generalized-outer-electron-radii-of-neutral-Coulomb-atoms-September-24-2026/paper.pdf"}],"plainFr":"Dans ce modèle, des électrons sont liés à des noyaux fixes par l'attraction de Coulomb. Le manuscrit affirme qu'une molécule de charge nucléaire totale donnée ne peut lier strictement qu'un nombre d'électrons borné par cette charge plus une constante fois le nombre de noyaux.","plainEn":"In this model, electrons are bound to fixed nuclei by the Coulomb attraction. The manuscript asserts that a molecule of a given total nuclear charge can strictly bind only a number of electrons bounded by that charge plus a constant times the number of nuclei.","expertFr":"Le manuscrit affirme que, dans le modèle coulombien non relativiste à deux spins, une molécule à M noyaux de charges au moins un et de charge totale Z lie strictement au plus Z plus C M électrons, C universelle. Il affirme aussi des bornes universelles pour la première ionisation et certains rayons des atomes neutres, ainsi que des asymptotiques de Thomas–Fermi lorsqu'on retire beaucoup d'électrons.","expertEn":"The manuscript asserts that, for the full nonrelativistic Coulomb Hamiltonian with two spin states, a molecule with M fixed nuclei of charges at least one and total charge Z strictly binds at most Z plus C M electrons, with C universal. It also asserts universal positive bounds for neutral-atom first ionization energies and certain radii, and Thomas–Fermi asymptotics as more and more electrons are removed.","sparkFr":"Si l'on y lit la chimie quantique, le texte n'affirme qu'une borne mathématique sur les électrons liés.","sparkEn":"If read as quantum chemistry, the text asserts only a mathematical bound on bound electrons."},{"id":"264","titleEn":"Strong cosmic censorship near two-ended Kerr data","titleFr":"Censure cosmique forte près des données de Kerr à deux bouts","claim":"Proves local strong cosmic censorship near each fixed rotating subextremal Kerr bridge. A dense Gδ subset of a weighted smooth neighborhood of smooth complete two-ended asymptotically flat vacuum data has full maximal globally hyperbolic developments with no future continuous nondegenerate extension whose weak connection is locally square-integrable. No symmetry is imposed; extensions need not satisfy the vacuum equations.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1969,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Generic Future Inextendibility with Square-Integrable Connection Near a Fixed Kerr Spacetime","href":"preprints/Generic-Future-Inextendibility-with-Square-Integrable-Connection-Near-a-Fixed-Kerr-Spacetime-September-23-2026/paper.pdf"},{"title":"Generic C1 Future Inextendibility Near Rotating Subextremal Kerr Spacetimes","href":"preprints/Generic-C1-Future-Inextendibility-Near-Rotating-Subextremal-Kerr-Spacetimes-September-23-2026/paper.pdf"},{"title":"Quantitative Near-Kerr Evolution and Generic C2 Future Inextendibility","href":"preprints/Quantitative-Near-Kerr-Evolution-and-Generic-C2-Future-Inextendibility-September-23-2026/paper.pdf"}],"plainFr":"La censure cosmique forte demande si l'évolution d'un espace-temps reste unique au-delà d'une frontière interne. Le manuscrit affirme que, près de chaque pont de Kerr tournant non extrême, une classe dense de données du vide n'admet pas l'extension future continue décrite.","plainEn":"Strong cosmic censorship asks whether a spacetime evolution stays unique beyond an inner boundary. The manuscript asserts that, near each rotating nonextreme Kerr bridge, a dense class of vacuum data admits no future continuous extension of the kind described.","expertFr":"Le manuscrit affirme que, près de chaque pont de Kerr tournant sous-extrémal, un G delta dense de données du vide proches, à deux bouts, a un développement maximal sans extension future continue non dégénérée à connexion faible de carré intégrable. Aucune symétrie n'est imposée, et l'extension n'a pas à vérifier les équations du vide.","expertEn":"The manuscript asserts that near each rotating subextremal Kerr bridge, a dense G-delta of nearby complete two-ended asymptotically flat vacuum data has a maximal globally hyperbolic development with no future continuous nondegenerate extension of locally square-integrable weak connection. No symmetry is imposed, and the extension need not solve the vacuum equations.","sparkFr":"Le pont avec la relativité resterait une contrainte d'unicité mathématique, non une observation astronomique.","sparkEn":"The bridge to relativity would remain a mathematical uniqueness constraint, not an astronomical observation."},{"id":"265","titleEn":"Area laws and tensor networks for two-dimensional gapped systems","titleFr":"Lois d'aire et réseaux de tenseurs pour les systèmes plans à trou spectral","claim":"Proves an entropy area law for unique ground states of finite-range Hamiltonians on arbitrary finite induced square-lattice domains, using only a uniform full-system spectral gap and bounds on the local interactions. On open L× L squares, uniformly gapped nearest-neighbor ground states also admit projected entangled-pair state approximations with polynomial bond dimension and global vector error at most L−1.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A two-dimensional area law from a global spectral gap","href":"preprints/A-two-dimensional-area-law-from-a-global-spectral-gap-September-24-2026/paper.pdf"},{"title":"Polynomial PEPS approximation of gapped square-grid ground states","href":"preprints/Polynomial-PEPS-approximation-of-gapped-square-grid-ground-states-September-24-2026/paper.pdf"}],"plainFr":"L'état fondamental est la configuration de plus basse énergie d'un système quantique sur un réseau. Le manuscrit affirme que, si le trou d'énergie est uniforme, l'entropie d'intrication d'une région du réseau carré est bornée par le nombre de liens qui sortent de son bord.","plainEn":"The ground state is the lowest-energy configuration of a quantum system on a lattice. The manuscript asserts that if the energy gap is uniform, the entanglement entropy of a square-lattice region is bounded by the number of links leaving its boundary.","expertFr":"Le manuscrit affirme une loi d'aire pour l'état fondamental unique d'un hamiltonien à portée finie sur tout domaine fini du réseau carré, dès qu'un trou spectral uniforme et des bornes locales sont fixés. Sur les carrés de côté L, les états à voisins proches uniformément gappés ont des approximations par paires intriquées projetées, de lien polynomial et d'erreur au plus un sur L.","expertEn":"The manuscript asserts an area law for the unique ground state of a finite-range Hamiltonian on any finite induced subgraph of the square lattice, from a uniform spectral gap and bounds on local interactions. On open squares of side L, uniformly gapped nearest-neighbor states admit projected entangled-pair approximations of polynomial bond dimension and global error at most one over L.","sparkFr":"La piste calculatoire est prudente : le texte borne une entropie et une approximation, sans usage industriel.","sparkEn":"The computational lead is cautious: the text bounds an entropy and an approximation, with no industrial use."},{"id":"266","titleEn":"Exactly three mutually unbiased bases in dimension six","titleFr":"Exactement trois bases mutuellement non biaisées en dimension six","claim":"Proves N(6)=3, resolving Zauner's dimension-six mutually unbiased bases conjecture: three such bases exist in ℂ6, but four cannot. The exclusion is a complete certified computation under the stated binary64 arithmetic and compiler conditions. An independent companion proves the Matolcsi–Ruzsa–Weiner Fourier-vanishing conjecture for order-six complex Hadamard matrices outside Tao's cubic equivalence class.","nature":"combinatoire","domain":"structures","complexity":"avance","problemYear":1822,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The maximum number of mutually unbiased bases in dimension six","href":"preprints/The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026/The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026.pdf"},{"title":"Exact Fourier certificates for complex Hadamard matrices of order six","href":"preprints/Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026/Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026.pdf"}],"plainFr":"Des bases mutuellement non biaisées sont des repères d'un espace dont les chevauchements sont aussi égaux que possible. Le manuscrit affirme qu'en dimension complexe six il en existe trois, mais que quatre sont impossibles.","plainEn":"Mutually unbiased bases are frames of a space whose overlaps are as equal as possible. The manuscript asserts that in complex dimension six three exist, but four are impossible.","expertFr":"Le manuscrit affirme qu'il existe exactement trois bases orthonormales mutuellement non biaisées en dimension complexe six, ce qui résout Zauner. L'exclusion de quatre est un calcul certifié sous l'arithmétique binary64 et le compilateur indiqués ; un compagnon traite la conjecture de Fourier de Matolcsi, Ruzsa et Weiner hors de la classe cubique de Tao.","expertEn":"The manuscript asserts that the maximum number of mutually unbiased orthonormal bases in complex dimension six is three, resolving Zauner's conjecture in that dimension. The exclusion is a complete certified computation under the stated binary64 arithmetic and compiler conditions; a companion treats the Matolcsi–Ruzsa–Weiner Fourier conjecture outside Tao's cubic class.","sparkFr":"L'intérêt est structural : le cas de la dimension six serait tranché par un calcul certifié, non par un appareil.","sparkEn":"The interest is structural: dimension six would be settled by a certified computation, not by a device."},{"id":"267","titleEn":"Positive-temperature Bose–Einstein condensation and exact quantum depletion","titleFr":"Condensation de Bose–Einstein à température positive et déplétion quantique exacte","claim":"Proves Bose–Einstein condensation for the exact canonical Gibbs state of the three-dimensional hard-sphere gas: each fixed exclusion distance and sufficiently small fixed density admit a strictly positive temperature, independent of volume, with positive condensate fraction in the thermodynamic limit. At zero temperature, proves the Bogoliubov leading quantum-depletion law for hard spheres and fixed bounded nonnegative radial finite-range potentials of positive scattering length, taking the thermodynamic limit befo","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1915,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Bose–Einstein condensation at positive temperature in the dilute hard-sphere gas","href":"preprints/Bose-Einstein-condensation-at-positive-temperature-in-the-dilute-hard-sphere-gas-October-5-2026/positive-temperature-hard-spheres.pdf"},{"title":"Quantum Depletion and Momentum Distribution in the Dilute Hard-Sphere Bose Gas","href":"preprints/Quantum-Depletion-and-Momentum-Distribution-in-the-Dilute-Hard-Sphere-Bose-Gas-October-5-2026/Quantum-Depletion-in-the-Dilute-Hard-Sphere-Bose-Gas.pdf"},{"title":"Quantum Depletion for Fixed Bounded Repulsive Potentials","href":"preprints/Quantum-Depletion-for-Fixed-Bounded-Repulsive-Potentials-October-5-2026/fixed-repulsion-quantum-depletion.pdf"},{"title":"A density-uniform condensate bound for dilute Bose gases","href":"preprints/A-density-uniform-condensate-bound-for-dilute-Bose-gases-September-27-2026/paper.pdf"},{"title":"Ground-state condensation in the dilute hard-sphere gas","href":"preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/paper.pdf"}],"plainFr":"La condensation de Bose–Einstein rassemble une fraction d'un gaz quantique dans un même état. Le manuscrit affirme que le gaz de sphères dures en trois dimensions, assez dilué, condense à une température strictement positive qui ne dépend pas du volume.","plainEn":"Bose–Einstein condensation gathers a fraction of a quantum gas into one state. The manuscript asserts that the three-dimensional hard-sphere gas, when dilute enough, condenses at a strictly positive temperature that does not depend on the volume.","expertFr":"Le manuscrit affirme la condensation de l'état de Gibbs canonique du gaz de sphères dures en trois dimensions : à exclusion fixée et densité assez petite, une température positive indépendante du volume donne un condensat à la limite thermodynamique. À température nulle, il affirme la déplétion de Bogoliubov au premier ordre pour les sphères dures et certains potentiels radiaux, limite thermodynamique d'abord.","expertEn":"The manuscript asserts condensation of the canonical Gibbs state of the three-dimensional hard-sphere gas: at fixed exclusion and small enough density, a positive volume-independent temperature yields a condensate in the thermodynamic limit. At zero temperature, it asserts the leading Bogoliubov depletion law for hard spheres and certain finite-range radial potentials, taking that limit first.","sparkFr":"Le lien avec les gaz quantiques reste théorique : le texte affirme une condensation mathématique, non une expérience.","sparkEn":"The link to quantum gases stays theoretical: the text asserts a mathematical condensation, not an experiment."},{"id":"268","titleEn":"The spin-one Haldane gap","titleFr":"Le trou spectral de Haldane pour le spin un","claim":"Proves the spin-one Haldane gap conjecture for the pure antiferromagnetic Heisenberg chain on even periodic rings: the spectral gap stays uniformly positive as the chain grows. A companion establishes a gap for odd open chains with endpoint field h=3/5 and gives boundary-selected infinite-volume states with topological index −1.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1983,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The periodic spin-one Haldane gap","href":"preprints/The-periodic-spin-one-Haldane-gap-September-24-2026/paper.pdf"},{"title":"A boundary-field gap for the spin-one Heisenberg chain","href":"preprints/A-boundary-field-gap-for-the-spin-one-Heisenberg-chain-September-24-2026/paper.pdf"}],"plainFr":"Une chaîne antiferromagnétique de Heisenberg aligne des spins voisins dans des sens opposés. Le manuscrit affirme que, pour le spin un sur des anneaux périodiques de longueur paire, le trou d'énergie reste uniformément positif quand la chaîne grandit.","plainEn":"An antiferromagnetic Heisenberg chain aligns neighboring spins in opposite directions. The manuscript asserts that for spin one on even periodic rings, the energy gap stays uniformly positive as the chain grows.","expertFr":"Le manuscrit affirme la formulation périodique paire de la conjecture du trou de Haldane de spin un : le trou spectral de la chaîne de Heisenberg antiferromagnétique pure reste uniformément positif. Un compagnon établit un trou pour les chaînes ouvertes impaires avec champ d'extrémité trois cinquièmes, et des états de volume infini d'indice topologique moins un sélectionnés par le bord.","expertEn":"The manuscript asserts the even-periodic formulation of the spin-one Haldane gap conjecture: the spectral gap of the pure antiferromagnetic Heisenberg chain stays uniformly positive. A companion establishes a gap for odd open chains with endpoint field three fifths, and boundary-selected infinite-volume states of topological index minus one.","sparkFr":"L'intérêt reste une propriété spectrale de chaîne de spins, sans dispositif matériel affirmé.","sparkEn":"The interest remains a spectral property of a spin chain, with no material device asserted."},{"id":"269","titleEn":"Uniform Laughlin gap and stability under bounded scalar disorder","titleFr":"Trou de Laughlin uniforme et stabilité sous un désordre scalaire borné","claim":"Proves the fermionic Laughlin spectral-gap conjecture for the full V1 interaction at filling 1/3 on the round sphere. The unique ground state remains uniformly gapped under sufficiently weak bounded real scalar one-body potentials projected to the lowest Landau level. Both the gap and disorder threshold are uniform over all sufficiently large particle numbers and all normalized potential profiles.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1983,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Uniform Stability of the Spherical Laughlin Gap","href":"preprints/Uniform-Stability-of-the-Spherical-Laughlin-Gap-October-5-2026/uniform-stability-spherical-laughlin-gap.pdf"},{"title":"A Fock-space inequality and the Laughlin spectral gap","href":"preprints/A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026/A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026.pdf"}],"plainFr":"L'état de Laughlin est un état proposé pour des électrons fortement liés entre eux dans un champ magnétique. Le manuscrit affirme qu'au remplissage un tiers sur la sphère, son trou d'énergie reste uniforme sous un désordre scalaire assez faible.","plainEn":"The Laughlin state is a state proposed for strongly mutually bound electrons in a magnetic field. The manuscript asserts that at filling one third on the sphere, its energy gap stays uniform under weak enough scalar disorder.","expertFr":"Le manuscrit affirme la conjecture de trou spectral de Laughlin fermionique pour l'interaction V1 complète au remplissage un tiers sur la sphère ronde : l'état fondamental unique reste uniformément gappé sous des potentiels scalaires réels bornés assez faibles, projetés sur le plus bas niveau de Landau. Le trou et le seuil sont uniformes pour tous les grands nombres de particules et tous les profils normalisés.","expertEn":"The manuscript asserts the fermionic Laughlin gap conjecture for the full V1 interaction at filling one third on the round sphere: the unique ground state stays uniformly gapped under sufficiently weak bounded real scalar potentials projected to the lowest Landau level. The gap and threshold are uniform for all large particle numbers and all normalized profiles.","sparkFr":"Le pont avec l'effet Hall fractionnaire resterait une stabilité spectrale mathématique, non une mesure.","sparkEn":"The bridge to the fractional Hall effect would remain a mathematical spectral stability, not a measurement."},{"id":"270","titleEn":"Threshold and positive-energy bound states of the BFSS matrix model","titleFr":"États liés de seuil et d'énergie positive du modèle matriciel BFSS","claim":"Proves that the undeformed relative SU(N) BFSS model has exactly one normalizable zero-energy state for every finite N ≥ 2, resolving the threshold-bound-state conjecture. For SU(2), a companion proves infinitely many normalizable positive-energy eigenstates with unbounded energies, contradicting the original BFSS paper's exclusion of additional bound states at N = 2.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1963,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The unique threshold bound state of the SU(N) BFSS model","href":"preprints/The-unique-threshold-bound-state-of-the-SU-N-BFSS-model-September-24-2026/paper.pdf"},{"title":"Positive eigenvalues of the relative SU(2) BFSS Hamiltonian","href":"preprints/Positive-eigenvalues-of-the-relative-SU-2-BFSS-Hamiltonian-October-5-2026/positive-eigenvalues-relative-su2-bfss.pdf"}],"plainFr":"Le modèle BFSS est une mécanique quantique de matrices, proposée comme description de certaines membranes. Le manuscrit affirme que, pour chaque taille finie au moins deux, il n'y a qu'un seul état normalisable d'énergie nulle une fois le centre de masse retiré.","plainEn":"The BFSS model is a matrix quantum mechanics, proposed as a description of certain membranes. The manuscript asserts that for every finite size at least two, there is exactly one normalizable zero-energy state once the center of mass is removed.","expertFr":"Le manuscrit affirme que le modèle relatif SU(N) BFSS non déformé a exactement un état normalisable d'énergie nulle pour tout N fini au moins deux, ce qui résout la conjecture d'état lié de seuil. Pour SU(2), un compagnon affirme une infinité d'états propres normalisables d'énergie positive et non bornée, contre l'exclusion d'états liés supplémentaires à N égal à deux dans l'article d'origine.","expertEn":"The manuscript asserts that the undeformed relative SU(N) BFSS model has exactly one normalizable zero-energy state for every finite N at least two, resolving the threshold bound-state conjecture. For SU(2), a companion asserts infinitely many normalizable positive-energy eigenstates of unbounded energy, against the original paper's exclusion of further bound states at N equal to two.","sparkFr":"L'intérêt reste interne à ce modèle matriciel : le texte compte des états liés, sans scénario expérimental.","sparkEn":"The interest stays inside this matrix model: the text counts bound states, with no experimental scenario."},{"id":"271","titleEn":"Bloch's law, its lattice correction, and the spherical magnetization law","titleFr":"Loi de Bloch, sa correction de réseau et la loi d'aimantation sphérique","claim":"Proves Bloch's T3/2 law with its exact coefficient for three-dimensional quantum Heisenberg ferromagnets at every positive quantum spin, allowing nonnegative symmetric finite-range couplings whose support generates ℤ3. The thermodynamic limit precedes the zero-field derivative and low-temperature limit. The family also proves spontaneous magnetization for nearest-neighbor models in every dimension d ≥ 3 and determines the first lattice correction for three-dimensional nearest-neighbor couplings.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1928,"yearKnown":true,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Bloch's Law for Finite-Range Heisenberg Ferromagnets in Three Dimensions","href":"preprints/Blochs-Law-for-Finite-Range-Heisenberg-Ferromagnets-in-Three-Dimensions-October-5-2026/bloch-law-heisenberg.pdf"},{"title":"The first lattice correction to Bloch's law","href":"preprints/The-first-lattice-correction-to-Blochs-law-October-5-2026/first-lattice-correction-bloch-law.pdf"},{"title":"The spherical magnetization law for the three-dimensional quantum Heisenberg ferromagnet","href":"preprints/The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026/spherical-magnetization.pdf"},{"title":"Spontaneous magnetization in the quantum Heisenberg ferromagnet","href":"preprints/Spontaneous-magnetization-in-the-quantum-Heisenberg-ferromagnet-September-24-2026/paper.pdf"}],"plainFr":"L'aimantation spontanée mesure l'alignement collectif des spins d'un aimant quantique sans champ extérieur. Le manuscrit affirme la loi de Bloch en température à la puissance trois demis, avec son coefficient exact, pour des ferromagnétiques de Heisenberg en trois dimensions.","plainEn":"Spontaneous magnetization measures the collective alignment of spins in a quantum magnet with no external field. The manuscript asserts Bloch's three-halves temperature law, with its exact coefficient, for three-dimensional Heisenberg ferromagnets.","expertFr":"Le manuscrit affirme la loi de Bloch en puissance trois demis, au coefficient du déterminant de dispersion d'un magnon, pour tout spin positif et tout couplage symétrique non négatif de portée finie engendrant le réseau. La limite thermodynamique précède le champ nul puis le froid ; la famille traite aussi l'aimantation aux plus proches voisins en dimension au moins trois et la première correction de réseau.","expertEn":"The manuscript asserts Bloch's three-halves law, with the one-magnon dispersion determinant as coefficient, for every positive spin and every nonnegative symmetric finite-range coupling generating the cubic lattice. The thermodynamic limit precedes the zero-field derivative and low temperature; the family also treats nearest-neighbor magnetization in dimension at least three and the first lattice correction.","sparkFr":"Le lien avec le magnétisme reste une asymptotique mathématique, sans matériau particulier affirmé.","sparkEn":"The link to magnetism remains a mathematical asymptotic, with no particular material asserted."},{"id":"272","titleEn":"Entanglement without distillable secret key","titleFr":"Intrication sans clé secrète distillable","claim":"Constructs an entangled state on C^10 C^10 with zero distillable secret key for the specified local-instrument protocols that complete almost surely. These allow joint local processing and authenticated two-way public communication, with no other shared private resource and an eavesdropper holding the input purification and public record. A trace-preserving PPT channel on M_21( C) whose square is not entanglement breaking disproves Christandl's PPT-square conjecture.","nature":"algebre","domain":"information","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Entanglement with zero distillable secret key in local dimension ten","href":"preprints/Entanglement-with-zero-distillable-secret-key-in-local-dimension-ten-September-27-2026/paper.pdf"}],"plainFr":"Deux parties peuvent partager un état intriqué sans pouvoir en extraire une clé secrète. Le manuscrit affirme qu'un état intriqué sur un espace de dimension dix par dix a une clé distillable nulle pour les protocoles locaux qui terminent presque sûrement, même avec une communication publique dans les deux sens.","plainEn":"Two parties may share an entangled state without being able to extract a secret key. The manuscript asserts that an entangled state on a ten-by-ten space has zero distillable key for the local protocols that finish almost surely, even with public communication both ways.","expertFr":"Le manuscrit affirme un état intriqué de dimension dix par dix, sans clé secrète distillable pour les protocoles locaux presque sûrs, avec communication publique authentifiée et sans autre ressource privée. Il réfute la conjecture PPT à deux applications, et donne un canal PPT de taille vingt-et-un dont le carré ne brise pas l'intrication, contre Christandl.","expertEn":"The manuscript asserts a ten-by-ten entangled state with zero distillable secret key for almost surely terminating local protocols, with authenticated public communication and no other private resource. It disproves the two-map PPT conjecture and gives a size-twenty-one PPT channel whose square is not entanglement-breaking, against Christandl.","sparkFr":"La piste cryptographique est négative et théorique : l'intrication ne fournirait pas toujours une clé.","sparkEn":"The cryptographic lead is negative and theoretical: entanglement would not always yield a key."},{"id":"273","titleEn":"The entropy photon-number inequality","titleFr":"L'inégalité d'entropie du nombre de photons","claim":"Proves the entropy photon-number inequality for beam-splitter mixing of two independent finite-energy bosonic inputs in any finite number of modes: the output's entropy photon number is at least the transmissivity-weighted average of the inputs'. Arbitrary entanglement within each input is allowed, and product thermal inputs attain equality even when their entropies differ.","nature":"dynamique","domain":"information","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The entropy photon-number inequality","href":"preprints/The-entropy-photon-number-inequality-September-24-2026/paper.pdf"}],"plainFr":"Un séparateur de faisceau mélange deux signaux lumineux quantiques. Le manuscrit affirme que le nombre de photons compté par l'entropie de la sortie est au moins la moyenne pondérée des deux entrées indépendantes, d'énergie finie.","plainEn":"A beam splitter mixes two quantum light signals. The manuscript asserts that the photon number counted by the output entropy is at least the weighted average of the two independent finite-energy inputs.","expertFr":"Le manuscrit affirme l'inégalité d'entropie du nombre de photons pour le mélange, par séparateur de faisceau, de deux entrées bosoniques indépendantes d'énergie moyenne finie, en tout nombre fini de modes : la sortie vaut au moins la moyenne pondérée par la transmissivité. L'intrication interne à chaque entrée est permise, et des entrées thermiques en produit atteignent l'égalité même si leurs entropies diffèrent.","expertEn":"The manuscript asserts the entropy photon-number inequality for beam-splitter mixing of two independent bosonic inputs of finite mean energy, in every finite number of modes: the output is at least the transmissivity-weighted average. Entanglement inside each input is allowed, and product thermal inputs attain equality even when their entropies differ.","sparkFr":"Si l'on pense aux canaux optiques, le texte n'affirme qu'une borne d'entropie, pas un débit réalisé.","sparkEn":"If one thinks of optical channels, the text asserts only an entropy bound, not an achieved rate."},{"id":"274","titleEn":"Parity is not in QAC0","titleFr":"La parité n'est pas dans QAC0","claim":"Resolves Moore's parity conjecture in the measured-output model: constant-depth quantum circuits with arbitrary one-qubit gates, unbounded-arity Toffoli gates and polynomially many total qubits cannot compute parity with any fixed positive worst-case advantage. Ancillas start in zero, one output qubit is measured, and all other registers may be discarded. Xu–Li's reductions give the same bounded-error obstruction for strict majority.","nature":"informatique","domain":"information","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Product-projection localization and the QAC0 parity lower bound","href":"preprints/Product-projection-localization-and-the-QAC0-parity-lower-bound-September-24-2026/paper.pdf"},{"title":"Regular trajectories, pruning and quantum parity","href":"preprints/Regular-trajectories-pruning-and-quantum-parity-September-24-2026/paper.pdf"}],"plainFr":"La parité d'une suite de bits dit si le nombre de uns est pair. Le manuscrit affirme que des circuits quantiques de profondeur constante, avec des portes de Toffoli de taille libre et un nombre polynomial de qubits, ne la calculent pas avec un avantage fixe.","plainEn":"The parity of a bit string says whether the number of ones is even. The manuscript asserts that constant-depth quantum circuits, with unbounded Toffoli gates and polynomially many qubits, do not compute it with any fixed advantage.","expertFr":"Le manuscrit affirme la conjecture de parité de Moore : des circuits quantiques de profondeur constante, à portes sur un qubit et Toffoli d'arité libre, avec un nombre polynomial de qubits, ne calculent pas la parité avec un avantage fixe. Les ancillas partent de zéro, un qubit est mesuré, et Xu–Li donnent la même obstruction pour la majorité stricte.","expertEn":"The manuscript asserts Moore's parity conjecture in the measured-output model: constant-depth circuits with arbitrary one-qubit gates and unbounded-arity Toffoli gates do not compute parity with any fixed positive worst-case advantage, using polynomially many qubits. Ancillas start at zero, one qubit is measured, and the Xu–Li reductions give the same bounded-error obstruction for strict majority.","sparkFr":"L'intérêt est structural en complexité quantique : une profondeur constante ne suffirait pas pour la parité.","sparkEn":"The interest is structural in quantum complexity: constant depth would not suffice for parity."},{"id":"275","titleEn":"QMA-hardness of continuum Coulomb energy","titleFr":"Difficulté QMA de l'énergie coulombienne continue","claim":"Proves QMA-hardness of approximating the electronic Coulomb energy infimum in three dimensions, minimizing over the full spinful fermionic continuum space. Deterministic polynomial-time reductions work even with only unit-charge nuclei at distinct rational positions, polynomially many electrons and an energy-threshold separation of at least one.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Continuum Coulomb hardness with binary nuclear charges","href":"preprints/Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026/Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026.pdf"},{"title":"QMA-hardness of continuum Coulomb energy with unit nuclear charges","href":"preprints/QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026/QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026.pdf"}],"plainFr":"QMA désigne les problèmes qu'un vérificateur quantique peut contrôler à l'aide d'un témoin quantique. Le manuscrit affirme qu'approcher l'énergie coulombienne minimale des électrons en trois dimensions est difficile pour cette classe, même avec seulement des noyaux de charge un.","plainEn":"QMA names problems that a quantum verifier can check with a quantum witness. The manuscript asserts that approximating the minimal Coulomb energy of electrons in three dimensions is hard for this class, even with only unit-charge nuclei.","expertFr":"Le manuscrit affirme la QMA-difficulté de l'approximation de l'infimum de l'énergie coulombienne électronique en trois dimensions, sur tout l'espace fermionique continu avec spin. Des réductions déterministes en temps polynomial marchent même avec des noyaux de charge un en positions rationnelles distinctes, un nombre polynomial d'électrons et une séparation des seuils d'énergie au moins égale à un.","expertEn":"The manuscript asserts QMA-hardness of approximating the electronic Coulomb energy infimum in three dimensions, over the full spinful fermionic continuum. Deterministic polynomial-time reductions work even with unit-charge nuclei at distinct rational positions, polynomially many electrons, and an energy-threshold separation of at least one.","sparkFr":"La piste calculatoire reste une difficulté théorique d'approximation, sans algorithme pratique affirmé.","sparkEn":"The computational lead remains a theoretical hardness of approximation, with no practical algorithm asserted."},{"id":"276","titleEn":"Classical capacity of generalized amplitude damping","titleFr":"Capacité classique de l'atténuation d'amplitude généralisée","claim":"Determines the unassisted classical capacity of every qubit generalized amplitude-damping channel, including all damping and thermal parameters. An explicit one-variable optimization gives the capacity, attained by independent two-state signal ensembles with collective decoding. Holevo capacity, minimum output entropy and regularized classical capacity are additive when tensoring with any finite-dimensional quantum channel.","nature":"dynamique","domain":"information","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Classical capacity and entropy inequalities for generalized amplitude damping","href":"preprints/Classical-capacity-and-entropy-inequalities-for-generalized-amplitude-damping-September-24-2026/paper.pdf"}],"plainFr":"Ce canal quantique bruit un qubit en le rapprochant d'un état thermique. Le manuscrit affirme que sa capacité classique, sans aide extérieure, est donnée pour tous les paramètres par une optimisation explicite à une seule variable.","plainEn":"This quantum channel noisily drives a qubit toward a thermal state. The manuscript asserts that its unassisted classical capacity is given, for all parameters, by an explicit optimization in a single variable.","expertFr":"Le manuscrit affirme la capacité classique sans assistance de tout canal qubit d'atténuation d'amplitude généralisée : elle égale la capacité de Holevo en un usage et un maximum à une variable, atteint par un ensemble binaire d'états purs et par ses produits indépendants. Capacité de Holevo, entropie de sortie minimale et capacité classique régularisée sont additives avec tout canal quantique de dimension finie.","expertEn":"The manuscript asserts the unassisted classical capacity of every qubit generalized amplitude-damping channel: it equals the one-shot Holevo capacity and a one-variable maximum, attained by a binary pure-state ensemble and its independent products. Holevo capacity, minimum output entropy, and regularized classical capacity are additive with every finite-dimensional quantum channel.","sparkFr":"Le pont avec la communication quantique resterait un calcul de capacité, non un débit d'appareil.","sparkEn":"The bridge to quantum communication would remain a capacity computation, not a device rate."},{"id":"277","titleEn":"Threshold repetition for entangled games","titleFr":"Répétition à seuil pour les jeux intriqués","claim":"Proves exponential threshold repetition for every finite two-player one-round game: if its entangled value is v < 1, the probability of winning at least a fraction v+δ of k independent repetitions decays exponentially in k, for 0 δ 1-v. Arbitrary joint finite-dimensional entangled strategies and correlated question distributions are allowed.","nature":"algebre","domain":"hasard","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Threshold parallel repetition for finite-dimensional entangled games","href":"preprints/Threshold-parallel-repetition-for-finite-dimensional-entangled-games-September-25-2026/paper.pdf"}],"plainFr":"Un jeu à deux joueurs pose des questions et note les réponses selon une règle fixée. Le manuscrit affirme que si la meilleure valeur avec intrication est strictement inférieure à un, la chance de réussir une fraction nettement plus grande sur beaucoup de parties indépendantes décroît exponentiellement.","plainEn":"A two-player game asks questions and scores the answers by a fixed rule. The manuscript asserts that if the best value with entanglement is strictly below one, the chance of succeeding on a noticeably larger fraction of many independent rounds decays exponentially.","expertFr":"Le manuscrit affirme que pour tout jeu fini à deux joueurs et un tour de valeur intriquée v strictement inférieure à un, la probabilité de gagner au moins une fraction v plus delta de k répétitions indépendantes décroît exponentiellement en k, pour tout delta entre zéro et un moins v. Cela vaut uniformément pour les stratégies conjointes de dimension finie et pour des questions corrélées.","expertEn":"The manuscript asserts that for every finite two-player one-round game of entangled value v strictly below one, the probability of winning at least a fraction v plus delta of k independent repetitions decays exponentially in k, for every delta between zero and one minus v. This holds uniformly for finite-dimensional joint strategies and for correlated questions.","sparkFr":"L'intérêt est structural : répéter un jeu sous-optimal n'en ferait pas un succès fréquent.","sparkEn":"The interest is structural: repeating a suboptimal game would not make success frequent."},{"id":"278","titleEn":"Failure of Kohn–Sham ensemble representation","titleFr":"Échec de la représentation d'ensemble de Kohn–Sham","claim":"Constructs a three-electron Coulomb molecule with two equal positive-integer-charge nuclei whose absolute ground-state density has no noninteracting ground-state ensemble representation by a single real spin-independent local potential in L^3/2( R^3)+L^∞( R^3). This disproves Kohn–Sham ensemble representability for that potential class; the required nuclear charge is specified nonnumerically.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"A Coulomb ground-state density without Kohn-Sham ensemble representation","href":"preprints/A-Coulomb-Ground-State-Density-without-Kohn-Sham-Ensemble-Representation-September-25-2026/paper.pdf"}],"plainFr":"L'approche de Kohn–Sham espère remplacer des électrons en interaction par des électrons libres dans un seul potentiel qui reproduit la même densité. Le manuscrit affirme qu'une molécule à trois électrons a une densité d'état fondamental qu'aucun potentiel de la classe indiquée ne reproduit ainsi.","plainEn":"The Kohn–Sham approach hopes to replace interacting electrons by free electrons in one potential that reproduces the same density. The manuscript asserts that a three-electron molecule has a ground-state density that no potential in the stated class reproduces in this way.","expertFr":"Le manuscrit affirme une molécule coulombienne à trois électrons et deux noyaux de même charge entière positive, spécifiée sans nombre décimal, dont la densité d'état fondamental sommée sur le spin n'est la densité d'aucun ensemble d'état fondamental sans interaction dans un potentiel local réel indépendant du spin de la classe indiquée. Cela réfute la représentabilité d'ensemble de Kohn–Sham pour cette classe.","expertEn":"The manuscript asserts a three-electron Coulomb molecule with two equal positive integer nuclear charges, specified without a decimal, whose spin-summed ground-state density is not the density of any noninteracting ground-state ensemble in a real spin-independent local potential of the stated class. This disproves Kohn–Sham ensemble representability for that class.","sparkFr":"La piste en chimie quantique est un contre-exemple de représentabilité, non une méthode de calcul.","sparkEn":"The quantum-chemistry lead is a representability counterexample, not a computational method."},{"id":"279","titleEn":"Exact quantum factoring over a fixed finite gate set","titleFr":"Factorisation quantique exacte sur un jeu de portes fini fixé","claim":"Gives a polynomial-time uniform quantum circuit family that outputs the complete prime factorization of every integer with probability one. Both gate count and qubit count are polynomial in the input length, and one fixed finite gate set suffices.","nature":"informatique","domain":"information","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Exact quantum factoring over a fixed finite gate set","href":"preprints/Exact-quantum-factoring-over-a-fixed-finite-gate-set-September-25-2026/main.pdf"}],"plainFr":"Factoriser un entier, c'est l'écrire comme produit de nombres premiers. Le manuscrit affirme une famille uniforme de circuits quantiques, de taille polynomiale et sur un jeu fini fixé de portes, qui donne la factorisation complète de tout entier avec probabilité un.","plainEn":"To factor an integer is to write it as a product of primes. The manuscript asserts a uniform family of quantum circuits, of polynomial size and over one fixed finite gate set, that outputs the complete factorization of every integer with probability one.","expertFr":"Le manuscrit affirme une famille uniforme de circuits quantiques en temps polynomial qui produit la factorisation première complète de tout entier au moins deux avec probabilité un. Un jeu fini fixé de portes d'arité bornée suffit, et le nombre de portes comme le nombre de qubits admettent une borne polynomiale en la longueur de l'entrée.","expertEn":"The manuscript asserts a polynomial-time uniform quantum circuit family that outputs the complete prime factorization of every integer at least two with probability one. One fixed finite set of bounded-arity gates suffices, and both gate count and qubit count have polynomial bounds in the input length.","sparkFr":"La piste algorithmique est théorique : le texte affirme un circuit exact, sans machine construite.","sparkEn":"The algorithmic lead is theoretical: the text asserts an exact circuit, with no machine built."},{"id":"280","titleEn":"Unitary vertex operator algebras and conformal nets","titleFr":"Algèbres d'opérateurs de vertex unitaires et réseaux conformes","claim":"Proves the strongly rational case of the strong-locality conjecture: every simple unitary strongly rational complex vertex operator algebra generates a completely rational conformal net. Its simple modules are unitarizable, and its representation category agrees with the net’s finite-index sectors as a braided unitary tensor category.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Strongly rational unitary vertex operator algebras and conformal nets","href":"preprints/Strongly-rational-unitary-vertex-operator-algebras-and-conformal-nets-September-25-2026/paper.pdf"}],"plainFr":"Une algèbre d'opérateurs de vertex encode, de façon algébrique, les symétries d'une théorie conforme des champs. Le manuscrit affirme que, dans le cas unitaire simple et fortement rationnel, elle engendre un réseau conforme complètement rationnel dont les secteurs coïncident avec ses modules.","plainEn":"A vertex operator algebra encodes, algebraically, the symmetries of a conformal field theory. The manuscript asserts that in the simple unitary strongly rational case, it generates a completely rational conformal net whose sectors match its modules.","expertFr":"Le manuscrit affirme le cas fortement rationnel de la conjecture de localité forte : toute algèbre d'opérateurs de vertex complexe, unitaire, simple et fortement rationnelle, engendre un réseau conforme complètement rationnel. Ses modules simples sont unitarisables, et sa catégorie de représentations équivaut, comme catégorie tensorielle unitaire tressée, aux secteurs d'indice fini du réseau.","expertEn":"The manuscript asserts the strongly rational case of the strong-locality conjecture: every simple unitary strongly rational complex vertex operator algebra generates a completely rational conformal net. Its simple modules are unitarizable, and its representation category agrees, as a braided unitary tensor category, with the finite-index sectors of the net.","sparkFr":"L'intérêt est structural : deux langages de la théorie conforme s'identifieraient dans ce cas rationnel.","sparkEn":"The interest is structural: two languages of conformal theory would match in this rational case."},{"id":"281","titleEn":"QAOA attains the SK optimum in the thermodynamic-first limit","titleFr":"QAOA atteint l'optimum de Sherrington–Kirkpatrick si la taille tend d'abord vers l'infini","claim":"Proves that QAOA approaches the ground-state energy of the Gaussian zero-field Sherrington–Kirkpatrick model when system size tends to infinity before circuit depth. For every accuracy, finite depth and deterministic angles independent of size and disorder achieve the required limiting expected energy per spin. This also yields leading-order optimal expected MaxCut values on large-degree random regular graphs, with size tending to infinity before degree.","nature":"physique-math","domain":"calcul","complexity":"avance","problemYear":1975,"yearKnown":true,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"QAOA attains the SK ground-state energy in the thermodynamic-first limit","href":"preprints/QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026/QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026.pdf"},{"title":"Full support of the zero-temperature Sherrington-Kirkpatrick order parameter","href":"preprints/Full-support-of-the-zero-temperature-Sherrington-Kirkpatrick-order-parameter-September-27-2026/main.pdf"}],"plainFr":"QAOA est un algorithme quantique à couches qui cherche une énergie minimale. Le manuscrit affirme qu'il approche l'énergie fondamentale du modèle de verres de spin de Sherrington–Kirkpatrick gaussien à champ nul lorsque la taille tend vers l'infini avant la profondeur.","plainEn":"QAOA is a layered quantum algorithm that seeks a minimal energy. The manuscript asserts that it approaches the ground-state energy of the Gaussian zero-field Sherrington–Kirkpatrick spin-glass model when size tends to infinity before depth.","expertFr":"Le manuscrit affirme que QAOA approche l'énergie par spin du modèle de Sherrington–Kirkpatrick gaussien à champ nul quand la taille tend vers l'infini avant la profondeur. Pour toute précision, une profondeur finie et des angles fixes, indépendants de la taille et du désordre, suffisent, et donnent aussi l'ordre principal de MaxCut sur de grands graphes réguliers aléatoires.","expertEn":"The manuscript asserts that QAOA approaches the ground-state energy per spin of the Gaussian zero-field Sherrington–Kirkpatrick model when size tends to infinity before circuit depth. For every accuracy, finite depth and deterministic angles independent of size and disorder suffice; the text also deduces leading-order expected optimality for MaxCut on large random regular graphs, with size before degree.","sparkFr":"La piste algorithmique reste asymptotique : aucune profondeur chiffrée ni machine n'est affirmée.","sparkEn":"The algorithmic lead stays asymptotic: neither a numerical depth nor a machine is asserted."},{"id":"282","titleEn":"From scale symmetry to local conformal symmetry in four-dimensional QFT","titleFr":"De la symétrie d'échelle à la symétrie conforme locale en dimension quatre","claim":"Under the stated bounded-local-net and field-reconstruction hypotheses, proves that scale symmetry implies local conformal symmetry for four-dimensional unitary positive-energy theories with a discrete bounded-below scaling spectrum of finite multiplicity, finite scaling support and a physical local scale current. The stress tensor has a traceless improvement with unchanged spacetime charges. The conclusion concerns local Ward identities, not a global conformal action on the whole net.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":false,"pdfs":[{"title":"Scale and conformal symmetry in four-dimensional operational quantum field theory","href":"preprints/Scale-and-conformal-symmetry-in-four-dimensional-operational-quantum-field-theory-September-26-2026/main.pdf"}],"plainFr":"Une théorie quantique des champs peut rester la même quand on change l'échelle des longueurs. Le manuscrit affirme que, sous les hypothèses indiquées en dimension quatre, cette symétrie d'échelle implique une symétrie conforme locale.","plainEn":"A quantum field theory may stay the same when lengths are rescaled. The manuscript asserts that, under the stated hypotheses in four dimensions, this scale symmetry implies local conformal symmetry.","expertFr":"Sous les hypothèses indiquées de réseau borné, de courant d'échelle et de spectre discret minoré, le manuscrit affirme que la symétrie d'échelle implique la conformité locale pour des théories unitaires d'énergie positive en dimension quatre. Le tenseur d'énergie-impulsion a une amélioration sans trace aux charges inchangées ; la conclusion porte sur des identités locales, non sur une action globale.","expertEn":"Under the stated bounded-net, scale-current, and discrete spectrum hypotheses, the manuscript asserts that scale symmetry implies local conformal symmetry for four-dimensional unitary positive-energy theories. The stress tensor has a traceless improvement with unchanged charges; the conclusion is local identities, not a global action on the whole net.","sparkFr":"L'intérêt reste interne à la théorie quantique des champs axiomatique, sans modèle physique particulier.","sparkEn":"The interest stays inside axiomatic quantum field theory, with no particular physical model."},{"id":"283","titleEn":"Polynomial-time unitary synthesis from a Boolean oracle","titleFr":"Synthèse unitaire en temps polynomial à partir d'un oracle booléen","claim":"Solves the constant-error Aaronson–Kuperberg unitary synthesis problem: a uniform polynomial-size quantum oracle circuit approximates every n-qubit unitary channel within diamond-norm error 1/2, after a suitable Boolean oracle is chosen. Gates, qubits, oracle calls and query length are polynomially bounded. The target-dependent oracle may have an unrestricted truth table; its efficient classical construction is not asserted.","nature":"informatique","domain":"information","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"Polynomial-Time Unitary Synthesis from a Boolean Oracle","href":"preprints/Polynomial-Time-Unitary-Synthesis-from-a-Boolean-Oracle-October-5-2026/paper.pdf"}],"plainFr":"Synthétiser une transformation unitaire, c'est approcher n'importe quelle évolution quantique réversible par un circuit. Le manuscrit affirme qu'un circuit uniforme de taille polynomiale, après choix d'un oracle booléen adapté, approche toute transformation sur n qubits avec une erreur constante.","plainEn":"Unitary synthesis means approximating any reversible quantum evolution by a circuit. The manuscript asserts that a uniform polynomial-size circuit, after a suitable Boolean oracle is chosen, approximates every transformation on n qubits to a constant error.","expertFr":"Le manuscrit affirme la synthèse unitaire d'Aaronson–Kuperberg à erreur constante : un circuit oracle polynomial approche tout canal sur n qubits à erreur diamant au plus un demi, après choix d'un oracle booléen. Portes, qubits et appels sont polynomiaux ; une construction classique efficace de l'oracle n'est pas affirmée.","expertEn":"The manuscript asserts the constant-error Aaronson–Kuperberg unitary synthesis problem: a quantum oracle circuit, generated in polynomial time from n alone, approximates every n-qubit unitary channel to diamond-norm error at most one half, once the Boolean oracle is chosen. Gates, qubits, calls, and query length are polynomial; efficient classical construction of the truth table is not asserted.","sparkFr":"La piste est conditionnelle à un oracle : le texte n'affirme pas sa construction classique efficace.","sparkEn":"The lead is conditional on an oracle: the text does not assert its efficient classical construction."},{"id":"284","titleEn":"The optimal quartic separation between randomized and quantum queries","titleFr":"La séparation quartique optimale entre requêtes aléatoires et quantiques","claim":"Shows that the universal bound R(f)=O((1+Q(f))^4) for total Boolean functions is sharp in its exponent, ruling out every smaller power and disproving the conjectured cubic relation. Here R and Q are randomized and quantum worst-case bit-query complexities with error at most 1/3; computation between queries is unrestricted.","nature":"informatique","domain":"information","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"A Nearly Quartic Separation Between Randomized and Quantum Query Complexity","href":"preprints/A-Nearly-Quartic-Separation-Between-Randomized-and-Quantum-Query-Complexity-October-5-2026/quartic-query-separation.pdf"}],"plainFr":"La complexité en requêtes compte combien de bits d'une entrée il faut lire. Le manuscrit affirme que l'écart entre lectures aléatoires et lectures quantiques peut être presque une puissance quatre, et qu'aucune puissance plus petite ne convient à toutes les fonctions booléennes totales.","plainEn":"Query complexity counts how many bits of an input must be read. The manuscript asserts that the gap between randomized and quantum readings can be nearly a fourth power, and that no smaller power works for every total Boolean function.","expertFr":"Le manuscrit affirme que la borne universelle faisant de la complexité aléatoire un grand O de la puissance quatre de un plus la complexité quantique, pour les fonctions booléennes totales, est optimale en l'exposant. Tout exposant strictement inférieur à quatre est exclu, ce qui réfute la relation cubique conjecturée ; les deux complexités comptent des requêtes de bits au pire cas, à erreur au plus un tiers.","expertEn":"The manuscript asserts that the universal bound making randomized complexity a big O of the fourth power of one plus quantum complexity, for total Boolean functions, is optimal in the exponent. Every exponent strictly below four is ruled out, disproving the conjectured cubic relation; both complexities count worst-case bit queries with error at most one third.","sparkFr":"L'intérêt est structural en complexité des requêtes : l'exposant quatre serait le meilleur possible.","sparkEn":"The interest is structural in query complexity: the exponent four would be the best possible."},{"id":"285","titleEn":"Counterexamples to Baum–Connes and Kadison–Kaplansky","titleFr":"Contre-exemples à Baum–Connes et à Kadison–Kaplansky","claim":"Disproves the coefficient-free reduced Baum–Connes conjecture through a failure of rational injectivity and a separate failure of surjectivity of assembly. A finitely generated torsion-free example witnesses the injectivity failure. Separately, a torsion-free group has a nontrivial projection in its reduced group C∗-algebra, disproving the Kadison–Kaplansky conjecture.","nature":"operateurs","domain":"structures","complexity":"avance","problemYear":1970,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A torsion-free counterexample to reduced Baum–Connes injectivity","href":"preprints/A-Torsion-Free-Counterexample-to-Reduced-Baum-Connes-Injectivity-September-23-2026/paper.pdf"},{"title":"A torsion-free counterexample to the Kadison–Kaplansky projection conjecture","href":"preprints/A-Torsion-Free-Counterexample-to-the-Kadison-Kaplansky-Projection-Conjecture-September-23-2026/paper.pdf"},{"title":"An irrational-trace counterexample to reduced Baum–Connes","href":"preprints/An-Irrational-Trace-Counterexample-to-Reduced-Baum-Connes-September-23-2026/paper.pdf"}],"plainFr":"La conjecture de Baum–Connes relie la géométrie d'un groupe à une algèbre d'opérateurs associée. Le manuscrit affirme que sa forme réduite sans coefficients échoue, et qu'un groupe sans torsion a une projection non triviale dans son algèbre réduite, contre la conjecture de Kadison–Kaplansky.","plainEn":"The Baum–Connes conjecture relates the geometry of a group to an associated operator algebra. The manuscript asserts that its coefficient-free reduced form fails, and that a torsion-free group has a nontrivial projection in its reduced algebra, against the Kadison–Kaplansky conjecture.","expertFr":"Le manuscrit affirme l'échec de l'injectivité rationnelle, et séparément de la surjectivité, de l'assemblage de Baum–Connes réduit sans coefficients ; un groupe discret de type fini et sans torsion a une classe de noyau d'ordre infini en degré zéro. Séparément, un groupe sans torsion possède une projection non triviale dans son algèbre de groupe réduite, ce qui réfute la conjecture de Kadison–Kaplansky.","expertEn":"The manuscript asserts the failure of rational injectivity, and separately of surjectivity, of coefficient-free reduced Baum–Connes assembly; a finitely generated torsion-free discrete group has an infinite-order kernel class in degree zero. Separately, a torsion-free group has a nontrivial projection in its reduced group algebra, disproving the Kadison–Kaplansky conjecture.","sparkFr":"L'intérêt est structural : ces deux conjectures échoueraient même pour des groupes sans torsion.","sparkEn":"The interest is structural: these two conjectures would fail even for torsion-free groups."},{"id":"286","titleEn":"Rigidity and arithmetic of lattice von Neumann algebras","titleFr":"Rigidité et arithmétique des algèbres de von Neumann de réseaux","claim":"Classifies finite-index bimodules between scalar-twisted group factors of ICC groups commensurable with property-(T) lattices over characteristic-zero local fields and arbitrary ICC group factors. Every such bimodule is a summand of finite sums of models arising from finite-index subgroup isomorphisms and finite-dimensional projective representations. The classification also recovers the group, scalar cocycle and amplification scale up to the stated stable equivalence.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1920,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Arithmeticity of twisted finite correspondences for lattices over local fields","href":"preprints/Arithmeticity-of-twisted-finite-correspondences-for-lattices-over-local-fields-September-23-2026/paper.pdf"},{"title":"The arithmetic category and stable recovery of lattice factors","href":"preprints/The-arithmetic-category-and-stable-recovery-of-lattice-factors-September-23-2026/paper.pdf"}],"plainFr":"L'algèbre de von Neumann d'un groupe est l'algèbre d'opérateurs engendrée par ses translations. Le manuscrit affirme une classification des correspondances d'indice fini entre certains facteurs issus de réseaux à propriété (T) et des facteurs de groupes quelconques.","plainEn":"The von Neumann algebra of a group is the operator algebra generated by its translations. The manuscript asserts a classification of finite-index correspondences between certain factors from property-(T) lattices and factors of arbitrary groups.","expertFr":"Le manuscrit affirme que tout bimodule d'indice fini entre facteurs de groupes à conjugaison infinie, l'un tordu et commensurable à un réseau de propriété (T) sur un corps local de caractéristique nulle, est sommant de modèles venus d'isomorphismes de sous-groupes d'indice fini et de représentations projectives finies. On retrouve le groupe, le cocycle et l'échelle, à l'équivalence stable indiquée.","expertEn":"The manuscript asserts that every finite-index bimodule between ICC group factors, one scalar-twisted and commensurable with a property-(T) lattice over a characteristic-zero local field, is a summand of models from finite-index subgroup isomorphisms and finite-dimensional projective representations. The group, cocycle, and scale are recovered up to the stated stable equivalence.","sparkFr":"L'intérêt est structural : ces algèbres d'opérateurs retrouveraient le réseau qui les engendre.","sparkEn":"The interest is structural: these operator algebras would recover the lattice that generates them."},{"id":"287","titleEn":"Isomorphism of the free group factors","titleFr":"Isomorphisme des facteurs des groupes libres","claim":"Resolves the free group factor isomorphism problem: L( F_2) L( F_3), and hence all interpolated free group factors, including L( F_∞), are isomorphic. Their common factor has fundamental group R_ 0.","nature":"operateurs","domain":"structures","complexity":"avance","problemYear":1936,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An isomorphism of the free group factors","href":"preprints/An-isomorphism-of-the-free-group-factors-September-23-2026/An-isomorphism-of-the-free-group-factors-September-23-2026.pdf"}],"plainFr":"Le facteur d'un groupe libre est une algèbre d'opérateurs bâtie sur les mots réduits de ce groupe. Le manuscrit affirme que les facteurs des groupes libres à deux et à trois générateurs sont les mêmes, et donc que tous les facteurs libres interpolés le sont aussi.","plainEn":"The factor of a free group is an operator algebra built from the reduced words of that group. The manuscript asserts that the factors of the free groups on two and three generators are the same, and hence that all interpolated free factors are the same.","expertFr":"Le manuscrit affirme que les facteurs du groupe libre à deux générateurs et à trois générateurs sont isomorphes comme algèbres de von Neumann à trace, ce qui résout le problème d'isomorphisme des facteurs libres. L'alternative classique implique alors que tous les facteurs libres interpolés, y compris celui du groupe libre infini, sont isomorphes et ont pour groupe fondamental les réels strictement positifs.","expertEn":"The manuscript asserts that the factors of the free group on two generators and on three generators are isomorphic as tracial von Neumann algebras, resolving the free group factor isomorphism problem. The classical alternative then implies that all interpolated free group factors, including the infinite one, are isomorphic and have fundamental group the positive reals.","sparkFr":"L'intérêt est structural : le nombre de générateurs libres ne distinguerait plus ces facteurs.","sparkEn":"The interest is structural: the number of free generators would no longer distinguish these factors."},{"id":"288","titleEn":"Kadison's similarity conjecture","titleFr":"La conjecture de similarité de Kadison","claim":"Proves Kadison's similarity conjecture: every bounded complex-linear unital algebra homomorphism from a unital complex C∗-algebra to operators on a Hilbert space becomes a *-homomorphism after conjugation by a bounded invertible operator.","nature":"operateurs","domain":"structures","complexity":"frontiere","problemYear":1955,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Kadison's similarity theorem through uniform derivation estimates","href":"preprints/Kadisons-similarity-theorem-through-uniform-derivation-estimates-September-23-2026/paper.pdf"}],"plainFr":"Un homomorphisme d'algèbres préserve les produits, pas forcément l'adjoint. Le manuscrit affirme que tout homomorphisme borné unitaire, d'une algèbre d'opérateurs complexe vers un espace de Hilbert, devient compatible avec l'adjoint après un changement de base borné inversible.","plainEn":"An algebra homomorphism preserves products, without necessarily preserving adjoints. The manuscript asserts that every bounded unital homomorphism from a complex operator algebra of the stated kind to operators on a Hilbert space becomes adjoint-compatible after a bounded invertible change of basis.","expertFr":"Le manuscrit affirme la conjecture de similarité de Kadison : tout homomorphisme d'algèbres, linéaire complexe, borné et unitaire, d'une algèbre C-étoile complexe unitaire vers les opérateurs bornés d'un espace de Hilbert, est semblable à un homomorphisme étoile. Il obtient aussi une constante universelle d'hyperréflexivité pour toutes les algèbres de von Neumann unitaires.","expertEn":"The manuscript asserts Kadison's similarity conjecture: every bounded complex-linear unital algebra homomorphism from a unital complex C-star algebra to the bounded operators on a Hilbert space is similar to a star-homomorphism. It also obtains one universal hyperreflexivity constant for all unital von Neumann algebras.","sparkFr":"L'intérêt est structural : bornitude et produit suffiraient à retrouver l'adjoint, à conjugaison près.","sparkEn":"The interest is structural: boundedness and the product would suffice to recover the adjoint, up to conjugation."},{"id":"289","titleEn":"Strong Kadison–Kastler stability and its spatial boundaries","titleFr":"Stabilité forte de Kadison–Kastler et ses frontières spatiales","claim":"Proves that sufficiently close unital von Neumann algebras on the same Hilbert space are conjugate by a unitary arbitrarily close to the identity, with a universal tolerance in the operator-norm distance between unit balls. Counterexamples show that near-identity conjugacy fails for one-sided near inclusions, and that arbitrarily close norm-separable C∗-algebras need not be ambiently unitarily conjugate.","nature":"operateurs","domain":"formes","complexity":"avance","problemYear":1955,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Universal strong Kadison–Kastler stability","href":"preprints/Universal-strong-Kadison-Kastler-stability-September-23-2026/paper.pdf"},{"title":"Near Inclusions of von Neumann Algebras Without Small Spatial Embeddings","href":"preprints/Near-Inclusions-of-von-Neumann-Algebras-Without-Small-Spatial-Embeddings-October-5-2026/near-inclusions.pdf"},{"title":"Close Separable C*-Algebras Without Spatial Conjugacy","href":"preprints/Close-Separable-Cstar-Algebras-Without-Spatial-Conjugacy-October-5-2026/paper.pdf"}],"plainFr":"Deux algèbres d'opérateurs sont proches lorsque leurs éléments de norme au plus un sont voisins. Le manuscrit affirme que des algèbres de von Neumann unitaires assez proches, sur le même espace, sont conjuguées par un unitaire arbitrairement proche de l'identité.","plainEn":"Two operator algebras are close when their elements of norm at most one lie near each other. The manuscript asserts that sufficiently close unital von Neumann algebras, on the same space, are conjugate by a unitary arbitrarily close to the identity.","expertFr":"Le manuscrit affirme que des algèbres de von Neumann unitaires assez proches sont conjuguées par un unitaire arbitrairement proche de l'identité, avec une tolérance universelle, résolvant la conjecture forte de Kadison–Kastler. Cette conjugaison échoue pour des inclusions unilatérales, et des algèbres C-étoile séparables proches ne sont pas toujours conjuguées dans l'espace ambiant.","expertEn":"The manuscript asserts that sufficiently close unital von Neumann algebras are conjugate by a unitary arbitrarily close to the identity, with a universal tolerance in the norm distance between unit balls, resolving the strong Kadison–Kastler conjecture. Counterexamples show failure for one-sided near inclusions, and for arbitrarily close separable C-star algebras that are not ambiently unitarily conjugate.","sparkFr":"L'intérêt est structural : la proximité des boules forcerait une conjugaison, avec des limites nettes.","sparkEn":"The interest is structural: closeness of the balls would force conjugacy, with sharp boundaries."},{"id":"290","titleEn":"Relative bicentralizers and modular spectral recovery","titleFr":"Bicentraliseurs relatifs et récupération spectrale modulaire","claim":"Proves Connes' bicentralizer conjecture for every type III1 factor with separable predual and every faithful normal state. More generally, for every inclusion N⊂ M of von Neumann algebras with separable preduals admitting a faithful normal conditional expectation, constructs an amenable expected subalgebra P⊂ N with P'∩ c(M)=N'∩ c(M), resolving the relative bicentralizer conjecture.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1980,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Expected amenable subalgebras preserving core commutants","href":"preprints/Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026/Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026.pdf"},{"title":"Bounded recovery for modular spectral averages","href":"preprints/Bounded-recovery-for-modular-spectral-averages-September-23-2026/Bounded-recovery-for-modular-spectral-averages-September-23-2026.pdf"}],"plainFr":"Le bicentraliseur d'un état rassemble les opérateurs qui commutent avec lui dans un certain cœur de l'algèbre. Le manuscrit affirme la conjecture de bicentraliseur de Connes pour tout facteur de type III un à prédual séparable et tout état fidèle normal.","plainEn":"The bicentralizer of a state gathers the operators that commute with it inside a certain core of the algebra. The manuscript asserts Connes' bicentralizer conjecture for every type III-one factor with separable predual and every faithful normal state.","expertFr":"Le manuscrit affirme la conjecture du bicentraliseur de Connes pour tout facteur de type III un à prédual séparable et tout état normal fidèle. Plus généralement, pour toute inclusion d'algèbres de von Neumann à préduaux séparables admettant une espérance conditionnelle normale fidèle, il construit une sous-algèbre moyennable attendue dont le commutant coupe le cœur continu comme celui de la plus petite algèbre.","expertEn":"The manuscript asserts Connes' bicentralizer conjecture for every type III-one factor with separable predual and every faithful normal state. More generally, for every inclusion of von Neumann algebras with separable preduals and a faithful normal conditional expectation, it builds an amenable expected subalgebra whose commutant meets the continuous core as that of the smaller algebra does.","sparkFr":"L'intérêt est structural : le bicentraliseur relatif serait contrôlé par une sous-algèbre moyennable.","sparkEn":"The interest is structural: the relative bicentralizer would be controlled by an amenable subalgebra."},{"id":"291","titleEn":"Cuntz comparison, nuclear dimension, and equivariant Jiang–Su stability","titleFr":"Comparaison de Cuntz, dimension nucléaire et stabilité équivariante de Jiang–Su","claim":"Proves equivariant Jiang–Su stability for every countable discrete amenable group action on a simple separable unital infinite-dimensional nuclear stably finite Jiang–Su-stable C∗-algebra, resolving this case of Szabó's conjecture without restrictions on trace dynamics. The family also proves the unital Toms–Winter conjecture, equating strict comparison, finite nuclear dimension and Jiang–Su stability in the simple separable unital infinite-dimensional nuclear setting.","nature":"analyse","domain":"formes","complexity":"avance","problemYear":1929,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Equivariant Jiang–Su Stability for Amenable Actions in the Unital Stably Finite Case","href":"preprints/Equivariant-Jiang-Su-Stability-for-Amenable-Actions-in-the-Unital-Stably-Finite-Case-October-5-2026/paper.pdf"},{"title":"Cuntz comparison and Jiang–Su absorption","href":"preprints/Cuntz-comparison-and-Jiang-Su-absorption-September-23-2026/paper.pdf"},{"title":"Nuclear dimension and Jiang–Su stability without elementary subquotients","href":"preprints/Nuclear-dimension-and-Jiang-Su-stability-without-elementary-subquotients-September-23-2026/paper.pdf"},{"title":"Tracial projection methods and uniform property Gamma","href":"preprints/Tracial-projection-methods-and-uniform-property-Gamma-September-23-2026/paper.pdf"}],"plainFr":"L'algèbre de Jiang–Su est un objet modèle qui peut absorber certaines algèbres d'opérateurs sans changer leur type. Le manuscrit affirme que toute action d'un groupe discret dénombrable moyennable sur une algèbre nucléaire simple déjà stable en ce sens absorbe l'action triviale sur ce modèle.","plainEn":"The Jiang–Su algebra is a model object that can absorb certain operator algebras without changing their type. The manuscript asserts that every action of a countable discrete amenable group on a simple nuclear algebra already stable in this sense absorbs the trivial action on that model.","expertFr":"Le manuscrit affirme que toute action d'un groupe discret dénombrable moyennable sur une algèbre nucléaire simple, séparable, unitaire, stablement finie et déjà stable au sens de Jiang–Su absorbe l'action triviale, sans condition sur les traces. La famille affirme aussi la conjecture unitaire de Toms–Winter : comparaison stricte, dimension nucléaire finie et stabilité de Jiang–Su s'équivalent.","expertEn":"The manuscript asserts equivariant Jiang–Su stability for every countable discrete amenable group action on a simple separable unital nuclear infinite-dimensional stably finite C-star algebra that is already Jiang–Su stable, with no trace restriction. The family also asserts the unital Toms–Winter conjecture, equating strict comparison, finite nuclear dimension, and Jiang–Su stability in this setting.","sparkFr":"L'intérêt est structural : plusieurs régularités des algèbres nucléaires y seraient équivalentes.","sparkEn":"The interest is structural: several regularities of nuclear algebras would be equivalent here."},{"id":"292","titleEn":"Kirchberg's O_2 norm-ultrapower embedding problem","titleFr":"Le problème de plongement dans l'ultrapuissance en norme de Kirchberg","claim":"Constructs an explicit separable unital full group C∗-algebra that cannot embed unitally into the norm ultrapower of any fixed nonzero unital nuclear C∗-algebra, for any free ultrafilter on the natural numbers. Taking the target to be O_2 answers Kirchberg's norm-ultrapower embedding problem negatively.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"An explicit obstruction to nuclear norm-ultrapower embeddings","href":"preprints/An-explicit-obstruction-to-nuclear-norm-ultrapower-embeddings-September-23-2026/paper.pdf"}],"plainFr":"Une ultrapuissance en norme est une limite idéale d'algèbres le long d'un ultrafiltre. Le manuscrit affirme qu'une algèbre de groupe pleine, séparable et explicite, ne se plonge pas dans l'ultrapuissance d'une algèbre nucléaire non nulle, ni dans celle de l'algèbre de Cuntz O2.","plainEn":"A norm ultrapower is an ideal limit of an operator algebra along an ultrafilter. The manuscript asserts that an explicit separable unital full group algebra does not embed unitally into the ultrapower of a nonzero unital nuclear algebra, in particular not into that of the Cuntz algebra O2.","expertFr":"Le manuscrit affirme une réponse négative au problème de plongement dans l'ultrapuissance en norme de Kirchberg. Il construit une algèbre C-étoile de groupe pleine, séparable et unitaire, explicite, sans plongement unitaire dans l'ultrapuissance en norme d'une algèbre nucléaire unitaire non nulle, pour aucun ultrafiltre libre sur les entiers, et en particulier pas dans celle de O2.","expertEn":"The manuscript asserts a negative answer to Kirchberg's norm-ultrapower embedding problem. It constructs an explicit separable unital full group C-star algebra with no unital embedding into the norm ultrapower of any nonzero unital nuclear algebra, for any free ultrafilter on the integers, and in particular not into that of O2.","sparkFr":"L'intérêt est structural : même O2 n'absorberait pas toute algèbre séparable dans son ultrapuissance.","sparkEn":"The interest is structural: even O2 would not absorb every separable algebra in its ultrapower."},{"id":"293","titleEn":"Invariant projections, hyperinvariant subspaces, and transitive algebras","titleFr":"Projections invariantes, sous-espaces hyperinvariants et algèbres transitives","claim":"Constructs a nonzero norm-quasinilpotent operator on every infinite-dimensional separable complex Hilbert space with no nonzero proper closed subspace invariant under every commuting operator. The construction also gives operators with no nontrivial invariant projection in the hyperfinite type II1 factor.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Invariant-projection counterexamples for every irrational rotation","href":"preprints/Invariant-projection-counterexamples-for-every-irrational-rotation-September-27-2026/paper.pdf"},{"title":"Backward intertwiners and a transitive commutant","href":"preprints/Backward-intertwiners-and-a-transitive-commutant-September-27-2026/paper.pdf"}],"plainFr":"Un sous-espace invariant est une direction qu'un opérateur, et ceux qui commutent avec lui, ne quittent pas. Le manuscrit affirme que, sur tout grand espace de Hilbert séparable, un opérateur non nul presque nilpotent en norme peut n'avoir aucun sous-espace fermé propre non nul de cette sorte.","plainEn":"An invariant subspace is a direction that an operator, and those that commute with it, never leave. The manuscript asserts that on every large separable Hilbert space, a nonzero almost nilpotent operator may have no nonzero proper closed subspace of this kind.","expertFr":"Le manuscrit affirme, sur tout Hilbert complexe séparable infini, un opérateur non nul quasi nilpotent en norme sans sous-espace fermé propre invariant sous tous les commutants. Pour tout angle irrationnel, un poids du cercle donne aussi un opérateur sans projection invariante non triviale dans le facteur hyperfini de type II un, contre Zhu, Fang et Shi.","expertEn":"The manuscript asserts, on every infinite-dimensional separable complex Hilbert space, a nonzero norm-quasinilpotent operator with no nonzero proper closed subspace invariant under every commuting operator. The construction also gives, for every irrational angle, a continuous circle weight with no nontrivial invariant projection in the hyperfinite type II-one factor, against the question of Zhu, Fang, and Shi.","sparkFr":"L'intérêt est structural : la commutation ne forcerait pas toujours un sous-espace invariant non trivial.","sparkEn":"The interest is structural: commutation would not always force a nontrivial invariant subspace."},{"id":"294","titleEn":"Kaplansky's quasitrace conjecture and failure of tensor-product stable finiteness","titleFr":"Quasi-traces de Kaplansky et échec de la finitude stable par produit tensoriel","claim":"Disproves Kaplansky's quasitrace conjecture by constructing a separable unital complex C∗-algebra admitting normalized 2-quasitraces, all of which are nonadditive. As a consequence, two unital simple stably finite C∗-algebras can have a properly infinite minimal tensor product, with one factor C_r^*( F_2).","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1970,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A counterexample to Kaplansky's quasitrace conjecture and failure of tensor-product stable finiteness","href":"preprints/A-counterexample-to-Kaplanskys-quasitrace-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Une trace mesure de façon additive la taille des éléments positifs d'une algèbre d'opérateurs. Le manuscrit affirme une algèbre séparable et unitaire qui admet des quasi-traces normalisées d'ordre deux, toutes non additives, et donc aucune trace.","plainEn":"A trace additively measures the size of the positive elements of an operator algebra. The manuscript asserts a separable unital algebra that admits normalized two-quasitraces, all nonadditive, and hence no trace.","expertFr":"Le manuscrit affirme la réfutation de la conjecture des quasi-traces de Kaplansky par une algèbre C-étoile complexe séparable et unitaire qui admet des 2-quasi-traces normalisées mais aucun état tracial. En conséquence, le produit tensoriel minimal de deux algèbres unitaires simples stablement finies peut être proprement infini, même si l'un des facteurs est l'algèbre réduite du groupe libre à deux générateurs.","expertEn":"The manuscript asserts a refutation of Kaplansky's quasitrace conjecture by a separable unital complex C-star algebra that admits normalized two-quasitraces but no tracial state. Consequently, the minimal tensor product of two unital simple stably finite algebras can be properly infinite, even if one factor is the reduced algebra of the free group on two generators.","sparkFr":"L'intérêt est structural : finitude stable et trace ne passeraient pas toujours au produit tensoriel.","sparkEn":"The interest is structural: stable finiteness and a trace would not always pass to the tensor product."},{"id":"295","titleEn":"The Kadison–Ringrose cohomology conjecture","titleFr":"La conjecture de cohomologie de Kadison–Ringrose","claim":"Proves that every bounded Hochschild cocycle of degree at least two on a complex von Neumann algebra, with coefficients in the algebra itself, has a bounded primitive. Equivalently, all higher bounded Hochschild cohomology groups vanish, resolving the Kadison–Ringrose conjecture.","nature":"operateurs","domain":"structures","complexity":"frontiere","problemYear":1955,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Vanishing of higher bounded Hochschild cohomology","href":"preprints/Vanishing-of-higher-bounded-Hochschild-cohomology-September-23-2026/paper.pdf"}],"plainFr":"Un cocycle mesure une obstruction à écrire une formule à plusieurs variables comme un bord élémentaire. Le manuscrit affirme que, sur une algèbre de von Neumann complexe, tout cocycle borné de degré au moins deux, à valeurs dans l'algèbre, est le bord d'une formule bornée.","plainEn":"A cocycle measures an obstruction to writing a formula in several variables as an elementary boundary. The manuscript asserts that on a complex von Neumann algebra, every bounded cocycle of degree at least two, with values in the algebra, is the boundary of a bounded formula.","expertFr":"Le manuscrit affirme que tout cocycle de Hochschild borné de degré au moins deux sur une algèbre de von Neumann complexe, à coefficients dans l'algèbre elle-même, possède un primitif borné. Avec le théorème déjà connu des dérivations intérieures en degré un, cela résout positivement la conjecture de cohomologie de Kadison–Ringrose.","expertEn":"The manuscript asserts that every bounded Hochschild cocycle of degree at least two on a complex von Neumann algebra, with values in the algebra itself, has a bounded primitive. Together with the known inner-derivation theorem in degree one, this resolves the Kadison–Ringrose cohomology conjecture positively.","sparkFr":"L'intérêt est structural : ces obstructions cohomologiques bornées disparaîtraient dès le degré deux.","sparkEn":"The interest is structural: these bounded cohomological obstructions would vanish from degree two on."},{"id":"296","titleEn":"The generator problem for finite factors","titleFr":"Le problème du générateur pour les facteurs finis","claim":"Proves that every type II1 factor with separable predual is generated by a single operator, equivalently by two self-adjoint operators, resolving the generator problem. More strongly, for every irreducible inclusion P⊂ M of such factors, the unitaries u with M=W^*(P,u) form a dense Gδ subset in the trace 2-norm topology.","nature":"operateurs","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Relative generation and the generator problem for finite factors","href":"preprints/Relative-generation-and-the-generator-problem-for-finite-factors-September-23-2026/paper.pdf"}],"plainFr":"Engendrer une algèbre d'opérateurs, c'est la reconstruire à partir de quelques éléments par les opérations permises. Le manuscrit affirme que tout facteur fini de type II un, à prédual séparable, est engendré par un seul opérateur, ou de façon équivalente par deux opérateurs symétriques.","plainEn":"To generate an operator algebra is to rebuild it from a few elements by the allowed operations. The manuscript asserts that every finite type II-one factor with separable predual is generated by one operator, or equivalently by two symmetric operators.","expertFr":"Le manuscrit affirme que tout facteur de type II un à prédual séparable est engendré par un opérateur, de façon équivalente par deux opérateurs autoadjoints, ce qui résout le problème du générateur dans ce cas. Plus fortement, pour toute inclusion irréductible de tels facteurs, les unitaires qui engendrent le grand avec le petit forment un ensemble G delta dense pour la 2-norme de la trace.","expertEn":"The manuscript asserts that every type II-one factor with separable predual is generated by one operator, equivalently by two self-adjoint operators, resolving the generator problem in this case. More strongly, for every irreducible inclusion of such factors, the unitaries generating the larger with the smaller form a dense G-delta set in the trace two-norm.","sparkFr":"L'intérêt est structural : un seul opérateur suffirait à engendrer ces facteurs finis séparables.","sparkEn":"The interest is structural: one operator would suffice to generate these separable finite factors."},{"id":"297","titleEn":"A ZFC counterexample to Naimark's problem","titleFr":"Un contre-exemple dans ZFC au problème de Naimark","claim":"Gives an alternative to [Tanaka's ZFC construction](https://arxiv.org/abs/2609.26930v1) of a unital infinite-dimensional simple complex C∗-algebra with a faithful tracial state and exactly one nonzero irreducible representation up to unitary equivalence. Thus the unrestricted compact-operator characterization fails without additional set-theoretic assumptions; the counterexample is nonseparable.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A counterexample to Naimark's problem in ZFC","href":"preprints/A-counterexample-to-Naimarks-problem-in-ZFC-September-24-2026/naimark-counterexample-zfc.pdf"}],"plainFr":"Le problème de Naimark demande si une seule représentation irréductible force les opérateurs compacts. Le manuscrit affirme, en théorie des ensembles usuelle, une algèbre simple infinie à trace fidèle qui a cette unicité sans être de ce type ; elle n'est pas séparable.","plainEn":"Naimark's problem asks whether one irreducible representation forces the compact operators. The manuscript asserts, in ordinary set theory, an infinite simple algebra with a faithful trace and this uniqueness, yet not of that type; it is nonseparable.","expertFr":"Le manuscrit affirme, dans ZFC et comme alternative à Tanaka, une algèbre C-étoile simple unitaire infinie, à trace fidèle, dont toute représentation irréductible non nulle est la même à équivalence unitaire près. La caractérisation par les opérateurs compacts échoue donc sans axiome supplémentaire ; l'exemple est non séparable.","expertEn":"The manuscript asserts a ZFC construction, alternative to Tanaka's, of a unital infinite-dimensional simple complex C-star algebra with a faithful tracial state whose nonzero irreducible representations are all unitarily equivalent. Thus the unrestricted compact-operator characterization fails without extra set-theoretic assumptions; the counterexample is nonseparable.","sparkFr":"L'intérêt est structural : sans séparabilité, l'unicité des représentations n'imposerait pas les compacts.","sparkEn":"The interest is structural: without separability, uniqueness of representations would not force the compacts."},{"id":"298","titleEn":"Two notions of free entropy differ even when both are finite","titleFr":"Deux notions d'entropie libre diffèrent même lorsqu'elles sont finies","claim":"Constructs a bounded self-adjoint tuple in a tracial von Neumann algebra whose microstates and nonmicrostates free entropies satisfy -∞ ^* ∞. This answers Voiculescu’s finite-entropy equality question negatively: the matrix-approximation and free-Fisher-information definitions differ even when both are finite.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1991,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A finite-entropy separation of microstates and nonmicrostates free entropy","href":"preprints/A-finite-entropy-separation-of-microstates-and-nonmicrostates-free-entropy-September-25-2026/paper.pdf"}],"plainFr":"L'entropie libre tente de mesurer le désordre d'opérateurs qui ne commutent pas, soit par approximation par des matrices, soit par une information de Fisher libre. Le manuscrit affirme un uplet borné d'opérateurs symétriques pour lequel les deux quantités sont finies mais distinctes.","plainEn":"Free entropy tries to measure the disorder of operators that do not commute, either by matrix approximation or by a free Fisher information. The manuscript asserts a bounded tuple of symmetric operators for which the two quantities are finite but different.","expertFr":"Le manuscrit affirme un uplet autoadjoint borné, dans une algèbre de von Neumann à trace fidèle normale, dont l'entropie libre des microétats et celle des non-microétats sont toutes deux finies mais distinctes. Cela répond négativement à la question d'égalité à entropie finie de Voiculescu entre la définition par approximation matricielle et celle par information de Fisher libre.","expertEn":"The manuscript asserts a bounded self-adjoint tuple, in a von Neumann algebra with a faithful normal tracial state, whose microstates and nonmicrostates free entropies are both finite but different. This answers negatively Voiculescu's finite-entropy equality question between the matrix-approximation definition and the free Fisher-information definition.","sparkFr":"L'intérêt est structural : deux définitions du désordre libre ne coïncideraient pas toujours, même finies.","sparkEn":"The interest is structural: two definitions of free disorder would not always agree, even when finite."},{"id":"299","titleEn":"The Kirchberg–Rørdam character criterion and infinite tensor-power Jiang–Su stability","titleFr":"Critère de caractères de Kirchberg–Rørdam et stabilité infinie de Jiang–Su","claim":"A nonzero unital separable complex C∗-algebra is Jiang–Su stable exactly when its norm central-sequence algebra has no characters, for every free ultrafilter. This answers the Kirchberg–Rørdam character question. Also, the infinite minimal tensor power of every such algebra without characters is Jiang–Su stable, answering the Dadarlat–Toms question.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The Kirchberg–Rørdam character criterion","href":"preprints/The-Kirchberg-Rordam-character-criterion-September-25-2026/paper.pdf"}],"plainFr":"Un caractère est une façon d'envoyer une algèbre vers les nombres complexes, comme un point. Le manuscrit affirme qu'une algèbre séparable unitaire non nulle absorbe l'algèbre de Jiang–Su exactement lorsque son algèbre de suites centrales en norme n'a aucun caractère.","plainEn":"A character is a way of sending an algebra to the complex numbers, like a point. The manuscript asserts that a nonzero unital separable algebra absorbs the Jiang–Su algebra exactly when its norm central-sequence algebra has no character.","expertFr":"Le manuscrit affirme le critère de Kirchberg–Rørdam : pour tout ultrafiltre libre, une algèbre C-étoile séparable unitaire non nulle absorbe Jiang–Su exactement si ses suites centrales en norme n'ont pas de caractère. La puissance tensorielle infinie de toute telle algèbre sans caractère est stable au sens de Jiang–Su, répondant à Dadarlat et Toms.","expertEn":"The manuscript asserts the Kirchberg–Rørdam criterion: for every free ultrafilter, a nonzero unital separable complex C-star algebra absorbs the Jiang–Su algebra if and only if its norm central-sequence algebra has no character. It also asserts that the infinite minimal tensor power of every such algebra without characters is Jiang–Su stable, answering Dadarlat and Toms.","sparkFr":"L'intérêt est structural : l'absence de caractères détecterait la stabilité de Jiang–Su.","sparkEn":"The interest is structural: the absence of characters would detect Jiang–Su stability."},{"id":"300","titleEn":"Approximation and quadratic strong-operator paving","titleFr":"Approximation et pavage quadratique en topologie forte","claim":"Proves that every self-adjoint element of a complex von Neumann algebra admits strong-operator paving relative to any maximal abelian subalgebra with O(ε^-2) blocks. The norm bound holds after compression by a projection arbitrarily close to the identity in the strong topology, resolving the Popa–Vaes quadratic paving conjecture.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1959,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"Approximation Paving over Arbitrary Maximal Abelian Subalgebras","href":"preprints/Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026/Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf"},{"title":"Quadratic Strong-Operator Paving over Arbitrary Maximal Abelian Subalgebras","href":"preprints/Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026/Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf"}],"plainFr":"Paver un opérateur, c'est le couper en blocs petits hors de leur moyenne. Le manuscrit affirme que tout élément symétrique d'une algèbre de von Neumann admet un pavage fort relatif à toute sous-algèbre abélienne maximale, avec un nombre de blocs d'ordre inverse du carré de la précision.","plainEn":"To pave an operator is to cut it into blocks that stay small away from their average. The manuscript asserts that every symmetric element of a von Neumann algebra admits a strong paving relative to any maximal abelian subalgebra, with a block count of order one over the square of the precision.","expertFr":"Le manuscrit affirme le pavage fort de Popa–Vaes : tout autoadjoint, après compression proche de l'identité, admet un pavage relatif à toute sous-algèbre abélienne maximale, d'ordre inverse du carré de la tolérance en nombre de blocs. Le même texte donne aussi une forme approchée, à nombre de projections au plus une constante fois l'erreur à la puissance moins six.","expertEn":"The manuscript asserts the Popa–Vaes strong paving: every self-adjoint, after compression near the identity, admits a paving relative to any maximal abelian subalgebra, with order one over the square of the tolerance in the number of blocks. The same text also gives an approximation form, in which the number of projections is at most a constant times the error to the power minus six.","sparkFr":"L'intérêt est structural : un découpage quadratique en précision contrôlerait ces opérateurs.","sparkEn":"The interest is structural: a quadratic cutting in the precision would control these operators."},{"id":"301","titleEn":"Trace cones and Razak–Jacelon stabilization","titleFr":"Cônes de traces et stabilisation de Razak–Jacelon","claim":"Classifies separable nuclear complex C∗-algebras after tensoring with the Razak–Jacelon algebra and the compact operators, using their full topological cones of extended lower-semicontinuous tracial weights. This answers Robert’s trace-cone question, including algebras with arbitrary ideal structure and both finite and infinite subquotients.","nature":"operateurs","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"The trace cone classifies Razak–Jacelon stabilizations","href":"preprints/The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026/The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026.pdf"}],"plainFr":"Une trace étendue mesure la taille des éléments positifs, en autorisant la valeur infinie. Le manuscrit affirme que le cône de toutes ces traces reconnaît une algèbre nucléaire séparable après produit avec l'algèbre de Razak–Jacelon et les opérateurs compacts.","plainEn":"An extended trace measures the size of positive elements, allowing the value infinity. The manuscript asserts that the cone of all such traces recognizes a separable nuclear algebra after product with the Razak–Jacelon algebra and the compact operators.","expertFr":"Le manuscrit affirme que le cône topologique de tous les poids traciaux étendus semicontinus inférieurement détermine une algèbre C-étoile nucléaire séparable après produit tensoriel avec l'algèbre de Razak–Jacelon et les opérateurs compacts. Cela répond positivement à la question de classification par cône de traces de Robert, y compris pour une structure d'idéaux arbitraire et des sous-quotients finis ou infinis.","expertEn":"The manuscript asserts that the topological cone of all extended lower-semicontinuous tracial weights determines a separable nuclear C-star algebra after tensoring with the Razak–Jacelon algebra and the compact operators. This answers Robert's trace-cone classification question positively, including for arbitrary ideal structure and finite or infinite subquotients.","sparkFr":"L'intérêt est structural : après ces stabilisations, le cône des traces suffirait à reconnaître l'algèbre.","sparkEn":"The interest is structural: after these stabilizations, the trace cone would suffice to recognize the algebra."},{"id":"302","titleEn":"Radius of comparison equals half the mean dimension","titleFr":"Le rayon de comparaison égale la moitié de la dimension moyenne","claim":"For every minimal homeomorphism h of an infinite compact metrizable space X, the radius of comparison of C(X) _h Z equals 12mdim(X,h), including infinite values. Zero mean dimension is equivalent to the small boundary property, Jiang–Su stability and finite nuclear dimension; in this case nuclear dimension is at most one.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"Filtered products and boundary-preserving compression in complex cobordism","href":"preprints/Filtered-products-and-boundary-preserving-compression-in-complex-cobordism-September-25-2026/paper.pdf"},{"title":"Radius of comparison equals half the mean dimension","href":"preprints/Radius-of-comparison-equals-half-the-mean-dimension-September-25-2026/paper.pdf"}],"plainFr":"La dimension moyenne mesure la complexité d'un système dynamique sur un espace compact. Le manuscrit affirme que, pour tout homéomorphisme minimal d'un tel espace infini, le rayon de comparaison de l'algèbre des fonctions continues croisée par les entiers vaut la moitié de cette dimension.","plainEn":"Mean dimension measures the complexity of a dynamical system on a compact space. The manuscript asserts that for every minimal homeomorphism of such an infinite space, the radius of comparison of the continuous-function algebra crossed by the integers equals half that dimension.","expertFr":"Le manuscrit affirme que pour tout homéomorphisme minimal d'un espace métrisable compact infini, le rayon de comparaison de l'algèbre des fonctions continues croisée par les entiers égale la moitié de la dimension moyenne, valeurs infinies comprises. La dimension moyenne nulle équivaut à la propriété de petit bord, à la stabilité de Jiang–Su et à la dimension nucléaire finie, laquelle vaut alors au plus un.","expertEn":"The manuscript asserts that for every minimal homeomorphism of an infinite compact metrizable space, the radius of comparison of the continuous-function algebra crossed by the integers equals half the mean dimension, including infinite values. Zero mean dimension is equivalent to the small boundary property, Jiang–Su stability, and finite nuclear dimension, which is then at most one.","sparkFr":"L'intérêt est structural : une complexité dynamique déterminerait un invariant d'algèbre d'opérateurs.","sparkEn":"The interest is structural: a dynamical complexity would determine an operator-algebra invariant."},{"id":"303","titleEn":"Weak pure infiniteness and Cuntz-algebra absorption","titleFr":"Pure infinité faible et absorption de l'algèbre de Cuntz","claim":"Resolves the ordinary-to-strong pure-infiniteness question of Kirchberg and Rørdam for complex C∗-algebras. For exact algebras, proper infiniteness of one fixed finite amplification of every positive element also suffices. Consequently, every separable nuclear algebra with this property absorbs O_∞, without unitality or simplicity assumptions.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Weak pure infiniteness and O-infinity absorption","href":"preprints/Weak-pure-infiniteness-and-O-infinity-absorption-September-25-2026/paper.pdf"}],"plainFr":"Un élément positif est proprement infini lorsqu'il contient, au sens algébrique, deux copies de lui-même. Le manuscrit affirme que si tout élément positif d'une algèbre d'opérateurs complexe est ainsi infini, alors l'algèbre est fortement purement infinie.","plainEn":"A positive element is properly infinite when it contains, in the algebraic sense, two copies of itself. The manuscript asserts that if every positive element of a complex operator algebra is infinite in this way, then the algebra is strongly purely infinite.","expertFr":"Le manuscrit affirme que toute algèbre C-étoile dont chaque positif est proprement infini est fortement purement infinie, répondant à Kirchberg et Rørdam. Pour les algèbres exactes, une amplification finie fixée suffit, et toute algèbre nucléaire séparable de cette sorte absorbe O infini, sans unitarité ni simplicité.","expertEn":"The manuscript asserts that every complex C-star algebra in which every positive element is properly infinite is strongly purely infinite, answering Kirchberg and Rørdam's question from ordinary to strong infiniteness. For exact algebras, proper infiniteness of one fixed finite amplification suffices, and every separable nuclear algebra with this property absorbs O infinity, without unitality or simplicity.","sparkFr":"L'intérêt est structural : une infinité assez uniforme forcerait l'absorption de l'algèbre de Cuntz infinie.","sparkEn":"The interest is structural: sufficiently uniform infiniteness would force absorption of the infinite Cuntz algebra."},{"id":"304","titleEn":"The Hilbert–Smith conjecture in every dimension","titleFr":"La conjecture de Hilbert–Smith en toute dimension","claim":"Every locally compact second-countable Hausdorff group acting faithfully and jointly continuously on a connected finite-dimensional topological manifold is a Lie group. This proves the Hilbert–Smith conjecture in all finite dimensions, for Hausdorff second-countable manifolds without boundary.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Hilbert–Smith conjecture in every finite dimension","href":"preprints/The-Hilbert-Smith-conjecture-in-every-finite-dimension-September-23-2026/paper.pdf"}],"plainFr":"Un groupe de Lie est un groupe de symétries qui est en même temps une variété lisse. Le manuscrit affirme que tout groupe localement compact, séparé et à base dénombrable, qui agit fidèlement et continûment sur une variété connexe de dimension finie, est un groupe de Lie.","plainEn":"A Lie group is a symmetry group that is at the same time a smooth manifold. The manuscript asserts that every locally compact Hausdorff second-countable group acting faithfully and continuously on a connected finite-dimensional manifold is a Lie group.","expertFr":"Le manuscrit affirme que tout groupe localement compact, à base dénombrable et séparé, agissant fidèlement et conjointement continûment sur une variété topologique connexe, séparée, à base dénombrable, de dimension finie et sans bord, est un groupe de Lie. Cela établit la conjecture de Hilbert–Smith en toute dimension finie.","expertEn":"The manuscript asserts that every locally compact second-countable Hausdorff group acting faithfully and jointly continuously on a connected Hausdorff second-countable finite-dimensional topological manifold without boundary is a Lie group. This establishes the Hilbert–Smith conjecture in every finite dimension.","sparkFr":"L'intérêt est structural : une action fidèle sur une variété forcerait le groupe à être de Lie.","sparkEn":"The interest is structural: a faithful action on a manifold would force the group to be a Lie group."},{"id":"305","titleEn":"Four-dimensional disk embedding and Wall's conjecture","titleFr":"Plongement de disques en dimension quatre et conjecture de Wall","claim":"The unrestricted four-dimensional disk-embedding conjecture fails: framed algebraic dual spheres do not suffice to obtain disjoint locally flat spanning disks. In particular, the free group F2 is not good in the sense of Freedman–Quinn. Also constructs a finitely presented integral Poincaré duality group of dimension four with a finite classifying space but no realization as the fundamental group of a closed aspherical topological four-manifold, disproving Wall's conjecture.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1895,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A boundary-only obstruction to four-dimensional disk embedding","href":"preprints/A-boundary-only-obstruction-to-four-dimensional-disk-embedding-September-24-2026/paper.pdf"},{"title":"A marked tensor obstruction to four-dimensional disk embedding","href":"preprints/A-marked-tensor-obstruction-to-four-dimensional-disk-embedding-September-24-2026/paper.pdf"},{"title":"A PD4 group without an aspherical manifold model","href":"preprints/A-PD4-group-without-an-aspherical-manifold-model-September-24-2026/paper.pdf"}],"plainFr":"En dimension quatre, on demande si des sphères duales algébriques permettent de trouver des disques plongés et disjoints. Le manuscrit affirme que non, sans restriction sur le groupe fondamental : le groupe libre à deux générateurs n'est pas bon au sens de Freedman et Quinn, et la conjecture de Wall échoue aussi.","plainEn":"In dimension four, one asks whether algebraic dual spheres yield disjoint embedded disks. The manuscript asserts that they do not, with no restriction on the fundamental group: the free group on two generators is not good in the sense of Freedman and Quinn, and Wall's conjecture also fails.","expertFr":"Le manuscrit affirme que le plongement de disques en dimension quatre échoue sans hypothèse de groupe : des sphères duales cadrées ne donnent pas des disques localement plats disjoints. Le groupe libre à deux générateurs n'est pas bon au sens de Freedman–Quinn, et un groupe de dualité de Poincaré de dimension quatre, à espace classifiant fini, n'est pas réalisé par une variété close asphérique, contre Wall.","expertEn":"The manuscript asserts that four-dimensional disk embedding fails with no group hypothesis: framed dual spheres do not yield disjoint locally flat disks. The free group on two generators is not good in the sense of Freedman–Quinn, and a four-dimensional Poincaré duality group with finite classifying space is realized by no closed aspherical manifold, against Wall.","sparkFr":"L'intérêt est structural en dimension quatre : les critères algébriques ne suffiraient pas à plonger les disques.","sparkEn":"The interest is structural in dimension four: algebraic criteria would not suffice to embed the disks."},{"id":"306","titleEn":"The purely cosmetic surgery conjecture","titleFr":"La conjecture de chirurgie purement cosmétique","claim":"Distinct Dehn surgery slopes on a nontrivial smooth knot in S3 never produce orientation-preservingly homeomorphic manifolds, proving the purely cosmetic surgery conjecture. The statement includes the meridional slope.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1867,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Purely cosmetic surgery on knots in the three-sphere","href":"preprints/Purely-Cosmetic-Surgery-on-Knots-in-the-Three-Sphere-September-23-2026/paper.pdf"}],"plainFr":"La chirurgie de Dehn modifie un nœud de la sphère de dimension trois en recollant un tore selon une pente. Le manuscrit affirme que deux pentes distinctes sur un nœud lisse non trivial ne donnent jamais des variétés homéomorphes en préservant l'orientation.","plainEn":"Dehn surgery modifies a knot in the three-sphere by regluing a torus along a slope. The manuscript asserts that two distinct slopes on a nontrivial smooth knot never yield orientation-preservingly homeomorphic manifolds.","expertFr":"Le manuscrit affirme la conjecture de chirurgie purement cosmétique pour les nœuds de la sphère de dimension trois. Des pentes de Dehn distinctes sur un nœud lisse non trivial ne produisent jamais des variétés homéomorphes en préservant l'orientation, et l'énoncé inclut la pente méridienne.","expertEn":"The manuscript asserts the purely cosmetic surgery conjecture for knots in the three-sphere. Distinct Dehn slopes on a nontrivial smooth knot never produce orientation-preservingly homeomorphic manifolds, and the statement includes the meridional slope.","sparkFr":"L'intérêt est structural en topologie des nœuds : la pente laisserait une trace sur la variété obtenue.","sparkEn":"The interest is structural in knot topology: the slope would leave a trace on the resulting manifold."},{"id":"307","titleEn":"Failure of rational injectivity for maximal coarse assembly","titleFr":"Échec de l'injectivité rationnelle pour l'assemblage grossier maximal","claim":"Constructs a uniformly discrete bounded-geometry space whose maximal coarse assembly map is not rationally injective. The example is a coarse disjoint union of finite connected graphs of uniformly bounded degree, with an infinite-order kernel class. A companion gives the analogous failure for reduced coarse assembly, disproving the rational coarse Novikov conjecture.","nature":"combinatoire","domain":"structures","complexity":"frontiere","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Failure of rational injectivity for maximal coarse assembly","href":"preprints/Failure-of-rational-injectivity-for-maximal-coarse-assembly-October-5-2026/paper.pdf"},{"title":"A counterexample to the coarse Novikov conjecture","href":"preprints/A-counterexample-to-the-coarse-Novikov-conjecture-September-23-2026/paper.pdf"}],"plainFr":"L'assemblage grossier relie la géométrie à grande échelle d'un espace à une homologie. Le manuscrit affirme qu'un espace fait de points espacés, à géométrie bornée, peut avoir un assemblage grossier maximal qui n'est pas injectif même après passage aux rationnels.","plainEn":"Coarse assembly relates the large-scale geometry of a space to a homology. The manuscript asserts that a space of spaced points, with bounded geometry, may have a maximal coarse assembly map that is not injective even after passing to the rationals.","expertFr":"Le manuscrit affirme un espace uniformément discret à géométrie bornée, union grossière disjointe de graphes finis connexes de degré uniformément borné, dont l'assemblage grossier maximal a une classe de noyau d'ordre infini. Un compagnon donne l'échec analogue pour l'assemblage réduit, ce qui réfute la conjecture de Novikov grossière rationnelle.","expertEn":"The manuscript asserts a uniformly discrete bounded-geometry space, a coarse disjoint union of finite connected graphs of uniformly bounded degree, whose maximal coarse assembly map has an infinite-order kernel class. A companion gives the analogous failure for reduced assembly, disproving the rational coarse Novikov conjecture.","sparkFr":"L'intérêt est structural : même pour des graphes bornés, l'assemblage grossier rationnel ne serait pas injectif.","sparkEn":"The interest is structural: even for bounded graphs, rational coarse assembly would not be injective."},{"id":"308","titleEn":"Finite Smith–Toda complexes at every height","titleFr":"Complexes de Smith–Toda finis à toute hauteur","claim":"For every n ≥ 0, constructs a finite Smith–Toda spectrum at a prime p depending on n, with Brown–Peterson homology BP_*/(p,v_1, ,v_n) and the canonical comodule structure. Thus Smith–Toda complexes exist at every height when the prime may vary; an explicit example realizes V(4) at p = 1009.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Finite Smith–Toda Complexes at Varying Primes","href":"preprints/Finite-Smith-Toda-Complexes-at-Varying-Primes-September-23-2026/paper.pdf"},{"title":"A finite Smith–Toda complex V(4) at the prime 1009","href":"preprints/A-finite-Smith-Toda-complex-V4-at-the-prime-1009-September-23-2026/paper.pdf"}],"plainFr":"Un spectre fini est un objet de la topologie stable qui se comporte comme un espace fini après assez de suspensions. Le manuscrit affirme que, pour toute hauteur, il existe un nombre premier, dépendant de cette hauteur, pour lequel un complexe de Smith–Toda fini existe.","plainEn":"A finite spectrum is an object of stable topology that behaves like a finite space after enough suspensions. The manuscript asserts that for every height there is a prime, depending on that height, at which a finite Smith–Toda complex exists.","expertFr":"Le manuscrit affirme que pour tout entier n au moins zéro, il existe un complexe de Smith–Toda fini V(n) à un premier p dépendant de n, spectre p-local fini dont l'homologie de Brown–Peterson est le quotient par p et les générateurs jusqu'à v indice n, avec la structure de comodule canonique et un générateur en degré zéro. Un exemple explicite réalise V(4) au premier 1009.","expertEn":"The manuscript asserts that for every integer n at least zero there is a finite Smith–Toda complex V(n) at a prime p depending on n, a finite p-local spectrum whose Brown–Peterson homology is the quotient by p and the generators up through v sub n, with the canonical comodule structure and a generator in degree zero. An explicit example realizes V(4) at the prime 1009.","sparkFr":"L'intérêt est structural en homotopie chromatique : chaque hauteur aurait son complexe, pour un premier adapté.","sparkEn":"The interest is structural in chromatic homotopy: each height would have its complex, for a suitable prime."},{"id":"309","titleEn":"The Kervaire invariant problem at the prime three","titleFr":"Le problème de l'invariant de Kervaire au premier trois","claim":"Resolves the odd-primary Kervaire invariant problem at the prime three: exactly the standard classes with indices 0, 2, and 3 survive in the mod-three Adams spectral sequence, in stems 10, 106, and 322. Each surviving detection coset contains an element of exact additive order three.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1958,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"The Kervaire invariant problem at the prime three","href":"preprints/The-Kervaire-Invariant-Problem-at-the-Prime-Three-September-24-2026/paper.pdf"}],"plainFr":"L'invariant de Kervaire détecte certains phénomènes rares dans les déformations des sphères. Le manuscrit affirme qu'au premier trois, seules les classes standard d'indices zéro, deux et trois survivent dans la suite spectrale d'Adams modulo trois.","plainEn":"The Kervaire invariant detects certain rare phenomena in the deformations of spheres. The manuscript asserts that at the prime three, only the standard classes of indices zero, two, and three survive in the mod-three Adams spectral sequence.","expertFr":"Le manuscrit affirme que, dans la suite spectrale d'Adams modulo trois, les classes de Kervaire standard survivent exactement aux indices zéro, deux et trois, dans les tiges dix, cent six et trois cent vingt-deux. Chaque classe de détection survivante contient un élément d'ordre additif exactement trois.","expertEn":"The manuscript asserts that, in the mod-three Adams spectral sequence, the standard Kervaire classes survive exactly at indices zero, two, and three, in stems ten, one hundred six, and three hundred twenty-two. Each surviving detection coset contains an element of exact additive order three.","sparkFr":"L'intérêt est structural en homotopie : au premier trois, seules trois tiges porteraient cet élément.","sparkEn":"The interest is structural in homotopy: at the prime three, only three stems would carry this element."},{"id":"310","titleEn":"Quillen's conjecture in rational homology","titleFr":"La conjecture de Quillen en homologie rationnelle","claim":"Proves the rational-homology form of Quillen's conjecture for every finite group and every prime. If the largest normal p-subgroup of G is trivial, the poset of nontrivial elementary abelian p-subgroups has nonzero augmented reduced rational homology and is therefore not contractible.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Rational homology and Quillen's conjecture","href":"preprints/Rational-homology-and-Quillens-conjecture-September-24-2026/paper.pdf"}],"plainFr":"On regarde l'ensemble des sous-groupes abéliens élémentaires d'un groupe fini, ordonné par inclusion. Le manuscrit affirme que si le plus grand sous-groupe normal de puissance d'un premier est trivial, cet ensemble a une homologie rationnelle non nulle, et n'est donc pas contractile.","plainEn":"One looks at the set of elementary abelian subgroups of a finite group, ordered by inclusion. The manuscript asserts that if the largest normal subgroup of prime-power order is trivial, this set has nonzero rational homology, and hence is not contractible.","expertFr":"Le manuscrit affirme la forme en homologie rationnelle de la conjecture de Quillen pour tout groupe fini et tout premier : si le plus grand p-sous-groupe normal est trivial, le poset des p-sous-groupes abéliens élémentaires non triviaux a une homologie rationnelle réduite augmentée non nulle. Il n'est donc pas contractile.","expertEn":"The manuscript asserts the rational-homology form of Quillen's conjecture for every finite group and every prime: if the largest normal p-subgroup is trivial, the poset of nontrivial elementary abelian p-subgroups has nonzero augmented reduced rational homology. It is therefore not contractible.","sparkFr":"L'intérêt est structural : l'absence de sous-groupe normal de p-puissance se lirait dans l'homologie du poset.","sparkEn":"The interest is structural: the absence of a normal prime-power subgroup would be read in the poset homology."},{"id":"311","titleEn":"The Hovey–Strickland and Chai conjectures","titleFr":"Les conjectures de Hovey–Strickland et de Chai","claim":"Proves Chai's invariant-ideal conjecture for Lubin–Tate deformation rings over finite residue fields, at every prime and positive height n. Through the implication of Barthel–Heard–Naumann, this proves the Hovey–Strickland conjecture: dualizable K(n)-local spectra have exactly n+2 thick tensor ideals, and their Balmer spectrum is a chain of n+1 points.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":1963,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Stabilizer orbits and thick tensor ideals of dualizable K(n)-local spectra","href":"preprints/Stabilizer-Orbits-and-Thick-Tensor-Ideals-of-Dualizable-Kn-Local-Spectra-September-24-2026/paper.pdf"}],"plainFr":"Les anneaux de déformation de Lubin–Tate classent certaines déformations de lois de groupe formelles. Le manuscrit affirme la conjecture des idéaux invariants de Chai, et en déduit que les objets dualisables localisés au cran chromatique n ont exactement n plus deux idéaux tensoriels épais.","plainEn":"Lubin–Tate deformation rings classify certain deformations of formal group laws. The manuscript asserts Chai's invariant-ideal conjecture, and deduces that the dualizable objects localized at chromatic level n have exactly n plus two thick tensor ideals.","expertFr":"Le manuscrit affirme la conjecture des idéaux invariants de Chai pour les anneaux de déformation de Lubin–Tate sur des corps résiduels finis, à tout premier et toute hauteur positive. Par l'implication de Barthel, Heard et Naumann, les spectres dualisables localisés en K(n) ont exactement n plus deux idéaux tensoriels épais, et leur spectre de Balmer est une chaîne de n plus un points.","expertEn":"The manuscript asserts Chai's invariant-ideal conjecture for Lubin–Tate deformation rings over finite residue fields, at every prime and positive height. Through the implication of Barthel, Heard, and Naumann, dualizable K(n)-local spectra have exactly n plus two thick tensor ideals, and their Balmer spectrum is a chain of n plus one points.","sparkFr":"L'intérêt est structural en homotopie chromatique : le spectre de Balmer y serait une simple chaîne.","sparkEn":"The interest is structural in chromatic homotopy: the Balmer spectrum would be a simple chain."},{"id":"312","titleEn":"The Grothendieck homotopy hypothesis","titleFr":"L'hypothèse d'homotopie de Grothendieck","claim":"Proves the Grothendieck homotopy hypothesis for ∞-groupoids associated with every Grothendieck coherator in the Ara–Henry convention: these algebraic objects recover the homotopy theory of spaces.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1968,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Grothendieck homotopy hypothesis via elementary expansions","href":"preprints/The-Grothendieck-homotopy-hypothesis-via-elementary-expansions-September-24-2026/paper.pdf"}],"plainFr":"Un infini-groupoïde est une structure où objets, flèches et déformations supérieures se composent de façon souple. Le manuscrit affirme que, pour tout cohérateur de Grothendieck dans la convention d'Ara et Henry, ces objets algébriques retrouvent la théorie de l'homotopie des espaces.","plainEn":"An infinity-groupoid is a structure in which objects, arrows, and higher deformations compose in a flexible way. The manuscript asserts that for every Grothendieck coherator in the Ara–Henry convention, these algebraic objects recover the homotopy theory of spaces.","expertFr":"Le manuscrit affirme l'hypothèse d'homotopie de Grothendieck pour tout cohérateur de Grothendieck dans la convention d'Ara et Henry : ses infini-groupoïdes globulaires faibles retrouvent la théorie de l'homotopie des espaces. Il résout aussi la conjecture des sommes amalgamées de Henry : les expansions élémentaires préservent les composantes et tous les groupes d'homotopie des infini-groupoïdes cellulaires.","expertEn":"The manuscript asserts the Grothendieck homotopy hypothesis for every Grothendieck coherator in the Ara–Henry convention: its weak globular infinity-groupoids recover the homotopy theory of spaces. It also resolves Henry's pushout conjecture: elementary expansions preserve components and all homotopy groups of cellular infinity-groupoids.","sparkFr":"L'intérêt est structural : une présentation algébrique retrouverait ici l'homotopie des espaces.","sparkEn":"The interest is structural: an algebraic presentation would recover here the homotopy of spaces."},{"id":"313","titleEn":"Finite generation for the K(n)-local sphere","titleFr":"Engendrement fini pour la sphère localisée en K(n)","claim":"Answers the degreewise finiteness question of Hovey and Hovey–Strickland: every homotopy group of the K(n)-local sphere is a finitely generated ℤp-module, for every prime, positive height and integer degree. The same conclusion holds after K(n)-localizing any finite p-local spectrum.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Finite generation for the K(n)-local sphere","href":"preprints/Finite-generation-for-the-Kn-local-sphere-September-24-2026/Finite-generation-for-the-Kn-local-sphere-September-24-2026.pdf"}],"plainFr":"Les groupes d'homotopie de la sphère mesurent les façons de déformer des applications entre sphères. Le manuscrit affirme qu'après localisation chromatique au cran n, chacun de ces groupes est engendré de façon finie sur les entiers complétés en un nombre premier.","plainEn":"The homotopy groups of the sphere measure ways of deforming maps between spheres. The manuscript asserts that after chromatic localization at level n, each of these groups is finitely generated over the integers completed at a prime.","expertFr":"Le manuscrit affirme que tout groupe d'homotopie de la sphère localisée en K(n) est un module de type fini sur les entiers p-adiques, pour tout premier, toute hauteur positive et tout degré entier. La même conclusion vaut après localisation K(n) de tout spectre p-local fini, ce qui répond à la question de finitude degré par degré de Hovey et de Hovey–Strickland.","expertEn":"The manuscript asserts that every homotopy group of the K(n)-local sphere is a finitely generated module over the p-adic integers, for every prime, positive height, and integer degree. The same conclusion holds after K(n)-localizing any finite p-local spectrum, answering the degreewise finiteness question of Hovey and Hovey–Strickland.","sparkFr":"L'intérêt est structural : la localisation chromatique rendrait ces groupes d'homotopie de type fini.","sparkEn":"The interest is structural: chromatic localization would make these homotopy groups finitely generated."},{"id":"314","titleEn":"Cyclic length and chromatic fixed-point loss","titleFr":"Longueur cyclique et perte de point fixe chromatique","claim":"Determines the optimal chromatic loss from geometric H-fixed points to geometric G-fixed points for every subgroup H of a finite p-group G. At every nonnegative height, the loss equals the shortest subnormal-chain length from H to G with cyclic quotients. Each quotient counts once regardless of order, and finite spectra witness sharpness.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Cyclic length and chromatic fixed-point loss","href":"preprints/Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026/Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026.pdf"}],"plainFr":"Les points fixes géométriques d'un objet à symétrie de groupe gardent une partie de son information chromatique. Le manuscrit affirme que la perte optimale, d'un sous-groupe vers le groupe, égale la plus courte chaîne de quotients cycliques qui les relie.","plainEn":"Geometric fixed points of an object with a group symmetry keep part of its chromatic information. The manuscript asserts that the optimal loss, from a subgroup to the group, equals the shortest chain of cyclic quotients joining them.","expertFr":"Le manuscrit affirme que, pour un p-groupe fini G et un sous-groupe H, la perte chromatique optimale des points fixes géométriques de H vers ceux de G égale la plus courte longueur d'une chaîne sous-normale de quotients cycliques. L'égalité vaut à tout premier et toute hauteur non négative, chaque quotient comptant une fois quel que soit son ordre, et des spectres finis montrent l'optimalité.","expertEn":"The manuscript asserts that for a finite p-group G and a subgroup H, the optimal chromatic loss from geometric fixed points of H to those of G equals the shortest length of a subnormal chain of cyclic quotients. The equality holds at every prime and every nonnegative height, each quotient counting once regardless of order, and finite spectra show sharpness.","sparkFr":"L'intérêt est structural : une longueur de chaîne de sous-groupes mesurerait la perte chromatique.","sparkEn":"The interest is structural: a chain length of subgroups would measure the chromatic loss."},{"id":"315","titleEn":"The four-dimensional Singer conjecture","titleFr":"La conjecture de Singer en dimension quatre","claim":"Proves that the L2-Betti numbers of the universal cover of every closed connected aspherical topological four-manifold vanish outside degree two. More generally, the same conclusion holds for every finite connected aspherical integral Poincaré complex of formal dimension four, proving the four-dimensional Singer conjecture in this wider class.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1895,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"The Singer conjecture in dimension four","href":"preprints/The-Singer-conjecture-in-dimension-four-September-25-2026/paper.pdf"}],"plainFr":"Les nombres de Betti de dimension généralisée mesurent les trous du revêtement universel d'une variété. Le manuscrit affirme que, pour toute variété close, connexe et asphérique de dimension quatre, ces nombres s'annulent en dehors du degré deux.","plainEn":"Generalized-dimension Betti numbers measure the holes in the universal cover of a manifold. The manuscript asserts that for every closed connected aspherical four-dimensional manifold, these numbers vanish outside degree two.","expertFr":"Le manuscrit affirme que les nombres de Betti L2 du revêtement universel de toute variété topologique close, connexe et asphérique de dimension quatre s'annulent hors du degré deux. La même annulation vaut pour tout complexe de Poincaré entier, fini, connexe et asphérique, de dimension formelle quatre, y compris non orientable.","expertEn":"The manuscript asserts that the L2-Betti numbers of the universal cover of every closed connected aspherical topological four-manifold vanish outside degree two. The same vanishing holds for every finite connected aspherical integral Poincaré complex of formal dimension four, including nonorientable ones.","sparkFr":"L'intérêt est structural : en dimension quatre, l'asphéricité concentrerait cette homologie au degré deux.","sparkEn":"The interest is structural: in dimension four, asphericity would concentrate this homology in degree two."},{"id":"316","titleEn":"Curtis’s conjecture","titleFr":"La conjecture de Curtis","claim":"Proves Curtis’s conjecture: the positive-degree mod-two stable Hurewicz image of the sphere is spanned by the images of the Hopf-invariant-one classes η, ν, σ and the Kervaire-invariant-one classes that exist.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"The Stable Hurewicz Image of the Sphere at Two","href":"preprints/The-Stable-Hurewicz-Image-of-the-Sphere-at-Two-September-25-2026/paper.pdf"}],"plainFr":"En topologie stable modulo deux, l'image de Hurewicz de la sphère retient des classes visibles en degrés positifs. Le manuscrit affirme qu'elle est engendrée par les classes d'invariant de Hopf un et celles d'invariant de Kervaire un qui existent, d'où la conjecture d'Eccles pour toute sphère positive.","plainEn":"In mod-two stable topology, the Hurewicz image of the sphere keeps classes visible in positive degrees. The manuscript asserts that it is spanned by the Hopf-invariant-one classes and the existing Kervaire-invariant-one classes, so Eccles's conjecture follows for every sphere of positive dimension.","expertFr":"Le manuscrit affirme la conjecture de Curtis : en tout degré positif, l'image de Hurewicz stable modulo deux de la sphère est engendrée par les images de η, ν, σ et des classes d'invariant de Kervaire un qui existent. Il en tire la conjecture d'Eccles pour toute sphère de dimension n strictement positive.","expertEn":"The manuscript asserts Curtis's conjecture: in every positive degree, the mod-two stable Hurewicz image of the sphere is spanned by the images of η, ν, σ and the Kervaire-invariant-one classes that exist. It deduces Eccles's conjecture for every sphere of strictly positive dimension.","sparkFr":"L'intérêt est structural : ces quelques classes pourraient engendrer toute l'image de Hurewicz stable modulo deux.","sparkEn":"The interest is structural: these few classes may span the whole mod-two stable Hurewicz image."},{"id":"317","titleEn":"Thomason model structures in all strict higher dimensions","titleFr":"Structures de modèles de Thomason en toute dimension stricte","claim":"Resolves the Ara–Maltsiniotis conjecture: for every n ≥ 1 and n = ω, small strict globular n-categories admit proper combinatorial Thomason model structures Quillen equivalent to simplicial sets. Thus strict higher categories model the homotopy theory of spaces in every stated dimension.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1970,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Thomason Model Structures in Every Strict Higher Dimension","href":"preprints/Thomason-Model-Structures-in-Every-Strict-Higher-Dimension-September-25-2026/paper.pdf"}],"plainFr":"Une catégorie stricte supérieure empile des objets et des flèches de plusieurs niveaux, avec une composition sans jeu. Le manuscrit affirme que, en toute dimension finie et à l'infini, ces catégories portent une structure de modèles équivalente à celle des espaces, donc modélisent leur homotopie.","plainEn":"A strict higher category stacks objects and arrows through several levels, with composition that has no slack. The manuscript asserts that, in every finite dimension and at infinity, these categories carry a model structure equivalent to that of spaces, and so model their homotopy.","expertFr":"Le manuscrit affirme la conjecture d'Ara et Maltsiniotis : pour tout n de un à l'infini, les petites n-catégories globulaires strictes admettent une structure de modèles de Thomason propre et combinatoire, équivalente de Quillen aux ensembles simpliciaux. Équivalences faibles et fibrations sont détectées par le nerf de Street doublement étendu, et l'équivalence de Quillen passe par ce nerf et une subdivision double.","expertEn":"The manuscript asserts the Ara–Maltsiniotis conjecture: for every n from one through infinity, small strict globular n-categories admit a proper combinatorial Thomason model structure Quillen equivalent to simplicial sets. Weak equivalences and fibrations are detected by the twice-extended Street nerve, and the Quillen equivalence runs through that nerve and a double subdivision.","sparkFr":"L'intérêt est structural : les catégories strictes pourraient déjà porter l'homotopie des espaces à chaque niveau.","sparkEn":"The interest is structural: strict higher categories may already carry the homotopy of spaces at every level."},{"id":"318","titleEn":"Chromatic splitting: filtrations and counterexamples","titleFr":"Scindement chromatique : filtrations et contre-exemples","claim":"Disproves strong chromatic splitting at height three for primes p ≥ 5, and weak splitting for the derived p-completed sphere at heights p (p ≥ 5) and p+1 (p ≥ 7). Nevertheless, for n ≥ 1 and p n+1, the overlap L_n-1L_K(n)S_p^ admits a 2^n-stage filtration by the predicted localized-sphere pieces. At height three and prime three, even finite assembly from such pieces fails in the category of E(2)-local modules over the derived completed sphere.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"Filtered chromatic splitting at generic primes","href":"preprints/Filtered-chromatic-splitting-at-generic-primes-September-25-2026/paper.pdf"},{"title":"The height-three chromatic overlap: an explicit filtration and its attachments","href":"preprints/The-height-three-chromatic-overlap-an-explicit-filtration-and-its-attachments-September-27-2026/paper.pdf"},{"title":"A rational obstruction to strong chromatic splitting at height three","href":"preprints/A-rational-obstruction-to-strong-chromatic-splitting-at-height-three-September-25-2026/paper.pdf"},{"title":"Failure of finite assembly for a chromatic overlap at the prime three","href":"preprints/Failure-of-finite-assembly-for-a-chromatic-overlap-at-the-prime-three-September-25-2026/paper.pdf"},{"title":"Counterexamples to weak chromatic splitting: sphere kernels and descent exponents","href":"preprints/Counterexamples-to-weak-chromatic-splitting-sphere-kernels-and-descent-exponents-September-27-2026/paper.pdf"}],"plainFr":"Le scindement chromatique demande si certaines localisations de la sphère se décomposent en pièces prévues. Le manuscrit affirme que le fort échoue à la hauteur trois pour de grands premiers, le faible à des hauteurs liées au premier, mais qu'une filtration subsiste sous son hypothèse.","plainEn":"Chromatic splitting asks whether certain localizations of the sphere break into predicted pieces. The manuscript asserts that strong splitting fails at height three for large primes, and weak splitting at heights tied to the prime, while a filtration by those pieces still exists under its numerical hypothesis.","expertFr":"Le manuscrit affirme l'échec du scindement fort à la hauteur trois pour les premiers au moins cinq, et du faible pour la sphère p-complétée dérivée aux hauteurs p et p+1 dans les plages écrites. Sous la relation entre p et n+1, le recouvrement a une filtration à 2 puissance n par les cofibres prévues, mais à hauteur trois et premier trois l'assemblage fini échoue pour les modules E(2)-locaux.","expertEn":"The manuscript asserts that strong splitting fails at height three for primes at least five, and weak splitting of the derived p-completed sphere fails at heights p and p+1 in the stated ranges. Under the relation of p and n+1, the overlap has a 2^n-stage filtration by the predicted cofibers, but at height three and prime three finite assembly fails for E(2)-local modules.","sparkFr":"L'intérêt est structural : la filtration prévue pourrait survivre là où le scindement fort tombe.","sparkEn":"The interest is structural: the predicted filtration may survive where strong splitting fails."},{"id":"319","titleEn":"Counterexamples to finite generation at chromatic height two","titleFr":"Contre-exemples à la génération finie en hauteur chromatique deux","claim":"Refutes the Hahn–Wilson conjecture at chromatic height two. For every sufficiently large prime p, constructs a connective p-complete spectrum of exact fp-type two that cannot be built from completed BP 2 by finitely many sums, shifts, cones and retracts. The examples nevertheless satisfy the finite and telescopic localization comparisons.","nature":"nombres","domain":"nombres","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":false,"pdfs":[{"title":"Counterexamples to the Hahn-Wilson conjecture at height two","href":"preprints/Counterexamples-to-the-Hahn-Wilson-conjecture-at-height-two-September-26-2026/paper.pdf"}],"plainFr":"À la hauteur chromatique deux, on demande si certains spectres se bâtissent en peu d'étapes depuis un spectre modèle. Le manuscrit affirme que non, pour tout grand premier : un spectre connexe p-complet de type exact deux y échappe, tout en gardant les comparaisons de localisation.","plainEn":"At chromatic height two, one asks whether certain spectra can be built in few steps from a model spectrum. The manuscript asserts that they cannot, for every large prime: a connective p-complete spectrum of exact type two lies outside, while the localization comparisons still hold.","expertFr":"Le manuscrit réfute, par l'exemple, la conjecture de Hahn et Wilson à la hauteur chromatique deux. Pour tout premier assez grand, il affirme un spectre connexe p-complet de type fp exact deux, hors de la sous-catégorie épaisse ordinaire engendrée par la forme standard indiquée du BP 2 p-complété, qui satisfait pourtant les comparaisons de localisation finie et télescopique.","expertEn":"The manuscript refutes, by example, the Hahn–Wilson conjecture at chromatic height two. For every sufficiently large prime, it asserts a connective p-complete spectrum of exact fp-type two, outside the ordinary thick subcategory generated by the specified standard form of p-completed BP 2, which nevertheless satisfies the finite and telescopic localization comparisons.","sparkFr":"L'intérêt est structural : la génération finie peut échouer sans que les comparaisons de localisation tombent.","sparkEn":"The interest is structural: finite generation may fail without the localization comparisons falling."},{"id":"320","titleEn":"Nonhomeomorphic closed aspherical four-manifolds","titleFr":"Variétés asphériques de dimension quatre, homotopes mais non homéomorphes","claim":"Constructs closed connected aspherical topological four-manifolds that are homotopy equivalent but not homeomorphic, with a common word-hyperbolic fundamental group. This disproves even the homeomorphism-existence formulation of the Borel conjecture in dimension four.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1953,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Nonhomeomorphic closed aspherical four-manifolds with the same homotopy type","href":"preprints/Nonhomeomorphic-closed-aspherical-four-manifolds-with-the-same-homotopy-type-October-4-2026/paper.pdf"}],"plainFr":"Une variété asphérique fermée est un espace compact sans bord dont toute l'homotopie se concentre dans son groupe fondamental. Le manuscrit affirme qu'en dimension quatre de telles variétés topologiques, de même groupe hyperbolique au sens des mots, peuvent être homotopiquement équivalentes sans être homéomorphes.","plainEn":"A closed aspherical manifold is a compact space without boundary whose homotopy sits entirely in its fundamental group. The manuscript asserts that in dimension four such topological manifolds, sharing a word-hyperbolic group, can be homotopy equivalent without being homeomorphic.","expertFr":"Le manuscrit affirme des variétés topologiques fermées, connexes et asphériques de dimension quatre, homotopiquement équivalentes mais non homéomorphes, au groupe fondamental commun hyperbolique au sens des mots. Cela réfute la formulation par existence d'homéomorphisme de la conjecture de Borel en dimension quatre, et l'une admet une autoéquivalence d'homotopie non homotope à un homéomorphisme.","expertEn":"The manuscript asserts closed connected aspherical topological four-manifolds that are homotopy equivalent but not homeomorphic, with a common word-hyperbolic fundamental group. This disproves the homeomorphism-existence form of the Borel conjecture in dimension four, and one of them has a self-homotopy equivalence not homotopic to a homeomorphism.","sparkFr":"L'intérêt est structural : en dimension quatre, l'homotopie et le groupe fondamental peuvent ne pas fixer la forme.","sparkEn":"The interest is structural: in dimension four, homotopy and the fundamental group may fail to fix the shape."},{"id":"321","titleEn":"A counterexample to Wall's finite D(2) problem","titleFr":"Un contre-exemple au problème D(2) fini de Wall","claim":"Constructs a finite connected three-dimensional CW complex whose universal cover has no integral homology above degree two and whose third cohomology vanishes for every local coefficient module, but which has no finite two-dimensional homotopy model. This disproves Wall's finite D(2) conjecture; the example has infinite fundamental group.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-06","lean":false,"pdfs":[{"title":"A Counterexample to Wall's D(2) Problem","href":"preprints/A-Counterexample-to-Walls-D2-Problem-October-6-2026/wall-d2-counterexample.pdf"}],"plainFr":"Un complexe cellulaire fini de dimension trois peut remplir des conditions d'homologie qui suggèrent un modèle de dimension deux. Le manuscrit affirme qu'un tel complexe, à groupe fondamental infini, n'est équivalent par déformation à aucun complexe fini de dimension au plus deux.","plainEn":"A finite three-dimensional cell complex can meet homology conditions that suggest a two-dimensional model. The manuscript asserts that one such complex, with infinite fundamental group, is not deformable to any finite complex of dimension at most two.","expertFr":"Le manuscrit affirme un complexe CW fini connexe de dimension trois dont le revêtement universel n'a pas d'homologie entière au-dessus du degré deux, et dont la cohomologie de degré trois s'annule pour tout module de coefficients locaux, sans modèle d'homotopie fini de dimension au plus deux. L'exemple a un groupe fondamental infini et répond négativement au problème D(2) fini de Wall.","expertEn":"The manuscript asserts a finite connected three-dimensional CW complex whose universal cover has no integral homology above degree two, and whose third cohomology vanishes for every local-coefficient module, yet which has no finite homotopy model of dimension at most two. The example has infinite fundamental group and answers Wall's finite D(2) problem in the negative.","sparkFr":"L'intérêt est structural : une finitude homologique peut ne pas donner de modèle fini de dimension deux.","sparkEn":"The interest is structural: homological finiteness may fail to yield a finite two-dimensional model."},{"id":"322","titleEn":"Tingley’s sphere-isometry problem","titleFr":"Le problème d'isométrie des sphères de Tingley","claim":"Resolves Tingley's problem: every surjective isometry between the unit spheres of nonzero real Banach spaces extends uniquely to a surjective real-linear isometry of the whole spaces. No dimension restriction is imposed, so the metric geometry of the unit sphere determines the Banach space up to linear isometry.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A positive solution to Tingley’s problem","href":"preprints/A-positive-solution-to-Tingleys-problem-September-23-2026/paper.pdf"}],"plainFr":"La sphère unité d'un espace de Banach réel est l'ensemble des vecteurs de longueur un. Le manuscrit affirme que toute isométrie surjective entre de telles sphères, pour des espaces non nuls et sans limite de dimension, s'étend de façon unique en une isométrie linéaire réelle de tout l'espace.","plainEn":"The unit sphere of a real Banach space is the set of vectors of length one. The manuscript asserts that every surjective isometry between such spheres, for nonzero spaces and with no dimension limit, extends uniquely to a real-linear isometry of the whole space.","expertFr":"Le manuscrit affirme que toute isométrie surjective entre sphères unités d'espaces de Banach réels non nuls s'étend de façon unique en une isométrie réelle linéaire surjective des espaces. Si les distances entre rayons distincts manquent, il réalise le défaut maximal positif, puis une contradiction par supports, le point fixe de Darbo et la convexité.","expertEn":"The manuscript asserts that every surjective isometry between the unit spheres of nonzero real Banach spaces extends uniquely to a surjective real-linear isometry of the whole spaces. If distances between different radii are not preserved, it realizes the positive maximal defect in a possibly enlarged pair, then a contradiction from common supports, Darbo's fixed-point theorem, and convexity.","sparkFr":"L'intérêt est structural : la seule sphère unité pourrait déterminer l'espace de Banach à isométrie linéaire près.","sparkEn":"The interest is structural: the unit sphere alone may determine the Banach space up to linear isometry."},{"id":"323","titleEn":"Independence of the separable quotient problem","titleFr":"Indépendance du problème du quotient séparable","claim":"Establishes, relative to the consistency of a measurable cardinal, that the separable quotient problem is independent of ZFC. The assertion that every infinite-dimensional Banach space has a separable infinite-dimensional quotient can hold for all real and complex Banach spaces, whereas the continuum hypothesis yields counterexamples over both fields.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Relative independence of the separable quotient problem","href":"preprints/Relative-independence-of-the-separable-quotient-problem-September-23-2026/paper.pdf"}],"plainFr":"Le problème du quotient séparable demande si tout espace de Banach de dimension infinie a un quotient séparable encore infini. Le manuscrit affirme que cet énoncé est indépendant de la théorie usuelle des ensembles, relativement à un grand cardinal, sur les réels comme sur les complexes.","plainEn":"The separable quotient problem asks whether every infinite-dimensional Banach space has a separable infinite-dimensional quotient. The manuscript asserts that this statement is independent of ordinary set theory, relative to a large cardinal, over both the reals and the complexes.","expertFr":"Le manuscrit affirme, relativement à un cardinal mesurable, que l'existence d'un quotient séparable infini pour tout Banach infini-dimensionnel est indépendante de ZFC, sur les réels et les complexes. L'assertion peut valoir pour tous, tandis que l'hypothèse du continu donne des contre-exemples ; en densité aleph un, seule la cohérence de ZFC est requise.","expertEn":"The manuscript asserts, relative to the consistency of a measurable cardinal, that a separable infinite-dimensional quotient for every infinite-dimensional Banach space is independent of ZFC, over both the reals and the complexes. The assertion can hold for all such spaces, while the continuum hypothesis yields counterexamples; at norm density aleph one, independence needs only the consistency of ZFC.","sparkFr":"L'intérêt est surtout fondationnel : la réponse pourrait dépendre d'axiomes, et non d'une construction explicite.","sparkEn":"The interest is mainly foundational: the answer may depend on axioms, rather than on an explicit construction."},{"id":"324","titleEn":"Lipschitz equivalent Banach spaces need not be linearly isomorphic","titleFr":"Équivalence lipschitzienne sans isomorphisme linéaire","claim":"Constructs separable real Banach spaces that are globally bi-Lipschitz equivalent but not linearly isomorphic, resolving the separable Lipschitz-isomorphism problem negatively. Thus even the complete metric structure up to bi-Lipschitz equivalence does not determine a separable Banach space's linear isomorphism class.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Lipschitz Equivalent Separable Banach Spaces Need Not Be Linearly Isomorphic","href":"preprints/Lipschitz-Equivalent-Separable-Banach-Spaces-Need-Not-Be-Linearly-Isomorphic-September-24-2026/paper.pdf"},{"title":"Bi-Lipschitz Absorption of c0 Without a Linear Copy of c0","href":"preprints/Bi-Lipschitz-Absorption-of-c0-Without-a-Linear-Copy-of-c0-September-26-2026/paper.pdf"}],"plainFr":"Deux espaces de Banach peuvent se correspondre par des déformations qui contrôlent les distances dans les deux sens. Le manuscrit affirme qu'il existe des exemples séparables réels, globalement bi-lipschitziens, qui ne sont pourtant pas linéairement isomorphes.","plainEn":"Two Banach spaces may correspond under deformations that control distances in both directions. The manuscript asserts that there are separable real examples, globally bi-Lipschitz, that are nevertheless not linearly isomorphic.","expertFr":"Le manuscrit affirme des espaces de Banach réels séparables globalement bi-lipschitziens mais non linéairement isomorphes. Ainsi la structure métrique complète, à équivalence bi-lipschitzienne près, ne détermine pas la classe d'isomorphisme linéaire, et le problème séparable reçoit une réponse négative.","expertEn":"The manuscript asserts separable real Banach spaces that are globally bi-Lipschitz equivalent but not linearly isomorphic. Thus the complete metric structure, up to bi-Lipschitz equivalence, does not determine the linear isomorphism class, and the separable problem receives a negative answer.","sparkFr":"L'intérêt est structural : contrôler les distances peut ne pas fixer la structure linéaire.","sparkEn":"The interest is structural: controlling distances may fail to fix the linear structure."},{"id":"325","titleEn":"The complete Crouzeix conjecture","titleFr":"La conjecture de Crouzeix complète","claim":"Resolves the complete Crouzeix conjecture: for every bounded operator A on a complex Hilbert space and every finite matrix-valued polynomial P, one has P[A] ≤2 _z∈ W(A) P(z), where W(A) is the numerical range. The constant 2 is sharp, independent of the matrix size, and valid in infinite dimensions.","nature":"algebre","domain":"structures","complexity":"avance","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"A direct proof of the complete Crouzeix inequality","href":"preprints/A-direct-proof-of-the-complete-Crouzeix-inequality-September-26-2026/paper.pdf"},{"title":"The complete Crouzeix theorem: optimal similarity and a common positive boundary representation","href":"preprints/The-complete-Crouzeix-theorem-September-23-2026/paper.pdf"}],"plainFr":"L'image numérique d'un opérateur est une région du plan liée à ses valeurs moyennes. Le manuscrit affirme que tout polynôme matriciel, évalué sur un opérateur borné d'un espace de Hilbert complexe, a une taille au plus double de son maximum sur cette région, et que le facteur deux est optimal.","plainEn":"The numerical range of an operator is a region in the plane tied to its average values. The manuscript asserts that every matrix-valued polynomial, evaluated on a bounded operator of a complex Hilbert space, has size at most twice its maximum on that region, and that the factor two is sharp.","expertFr":"Le manuscrit affirme la conjecture de Crouzeix complète : pour tout opérateur borné sur un Hilbert complexe et tout polynôme à valeurs matricielles fini, la norme de l'évaluation est au plus deux fois le maximum sur l'image numérique. La constante deux est optimale, indépendante de la taille des matrices, valable en dimension infinie, y compris si l'image numérique est un point ou un segment.","expertEn":"The manuscript asserts the complete Crouzeix conjecture: for every bounded operator on a complex Hilbert space and every finite matrix-valued polynomial, the norm of the evaluation is at most twice the maximum on the numerical range. The constant two is sharp, independent of matrix size, and valid in infinite dimensions, including when the numerical range is a point or a segment.","sparkFr":"L'intérêt est structural : le facteur deux pourrait être le bon contrôle universel par l'image numérique.","sparkEn":"The interest is structural: the factor two may be the right universal control by the numerical range."},{"id":"326","titleEn":"The cotype–cotype conjecture under the approximation property","titleFr":"La conjecture cotype-cotype sous la propriété d'approximation","claim":"Resolves the cotype–cotype conjecture for real Banach spaces with the approximation property. Such a nonzero space is K-convex if and only if both it and its dual have finite Rademacher cotype, with possibly different exponents. Equivalently, these cotype assumptions force nontrivial Rademacher type.","nature":"informatique","domain":"calcul","complexity":"avance","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"The cotype–cotype conjecture under the approximation property","href":"preprints/The-cotype-cotype-conjecture-under-the-approximation-property-September-23-2026/paper.pdf"}],"plainFr":"La cotype mesure une forme de convexité moyenne d'un espace normé, et la K-convexité une régularité voisine. Le manuscrit affirme que, pour un espace réel non nul qui s'approche bien par des opérateurs de rang fini, la K-convexité équivaut à la cotype finie de l'espace et de son dual.","plainEn":"Cotype measures a kind of average convexity of a normed space, and K-convexity a nearby regularity. The manuscript asserts that, for a nonzero real space well approximated by finite-rank operators, K-convexity is equivalent to finite cotype of both the space and its dual.","expertFr":"Le manuscrit affirme la conjecture cotype-cotype pour les espaces de Banach réels non nuls ayant la propriété d'approximation : un tel espace est K-convexe si et seulement si lui et son dual ont une cotype de Rademacher finie, d'exposants éventuellement distincts. De façon équivalente, ces cotype forcent un type de Rademacher non trivial.","expertEn":"The manuscript asserts the cotype–cotype conjecture for nonzero real Banach spaces with the approximation property: such a space is K-convex if and only if both it and its dual have finite Rademacher cotype, possibly with different exponents. Equivalently, these cotype assumptions force nontrivial Rademacher type.","sparkFr":"L'intérêt est structural : sous l'approximation, la cotype de l'espace et du dual pourrait caractériser la K-convexité.","sparkEn":"The interest is structural: under approximation, cotype of the space and its dual may characterize K-convexity."},{"id":"327","titleEn":"Markov type characterizes superreflexivity","titleFr":"Le type de Markov caractérise la superréflexivité","claim":"Proves that every real Banach space with Markov type p for some p > 1 admits an equivalent uniformly convex norm, answering Naor's renorming question. Together with the known converse, this characterizes superreflexivity by nontrivial Markov type.","nature":"probabilites","domain":"hasard","complexity":"avance","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Nontrivial Markov Type Forces Superreflexivity","href":"preprints/Nontrivial-Markov-Type-Forces-Superreflexivity-September-23-2026/paper.pdf"}],"plainFr":"La superréflexivité est une bonne géométrie forte d'un espace de Banach, liée à une norme très convexe. Le manuscrit affirme qu'un type de Markov d'exposant supérieur à un force une telle géométrie, et la caractérise donc avec la réciproque déjà connue.","plainEn":"Superreflexivity is a strong good geometry of a Banach space, tied to a very convex norm. The manuscript asserts that Markov type of some exponent greater than one forces this geometry, and so characterizes it together with the known converse.","expertFr":"Le manuscrit affirme que tout espace de Banach réel de type de Markov p supérieur à un admet une norme équivalente uniformément convexe, ce qui répond à la question de renormage de Naor, et qu'il est superréflexif. Avec la réciproque connue, le type de Markov non trivial caractérise la superréflexivité ; l'abrégé ajoute une norme équivalente uniformément lisse.","expertEn":"The manuscript asserts that every real Banach space of Markov type p greater than one admits an equivalent uniformly convex norm, answering Naor's renorming question, and that it is superreflexive. With the known converse, nontrivial Markov type characterizes superreflexivity; the abstract adds an equivalent uniformly smooth norm.","sparkFr":"L'intérêt est structural : un contrôle de type Markov pourrait reconnaître les espaces superréflexifs.","sparkEn":"The interest is structural: a Markov-type bound may recognize superreflexive spaces."},{"id":"328","titleEn":"Nonexpansive fixed points in reflexive Banach spaces","titleFr":"Points fixes non expansifs dans les espaces de Banach réflexifs","claim":"Resolves Kirk's reflexive-space fixed-point problem: every nonexpansive selfmap of a nonempty closed bounded convex subset of a real reflexive Banach space has a fixed point. The result uses the original norm, without assuming uniform convexity.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Fixed Points of Nonexpansive Maps in Reflexive Banach Spaces","href":"preprints/Fixed-Points-of-Nonexpansive-Maps-in-Reflexive-Banach-Spaces-September-24-2026/paper.pdf"}],"plainFr":"Une application non expansive d'un ensemble convexe dans lui-même ne rallonge aucune distance. Le manuscrit affirme que, dans un espace de Banach réel réflexif, toute telle application d'une partie convexe fermée bornée non vide a un point fixe, pour la norme donnée.","plainEn":"A nonexpansive self-map of a convex set never lengthens a distance. The manuscript asserts that, in a real reflexive Banach space, every such map of a nonempty closed bounded convex set has a fixed point, for the given norm.","expertFr":"Le manuscrit affirme le problème de point fixe de Kirk dans le cas réflexif : toute application non expansive d'une partie convexe fermée bornée non vide d'un espace de Banach réel réflexif admet un point fixe. Le résultat utilise la norme d'origine, sans convexité uniforme.","expertEn":"The manuscript asserts Kirk's fixed-point problem in the reflexive case: every nonexpansive self-map of a nonempty closed bounded convex subset of a real reflexive Banach space has a fixed point. The result uses the original norm, without uniform convexity.","sparkFr":"L'intérêt est structural : la réflexivité seule pourrait garantir ce point fixe, sans convexité uniforme.","sparkEn":"The interest is structural: reflexivity alone may guarantee this fixed point, without uniform convexity."},{"id":"329","titleEn":"A counterexample to metric-entropy duality","titleFr":"Un contre-exemple à la dualité d'entropie métrique","claim":"Disproves Pietsch's dimension-free duality conjecture for metric entropy. Origin-symmetric convex bodies violate every proposed choice of universal constants in the conjectured comparison between covering numbers and those of the polar bodies, even when the covering body is a cube.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":1887,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Counterexamples to the duality conjecture for metric entropy","href":"preprints/Counterexamples-to-the-duality-conjecture-for-metric-entropy-September-24-2026/main.pdf"}],"plainFr":"L'entropie métrique compare le nombre de petites boules qu'il faut pour recouvrir un corps convexe et son polaire. Le manuscrit affirme qu'aucune paire de constantes universelles ne réalise la comparaison conjecturée par Pietsch, même si le corps qui recouvre est un cube.","plainEn":"Metric entropy compares how many small balls are needed to cover a convex body and its polar. The manuscript asserts that no pair of universal constants realizes the comparison conjectured by Pietsch, even when the covering body is a cube.","expertFr":"Le manuscrit affirme la réfutation de la conjecture de dualité sans dimension de Pietsch pour l'entropie métrique. Pour tout choix proposé de constantes universelles, des corps convexes symétriques par rapport à l'origine violent l'inégalité de recouvrement, déjà lorsque le corps recouvrant est un cube.","expertEn":"The manuscript asserts the refutation of Pietsch's dimension-free duality conjecture for metric entropy. For every proposed choice of universal constants, origin-symmetric convex bodies violate the covering inequality, already when the covering body is a cube.","sparkFr":"L'intérêt est structural : aucune constante universelle ne semble lier l'entropie d'un corps à celle de son polaire.","sparkEn":"The interest is structural: no universal constant seems to tie a body's entropy to that of its polar."},{"id":"330","titleEn":"A uniformly discrete counterexample to bounded approximation in Lipschitz-free spaces","titleFr":"Approximation non bornée dans un espace libre lipschitzien","claim":"Constructs a countable uniformly discrete metric space whose real Lipschitz-free Banach space has the approximation property but not the bounded approximation property, answering Kalton's question negatively. Finite-rank operators approximate the identity on every compact set, but their norms cannot share a finite bound.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":true,"pdfs":[{"title":"A uniformly discrete counterexample to bounded approximation in Lipschitz-free spaces","href":"preprints/Failure-of-Bounded-Approximation-in-a-Lipschitz-Free-Space-over-a-Uniformly-Discrete-Metric-Space-September-26-2026/main.pdf"}],"plainFr":"À un espace de points discrets, on associe un espace de Banach qui encode les fonctions à pente contrôlée. Le manuscrit affirme qu'un exemple dénombrable et uniformément discret a la propriété d'approximation, mais pas sa version à normes bornées, contre une question de Kalton.","plainEn":"To a space of discrete points one attaches a Banach space that encodes functions of controlled slope. The manuscript asserts that a countable uniformly discrete example has the approximation property, but not the version with bounded norms, against a question of Kalton.","expertFr":"Le manuscrit affirme un espace métrique dénombrable uniformément discret dont l'espace libre lipschitzien réel a la propriété d'approximation mais non la propriété d'approximation bornée. L'identité s'approche sur tout compact par des opérateurs de rang fini, sans borne finie commune de leurs normes.","expertEn":"The manuscript asserts a countable uniformly discrete metric space whose real Lipschitz-free space has the approximation property but not the bounded approximation property. The identity can be approximated on every compact set by finite-rank operators, with no common finite bound on their norms.","sparkFr":"L'intérêt est structural : approcher l'identité sur les compacts peut exiger des normes arbitrairement grandes.","sparkEn":"The interest is structural: approximating the identity on compact sets may force arbitrarily large norms."},{"id":"331","titleEn":"Reflexive midpoint convexity and diamond distortion","titleFr":"Convexité médiane réflexive et distorsion des diamants","claim":"Constructs a real reflexive Banach space with an asymptotically midpoint uniformly convex norm but no equivalent asymptotically uniformly convex norm, extending Baudier's separation to reflexive spaces. In the same space, depth-k countably branching diamonds require distortion at least √(1+k/12), so midpoint uniform convexity does not force uniformly bounded diamond distortion even under reflexivity.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1932,"yearKnown":false,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Asymptotic midpoint uniform convexity and unbounded diamond distortion in a reflexive tree space","href":"preprints/Asymptotic-midpoint-uniform-convexity-and-unbounded-diamond-distortion-in-a-reflexive-tree-space-September-27-2026/manuscript.pdf"},{"title":"Midpoint lenses in segment spaces","href":"preprints/Midpoint-lenses-in-segment-spaces-September-27-2026/manuscript.pdf"},{"title":"Distortion of countably branching diamonds from midpoint and tree energies","href":"preprints/Diamond-distortion-from-midpoint-and-tree-energies-September-27-2026/manuscript.pdf"},{"title":"Exact asymptotic moduli in a Daugavet subspace of L1","href":"preprints/Exact-asymptotic-moduli-in-a-Daugavet-subspace-of-L1-September-27-2026/manuscript.pdf"},{"title":"Midpoint convexity from bounded tree potentials and path costs","href":"preprints/Midpoint-convexity-from-bounded-tree-potentials-and-path-costs-September-27-2026/manuscript.pdf"},{"title":"Independent products in real L1: asymptotic midpoint convexity without AUC renormings","href":"preprints/Independent-products-in-real-L1-asymptotic-midpoint-convexity-without-AUC-renormings-September-27-2026/manuscript.pdf"}],"plainFr":"Une norme asymptotiquement convexe pénalise les milieux de segments éloignés. Le manuscrit affirme qu'un Banach réel réflexif peut avoir cette convexité des milieux sans norme équivalente plus convexe, et que ses diamants ramifiés exigent une distorsion croissant avec la profondeur.","plainEn":"An asymptotically convex norm penalizes midpoints of segments that stay far apart. The manuscript asserts that a real reflexive Banach space can have this midpoint convexity with no more strongly convex equivalent norm, and that certain diamond grids there require distortion that grows with depth.","expertFr":"Le manuscrit affirme un espace de Banach réel réflexif séparable, de norme asymptotiquement uniformément convexe au sens des milieux, sans norme équivalente asymptotiquement uniformément convexe, ce qui étend la séparation de Baudier. Dans cet espace, le diamant dénombrablement ramifié de profondeur k a une distorsion au moins égale à la racine de un plus k sur douze.","expertEn":"The manuscript asserts a separable reflexive real Banach space whose norm is asymptotically midpoint uniformly convex, with no asymptotically uniformly convex equivalent norm, extending Baudier's separation. In this space, the countably branching diamond of depth k has distortion at least the square root of one plus k over twelve.","sparkFr":"L'intérêt est structural : la convexité des milieux peut survivre à la réflexivité sans borner la distorsion des diamants.","sparkEn":"The interest is structural: midpoint convexity may survive reflexivity without bounding diamond distortion."},{"id":"332","titleEn":"Metric Markov cotype of ℓ1 and Hilbert-space Lipschitz extension","titleFr":"Cotype de Markov de l'espace ell un et extension lipschitzienne","claim":"Proves that real ℓ1 has metric Markov cotype two, answering Mendel and Naor's question. Consequently, every Lipschitz map from an arbitrary subset of a real Hilbert space into ℓ1 extends to the whole space with a universal multiplicative loss in its Lipschitz constant, resolving Ball's extension problem for this target.","nature":"probabilites","domain":"hasard","complexity":"frontiere","problemYear":1900,"yearKnown":false,"manuscriptDate":"2026-10-05","lean":false,"pdfs":[{"title":"Metric Markov Cotype Two of ℓ1","href":"preprints/Metric-Markov-Cotype-Two-of-l1-October-5-2026/l1-markov-cotype.pdf"}],"plainFr":"L'espace ell un est celui des suites dont la somme des valeurs absolues est finie. Le manuscrit affirme qu'il a la cotype de Markov métrique deux, et qu'ainsi toute application à pente contrôlée, définie sur une partie d'un espace de Hilbert réel et à valeurs dans ell un, s'étend au tout avec une perte universelle.","plainEn":"The space ell one consists of sequences whose absolute values have a finite sum. The manuscript asserts that it has metric Markov cotype two, and thus that every controlled-slope map from a subset of a real Hilbert space into ell one extends to the whole space with a universal loss.","expertFr":"Le manuscrit affirme que l'espace de Banach réel ell un a la cotype de Markov métrique deux, répondant à Mendel et Naor. Toute application lipschitzienne d'une partie quelconque d'un Hilbert réel vers ell un s'étend donc à l'espace entier avec une perte multiplicative universelle, ce qui résout le problème d'extension de Ball pour cette cible.","expertEn":"The manuscript asserts that the real Banach space ell one has metric Markov cotype two, answering Mendel and Naor. Every Lipschitz map from an arbitrary subset of a real Hilbert space into ell one therefore extends to the whole space with a universal multiplicative loss, resolving Ball's extension problem for this target.","sparkFr":"L'intérêt est structural : cette cotype pourrait expliquer des extensions lipschitziennes contrôlées vers ell un.","sparkEn":"The interest is structural: this cotype may explain controlled Lipschitz extensions into ell one."},{"id":"333","titleEn":"Smooth isometric immersions of surfaces into ℝ4","titleFr":"Immersions isométriques lisses de surfaces dans l'espace de dimension quatre","claim":"Every closed smooth Riemannian surface admits a smooth isometric immersion into ℝ4, resolving the closed-surface form of the four-dimensional isometric-immersion problem. This includes nonorientable surfaces and metrics of arbitrary Gaussian curvature.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Smooth isometric immersions of closed surfaces into Euclidean four-space","href":"preprints/Smooth-isometric-immersions-of-closed-surfaces-into-Euclidean-four-space-September-23-2026/paper.pdf"}],"plainFr":"Une immersion isométrique pose une surface dans un espace euclidien sans changer les longueurs mesurées dessus. Le manuscrit affirme que toute surface lisse fermée, orientable ou non, et de courbure quelconque, admet une telle réalisation lisse dans l'espace de dimension quatre.","plainEn":"An isometric immersion places a surface in Euclidean space without changing lengths measured on it. The manuscript asserts that every closed smooth surface, orientable or not, and of arbitrary curvature, admits such a smooth realization in four-dimensional space.","expertFr":"Le manuscrit affirme que toute surface riemannienne lisse fermée admet une immersion isométrique lisse dans l'espace euclidien de dimension quatre. Cela comprend les surfaces non orientables et les métriques de courbure de Gauss arbitraire, et résout la forme fermée du problème classique en dimension quatre.","expertEn":"The manuscript asserts that every closed smooth Riemannian surface admits a smooth isometric immersion into Euclidean four-space. This includes nonorientable surfaces and metrics of arbitrary Gaussian curvature, and resolves the closed-surface form of the classical four-dimensional problem.","sparkFr":"L'intérêt est structural : quatre dimensions pourraient toujours suffire à réaliser isométriquement une surface fermée lisse.","sparkEn":"The interest is structural: four dimensions may always suffice for a smooth isometric realization of a closed surface."},{"id":"334","titleEn":"A smooth surface metric with no local isometric immersion in ℝ3","titleFr":"Une métrique lisse de surface sans réalisation isométrique locale","claim":"Constructs a smooth positive-definite metric on (-1,1)^2 for which no neighborhood of the origin admits a smooth isometric immersion into ℝ3. This answers the unrestricted smooth local isometric realization problem for surfaces negatively, even after shrinking the neighborhood.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Smooth Metric with No Local Isometric Immersion into Three-Space","href":"preprints/A-Smooth-Metric-with-No-Local-Isometric-Immersion-into-Three-Space-September-24-2026/paper.pdf"}],"plainFr":"On peut chercher, près d'un point, une surface lisse de l'espace usuel qui réalise une métrique. Le manuscrit affirme qu'une métrique lisse positive sur un carré ouvert peut coller à tout ordre à la métrique plate à l'origine, sans réalisation dans aucun voisinage de l'espace de dimension trois.","plainEn":"One may look, near a point, for a smooth surface in ordinary space that realizes a given metric. The manuscript asserts that a smooth positive metric on an open square can match the flat metric to every order at the origin, while no neighborhood admits such a realization in three-dimensional space.","expertFr":"Le manuscrit affirme une métrique riemannienne lisse définie positive sur le carré ouvert de côté deux centré à l'origine, égale à la métrique euclidienne à tout ordre en ce point, dont aucun voisinage n'admet d'immersion isométrique lisse dans l'espace euclidien de dimension trois. Cela répond négativement au problème local lisse sans restriction, même après rétrécissement.","expertEn":"The manuscript asserts a smooth positive-definite Riemannian metric on the open square of side two centered at the origin, agreeing with the Euclidean metric to every order there, such that no neighborhood admits a smooth isometric immersion into Euclidean three-space. This answers the unrestricted smooth local realization problem in the negative, even after shrinking.","sparkFr":"L'intérêt est structural : coller à tout ordre à la métrique plate peut ne pas donner de réalisation locale lisse.","sparkEn":"The interest is structural: matching the flat metric to every order may fail to give a smooth local realization."},{"id":"335","titleEn":"Gromov’s integral scalar-curvature bound for simplicial volume","titleFr":"Borne intégrale de Gromov entre courbure scalaire et volume simplicial","claim":"Proves _M(Scal_g^-)^n/2\\,dV_g≥ a_n M for every closed connected oriented smooth n-manifold, n ≥ 3, and every smooth metric, with a_n 0 depending only on dimension. Here Scal_g^-= \\0,-Scal_g\\ and M is real simplicial volume. Also proves rational inessentiality under positive scalar curvature, resolving the Gromov–Lawson conjecture; every nonnegative-scalar-curvature metric on a closed aspherical manifold is flat.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1981,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"An integral scalar curvature bound for real simplicial volume","href":"preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/v126-proof.pdf"},{"title":"Positive scalar curvature forces rational inessentiality","href":"preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/paper.pdf"}],"plainFr":"Le volume simplicial mesure, de façon topologique, une sorte de taille d'une variété fermée orientée. Le manuscrit affirme qu'en dimension au moins trois l'intégrale d'une puissance de la courbure scalaire négative vaut au moins une constante fois ce volume, et que la courbure positive impose une rigidité.","plainEn":"Simplicial volume measures, in a topological way, a kind of size of a closed oriented manifold. The manuscript asserts that in dimension at least three the integral of a power of negative scalar curvature is at least a constant times this volume, and that positive scalar curvature imposes a rigidity.","expertFr":"Le manuscrit affirme l'inégalité intégrale de Gromov dès la dimension trois : l'intégrale de la puissance n/2 de la partie négative de la courbure scalaire est au moins une constante positive de la dimension fois le volume simplicial réel. Il ajoute l'inessentialité rationnelle sous courbure scalaire positive, donc Gromov–Lawson, et la platitude des métriques non négatives sur une variété fermée asphérique.","expertEn":"The manuscript asserts, in dimension at least three, Gromov's integral inequality: the integral of the n/2 power of the negative part of scalar curvature is at least a positive dimensional constant times the real simplicial volume. It also asserts rational inessentiality under positive scalar curvature, hence Gromov–Lawson, and flatness when that curvature is nonnegative on a closed aspherical manifold.","sparkFr":"L'intérêt est structural : une courbure scalaire très négative pourrait forcer du volume simplicial, et une courbure positive de la rigidité.","sparkEn":"The interest is structural: very negative scalar curvature may force simplicial volume, and positive curvature some rigidity."},{"id":"336","titleEn":"Spectral scalar curvature, Urysohn width, and macroscopic dimension","titleFr":"Courbure scalaire spectrale, largeur d'Urysohn et dimension macroscopique","claim":"Every complete connected smooth boundaryless n-manifold, n ≥ 3, satisfying -4 +Scal≥1 as a quadratic-form inequality admits a continuous map to a simplicial complex of dimension at most n-2 whose entire fibers have diameter bounded only by n in the original metric. This strengthens Gromov's width conclusion to spectral scalar curvature. Universal covers of closed positive-scalar-curvature manifolds also have continuous macroscopic dimension at most n-2 for every n ≥ 2.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1981,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Spectral scalar curvature and uniform Urysohn width","href":"preprints/Spectral-scalar-curvature-and-uniform-Urysohn-width-October-5-2026/main.pdf"},{"title":"Spectral scalar curvature and Urysohn width in dimension three","href":"preprints/Spectral-scalar-curvature-and-Urysohn-width-in-dimension-three-October-5-2026/spectral-urysohn-three-manifolds.pdf"},{"title":"Positive scalar curvature and uniform codimension-two width","href":"preprints/Positive-scalar-curvature-and-uniform-codimension-two-width-September-23-2026/paper.pdf"}],"plainFr":"La largeur d'Urysohn demande si une variété s'envoie vers un squelette plus petit sans fibres trop longues. Le manuscrit affirme qu'une borne spectrale sur la courbure scalaire donne une telle application vers un complexe de dimension abaissée de deux, et borne aussi une dimension macroscopique des revêtements.","plainEn":"Urysohn width asks whether a manifold maps to a thinner skeleton without overly long fibers. The manuscript asserts that a spectral bound on scalar curvature yields such a map to a complex whose dimension drops by two, and also bounds a macroscopic dimension of covers.","expertFr":"Le manuscrit affirme qu'une variété lisse complète, connexe et sans bord, de dimension au moins trois, sous la borne spectrale indiquée, s'envoie vers un complexe de dimension abaissée de deux, à fibres bornées par la seule dimension. L'abrégé part de la dimension quatre, et le texte borne par n moins deux la dimension macroscopique des revêtements universels à courbure scalaire positive, dès la dimension deux.","expertEn":"The manuscript asserts that a complete connected boundaryless smooth manifold of dimension at least three, under the stated spectral bound, maps to a complex whose dimension drops by two, with fibers bounded by the dimension alone. The abstract starts at dimension four, and the text bounds by n minus two the macroscopic dimension of positive-scalar-curvature universal covers, from dimension two.","sparkFr":"L'intérêt est structural : une borne spectrale de courbure pourrait déjà amincir la variété à l'échelle macroscopique.","sparkEn":"The interest is structural: a spectral curvature bound may already thin the manifold at macroscopic scale."},{"id":"337","titleEn":"Sharp Cartan–Hadamard isoperimetry and rigidity","titleFr":"Isopérimétrie de Cartan–Hadamard et rigidité","claim":"Proves generalized Cartan–Hadamard isoperimetry in every dimension: in a complete simply connected manifold with sectional curvature at most κ ≤ 0, every finite-volume finite-perimeter set satisfies the sharp comparison with the equal-volume model ball. Bounded positive-volume equality regions for κ = 0 are Euclidean balls. Also proves sharp Euclidean filling bounds for compactly supported integral n-cycles, n ≥ 2, in arbitrary proper CAT(0) spaces.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Generalized Cartan–Hadamard isoperimetry and Euclidean equality rigidity","href":"preprints/Generalized-Cartan-Hadamard-isoperimetry-and-Euclidean-equality-rigidity-September-23-2026/paper.pdf"},{"title":"Sharp integral fillings in CAT(0) spaces","href":"preprints/Sharp-integral-fillings-in-CAT(0"}],"plainFr":"L'isopérimétrie compare le bord d'une région à la boule de même volume. Le manuscrit affirme que, dans une variété complète simplement connexe de courbure sectionnelle au plus nulle, toute région finie a un bord au moins aussi grand que la boule modèle, avec rigidité euclidienne.","plainEn":"Isoperimetry compares a region's boundary with the equal-volume ball. The manuscript asserts that, in a complete simply connected manifold of nonpositive sectional curvature, every finite region has boundary at least as large as the model ball, with Euclidean rigidity.","expertFr":"Le manuscrit affirme l'isopérimétrie de Cartan–Hadamard en toute dimension : sous courbure sectionnelle au plus κ négatif ou nul, toute partie de volume et de périmètre finis a au moins le périmètre de la boule modèle. Pour κ nul, l'égalité sur une région bornée de volume positif caractérise les boules euclidiennes, et des remplissages optimaux valent pour des cycles intégraux compacts dans les CAT(0) propres.","expertEn":"The manuscript asserts Cartan–Hadamard isoperimetry in every dimension: under sectional curvature at most a nonpositive κ, every finite-volume finite-perimeter set meets at least the model ball's perimeter. For vanishing κ, equality on a bounded positive-volume region characterizes Euclidean balls, and sharp fillings hold for compactly supported integral cycles in proper CAT(0) spaces.","sparkFr":"L'intérêt est structural : la boule modèle pourrait donner la comparaison optimale dès que la courbure sectionnelle est au plus nulle.","sparkEn":"The interest is structural: the model ball may give the sharp comparison whenever sectional curvature is at most zero."},{"id":"338","titleEn":"Yau's uniformization conjecture","titleFr":"La conjecture d'uniformisation de Yau","claim":"Proves Yau's uniformization conjecture: every complete connected noncompact Kähler manifold with strictly positive holomorphic bisectional curvature is biholomorphic to ℂn.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1978,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Uniformization of complete Kähler manifolds with positive bisectional curvature","href":"preprints/Uniformization-of-complete-Kahler-manifolds-with-positive-bisectional-curvature-September-23-2026/paper.pdf"}],"plainFr":"Une variété de Kähler est un espace complexe muni d'une métrique compatible avec ses rotations holomorphes. Le manuscrit affirme que si elle est complète, connexe, non compacte et de courbure bisectionnelle holomorphe strictement positive, elle est holomorphiquement l'espace euclidien complexe.","plainEn":"A Kähler manifold is a complex space with a metric compatible with its holomorphic rotations. The manuscript asserts that if it is complete, connected, noncompact, and of strictly positive holomorphic bisectional curvature, it is holomorphically complex Euclidean space.","expertFr":"Le manuscrit affirme la conjecture d'uniformisation de Yau en toute dimension complexe. Toute variété de Kähler complète, connexe et non compacte, à courbure bisectionnelle holomorphe strictement positive, est biholomorphe à l'espace euclidien complexe.","expertEn":"The manuscript asserts Yau's uniformization conjecture in every complex dimension. Every complete connected noncompact Kähler manifold with strictly positive holomorphic bisectional curvature is biholomorphic to complex Euclidean space.","sparkFr":"L'intérêt est structural : cette courbure holomorphe positive pourrait ne laisser que l'espace complexe standard.","sparkEn":"The interest is structural: this positive holomorphic curvature may leave only standard complex space."},{"id":"339","titleEn":"Katok's entropy rigidity conjecture","titleFr":"La conjecture de rigidité entropique de Katok","claim":"Proves Katok's entropy rigidity conjecture for closed connected Riemannian manifolds of dimension at least three with strictly negative sectional curvature: normalized Liouville measure maximizes entropy for the geodesic flow if and only if the metric is locally symmetric.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1986,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"Entropy equality and local symmetry in negative curvature","href":"preprints/Entropy-equality-and-local-symmetry-in-negative-curvature-September-23-2026/paper.pdf"}],"plainFr":"Le flot géodésique suit, à vitesse constante, les plus courts chemins d'une variété fermée. Le manuscrit affirme qu'en dimension au moins trois et à courbure sectionnelle strictement négative, la mesure de volume normalisée maximise l'entropie de ce flot exactement lorsque la métrique est localement symétrique.","plainEn":"The geodesic flow follows, at constant speed, the shortest paths of a closed manifold. The manuscript asserts that in dimension at least three and with strictly negative sectional curvature, normalized volume measure maximizes the entropy of this flow exactly when the metric is locally symmetric.","expertFr":"Le manuscrit affirme la conjecture de rigidité entropique de Katok pour les variétés riemanniennes fermées connexes de dimension au moins trois à courbure sectionnelle strictement négative. La mesure de Liouville normalisée a l'entropie maximale pour le flot géodésique de vitesse un si et seulement si la métrique est localement symétrique, y compris tous les types symétriques de rang un à échelle arbitraire.","expertEn":"The manuscript asserts Katok's entropy rigidity conjecture for closed connected Riemannian manifolds of dimension at least three with strictly negative sectional curvature. Normalized Liouville measure has maximal entropy for the unit-speed geodesic flow if and only if the metric is locally symmetric, including all rank-one symmetric types at arbitrary scale.","sparkFr":"L'intérêt est structural : le maximum d'entropie du flot géodésique pourrait reconnaître les métriques localement symétriques.","sparkEn":"The interest is structural: maximal entropy of the geodesic flow may recognize locally symmetric metrics."},{"id":"340","titleEn":"A counterexample to the nearby Lagrangian conjecture","titleFr":"Un contre-exemple à la conjecture des lagrangiennes voisines","claim":"Disproves the unrestricted nearby Lagrangian conjecture. For some sufficiently large even N, constructs a closed exact embedded Lagrangian in T^*(S^9× S^N-1) that is diffeomorphic to the base but not Hamiltonian isotopic to its zero section.","nature":"combinatoire","domain":"structures","complexity":"frontiere","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A counterexample to the nearby Lagrangian conjecture","href":"preprints/A-counterexample-to-the-nearby-Lagrangian-conjecture-September-23-2026/paper.pdf"}],"plainFr":"Dans le fibré des covecteurs, la section nulle est une sous-variété lagrangienne de référence. Le manuscrit affirme que, pour un entier pair assez grand, une lagrangienne exacte fermée d'un produit de sphères peut avoir la forme lisse de la base sans équivalence hamiltonienne à cette section.","plainEn":"In the bundle of covectors, the zero section is a reference Lagrangian. The manuscript asserts that, for a large enough even integer, a closed exact Lagrangian in a product of spheres can share the base's smooth shape without Hamiltonian equivalence to that section.","expertFr":"Le manuscrit réfute la conjecture des lagrangiennes voisines sans restriction. Pour un entier pair N assez grand, il affirme dans le cotangent de la sphère de dimension neuf fois la sphère de dimension N moins un une lagrangienne exacte fermée plongée, difféomorphe à la base, qui n'est pas isotope hamiltonienne à la section nulle.","expertEn":"The manuscript disproves the unrestricted nearby Lagrangian conjecture. For some sufficiently large even integer N, it asserts in the cotangent of the nine-sphere times the sphere of dimension N minus one a closed exact embedded Lagrangian, diffeomorphic to the base, that is not Hamiltonian isotopic to the zero section.","sparkFr":"L'intérêt est structural : avoir la forme lisse de la base peut ne pas forcer l'équivalence hamiltonienne à la section nulle.","sparkEn":"The interest is structural: having the smooth shape of the base may fail to force Hamiltonian equivalence to the zero section."},{"id":"341","titleEn":"Donaldson's hypersymplectic deformation conjecture","titleFr":"La conjecture de déformation hypersymplectique de Donaldson","claim":"Proves Donaldson's hypersymplectic deformation conjecture in a cohomology-preserving form. Every positive triple of smooth closed two-forms on a closed connected oriented four-manifold, normalized by ω_i ω_j=δ_ij, deforms through positive closed triples to a hyperkähler triple while preserving all three cohomology classes. Any positive triple can first be normalized by a constant linear change.","nature":"geometrie-algebrique","domain":"formes","complexity":"avance","problemYear":1983,"yearKnown":false,"manuscriptDate":"2026-10-07","lean":false,"pdfs":[{"title":"Deforming hypersymplectic four-manifolds to hyperkähler triples","href":"preprints/Deforming-hypersymplectic-four-manifolds-to-hyperkahler-triples-October-7-2026/paper.pdf"}],"plainFr":"Une structure hyperkählérienne fait coexister de façon rigide trois formes qui mesurent les aires sur une variété de dimension quatre. Le manuscrit affirme que tout triplet positif de formes fermées lisses, une fois normalisé, se déforme en un tel triplet sans changer les trois classes de cohomologie.","plainEn":"A hyperkähler structure makes three area-measuring forms coexist rigidly on a four-dimensional manifold. The manuscript asserts that every positive triple of smooth closed forms, once normalized, deforms into such a triple without changing the three cohomology classes.","expertFr":"Le manuscrit affirme une forme cohomologique de la conjecture de déformation hypersymplectique de Donaldson. Sur une variété fermée connexe orientée de dimension quatre, tout triplet positif normalisé de formes fermées lisses se déforme parmi les triplets positifs fermés vers un triplet hyperkählérien en fixant les trois classes, après une normalisation linéaire constante éventuelle.","expertEn":"The manuscript asserts a cohomological form of Donaldson's hypersymplectic deformation conjecture. On a closed connected oriented four-manifold, every normalized positive triple of smooth closed forms deforms through positive closed triples to a hyperkähler triple while fixing the three classes, after a possible constant linear normalization.","sparkFr":"L'intérêt est structural : la positivité de trois formes fermées pourrait toujours mener à une géométrie hyperkählérienne.","sparkEn":"The interest is structural: positivity of three closed forms may always lead to hyperkähler geometry."},{"id":"342","titleEn":"Donaldson's tamed-to-compatible conjecture","titleFr":"La conjecture de Donaldson, de l'apprivoisé au compatible","claim":"Proves Donaldson's tamed-to-compatible conjecture: every smooth almost complex structure on a closed four-manifold that is tamed by a symplectic form admits a compatible symplectic form. The almost complex structure stays fixed; the form's cohomology class may change.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1983,"yearKnown":false,"manuscriptDate":"2026-10-06","lean":true,"pdfs":[{"title":"Taming implies compatibility on four-manifolds","href":"preprints/Taming-implies-compatibility-on-four-manifolds-October-6-2026/paper.pdf"}],"plainFr":"Une structure presque complexe dit, en chaque point d'une variété de dimension quatre, comment tourner d'un quart de tour. Le manuscrit affirme que si une forme symplectique l'apprivoise, une forme symplectique, peut-être d'une autre classe, lui est compatible, la structure restant fixe.","plainEn":"An almost complex structure says, at each point of a four-dimensional manifold, how to turn by a quarter turn. The manuscript asserts that if a symplectic form tames it, some symplectic form, perhaps of another class, is compatible with it, while the structure stays fixed.","expertFr":"Le manuscrit affirme la conjecture de Donaldson : toute structure presque complexe lisse sur une variété fermée de dimension quatre, apprivoisée par une forme symplectique, admet une forme symplectique compatible. La structure reste fixe, la classe de la forme peut changer, et le cône compatible est caractérisé par la positivité stricte d'intersection sur l'adhérence de la partie invariante du cône apprivoisant.","expertEn":"The manuscript asserts Donaldson's conjecture: every smooth almost complex structure on a closed four-manifold, tamed by a symplectic form, admits a compatible symplectic form. The structure stays fixed, the form's class may change, and the compatible cone is characterized by strict intersection positivity on the closure of the invariant part of the taming cone.","sparkFr":"L'intérêt est structural : l'apprivoisement symplectique pourrait déjà garantir une forme vraiment compatible en dimension quatre.","sparkEn":"The interest is structural: symplectic taming may already guarantee a truly compatible form in dimension four."},{"id":"343","titleEn":"Symplectic ball packing in higher dimensions","titleFr":"Empilement de boules symplectiques en dimension au moins six","claim":"Resolves the Siegel–Yao conjecture for arbitrary capacities in every dimension 2n≥6. Finitely many closed symplectic balls of capacities R_1, ,R_k embed disjointly into an open ball of capacity R exactly when _iR_i^n R^n and R_i+R_j R for every distinct pair i, j.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1985,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Symplectic Ball Packings in Higher Dimensions","href":"preprints/Symplectic-Ball-Packings-in-Higher-Dimensions-September-23-2026/paper.pdf"}],"plainFr":"Empiler des boules symplectiques, c'est les placer sans chevauchement dans une plus grande, en respectant les aires. Le manuscrit affirme qu'en dimension au moins six cela tient, pour des capacités données, exactement sous une somme de puissances et des sommes deux à deux.","plainEn":"Packing symplectic balls means placing them without overlap in a larger ball while respecting the form that measures areas. The manuscript asserts that in dimension at least six this is possible, for given capacities, exactly under a sum-of-powers condition and a pairwise-sum condition.","expertFr":"Le manuscrit affirme la conjecture A de Siegel et Yao pour des capacités positives arbitraires en toute dimension paire au moins six. Des boules symplectiques standard fermées se plongent de façon disjointe dans l'intérieur d'une boule de capacité R exactement lorsque la somme des puissances et les sommes deux à deux satisfont les inégalités écrites ; la capacité est π fois le carré du rayon euclidien.","expertEn":"The manuscript asserts Siegel and Yao's Conjecture A for arbitrary positive capacities in every even dimension at least six. Closed standard symplectic balls embed disjointly into the interior of a ball of capacity R exactly when the sum of powers and the pairwise sums satisfy the stated inequalities; capacity is π times the square of the Euclidean radius.","sparkFr":"L'intérêt est structural : en dimension au moins six, deux inégalités de capacités pourraient décider tout empilement fini.","sparkEn":"The interest is structural: in dimension at least six, two capacity inequalities may decide every finite packing."},{"id":"344","titleEn":"The metric Blaschke conjecture","titleFr":"La conjecture métrique de Blaschke","claim":"Proves the metric Blaschke conjecture: every closed connected Riemannian manifold of positive dimension whose injectivity radius equals its diameter is, up to scaling, a standard compact rank-one symmetric space.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1916,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The metric Blaschke theorem","href":"preprints/The-metric-Blaschke-theorem-September-23-2026/paper.pdf"}],"plainFr":"Le rayon d'injectivité est la distance jusqu'à laquelle les géodésiques issues d'un point ne se recoupent pas, et le diamètre la plus grande distance. Le manuscrit affirme que s'ils coïncident sur une variété riemannienne fermée connexe, alors, à l'échelle près, c'est un espace symétrique compact standard de rang un.","plainEn":"The injectivity radius is the distance up to which geodesics from a point do not meet again, and the diameter is the greatest distance. The manuscript asserts that if they agree on a closed connected Riemannian manifold, then, up to scale, it is a standard compact rank-one symmetric space.","expertFr":"Le manuscrit affirme la conjecture métrique de Blaschke. Toute variété riemannienne lisse fermée connexe de dimension positive dont le rayon d'injectivité global égale le diamètre est, à l'échelle près, un espace symétrique compact standard de rang un.","expertEn":"The manuscript asserts the metric Blaschke conjecture. Every connected closed smooth Riemannian manifold of positive dimension whose global injectivity radius equals its diameter is, up to scale, a standard compact rank-one symmetric space.","sparkFr":"L'intérêt est structural : l'égalité du rayon d'injectivité et du diamètre pourrait ne laisser que les modèles symétriques de rang un.","sparkEn":"The interest is structural: equality of injectivity radius and diameter may leave only the rank-one symmetric models."},{"id":"345","titleEn":"Infinitely many closed geodesics on Riemannian spheres and closed three-manifolds","titleFr":"Infiniment de géodésiques fermées sur les sphères et en dimension trois","claim":"Proves that every smooth Riemannian metric on Sn, n ≥ 2, has infinitely many prime closed geodesics with pairwise distinct images. The same conclusion holds on every closed manifold admitting a finite smooth spherical cover and on every closed three-manifold, without orientability or nondegeneracy restrictions.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Infinitely many closed geodesic images on every Riemannian sphere","href":"preprints/Infinitely-many-closed-geodesic-images-on-every-Riemannian-sphere-September-24-2026/paper.pdf"}],"plainFr":"Une géodésique fermée première est une boucle de plus court chemin qui ne se répète pas. Le manuscrit affirme que toute métrique lisse sur une sphère de dimension au moins deux en a une infinité d'images distinctes, et de même sur toute variété fermée de dimension trois.","plainEn":"A prime closed geodesic is a shortest-path loop that does not repeat itself. The manuscript asserts that every smooth metric on a sphere of dimension at least two has infinitely many with distinct images, and likewise on every closed three-dimensional manifold.","expertFr":"Le manuscrit affirme qu'une métrique riemannienne lisse sur la sphère de dimension au moins deux a une infinité de géodésiques fermées premières d'images distinctes, même si elle dégénère au-delà de la dimension deux. La même conclusion vaut pour tout revêtement sphérique lisse fini et toute variété fermée de dimension trois, sans orientabilité ni non-dégénérescence.","expertEn":"The manuscript asserts that every smooth Riemannian metric on the sphere of dimension n at least two has infinitely many prime closed geodesics with pairwise distinct images, including degenerate metrics beyond dimension two. The same conclusion holds for every closed manifold with a finite smooth spherical cover and every closed three-manifold, with no orientability or nondegeneracy restriction.","sparkFr":"L'intérêt est structural : sur les sphères et en dimension trois, aucune métrique lisse ne semblerait n'avoir qu'un nombre fini de telles boucles.","sparkEn":"The interest is structural: on spheres and in dimension three, no smooth metric would seem to have only finitely many such loops."},{"id":"346","titleEn":"Sharp singular-set bounds for stationary integral varifolds","titleFr":"Singularités des varifolds intégraux stationnaires","claim":"Proves that every stationary integral m-varifold in a Euclidean open set has singular set of Hausdorff dimension at most m-1, a sharp bound in every positive dimension and codimension. On round spheres, the family also proves almost-everywhere regularity: the singular set has zero m-dimensional Hausdorff measure.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"A Codimension-One Bound for the Singular Set of a Stationary Integral Varifold","href":"preprints/A-Codimension-One-Bound-for-the-Singular-Set-of-a-Stationary-Integral-Varifold-October-5-2026/varifold-singular-dimension.pdf"},{"title":"Almost-everywhere regularity of stationary integral varifolds","href":"preprints/Almost-everywhere-regularity-of-stationary-integral-varifolds-September-23-2026/paper.pdf"}],"plainFr":"Un varifold intégral stationnaire est une surface généralisée, peut-être singulière, immobile au premier ordre pour l'aire. Le manuscrit affirme que ses singularités ont une dimension au plus inférieure d'une unité, borne optimale, et que sur les sphères rondes elles sont négligeables.","plainEn":"A stationary integral varifold is a generalized, possibly singular, surface that does not move to first order for area. The manuscript asserts that its singular set has dimension at most one less, a sharp bound, and that on round spheres it is negligible for the surface measure.","expertFr":"Le manuscrit affirme que tout varifold intégral stationnaire de dimension m dans un ouvert euclidien a un ensemble singulier de dimension de Hausdorff au plus m moins un, borne optimale en toute dimension et codimension positives. Sur les sphères rondes, cet ensemble a une mesure de Hausdorff m-dimensionnelle nulle.","expertEn":"The manuscript asserts that every stationary integral m-varifold in a Euclidean open set has singular set of Hausdorff dimension at most m minus one, a sharp bound in every positive dimension and codimension. On round spheres, this set has zero m-dimensional Hausdorff measure.","sparkFr":"L'intérêt est structural : la stationnarité pourrait limiter les singularités à une dimension de moins, de façon optimale.","sparkEn":"The interest is structural: stationarity may limit singularities to one dimension less, and sharply so."},{"id":"347","titleEn":"Counterexamples to stable-Morse and strong Arnold fixed-point bounds","titleFr":"Contre-exemples aux bornes de Morse stable et d'Arnold forte","claim":"Disproves stable-Morse lower bounds for nondegenerate Hamiltonian fixed points: on simply connected closed Kähler manifolds of real dimension 22, the deficit below the stable Morse number is unbounded. A separate Hamiltonian diffeomorphism of the complex quadric threefold has exactly three fixed points, fewer than the four critical points required of every smooth function.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Hamiltonian Fixed Points Below the Stable Morse Number in Dimension Twenty-Two","href":"preprints/Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-in-Dimension-Twenty-Two-October-5-2026/hamiltonian-fixed-points-below-stable-morse-number.pdf"},{"title":"Sharpness of the Cyclic Integral Floer Bound Below the Stable Morse Number","href":"preprints/Sharpness-of-the-Cyclic-Integral-Floer-Bound-Below-the-Stable-Morse-Number-October-5-2026/sharp-cyclic-integral-floer-bound-below-stable-morse-number.pdf"},{"title":"Hamiltonian Fixed Points Below the Stable Morse Number","href":"preprints/Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-October-5-2026/paper.pdf"},{"title":"A nondegenerate counterexample to the Morse-number Arnold bound","href":"preprints/A-nondegenerate-counterexample-to-the-Morse-number-Arnold-bound-September-23-2026/paper.pdf"},{"title":"Three fixed points on the symplectic quadric threefold","href":"preprints/A-degenerate-counterexample-to-the-critical-number-Arnold-bound-September-23-2026/paper.pdf"}],"plainFr":"On attend parfois autant de points fixes hamiltoniens que de points critiques d'une fonction lisse. Le manuscrit affirme que la borne de Morse stable échoue en dimension réelle vingt-deux, avec un déficit non borné, et qu'une quadrique complexe n'a que trois points fixes.","plainEn":"One sometimes expects as many Hamiltonian fixed points as critical points of a smooth function. The manuscript asserts that the stable Morse bound fails in real dimension twenty-two, with an unbounded deficit, and that a complex quadric has only three fixed points.","expertFr":"Le manuscrit affirme qu'en dimension réelle vingt-deux le déficit de points fixes hamiltoniens non dégénérés sous le nombre de Morse stable est non borné, via 80 plus 1968 m contre 80 plus 1952 m, soit au plus 127 sur 128. Une quadrique complexe de dimension trois a un difféomorphisme hamiltonien à trois points fixes, moins que les quatre points critiques de toute fonction lisse.","expertEn":"The manuscript asserts that in real dimension twenty-two the deficit of nondegenerate Hamiltonian fixed points below the stable Morse number is unbounded, via 80 plus 1968 m against 80 plus 1952 m, at most 127 over 128. A complex quadric threefold has a Hamiltonian diffeomorphism with three fixed points, fewer than the four critical points of every smooth function.","sparkFr":"L'intérêt est structural : le compte des points fixes hamiltoniens peut rester sous le nombre de Morse stable.","sparkEn":"The interest is structural: the count of Hamiltonian fixed points may stay below the stable Morse number."},{"id":"348","titleEn":"Nonnegative-curvature Einstein classification and an L2 topological gap","titleFr":"Classification d'Einstein à courbure sectionnelle non négative","claim":"Classifies closed connected Einstein four-manifolds with positive Einstein constant and nonnegative sectional curvature: up to scaling, their universal Riemannian covers are the round S4, Fubini–Study CP^2, or a product of equal round two-spheres. A closed simply connected nonnegatively curved four-manifold is diffeomorphic to one of these whenever the scale-invariant L2 norm of its trace-free Ricci curvature lies below a universal positive constant.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1915,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Zero-Plane Rigidity for Einstein Four-Manifolds","href":"preprints/Zero-Plane-Rigidity-for-Einstein-Four-Manifolds-October-4-2026/einstein-boundary.pdf"},{"title":"An L² Einstein Gap for Nonnegatively Curved Four-Manifolds","href":"preprints/An-L2-Einstein-Gap-for-Nonnegatively-Curved-Four-Manifolds-October-5-2026/einstein-gap.pdf"},{"title":"Positively curved Einstein four-manifolds","href":"preprints/Positively-curved-Einstein-four-manifolds-September-23-2026/paper.pdf"}],"plainFr":"Une variété d'Einstein a une courbure de Ricci proportionnelle à sa métrique. Le manuscrit affirme qu'en dimension quatre, à constante positive et courbure non négative, le revêtement universel est, à l'échelle près, la sphère, le plan projectif complexe, ou deux sphères rondes égales.","plainEn":"An Einstein manifold has Ricci curvature proportional to its metric. The manuscript asserts that in dimension four, with positive constant and nonnegative sectional curvature, the universal cover is, up to scale, the round sphere, complex projective plane, or a product of two equal round spheres.","expertFr":"Le manuscrit affirme que le revêtement universel d'une variété d'Einstein fermée connexe de dimension quatre, à constante positive et courbure sectionnelle non négative, est à l'échelle près la sphère ronde, Fubini–Study ou deux sphères égales. Si la norme L2 d'échelle du Ricci sans trace est sous une constante positive, le cas simplement connexe à courbure non négative est difféomorphe à l'un de ces modèles.","expertEn":"The manuscript asserts that a closed connected Einstein four-manifold of positive constant and nonnegative sectional curvature has universal cover, up to scale, the round sphere, Fubini–Study, or two equal round spheres. If the scale-invariant L2 norm of trace-free Ricci lies below a positive constant, the simply connected nonnegatively curved case is diffeomorphic to one of these models.","sparkFr":"L'intérêt est structural : en dimension quatre, ces hypothèses de courbure pourraient ne laisser que trois modèles.","sparkEn":"The interest is structural: in dimension four, these curvature assumptions may leave only three models."},{"id":"349","titleEn":"The Solomon–Yau least-volume conjecture","titleFr":"La conjecture de volume minimal de Solomon–Yau","claim":"Proves the Solomon–Yau least-volume conjecture for minimal hypersurfaces of round spheres. For every m ≥ 2, a closed connected minimal immersion into the unit sphere S^m+1 with non-totally-geodesic image has volume at least that of the smallest minimal Clifford product, counting covering multiplicity.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1978,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Solomon–Yau least-volume theorem","href":"preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/paper.pdf"}],"plainFr":"Une hypersurface minimale dans une sphère ronde ne diminue pas son volume au premier ordre. Le manuscrit affirme que, si elle n'est pas totalement géodésique, son volume est au moins celui du plus petit produit de Clifford minimal, en comptant les recouvrements.","plainEn":"A minimal hypersurface in a round sphere does not decrease its volume to first order. The manuscript asserts that if it is not totally geodesic, its volume is at least that of the smallest minimal Clifford product, counting coverings.","expertFr":"Le manuscrit affirme la conjecture de volume minimal de Solomon et Yau pour les hypersurfaces minimales des sphères rondes unités. Pour tout m au moins deux, une immersion minimale fermée connexe dans la sphère de dimension m plus un, d'image non totalement géodésique, a un volume de domaine au moins égal au plus petit produit de Clifford minimal, multiplicité comprise.","expertEn":"The manuscript asserts the Solomon–Yau least-volume conjecture for minimal hypersurfaces of unit round spheres. For every m at least two, a closed connected minimal immersion into the sphere of dimension m plus one, with non-totally-geodesic image, has domain volume at least that of the smallest minimal Clifford product, multiplicity included.","sparkFr":"L'intérêt est structural : le produit de Clifford pourrait réaliser le plus petit volume parmi ces hypersurfaces non géodésiques.","sparkEn":"The interest is structural: the Clifford product may realize the least volume among these nongeodesic hypersurfaces."},{"id":"350","titleEn":"Yau’s nodal bounds: surfaces and higher dimensions","titleFr":"Bornes nodales de Yau : surfaces et dimensions supérieures","claim":"Proves the sharp C λ upper bound for nodal length on every fixed smooth closed surface, completing Yau's conjecture there. The upper bound fails for fixed smooth metrics in dimensions three and four, including metrics on S3 arbitrarily close to round. In dimension five, nodal measure can grow faster than λ^1/2+ε_0 for some fixed ε_0 0, ruling out even arbitrarily small power losses.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1978,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Sharp nodal length on smooth surfaces","href":"preprints/Sharp-nodal-length-on-smooth-surfaces-September-23-2026/paper.pdf"},{"title":"Smooth counterexamples to Yau's nodal upper bound in dimensions three and four","href":"preprints/Smooth-counterexamples-to-Yaus-nodal-upper-bound-in-dimensions-three-and-four-September-23-2026/paper.pdf"},{"title":"Power-law violations of Yau's nodal upper bound","href":"preprints/Power-law-violations-of-Yaus-nodal-upper-bound-September-23-2026/paper.pdf"}],"plainFr":"L'ensemble nodal est le lieu où s'annule une vibration propre d'une variété. Le manuscrit affirme que, sur toute surface lisse fermée fixée, sa longueur obéit à la borne supérieure optimale de la conjecture de Yau, tandis que cette borne échoue pour certaines métriques lisses en dimensions trois, quatre et cinq.","plainEn":"The nodal set is the place where a proper vibration of a manifold vanishes. The manuscript asserts that, on every fixed closed smooth surface, its length obeys the sharp upper bound of Yau's conjecture, while that bound fails for some smooth metrics in dimensions three, four, and five.","expertFr":"Le manuscrit affirme que, sur une surface lisse fermée fixée, la longueur nodale d'une fonction propre non nulle est bornée comme l'écrit la conjecture de Yau, avec la borne inférieure connue. La borne supérieure échoue en dimensions trois et quatre, même près de la sphère ronde, et en dimension cinq la mesure nodale peut dépasser la puissance un demi plus un epsilon fixé.","expertEn":"The manuscript asserts that, on a fixed closed smooth surface, the nodal length of a nonzero eigenfunction is bounded as Yau's conjecture writes, together with the known lower bound. The upper bound fails in dimensions three and four, even near the round three-sphere, and in dimension five nodal measure can exceed the power one half plus a fixed epsilon.","sparkFr":"L'intérêt est structural : la borne nodale de Yau tiendrait sur les surfaces, mais déjà pas de la dimension trois à cinq.","sparkEn":"The interest is structural: Yau's nodal bound may hold on surfaces, yet already fail from dimension three to five."},{"id":"351","titleEn":"Scalar curvature and finite-time Ricci-flow singularities","titleFr":"Courbure scalaire et singularités en temps fini du flot de Ricci","claim":"Proves that a smooth Ricci flow on a closed four-manifold extends past any finite time at which scalar curvature remains uniformly bounded. A higher-dimensional counterexample has bounded scalar curvature but unbounded full curvature at its finite maximal time, disproving the unrestricted scalar-curvature extension conjecture.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A closed Ricci flow with bounded scalar curvature and finite-time curvature blowup","href":"preprints/A-closed-Ricci-flow-with-bounded-scalar-curvature-and-finite-time-curvature-blowup-September-24-2026/paper.pdf"},{"title":"Bounded scalar curvature and smooth extension of four-dimensional Ricci flow","href":"preprints/Bounded-scalar-curvature-and-smooth-extension-of-four-dimensional-Ricci-flow-September-24-2026/paper.pdf"},{"title":"Path selection and an elliptic inequality on degenerating Ricci-flat trees","href":"preprints/Path-selection-and-an-elliptic-inequality-on-degenerating-Ricci-flat-trees-September-24-2026/paper.pdf"}],"plainFr":"Le flot de Ricci déforme une métrique en suivant sa courbure. Le manuscrit affirme qu'en dimension quatre une courbure scalaire uniformément bornée permet de continuer le flot au-delà de tout temps fini, mais qu'en grande dimension la courbure totale peut exploser alors que la courbure scalaire reste bornée.","plainEn":"Ricci flow deforms a metric by following its curvature. The manuscript asserts that in dimension four a uniformly bounded scalar curvature lets the flow continue past any finite time, while in high dimension full curvature can blow up even though scalar curvature stays bounded.","expertFr":"Le manuscrit affirme qu'un flot de Ricci lisse sur une variété fermée de dimension quatre se prolonge si la courbure scalaire reste bornée en temps fini. En grande dimension, la courbure totale peut diverger en temps maximal fini malgré une courbure scalaire bornée, avec une explosion bilatérale d'exposants arbitrairement grands dans une dimension fixée.","expertEn":"The manuscript asserts that a smooth Ricci flow on a closed four-manifold extends past any finite time at which scalar curvature stays uniformly bounded. In high enough dimension, it asserts a flow with bounded scalar curvature whose full curvature diverges at a finite maximal time, and, in one fixed high dimension, a two-sided power-law blowup with arbitrarily large exponents.","sparkFr":"L'intérêt est structural : borner la seule courbure scalaire pourrait prolonger le flot en dimension quatre, mais pas en toute dimension.","sparkEn":"The interest is structural: bounding only scalar curvature may extend the flow in dimension four, but not in every dimension."},{"id":"352","titleEn":"A finite-time singularity of Calabi flow","titleFr":"Une singularité en temps fini du flot de Calabi","claim":"Disproves Chen's smooth long-time existence conjecture for Calabi flow by constructing a smooth U(10)-invariant Kähler metric on CP^10 whose flow develops a finite-time singularity. The metric lies in the Fubini–Study class, so the failure occurs even in a class containing a constant-scalar-curvature metric.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":1954,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"A finite-time singularity of Calabi flow on projective space","href":"preprints/A-finite-time-singularity-of-Calabi-flow-on-projective-space-September-24-2026/paper.pdf"}],"plainFr":"Le flot de Calabi déforme une métrique de Kähler pour en régulariser la courbure scalaire. Le manuscrit affirme qu'une métrique lisse, invariante par un groupe unitaire, sur l'espace projectif complexe de dimension dix et dans la classe de Fubini–Study, devient singulière en temps fini.","plainEn":"Calabi flow deforms a Kähler metric so as to regularize its scalar curvature. The manuscript asserts that a smooth metric, invariant under a unitary group, on ten-dimensional complex projective space and in the Fubini–Study class, becomes singular in finite time.","expertFr":"Le manuscrit réfute la conjecture d'existence lisse en temps long de Chen pour le flot de Calabi. Il affirme une métrique de Kähler lisse invariante par le groupe unitaire de dimension dix, dans la classe de Fubini–Study, dont le flot rend la courbure scalaire non bornée en temps fini, bien que la classe contienne une métrique à courbure scalaire constante.","expertEn":"The manuscript disproves Chen's smooth long-time existence conjecture for Calabi flow. It asserts a smooth Kähler metric invariant under the ten-dimensional unitary group, in the Fubini–Study class, whose flow makes scalar curvature unbounded in finite time, even though the class contains a constant-scalar-curvature metric.","sparkFr":"L'intérêt est structural : même une classe qui contient une métrique à courbure constante peut voir ce flot exploser.","sparkEn":"The interest is structural: even a class containing a constant-curvature metric may see this flow blow up."},{"id":"353","titleEn":"Affine Bernstein rigidity through dimension nine and a smooth dimension-ten counterexample","titleFr":"Rigidité de Bernstein affine jusqu'en dimension neuf","claim":"Proves that every smooth locally uniformly convex affine-maximal graph of dimension three through nine, complete for its induced Euclidean metric, is an elliptic paraboloid. A smooth entire nonquadratic example in dimension ten makes this range sharp. In dimensions three through nine, the paraboloid classification also holds for connected open locally uniformly convex affine-maximal hypersurfaces complete for the affine Berwald–Blaschke metric.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1916,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Smooth Nonquadratic Entire Affine Maximal Graph in Dimension Ten","href":"preprints/Smooth-Nonquadratic-Affine-Maximal-Graph-in-Dimension-Ten-October-5-2026/affine-maximal-dimension-ten.pdf"},{"title":"The affine Bernstein theorem in dimensions three through nine","href":"preprints/The-affine-Bernstein-theorem-in-dimensions-three-through-nine-September-24-2026/main.pdf"}],"plainFr":"Un graphe affine-maximal est une hypersurface convexe extrémale pour un volume affine. Le manuscrit affirme que, de la dimension trois à neuf, un tel graphe lisse et complet pour la distance euclidienne induite est un paraboloïde elliptique, tandis qu'un exemple entier lisse non quadratique existe en dimension dix.","plainEn":"An affine-maximal graph is a convex hypersurface extremal for an affine volume. The manuscript asserts that, from dimension three through nine, such a smooth graph complete for the induced Euclidean distance is an elliptic paraboloid, while a smooth entire nonquadratic example exists in dimension ten.","expertFr":"Le manuscrit affirme que tout graphe affine-maximal lisse, localement uniformément convexe, complet pour la métrique euclidienne et de dimension trois à neuf, est un paraboloïde elliptique, intervalle optimal par un exemple entier non quadratique en dimension dix. La même classification vaut pour les hypersurfaces ouvertes connexes complètes au sens de Berwald–Blaschke.","expertEn":"The manuscript asserts that every smooth locally uniformly convex affine-maximal graph of dimension three through nine, complete for the induced Euclidean metric, is an elliptic paraboloid, the range being sharp by a smooth entire nonquadratic graph in dimension ten. The same classification holds, in these dimensions, for connected open hypersurfaces complete in the sense of the affine Berwald–Blaschke metric.","sparkFr":"L'intérêt est structural : cette rigidité affine tiendrait jusqu'en dimension neuf et cesserait en dimension dix.","sparkEn":"The interest is structural: this affine rigidity may hold through dimension nine and fail in dimension ten."},{"id":"354","titleEn":"The isoperimetric profile of the cubic three-torus","titleFr":"Le profil isopérimétrique du tore cubique de dimension trois","claim":"Determines the isoperimetric profile of the unit cubic flat three-torus and classifies every finite-perimeter minimizer: balls, circular tubes around shortest closed geodesics, coordinate slabs, and their complements. The transition volumes are 4π/81 and 1/π, with exactly the adjacent two types minimizing at each transition.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1761,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Isoperimetric Conjecture for the Cubic Flat Three-Torus","href":"preprints/The-Isoperimetric-Conjecture-for-the-Cubic-Flat-Three-Torus-September-24-2026/article.pdf"}],"plainFr":"Sur un tore plat cubique, le profil isopérimétrique donne, pour chaque volume, la plus petite aire de bord. Le manuscrit affirme que les régions minimisantes sont des boules, des tubes autour des plus courtes boucles, des dalles parallèles aux faces, et leurs complémentaires, avec deux volumes de transition.","plainEn":"On a flat torus shaped like a cube, the isoperimetric profile gives, for each volume, the least possible boundary area. The manuscript asserts that the minimizing regions are balls, tubes around the shortest loops, slabs parallel to the faces, and their complements, with two transition volumes.","expertFr":"Le manuscrit affirme le profil isopérimétrique du tore plat cubique unité de dimension trois et la classification des minimisateurs de périmètre fini : boules, tubes circulaires autour des plus courtes géodésiques fermées, dalles de coordonnées et leurs complémentaires. Les volumes de transition sont quatre π sur 81 et un sur π, et exactement les deux types adjacents minimisent à chaque transition.","expertEn":"The manuscript asserts the isoperimetric profile of the unit cubic flat three-torus and the classification of finite-perimeter minimizers: balls, circular tubes about the shortest closed geodesics, coordinate slabs, and their complements. The transition volumes are four π over 81 and one over π, and exactly the two adjacent types minimize at each transition.","sparkFr":"L'intérêt est structural : sur ce tore, la forme minimisante pourrait n'avoir que trois types, selon le volume.","sparkEn":"The interest is structural: on this torus, the minimizing shape may have only three types, depending on volume."},{"id":"355","titleEn":"Unique tangent flows at the first surface singularity","titleFr":"Unicité du flot tangent à la première singularité de surface","claim":"Proves the first-singular-time case of tangent-flow uniqueness for smooth compact connected embedded surfaces without boundary in ℝ3. At every singular point, all fixed-center backward tangent flows agree as area measures at every negative time in the original ambient coordinates, without mean-convexity or a prescribed tangent model.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":null,"lean":false,"pdfs":[{"title":"Uniqueness of tangent flows at the first singular time of embedded surface mean-curvature flow","href":"preprints/Tangent-flow-uniqueness-2026-09-24/paper.pdf"}],"plainFr":"Le flot de courbure moyenne fait évoluer une surface selon la courbure de sa forme. Le manuscrit affirme que, pour une surface compacte lisse plongée sans bord dans l'espace usuel, tous les zooms arrière centrés en un point de la première singularité convergent vers le même modèle qui se contracte.","plainEn":"Mean-curvature flow evolves a surface according to the curvature of its shape. The manuscript asserts that, for a smooth compact embedded surface without boundary in ordinary space, all backward zooms centered at a point of the first singularity converge to the same shrinking model.","expertFr":"Le manuscrit affirme l'unicité du flot tangent au premier temps singulier du flot de courbure moyenne d'une surface compacte connexe lisse plongée sans bord dans l'espace de dimension trois. En chaque point singulier, les rééchelles à centre fixé convergent vers un unique flot auto-rétrécissant homothétique de multiplicité un, position et axes compris, sans convexité moyenne ni modèle prescrit.","expertEn":"The manuscript asserts tangent-flow uniqueness at the first singular time of mean-curvature flow for a smooth compact connected embedded surface without boundary in three-dimensional space. At each singular point, fixed-center rescalings converge to one multiplicity-one homothetic self-shrinking flow, including position and axes, with no mean convexity or prescribed model.","sparkFr":"L'intérêt est structural : à la première singularité, le zoom arrière pourrait être unique, position et axes compris.","sparkEn":"The interest is structural: at the first singularity, the backward zoom may be unique, including position and axes."},{"id":"356","titleEn":"Gigli’s characterization of Alexandrov curvature","titleFr":"La caractérisation de Gigli de la courbure d'Alexandrov","claim":"Proves Gigli's conjecture: in every integer dimension n ≥ 2, Alexandrov curvature at least κ is characterized by the full-support RCD ((n-1) ,n) condition with reference measure H^n and distributional sectional curvature at least κ in the original global test classes. The RCD condition is unreduced.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Gigli’s distributional curvature characterization of Alexandrov spaces","href":"preprints/Giglis-distributional-curvature-characterization-of-Alexandrov-spaces-September-24-2026/main.pdf"},{"title":"Weak Hessian bounds along every geodesic in RCD spaces","href":"preprints/Weak-Hessian-bounds-along-every-geodesic-in-RCD-spaces-September-24-2026/weak-hessian-geodesics.pdf"}],"plainFr":"Un espace d'Alexandrov compare sa courbure à celle de triangles modèles. Le manuscrit affirme qu'à partir de la dimension deux cette borne inférieure équivaut à une condition synthétique de courbure-dimension, avec la mesure de volume et une courbure sectionnelle distributionnelle.","plainEn":"An Alexandrov space is a distance space whose curvature is compared with that of model triangles. The manuscript asserts that from dimension two upward this lower bound is equivalent to a synthetic curvature-dimension condition, with the natural volume measure and a sectional curvature in the sense of distributions.","expertFr":"Le manuscrit affirme la conjecture de Gigli : pour n au moins deux, la courbure d'Alexandrov au moins κ équivaut à la condition RCD non réduite à support plein, de paramètres n moins un et n, pour la mesure de Hausdorff. La courbure sectionnelle distributionnelle vaut au moins κ dans les classes test globales d'origine, sur un espace complet séparable.","expertEn":"The manuscript asserts Gigli's conjecture for every integer n at least two and every real κ. A complete separable metric space is an n-dimensional Alexandrov space of curvature at least κ if and only if, for Hausdorff measure, it is an unreduced full-support RCD space with parameters (n minus one) and n, whose distributional sectional curvature is at least κ in the original global test classes.","sparkFr":"L'intérêt est structural : deux langages de courbure, synthétique et sectionnel, pourraient décrire les mêmes espaces.","sparkEn":"The interest is structural: two languages of curvature, synthetic and sectional, may describe the same spaces."},{"id":"357","titleEn":"Bi-Lipschitz coordinates at every regular RCD point","titleFr":"Coordonnées bi-lipschitziennes en tout point régulier RCD","claim":"Proves that every regular point of a noncollapsed RCD (K,n) space, for K ∈ ℝ and integer n ≥ 2, has an open neighborhood bi-Lipschitz to an open subset of ℝn. Regularity requires all pointed tangents to be Euclidean, the reference measure is exactly H^n, and the chart compares ambient distances with a point-dependent finite constant.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":false,"pdfs":[{"title":"Bi-Lipschitz Coordinates at Regular Points of Noncollapsed RCD Spaces","href":"preprints/Bi-Lipschitz-Coordinates-at-Regular-Points-of-Noncollapsed-RCD-Spaces-September-25-2026/paper.pdf"}],"plainFr":"Un espace à courbure synthétique peut avoir des points réguliers, où les zooms sont euclidiens. Le manuscrit affirme que, sans effondrement et dès la dimension deux, chacun a un voisinage comparable à un ouvert euclidien par des distances contrôlées des deux côtés.","plainEn":"A space of synthetic curvature can have regular points, where every zoom looks Euclidean. The manuscript asserts that, in the noncollapsed case and in dimension at least two, each such point has a neighborhood comparable to a Euclidean open set by distances controlled in both directions.","expertFr":"Le manuscrit affirme que tout point régulier d'un espace RCD non effondré de courbure K réelle et de dimension entière n au moins deux a un voisinage ouvert bi-lipschitzien à un ouvert de l'espace euclidien de dimension n. La régularité exige des tangents pointés euclidiens et la mesure de Hausdorff comme référence ; la constante est finie, et l'abrégé la fait dépendre seulement de n.","expertEn":"The manuscript asserts that every regular point of a noncollapsed RCD space of real curvature K and integer dimension n at least two has an open neighborhood bi-Lipschitz to an open set of n-dimensional Euclidean space. Regularity requires Euclidean pointed tangents and Hausdorff measure as reference; the constant is finite, and the abstract makes it depend only on n.","sparkFr":"L'intérêt est structural : aux points réguliers non effondrés, de vraies coordonnées bi-lipschitziennes pourraient exister.","sparkEn":"The interest is structural: at noncollapsed regular points, genuine bi-Lipschitz coordinates may exist."},{"id":"358","titleEn":"A three-manifold without conjugate points or nonpositive curvature","titleFr":"Une variété de dimension trois sans points conjugués ni courbure non positive","claim":"Constructs a closed connected orientable smooth three-manifold that admits a metric without conjugate points but no metric of nonpositive sectional curvature. This answers negatively, already in dimension three, whether the first metric-existence property implies the second.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1982,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"A Three-Manifold Without Conjugate Points and Without a Nonpositively Curved Metric","href":"preprints/A-Three-Manifold-Without-Conjugate-Points-and-Without-a-Nonpositively-Curved-Metric-September-24-2026/paper.pdf"}],"plainFr":"L'absence de points conjugués signifie que les géodésiques voisines ne se refocalisent pas. Le manuscrit affirme qu'une variété lisse fermée, connexe et orientable de dimension trois peut porter une métrique sans points conjugués et aucune métrique de courbure sectionnelle non positive.","plainEn":"Absence of conjugate points means that nearby geodesics do not refocus. The manuscript asserts that a closed connected orientable smooth three-dimensional manifold can carry a metric without conjugate points and no metric of nonpositive sectional curvature.","expertFr":"Le manuscrit affirme une variété lisse fermée, connexe et orientable de dimension trois qui admet une métrique riemannienne lisse sans points conjugués, mais aucune métrique riemannienne lisse de courbure sectionnelle non positive. Cela répond négativement, déjà en dimension trois, à l'implication entre ces deux propriétés d'existence.","expertEn":"The manuscript asserts a closed connected orientable smooth three-manifold that admits a smooth Riemannian metric without conjugate points, but no smooth Riemannian metric of nonpositive sectional curvature. This answers negatively, already in dimension three, whether the first existence property implies the second.","sparkFr":"L'intérêt est structural : l'absence de refocalisation peut ne pas donner de métrique à courbure non positive.","sparkEn":"The interest is structural: absence of refocusing may fail to yield a nonpositively curved metric."},{"id":"359","titleEn":"Negative Kähler curvature without bounded holomorphic coordinates","titleFr":"Courbure de Kähler négative sans coordonnées holomorphes bornées","claim":"Constructs a contractible domain in ℂ3 with a complete negatively pinched Kähler metric but no bounded holomorphic coordinates, disproving bounded-domain uniformization in this setting. A higher-dimensional example has sectional curvature at most −1 and only constant bounded holomorphic functions; its curvature is not bounded below.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1933,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A negatively pinched Kähler threefold without bounded holomorphic coordinates","href":"preprints/A-negatively-pinched-Kahler-threefold-without-bounded-holomorphic-coordinates-September-25-2026/paper.pdf"},{"title":"One-sided negative sectional curvature and the holomorphic Liouville property","href":"preprints/One-sided-negative-sectional-curvature-and-the-holomorphic-Liouville-property-September-25-2026/paper.pdf"}],"plainFr":"On demande si une métrique de Kähler complète, à courbure négative pincée, fait d'un domaine un domaine borné de l'espace complexe. Le manuscrit affirme qu'un domaine contractile de dimension complexe trois peut porter une telle métrique sans coordonnées holomorphes bornées.","plainEn":"One asks whether a complete Kähler metric of pinched negative curvature makes a domain into a bounded domain of complex space. The manuscript asserts that a contractible domain in complex dimension three can carry such a metric without bounded holomorphic coordinates.","expertFr":"Le manuscrit affirme un domaine contractile de dimension complexe trois, à métrique de Kähler complète pincée entre deux constantes négatives, sans carte holomorphe bornée de jacobien jamais nul, donc non biholomorphe à un domaine borné. Un exemple plus grand a une courbure au plus moins un, seulement des fonctions holomorphes bornées constantes, et aucune borne inférieure.","expertEn":"The manuscript asserts a contractible domain in complex dimension three, with a complete Kähler metric pinched between two negative constants and no bounded holomorphic chart of nonvanishing Jacobian, hence not a bounded domain. A higher-dimensional example has curvature at most minus one, only constant bounded holomorphic functions, and no lower bound.","sparkFr":"L'intérêt est structural : un pincement négatif de la courbure de Kähler peut ne pas uniformiser le domaine en domaine borné.","sparkEn":"The interest is structural: negative pinching of Kähler curvature may fail to uniformize the domain as a bounded domain."},{"id":"360","titleEn":"Weak MTW curvature gives convexity and regular optimal transport","titleFr":"Courbure de Ma–Trudinger–Wang faible et transport optimal régulier","claim":"On every closed connected Riemannian manifold of dimension at least two satisfying weak Ma–Trudinger–Wang curvature, all tangent injectivity domains are convex, resolving Villani’s conjecture in this setting. For squared-distance transport between measurable probability densities bounded above and away from zero, the optimal map and its inverse are Hölder continuous.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Global Support and Convex Injectivity Domains under Weak MTW","href":"preprints/Global-Support-and-Convex-Injectivity-Domains-under-Weak-MTW-September-25-2026/paper.pdf"},{"title":"Uniform Bi-Holder Transport from Weak MTW","href":"preprints/Uniform-Bi-Holder-Transport-from-Weak-MTW-September-25-2026/paper.pdf"}],"plainFr":"Le transport optimal déplace une masse au moindre coût du carré de la distance. Le manuscrit affirme que, sur une variété fermée de dimension au moins deux à courbure faible de Ma–Trudinger–Wang, les domaines d'injectivité sont convexes et l'application optimale entre densités bornées est höldérienne.","plainEn":"Optimal transport moves mass at least squared-distance cost. The manuscript asserts that, on a closed manifold of dimension at least two with weak Ma–Trudinger–Wang curvature, injectivity domains are convex and the optimal map between bounded densities is Hölder continuous.","expertFr":"Le manuscrit affirme la conjecture de Villani ici : la courbure faible de Ma–Trudinger–Wang, en dimension au moins deux sur une variété fermée connexe, rend convexes les domaines d'injectivité tangents, points conjugués admis. Pour le transport au carré entre densités bornées et minorées, l'application optimale et son inverse sont höldériens.","expertEn":"The manuscript asserts, in this setting, Villani's conjecture: weak Ma–Trudinger–Wang curvature on a closed connected Riemannian manifold of dimension at least two makes every tangent injectivity domain convex, conjugate cut points allowed. For squared-distance transport between measurable probability densities bounded above and below, the optimal map and its inverse are Hölder continuous.","sparkFr":"L'intérêt est structural : cette courbure faible pourrait rendre convexes les domaines d'injectivité et régulier le transport.","sparkEn":"The interest is structural: this weak curvature may make injectivity domains convex and transport regular."},{"id":"361","titleEn":"Failure of integer-degree harmonic dimension comparison","titleFr":"Échec de la comparaison de dimension pour les fonctions harmoniques","claim":"Disproves Yau's proposed Euclidean dimension bound for harmonic functions of integer growth on manifolds with nonnegative Ricci curvature. For every sufficiently large integer k, a complete smooth metric on ℝ3 has at least (k+2)^2 independent harmonic functions of growth at most k, exceeding the Euclidean count (k+1)^2. The metric may depend on k.","nature":"geometrie","domain":"formes","complexity":"frontiere","problemYear":1978,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A counterexample to integer-degree harmonic dimension comparison","href":"preprints/A-counterexample-to-integer-degree-harmonic-dimension-comparison-September-25-2026/paper.pdf"},{"title":"A Three-Dimensional Counterexample to Integer-Degree Harmonic Dimension Comparison","href":"preprints/A-Three-Dimensional-Counterexample-to-Integer-Degree-Harmonic-Dimension-Comparison-September-26-2026/paper.pdf"}],"plainFr":"Sur l'espace euclidien, les fonctions harmoniques à croissance polynomiale forment un espace de dimension connue. Le manuscrit affirme que, pour tout grand degré entier, une métrique lisse complète de courbure de Ricci non négative sur l'espace de dimension trois peut en contenir strictement davantage.","plainEn":"On Euclidean space, harmonic functions of polynomial growth form a space of known dimension. The manuscript asserts that, for every large integer degree, a complete smooth metric of nonnegative Ricci curvature on three-dimensional space can contain strictly more of them.","expertFr":"Le manuscrit affirme la réfutation de la borne euclidienne de Yau pour les fonctions harmoniques de croissance entière à courbure de Ricci non négative. Pour tout grand k, une métrique complète en dimension trois a au moins (k+2) au carré fonctions de croissance au plus k, contre (k+1) au carré ; en dimension paire au moins huit, l'exemple a des cônes tangents non uniques.","expertEn":"The manuscript asserts the failure of Yau's Euclidean bound for harmonic functions of integer growth under nonnegative Ricci curvature. For every large k, a complete metric in dimension three has at least (k+2) squared functions of growth at most k, against (k+1) squared; in even dimension at least eight, the example has nonunique tangent cones.","sparkFr":"L'intérêt est structural : la courbure de Ricci non négative peut ne pas limiter ces fonctions au compte euclidien.","sparkEn":"The interest is structural: nonnegative Ricci curvature may fail to limit these functions to the Euclidean count."},{"id":"362","titleEn":"Global smoothness for relativistic Vlasov–Maxwell","titleFr":"Régularité globale pour Vlasov–Maxwell relativiste","claim":"Proves large-data global existence and uniqueness for the three-dimensional, one-species relativistic Vlasov–Maxwell system. Smooth admissible initial data may be arbitrary provided the particle density is compactly supported and the electromagnetic fields have finite energy and bounded derivatives of every order; the solution remains smooth on every finite time interval.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":1938,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Global classical solutions of the three-dimensional relativistic Vlasov–Maxwell system","href":"preprints/Global-classical-solutions-of-the-three-dimensional-relativistic-Vlasov-Maxwell-system-September-23-2026/paper.pdf"}],"plainFr":"Le système de Vlasov–Maxwell relativiste couple des particules chargées à un champ électromagnétique. Le manuscrit affirme qu'en dimension trois, pour une seule espèce, des données lisses admissibles arbitraires, à densité compacte et champs d'énergie finie, donnent une solution lisse unique sur tout temps fini.","plainEn":"The relativistic Vlasov–Maxwell system couples charged particles to an electromagnetic field. The manuscript asserts that in three dimensions, for one species, arbitrary smooth admissible data, with compact density and finite-energy fields, yield a unique solution that stays smooth for all finite time.","expertFr":"Le manuscrit affirme l'existence et l'unicité globales à grandes données pour le système de Vlasov–Maxwell relativiste tridimensionnel à une espèce. Les données lisses admissibles sont arbitraires si la densité de particules est à support compact et si les champs ont une énergie finie et des dérivées bornées de tout ordre ; la solution reste lisse sur tout intervalle fini, sans restriction de taille ni de symétrie.","expertEn":"The manuscript asserts large-data global existence and uniqueness for the three-dimensional one-species relativistic Vlasov–Maxwell system. Smooth admissible data may be arbitrary if the particle density is compactly supported and the fields have finite energy and bounded derivatives of every order; the solution stays smooth on every finite interval, with no size or symmetry restriction.","sparkFr":"L'intérêt reste intérieur aux équations : ces données lisses pourraient ne jamais former de singularité en temps fini.","sparkEn":"The interest stays inside the equations: these smooth data may never form a singularity in finite time."},{"id":"363","titleEn":"Nonuniqueness with local conservation for the hard-sphere Boltzmann equation","titleFr":"Non-unicité avec conservation locale pour Boltzmann des sphères dures","claim":"Constructs two distinct global entropy solutions of the three-dimensional periodic hard-sphere Boltzmann equation from the same nonnegative initial density, with bounded velocity support and finite mass, energy and absolute entropy. Both are strongly continuous in L1 and satisfy exact local conservation of mass, momentum and kinetic energy.","nature":"dynamique","domain":"dynamique","complexity":"avance","problemYear":1872,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Nonuniqueness with local conservation for the hard-sphere Boltzmann equation","href":"preprints/Nonuniqueness-with-local-conservation-for-the-hard-sphere-Boltzmann-equation-October-5-2026/paper.pdf"},{"title":"Nonuniqueness for the periodic hard-sphere Boltzmann equation","href":"preprints/Nonuniqueness-for-the-periodic-hard-sphere-Boltzmann-equation-September-23-2026/paper.pdf"}],"plainFr":"L'équation de Boltzmann des sphères dures décrit un gaz de particules qui se cognent, ici sur un tore. Le manuscrit affirme qu'une même densité initiale non négative peut donner deux solutions d'entropie globales distinctes, continues et conservant exactement masse, impulsion et énergie cinétique.","plainEn":"The hard-sphere Boltzmann equation describes a gas of particles that collide, here on a torus. The manuscript asserts that the same nonnegative initial density can yield two distinct global entropy solutions, continuous and exactly conserving mass, momentum, and kinetic energy.","expertFr":"Le manuscrit affirme deux solutions d'entropie globales distinctes de l'équation de Boltzmann périodique tridimensionnelle des sphères dures, issues d'une même densité non négative à support en vitesse borné et à masse, énergie et entropie absolue finies. Elles sont fortement continues dans L1 et satisfont la conservation locale exacte de la masse, de l'impulsion et de l'énergie cinétique.","expertEn":"The manuscript asserts two distinct global entropy solutions of the three-dimensional periodic hard-sphere Boltzmann equation, from one nonnegative density of bounded velocity support and finite mass, energy, and absolute entropy. They are strongly continuous in L1 and satisfy exact local conservation of mass, momentum, and kinetic energy.","sparkFr":"L'intérêt est structural : même avec les conservations locales, l'entropie peut ne pas choisir une seule évolution.","sparkEn":"The interest is structural: even with local conservation, entropy may fail to select a single evolution."},{"id":"364","titleEn":"Kinetic limits and fluctuations over the Boltzmann lifespan","titleFr":"Limites cinétiques sur la durée de vie de Boltzmann","claim":"Derives the nonlinear Boltzmann equation from three-dimensional grand-canonical Newtonian gases throughout every regular kinetic interval with uniform Gaussian decay. Stable finite-range radial potentials may have attractive wells and a singular repulsive core; initial pair exclusion and spatially summable Gaussian density and gradient bounds are assumed. A companion gives finite-dimensional hard-sphere Gaussian fluctuations, centered at the exact microscopic expectation and governed by the linear fluctuating Boltz","nature":"geometrie-algebrique","domain":"hasard","complexity":"frontiere","problemYear":1872,"yearKnown":true,"manuscriptDate":"2026-09-23","lean":false,"pdfs":[{"title":"The Boltzmann–Grad limit for stable radial potentials on regular kinetic intervals","href":"preprints/The-Boltzmann-Grad-limit-for-stable-radial-potentials-on-regular-kinetic-intervals-September-23-2026/paper.pdf"},{"title":"Hard-sphere fluctuations on the regular Boltzmann lifespan","href":"preprints/Hard-sphere-fluctuations-on-the-regular-Boltzmann-lifespan-September-23-2026/paper.pdf"}],"plainFr":"On cherche à passer d'un gaz newtonien à l'équation de Boltzmann, description statistique des chocs. Le manuscrit affirme que cela vaut sur tout intervalle cinétique régulier à décroissance gaussienne, pour des forces stables pouvant attirer, avec un compagnon sur les fluctuations de sphères dures.","plainEn":"One seeks to pass from a Newtonian gas to the Boltzmann equation, a statistical account of collisions. The manuscript asserts that this holds on every regular kinetic interval with Gaussian decay, for stable forces that may attract, with a companion on hard-sphere fluctuations.","expertFr":"Le manuscrit affirme la dérivation du Boltzmann non linéaire depuis un gaz newtonien grand-canonique à exclusion de paires, sur tout intervalle à borne gaussienne uniforme. Les potentiels stables à portée finie peuvent attirer et avoir un cœur singulier, et un compagnon donne des fluctuations gaussiennes de sphères dures gouvernées par le Boltzmann linéaire fluctuant.","expertEn":"The manuscript asserts derivation of nonlinear Boltzmann from a grand-canonical Newtonian gas with pair exclusion, on every interval with a uniform Gaussian bound. Stable finite-range potentials may attract and have a singular core, and a companion gives hard-sphere Gaussian fluctuations governed by the linear fluctuating Boltzmann equation.","sparkFr":"L'intérêt est structural : le passage du microscopique au cinétique pourrait tenir sur toute la durée de vie régulière.","sparkEn":"The interest is structural: the passage from microscopic motion to kinetics may hold throughout the regular lifespan."},{"id":"365","titleEn":"Joint metric and connection recovery from one boundary patch","titleFr":"Métrique et connexion déterminées par un seul morceau de bord","claim":"Zero-frequency measurements on any nonempty open boundary patch determine a smooth metric and smooth unitary connection on a trivial Hermitian rank-two bundle over a compact connected manifold of dimension at least three, up to diffeomorphism and gauge fixed on that patch. Inputs and observations use the same patch. In contrast, distinct uniformly positive bounded measurable scalar conductivities on a three-dimensional ball can have identical full-boundary data.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1956,"yearKnown":false,"manuscriptDate":"2026-09-23","lean":true,"pdfs":[{"title":"Determination of a metric and a unitary connection from one boundary patch","href":"preprints/Determination-of-a-metric-and-a-unitary-connection-from-one-boundary-patch-October-5-2026/paper.pdf"},{"title":"Smooth anisotropic uniqueness in the Calderón problem from one boundary patch","href":"preprints/Smooth-Anisotropic-Uniqueness-in-the-Calderon-Problem-from-One-Boundary-Patch-September-24-2026/paper.pdf"},{"title":"Nonuniqueness for bounded measurable scalar conductivities in three dimensions","href":"preprints/Nonuniqueness-for-Bounded-Measurable-Scalar-Conductivities-in-Three-Dimensions-September-23-2026/paper.pdf"}],"plainFr":"Des mesures au bord, à fréquence nulle, enregistrent la réponse sur une partie de la frontière. Le manuscrit affirme qu'en dimension au moins trois un morceau ouvert détermine une métrique lisse et une connexion unitaire, à déformation près, alors que des conductivités distinctes peuvent coïncider.","plainEn":"Zero-frequency boundary measurements record the response on part of the boundary. The manuscript asserts that in dimension at least three one open patch determines a smooth metric and a unitary connection, up to deformation, while distinct conductivities can agree.","expertFr":"Le manuscrit affirme que des mesures à fréquence nulle sur tout ouvert non vide du bord déterminent, dès la dimension trois, une métrique lisse et une connexion unitaire de rang deux, à difféomorphisme et jauge fixés sur ce morceau. Des conductivités scalaires distinctes, positives et bornées, sur une boule de dimension trois peuvent partager tout le bord.","expertEn":"The manuscript asserts that zero-frequency data on any nonempty open boundary patch determine, from dimension three, a smooth metric and a rank-two unitary connection, up to diffeomorphism and gauge fixed on that patch. Distinct positive bounded scalar conductivities on a three-dimensional ball can share the whole boundary data.","sparkFr":"L'intérêt est structural : un seul morceau de bord pourrait fixer métrique et connexion, sans rendre la conductivité scalaire aussi rigide.","sparkEn":"The interest is structural: one boundary patch may fix metric and connection, without making scalar conductivity equally rigid."},{"id":"366","titleEn":"The planar Mumford–Shah regularity conjecture and local weak-L4 gradient bounds","titleFr":"Régularité intérieure des minimiseurs plans de Mumford–Shah","claim":"Resolves the interior regularity conjecture for reduced absolute planar Mumford–Shah minimizers with bounded fidelity data. Locally, the closed discontinuity set is a C^1,α arc, a regular crack tip, or three arcs meeting at 120^; only finitely many global connected components meet any compact interior region.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Interior regularity of planar Mumford–Shah minimizers","href":"preprints/Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026/Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026.pdf"}],"plainFr":"Un minimiseur de Mumford–Shah équilibre, dans le plan, un écart aux données et le coût d'un ensemble de sauts. Le manuscrit affirme qu'en intérieur, pour des données bornées, cet ensemble est localement un arc régulier, une pointe de fissure, ou trois arcs qui se rencontrent à cent vingt degrés.","plainEn":"A Mumford–Shah minimizer balances, in the plane, a mismatch with the data and the cost of a jump set. The manuscript asserts that in the interior, for bounded data, this set is locally a regular arc, a crack tip, or three arcs meeting at one hundred twenty degrees.","expertFr":"Le manuscrit affirme la régularité intérieure des minimiseurs absolus réduits plans de Mumford–Shah à données de fidélité bornées. Tout point intérieur de l'ensemble de discontinuité fermé a un voisinage qui est un arc de classe C un alpha, une pointe de fissure, ou trois arcs se rencontrant à cent vingt degrés, et seul un nombre fini de composantes globales rencontre toute région intérieure compacte.","expertEn":"The manuscript asserts the interior regularity of reduced absolute planar Mumford–Shah minimizers with bounded fidelity data. Every interior point of the closed discontinuity set has a neighborhood that is a C one alpha arc, a crack tip, or three arcs meeting at one hundred twenty degrees, and only finitely many global components meet any compact interior region.","sparkFr":"L'intérêt est structural : les sauts d'un tel minimiseur plan ne pourraient prendre que trois formes locales.","sparkEn":"The interest is structural: the jumps of such a planar minimizer might take only three local shapes."},{"id":"367","titleEn":"The critical dimension for the one-phase Bernoulli problem","titleFr":"La dimension critique du problème de Bernoulli à une phase","claim":"Establishes seven as the first dimension admitting a nonflat, one-homogeneous global minimizer of the one-phase Bernoulli energy. Consequently, minimizing free boundaries are smooth through dimension six, and their singular sets have dimension at most n-7 in higher dimensions.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The critical dimension for one-phase Bernoulli minimizers","href":"preprints/The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026/The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026.pdf"}],"plainFr":"Le problème de Bernoulli à une phase cherche des régions qui minimisent une énergie de type membrane, avec un bord libre. Le manuscrit affirme que sept est la première dimension où apparaît un minimiseur global homogène non plat, de sorte que ce bord est lisse jusqu'en dimension six.","plainEn":"The one-phase Bernoulli problem seeks regions that minimize a membrane-type energy, with a free boundary. The manuscript asserts that seven is the first dimension with a nonflat homogeneous global minimizer, so this boundary is smooth through dimension six.","expertFr":"Le manuscrit affirme que sept est la dimension critique du problème de Bernoulli à une phase : tout minimiseur global homogène de degré un, non nul, est plat jusqu'en dimension six, et un exemple non plat existe en sept. Les bords libres sont donc lisses jusqu'en dimension six, puis l'ensemble singulier a une dimension au plus n moins sept, borne optimale.","expertEn":"The manuscript asserts that seven is the critical dimension of the one-phase Bernoulli problem: every nonzero one-homogeneous global minimizer is flat through dimension six, and a nonflat example exists in dimension seven. Minimizing free boundaries are therefore smooth through dimension six, and in dimension n at least seven their singular set has Hausdorff dimension at most n minus seven, a sharp bound.","sparkFr":"L'intérêt est structural : la première singularité homogène de ce bord libre apparaîtrait exactement en dimension sept.","sparkEn":"The interest is structural: the first homogeneous singularity of this free boundary would appear exactly in dimension seven."},{"id":"368","titleEn":"The three-dimensional Ball–Evans approximation problem","titleFr":"Le problème d'approximation de Ball–Evans en dimension trois","claim":"Resolves the three-dimensional Ball–Evans approximation problem: every W^1,p homeomorphism between arbitrary bounded domains in ℝ3, for 1≤ p ∞, is a strong W^1,p limit of smooth diffeomorphisms onto the same target.","nature":"informatique","domain":"calcul","complexity":"frontiere","problemYear":1956,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":false,"pdfs":[{"title":"Strong diffeomorphic approximation in three dimensions for 1≤p≤2","href":"preprints/Strong-diffeomorphic-approximation-in-three-dimensions-for-1-le-p-le-2-September-24-2026/main.pdf"},{"title":"Strong diffeomorphic approximation in three dimensions for p>2","href":"preprints/Strong-diffeomorphic-approximation-in-three-dimensions-for-p-gt-2-September-24-2026/main.pdf"}],"plainFr":"Un homéomorphisme entre domaines est une déformation continue inversible, pas forcément lisse. Le manuscrit affirme qu'en dimension trois, dans les classes d'énergie indiquées, tout tel homéomorphisme entre domaines bornés est limite forte de déformations lisses inversibles sur la même cible.","plainEn":"A homeomorphism between domains is a continuous invertible deformation, not necessarily smooth. The manuscript asserts that in three dimensions, in the stated energy classes, every such homeomorphism between bounded domains is a strong limit of smooth invertible deformations onto the same target.","expertFr":"Le manuscrit affirme que tout homéomorphisme de classe de Sobolev W un p entre domaines bornés de l'espace de dimension trois est limite forte de difféomorphismes lisses sur la même cible, pour les exposants du texte, de un jusqu'à l'infini. L'abrégé établit en détail l'intervalle de un à deux.","expertEn":"The manuscript asserts that every Sobolev W one p homeomorphism between bounded domains in three-dimensional space is a strong limit of smooth diffeomorphisms onto the same target, for the exponents in the text, from one through infinity. The abstract establishes in detail the range from one to two.","sparkFr":"L'intérêt est structural : en dimension trois, les déformations inversibles d'énergie finie pourraient s'approcher par des déformations lisses.","sparkEn":"The interest is structural: in three dimensions, invertible finite-energy deformations may be approachable by smooth ones."},{"id":"369","titleEn":"The hot spots conjecture for simply connected planar domains","titleFr":"La conjecture des points chauds pour les domaines plans simplement connexes","claim":"Proves a strict form of Burdzy's simply connected hot spots conjecture. On every smooth bounded simply connected planar domain, each nonzero eigenfunction for the first positive Neumann eigenvalue has no interior critical point, so all global extrema lie on the boundary. Eigenvalue multiplicity is allowed.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Strict hot spots and absence of interior critical points on smooth simply connected planar domains","href":"preprints/Strict-hot-spots-and-absence-of-interior-critical-points-on-smooth-simply-connected-planar-domains-September-24-2026/main.pdf"}],"plainFr":"La première vibration de Neumann d'un domaine plan est un mode sans flux à travers le bord. Le manuscrit affirme que, sur tout domaine plan lisse borné et simplement connexe, une fonction propre non nulle de cette valeur propre n'a aucun point critique intérieur, donc ses extrema sont au bord.","plainEn":"The first Neumann vibration of a planar domain is a mode with no flux through the boundary. The manuscript asserts that, on every smooth bounded simply connected planar domain, a nonzero eigenfunction for this eigenvalue has no interior critical point, so its extrema lie on the boundary.","expertFr":"Le manuscrit affirme une forme stricte de la conjecture des points chauds de Burdzy pour les domaines plans lisses bornés simplement connexes. Toute fonction propre non nulle de la première valeur propre de Neumann positive a un gradient intérieur non nul, même si la valeur propre est multiple, donc tous ses extrema globaux sont au bord.","expertEn":"The manuscript asserts a strict form of Burdzy's hot spots conjecture for smooth bounded simply connected planar domains. Every nonzero eigenfunction for the first positive Neumann eigenvalue has nonvanishing interior gradient, even if the eigenvalue is multiple, so all its global extrema lie on the boundary.","sparkFr":"L'intérêt est structural : sur un domaine plan simplement connexe, les extrema de ce premier mode seraient toujours au bord.","sparkEn":"The interest is structural: on a simply connected planar domain, the extrema of this first mode would always lie on the boundary."},{"id":"370","titleEn":"The Lane–Emden and Hénon–Lane–Emden conjectures","titleFr":"Les conjectures de Lane–Emden et de Hénon–Lane–Emden","claim":"Resolves the subcritical Lane–Emden conjecture and its weighted Hénon extension. For n ≥ 2, p,q 0 and real A, B, the system - u=|x|^A v^p, - v=|x|^B u^q has no positive entire solution when (n+A)/(p+1)+(n+B)/(q+1) n-2, with solutions continuous at the origin and classical elsewhere. No symmetry or growth assumption is needed. Known radial existence gives the exact existence criterion for n ≥ 3 and A,B -2.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"The Subcritical Hénon–Lane–Emden Conjecture","href":"preprints/The-Subcritical-Henon-Lane-Emden-Conjecture-September-24-2026/paper.pdf"}],"plainFr":"Le système de Lane–Emden couple deux fonctions positives par des puissances, avec des poids éventuels. Le manuscrit affirme qu'aucune solution entière positive n'existe dans le régime sous-critique, sans symétrie, et que l'existence radiale connue rend le critère exact pour certains poids.","plainEn":"The Lane–Emden system couples two positive functions by powers, with possible weights. The manuscript asserts that no positive entire solution exists in the subcritical regime, without symmetry, and that known radial existence makes the criterion exact for some weights.","expertFr":"Le manuscrit affirme l'absence de solution entière strictement positive du système de Hénon–Lane–Emden sous-critique, dès la dimension deux, quand les quotients de poids rencontrent l'inégalité écrite avec n moins deux. Pour n au moins trois et des poids au moins moins deux au sens du texte, Bidaut-Véron et Giacomini rendent le critère exact, donc la conjecture C de Phan.","expertEn":"The manuscript asserts no strictly positive entire solution of the subcritical Hénon–Lane–Emden system, from dimension two, when the weight quotients meet the stated inequality with n minus two. For n at least three and weights at least minus two as written, Bidaut-Véron and Giacomini make the criterion exact, hence Phan's Conjecture C.","sparkFr":"L'intérêt est structural : le seuil sous-critique pourrait décider seul l'existence de solutions entières positives.","sparkEn":"The interest is structural: the subcritical threshold may by itself decide existence of positive entire solutions."},{"id":"371","titleEn":"Stable blowup for the defocusing Schrödinger equation","titleFr":"Explosion stable pour l'équation de Schrödinger défocalisante","claim":"For a sufficiently large odd nonlinearity power, constructs a nonempty open set of initial data in H^k( T^12), with k > 8, whose solutions of the scalar defocusing nonlinear Schrödinger equation blow up in finite time. Thus finite-time blowup is stable under Sobolev perturbations in this supercritical regime.","nature":"analyse","domain":"hasard","complexity":"frontiere","problemYear":1926,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Stable self-similar blowup for a supercritical defocusing Schrödinger equation on the torus","href":"preprints/Stable-Self-Similar-Blowup-for-a-Supercritical-Defocusing-Schrodinger-Equation-on-the-Torus-September-24-2026/paper.pdf"}],"plainFr":"L'équation de Schrödinger non linéaire défocalisante fait évoluer une onde complexe. Le manuscrit affirme que, sur un tore de dimension douze et pour une puissance impaire assez grande, un ouvert de données très régulières explose en temps fini, et que cette explosion résiste à de petites perturbations.","plainEn":"The defocusing nonlinear Schrödinger equation evolves a complex wave. The manuscript asserts that, on a twelve-dimensional torus and for a large enough odd power, an open set of highly regular data blows up in finite time, and that this blowup survives small perturbations.","expertFr":"Le manuscrit affirme, pour une grande puissance impaire, un ouvert de données de Sobolev d'ordre supérieur à huit sur le tore de dimension douze, dont les solutions défocalisantes explosent en temps fini de façon auto-semblable. Cette explosion est stable en Sobolev, et des données de Fourier gaussiennes très régulières peuvent exploser avec probabilité positive.","expertEn":"The manuscript asserts, for a large odd power, an open set of Sobolev data of order above eight on the twelve-torus, whose defocusing solutions blow up in finite time in a self-similar way. The blowup is Sobolev-stable, and highly regular Gaussian Fourier data can blow up with positive probability.","sparkFr":"L'intérêt est structural : même un signe défocalisant peut laisser l'explosion stable sur un tore de dimension douze.","sparkEn":"The interest is structural: even a defocusing sign may leave blowup stable on a twelve-dimensional torus."},{"id":"372","titleEn":"Global uniqueness in smooth isotropic elasticity","titleFr":"Unicité globale en élasticité isotrope lisse","claim":"Proves that full static boundary displacement-to-traction data determine both smooth real Lamé moduli on every bounded connected smooth domain in ℝ3, provided μ > 0 and 3λ+2μ 0 on the closure. Neither analyticity, proximity to constant coefficients nor prior knowledge near the boundary is required.","nature":"geometrie-algebrique","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-24","lean":true,"pdfs":[{"title":"Global Uniqueness for the Smooth Isotropic Elasticity Inverse Problem","href":"preprints/Global-Uniqueness-for-the-Smooth-Isotropic-Elasticity-Inverse-Problem-September-24-2026/article.pdf"}],"plainFr":"En élasticité isotrope, deux coefficients disent comment un solide répond à une déformation. Le manuscrit affirme que, sur tout domaine lisse borné de dimension trois, la correspondance statique déplacement-traction au bord détermine ces coefficients, sous les positivités indiquées.","plainEn":"In isotropic elasticity, two coefficients say how a solid responds to a deformation. The manuscript asserts that, on every bounded smooth three-dimensional domain, the static displacement-to-traction map determines these coefficients under the stated positivity assumptions.","expertFr":"Le manuscrit affirme que la correspondance statique complète déplacement-traction détermine les deux modules de Lamé réels lisses sur tout domaine lisse borné connexe de l'espace de dimension trois, dès que mu est positif et que trois lambda plus deux mu est positif sur l'adhérence. Ni l'analyticité, ni la proximité de coefficients constants, ni une connaissance préalable près du bord ne sont requises.","expertEn":"The manuscript asserts that the full static displacement-to-traction map determines both smooth real Lamé moduli on every bounded connected smooth domain in three-dimensional space, once mu is positive and three lambda plus two mu is positive on the closure. Neither analyticity, nor proximity to constant coefficients, nor prior knowledge near the boundary is required.","sparkFr":"L'intérêt est structural : la seule correspondance statique au bord pourrait fixer les deux coefficients élastiques lisses.","sparkEn":"The interest is structural: the static boundary map alone may determine both smooth elastic coefficients."},{"id":"373","titleEn":"Nonattainment of the three-marginal Coulomb Monge problem","titleFr":"Non-atteinte du problème de Monge coulombien à trois marges","claim":"An optimal three-particle Coulomb configuration need not be a deterministic function of the first particle, even for smooth identical spatial densities. The Monge and Kantorovich infima agree, but the Monge infimum is not attained. The same phenomenon occurs for every inverse-power Riesz exponent in each dimension at least two, with a suitable density in each case.","nature":"physique-math","domain":"physique","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"A counterexample to the Monge ansatz for the three-marginal Coulomb cost","href":"preprints/A-counterexample-to-the-Monge-ansatz-for-the-three-marginal-Coulomb-cost-September-25-2026/paper.pdf"}],"plainFr":"Le problème de Coulomb à trois particules apparie trois masses en minimisant une répulsion. Le manuscrit affirme que, même pour des densités lisses identiques, un optimum peut ne pas être une fonction de la première, bien que Monge et Kantorovich aient le même infimum.","plainEn":"The three-particle Coulomb problem pairs three mass distributions while minimizing a repulsion. The manuscript asserts that, even for identical smooth densities, an optimum need not be a deterministic function of the first particle, although the Monge and Kantorovich costs have the same infimum.","expertFr":"Le manuscrit affirme qu'une densité lisse à support compact sur l'espace de dimension trois rend le minimum coulombien à trois marges non atteint par aucun couple d'applications boréliennes préservant la mesure, alors que les infimums de Monge et de Kantorovich coïncident. Le même phénomène vaut pour tout exposant de Riesz en puissance inverse, en toute dimension au moins deux, avec une densité adaptée.","expertEn":"The manuscript asserts that a smooth compactly supported density on three-dimensional space makes the three-marginal Coulomb minimum unattained by any pair of measure-preserving Borel maps, while the Monge and Kantorovich infima agree. The same phenomenon holds for every inverse-power Riesz exponent, in every dimension at least two, with a suitable density.","sparkFr":"L'intérêt est structural : l'infimum de couplage peut être approché par des applications sans jamais être atteint.","sparkEn":"The interest is structural: the coupling infimum may be approached by maps without ever being attained."},{"id":"374","titleEn":"Sharp one-third stability of Brenier maps","titleFr":"Stabilité d'ordre un tiers des applications de Brenier","claim":"For uniform source measure ρ on a compact convex body with interior in dimension at least two, quadratic optimal transport maps satisfy \\|T_μ-T_ν\\|_L^2(ρ)≤ C W_2(μ,ν)^1/3 uniformly over targets in a fixed compact set. The exponent is sharp, even for three-atom targets, disproving Letrouit's conjectured square-root bound.","nature":"geometrie","domain":"formes","complexity":"avance","problemYear":1887,"yearKnown":false,"manuscriptDate":"2026-09-25","lean":true,"pdfs":[{"title":"Sharp One-Third Stability of Brenier Maps","href":"preprints/Sharp-One-Third-Stability-of-Brenier-Maps-September-25-2026/article.pdf"}],"plainFr":"Une application de transport quadratique envoie une mesure source vers une cible au moindre coût. Le manuscrit affirme que, pour la mesure uniforme sur un convexe compact, elle varie au plus comme la racine cubique de l'écart des cibles, et que cet exposant un tiers est optimal.","plainEn":"A quadratic optimal transport map moves a source measure to a target at least squared-distance cost. The manuscript asserts that, for the uniform measure on a compact convex body, these maps vary at most like the cube root of the targets' discrepancy, and that the one-third exponent is sharp.","expertFr":"Le manuscrit affirme que, pour la mesure uniforme sur un convexe compact d'intérieur, en dimension au moins deux, le transport quadratique est d'ordre un tiers en norme L2 pour la distance de Wasserstein deux, uniformément sur un compact. L'exposant est optimal même pour trois atomes, ce qui réfute la racine carrée conjecturée par Letrouit.","expertEn":"The manuscript asserts that, for the uniform measure on a compact convex body with interior in dimension at least two, quadratic transport maps are of order one third in L2 norm with respect to the targets' two-Wasserstein distance, with a constant uniform on a fixed compact set. The exponent is sharp, even for three-atom targets, which disproves the square-root bound conjectured by Letrouit.","sparkFr":"L'intérêt est structural : la stabilité de ces applications de transport serait d'ordre un tiers, et pas mieux.","sparkEn":"The interest is structural: the stability of these transport maps would be of order one third, and no better."},{"id":"375","titleEn":"De Giorgi's conjecture in dimension eight","titleFr":"La conjecture de De Giorgi en dimension huit","claim":"Proves De Giorgi's conjecture at its sharp dimension-eight endpoint: every entire C2 solution u: R^8→(-1,1) of u=u^3-u that is strictly increasing in one direction depends on only one linear coordinate. A stronger theorem classifies all stable entire solutions v: R^7→[-1,1] as constant wells or planar transitions, without an energy-growth assumption.","nature":"algebre","domain":"structures","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-09-26","lean":false,"pdfs":[{"title":"A positive resolution of De Giorgi's conjecture in dimension eight","href":"preprints/De-Giorgis-conjecture-in-dimension-eight-September-26-2026/article.pdf"}],"plainFr":"L'équation de De Giorgi décrit des transitions entre deux états. Le manuscrit affirme qu'en dimension huit une solution entière croissante dans une direction ne dépend que d'une coordonnée, et qu'en dimension sept les solutions stables sont constantes ou planes.","plainEn":"The De Giorgi equation describes transitions between two states. The manuscript asserts that in dimension eight an entire solution increasing in one direction depends on one coordinate only, and that in dimension seven the stable solutions are constant or planar.","expertFr":"Le manuscrit affirme qu'en dimension huit toute solution entière de classe C deux, à valeurs entre moins un et un, strictement croissante dans une direction pour l'équation écrite du manuscrit, est une hétérocline plane. En dimension sept, toute solution stable entière est un puits constant ou une hétérocline plane, sans hypothèse de croissance d'énergie.","expertEn":"The manuscript asserts that in dimension eight every entire solution of class C two, valued between minus one and one and strictly increasing in one direction for the equation as written, is a planar heteroclinic. In dimension seven, every stable entire solution is a constant well or a planar heteroclinic, with no energy-growth assumption.","sparkFr":"L'intérêt est structural : la rigidité plane de ces transitions tiendrait jusqu'au seuil de dimension huit.","sparkEn":"The interest is structural: planar rigidity of these transitions would hold up to the dimension-eight threshold."},{"id":"376","titleEn":"Universal computation in forced Navier–Stokes flows","titleFr":"Calcul universel dans des écoulements de Navier–Stokes forcés","claim":"Constructs viscous incompressible flows starting from rest on a fixed flat three-dimensional domain that perform universal computation under smooth external forcing. A terminating compiler turns a Turing machine and input into a finite program for the force, so a designated particle reaches a fixed region exactly when the machine halts. The viscosity is fixed, positive and computable.","nature":"physique-math","domain":"physique","complexity":"avance","problemYear":1822,"yearKnown":true,"manuscriptDate":"2026-09-27","lean":true,"pdfs":[{"title":"Finite Instructions and Solenoidal Shear Flows","href":"preprints/Finite-Instructions-and-Solenoidal-Shear-Flows-September-27-2026/manuscript.pdf"},{"title":"A Fixed Particle Test for Computation in a Forced Viscous Flow","href":"preprints/A-Fixed-Particle-Test-for-Computation-in-a-Forced-Viscous-Flow-September-27-2026/manuscript.pdf"},{"title":"Universal Computation with Eventually Stationary Navier–Stokes Forcing","href":"preprints/Universal-Computation-with-Eventually-Stationary-Navier-Stokes-Forcing-September-27-2026/manuscript.pdf"},{"title":"Geometric Programs for Solenoidal Forcing","href":"preprints/Geometric-Programs-for-Solenoidal-Forcing-September-27-2026/manuscript.pdf"},{"title":"Prefix Instructions and Incompressible Flows","href":"preprints/Prefix-Instructions-and-Incompressible-Flows-September-27-2026/manuscript.pdf"},{"title":"Computation under Rapidly Vanishing Navier–Stokes Forcing","href":"preprints/Computation-under-Rapidly-Vanishing-Navier-Stokes-Forcing-September-27-2026/manuscript.pdf"}],"plainFr":"Les équations de Navier–Stokes décrivent un fluide visqueux incompressible. Le manuscrit affirme que, sur un domaine plat fixé de dimension trois, des écoulements au repos sous une force lisse simulent tout calcul : une particule atteint une région exactement quand une machine s'arrête.","plainEn":"The Navier–Stokes equations describe a viscous fluid that does not compress. The manuscript asserts that, on a fixed flat three-dimensional domain, flows starting from rest under a smooth external force can simulate any computation: a designated particle reaches a fixed region exactly when a machine halts.","expertFr":"Le manuscrit affirme des écoulements visqueux incompressibles au repos, sur un domaine plat tridimensionnel fixé et à viscosité positive calculable, qui calculent universellement sous une force lisse. Un compilateur fini change une machine de Turing et son entrée en une force telle qu'une particule désignée entre dans une région fixée exactement à l'arrêt.","expertEn":"The manuscript asserts viscous incompressible flows starting from rest on a fixed flat three-dimensional domain, with fixed positive computable viscosity, that perform universal computation under smooth external forcing. A terminating compiler turns a Turing machine and an input into a finite program for the force, so that a designated particle enters a fixed region exactly when the machine halts.","sparkFr":"L'intérêt est structural : un fluide forcé pourrait encoder l'arrêt d'une machine, sans que le texte en fasse un usage appliqué.","sparkEn":"The interest is structural: a forced fluid might encode whether a machine halts, without the text making this an applied use."},{"id":"377","titleEn":"Interior C^1,α regularity for infinity-harmonic functions","titleFr":"Régularité intérieure des fonctions infini-harmoniques","claim":"Proves uniform interior C^1,α_d regularity for bounded infinity-harmonic functions in every dimension d ≥ 3, for a positive exponent depending only on dimension. The gradient's supremum norm and Hölder seminorm on the half unit ball are bounded by a dimension-dependent constant times the oscillation on the unit ball. The exponent is not explicit.","nature":"analyse","domain":"formes","complexity":"frontiere","problemYear":null,"yearKnown":false,"manuscriptDate":"2026-10-04","lean":false,"pdfs":[{"title":"Uniform Interior C^1,α Estimates for Infinity-Harmonic Functions","href":"preprints/Uniform-Interior-C1alpha-Estimates-for-Infinity-Harmonic-Functions-October-4-2026/interior-c1-infinity-harmonic.pdf"}],"plainFr":"Une fonction infini-harmonique minimise, localement, la plus grande pente plutôt qu'une énergie moyenne. Le manuscrit affirme qu'en toute dimension au moins trois une telle fonction bornée est continûment dérivable à l'intérieur, avec un gain de Hölder positif qui ne dépend que de la dimension.","plainEn":"An infinity-harmonic function minimizes, locally, the greatest slope rather than an average energy. The manuscript asserts that in every dimension at least three such a bounded function is continuously differentiable in the interior, with a positive Hölder gain that depends only on the dimension.","expertFr":"Le manuscrit affirme une régularité intérieure uniforme de classe C un alpha, d'exposant positif dépendant seulement de la dimension et non explicite, pour les fonctions infini-harmoniques bornées en toute dimension au moins trois. La norme du gradient et son séminorme de Hölder sur la demi-boule unité sont bornés par une constante de la dimension fois l'oscillation sur la boule unité.","expertEn":"The manuscript asserts a uniform interior regularity of class C one alpha, with a positive exponent depending only on the dimension and not explicit, for bounded infinity-harmonic functions in every dimension at least three. The gradient norm and its Hölder seminorm on the half unit ball are bounded by a dimension-dependent constant times the oscillation on the unit ball.","sparkFr":"L'intérêt est structural : ces fonctions à pente maximale pourraient toujours être dérivables, avec un gain höldérien intérieur.","sparkEn":"The interest is structural: these maximal-slope functions may always be differentiable, with an interior Hölder gain."}] as Family[];
